-- Source: database/functions/groups/map_group_ownership.sql
CREATE OR REPLACE FUNCTION public.mutate_map_entity_internal_v1(p_kind text, p_action text, p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_entity_id bigint, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO public, extensions
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_id bigint:=p_entity_id; v_version bigint;
  v_begin jsonb; v_hash text; v_current jsonb; v_requested jsonb;
  v_entity jsonb; v_commit jsonb; v_public jsonb; v_response jsonb;
  v_is_publishable boolean; v_old_hidden boolean; v_new_hidden boolean;
  v_impacts jsonb:='[]'; v_replacements jsonb:='[]';
  v_affects_public boolean:=false; v_label text; v_entity_key text;
BEGIN
  IF p_kind NOT IN ('place','place_type','path') OR p_action NOT IN ('save','delete')
    OR v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  SELECT NOT o.is_hidden INTO v_is_publishable FROM public.occasions o
    WHERE o.id=p_occasion;
  IF v_is_publishable IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='occasion not found';
  END IF;

  IF p_action='save' THEN
    IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object'
      OR octet_length(p_payload::text)>262144 THEN
      RAISE invalid_parameter_value USING MESSAGE='invalid map aggregate';
    END IF;
    IF p_kind='place' THEN
      IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_payload) key WHERE key NOT IN
          ('id','title','description','type','coordinates','isHidden','order','icon'))
        OR NOT (p_payload ?& ARRAY['title','coordinates','isHidden'])
        OR length(p_payload->>'title') NOT BETWEEN 1 AND 500
        OR jsonb_typeof(p_payload->'coordinates')<>'object'
        OR jsonb_typeof(p_payload#>'{coordinates,latLng}')<>'object'
        OR jsonb_typeof(p_payload#>'{coordinates,latLng,lat}')<>'number'
        OR jsonb_typeof(p_payload#>'{coordinates,latLng,lng}')<>'number'
        OR (p_payload#>>'{coordinates,latLng,lat}')::double precision NOT BETWEEN -90 AND 90
        OR (p_payload#>>'{coordinates,latLng,lng}')::double precision NOT BETWEEN -180 AND 180 THEN
        RAISE invalid_parameter_value USING MESSAGE='invalid place aggregate';
      END IF;
      v_id:=(p_payload->>'id')::bigint;
      v_requested:=jsonb_build_object('id',v_id,'title',p_payload->>'title',
        'description',p_payload->>'description','type',p_payload->>'type',
        'coordinates',p_payload->'coordinates','isHidden',(p_payload->>'isHidden')::boolean,
        'order',(p_payload->>'order')::bigint,'icon',(p_payload->>'icon')::bigint);
      v_entity_key:='place';
    ELSIF p_kind='place_type' THEN
      IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_payload) key WHERE key NOT IN
          ('id','code','title','icon','order','isHidden','isDefault'))
        OR NOT (p_payload ?& ARRAY['code','title','isHidden','isDefault'])
        OR length(p_payload->>'code') NOT BETWEEN 1 AND 100
        OR (p_payload->>'code') !~ '^[A-Za-z0-9_-]+$'
        OR length(p_payload->>'title') NOT BETWEEN 1 AND 500 THEN
        RAISE invalid_parameter_value USING MESSAGE='invalid place type aggregate';
      END IF;
      v_id:=(p_payload->>'id')::bigint;
      v_requested:=jsonb_build_object('id',v_id,'code',p_payload->>'code',
        'title',p_payload->>'title','icon',(p_payload->>'icon')::bigint,
        'order',(p_payload->>'order')::bigint,
        'isHidden',(p_payload->>'isHidden')::boolean,
        'isDefault',(p_payload->>'isDefault')::boolean);
      v_entity_key:='placeType';
    ELSE
      IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_payload) key WHERE key NOT IN
          ('id','title','pathData','data','icon','isHidden','order'))
        OR NOT (p_payload ?& ARRAY['title','isHidden'])
        OR length(p_payload->>'title') NOT BETWEEN 1 AND 500
        OR (p_payload->'pathData' IS NOT NULL
          AND jsonb_typeof(p_payload->'pathData')<>'array')
        OR COALESCE(jsonb_array_length(p_payload->'pathData'),0)>500 THEN
        RAISE invalid_parameter_value USING MESSAGE='invalid path aggregate';
      END IF;
      v_id:=(p_payload->>'id')::bigint;
      v_requested:=jsonb_build_object('id',v_id,'title',p_payload->>'title',
        'pathData',p_payload->'pathData','data',p_payload->'data',
        'icon',(p_payload->>'icon')::bigint,
        'isHidden',(p_payload->>'isHidden')::boolean,
        'order',(p_payload->>'order')::bigint);
      v_entity_key:='path';
    END IF;
  ELSE
    IF v_id IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='entity id required'; END IF;
    v_entity_key:=CASE p_kind WHEN 'place_type' THEN 'placeType' ELSE p_kind END;
  END IF;

  IF (p_payload->>'icon') IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.icons i JOIN public.occasions o
      ON o.id=p_occasion AND i.organization=o.organization
    WHERE i.id=(p_payload->>'icon')::bigint AND (i.unit=o.unit OR i.unit IS NULL)
  ) THEN RAISE invalid_parameter_value USING MESSAGE='cross-scope map icon'; END IF;
  IF p_kind='path' AND p_action='save' AND EXISTS (
    SELECT 1 FROM jsonb_array_elements(COALESCE(p_payload->'pathData','[]')) segment,
      LATERAL jsonb_array_elements(segment) node
    WHERE (jsonb_typeof(node)='number' AND NOT EXISTS (
      SELECT 1 FROM public.places p WHERE p.id=(node#>>'{}')::bigint
        AND p.occasion=p_occasion))
      OR (jsonb_typeof(node)='object' AND NOT (
        jsonb_typeof(node->'lat')='number' AND jsonb_typeof(node->'lng')='number'))
      OR jsonb_typeof(node) NOT IN ('number','object')
  ) THEN RAISE invalid_parameter_value USING MESSAGE='invalid or cross-scope path node'; END IF;

  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'kind',p_kind,'action',p_action,'occasion',p_occasion,'entityId',v_id,
    'expectedVersion',p_expected_version,'payload',p_payload)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'map.'||p_kind||'.'||p_action,p_occasion,v_actor,v_hash);
  IF p_kind='place' THEN PERFORM public.lock_group_occasion_internal_v1(p_occasion); END IF;
  IF NOT public.get_is_editor_on_occasion(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  IF p_kind='place' AND p_action='save' AND (
    ((p_payload->>'type')='group' AND (p_payload->>'isHidden')::boolean)
    OR EXISTS(SELECT 1 FROM public.places p WHERE p.id=v_id AND p.occasion=p_occasion AND p.type='group' AND p.is_hidden)) THEN
    RAISE invalid_parameter_value USING MESSAGE='private group place is owned by group save'; END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;

  IF v_id IS NOT NULL THEN
    IF p_kind='place' THEN
      PERFORM 1 FROM public.places p WHERE p.id=v_id AND p.occasion=p_occasion FOR UPDATE;
      IF FOUND THEN SELECT jsonb_build_object('id',p.id,'title',p.title,
        'description',p.description,'type',p.type,'coordinates',p.coordinates,
        'isHidden',p.is_hidden,'order',p."order",'icon',p.icon),p.is_hidden,p.title
        INTO v_current,v_old_hidden,v_label FROM public.places p WHERE p.id=v_id; END IF;
    ELSIF p_kind='place_type' THEN
      PERFORM 1 FROM public.place_types t WHERE t.id=v_id AND t.occasion=p_occasion FOR UPDATE;
      IF FOUND THEN SELECT jsonb_build_object('id',t.id,'code',t.code,'title',t.title,
        'icon',t.icon,'order',t."order",'isHidden',t.is_hidden,'isDefault',t.is_default),
        t.is_hidden,t.title INTO v_current,v_old_hidden,v_label
        FROM public.place_types t WHERE t.id=v_id; END IF;
    ELSE
      PERFORM 1 FROM public.path_groups pg WHERE pg.id=v_id AND pg.occasion=p_occasion FOR UPDATE;
      IF FOUND THEN SELECT jsonb_build_object('id',pg.id,'title',pg.title,
        'pathData',pg.path_data,'data',pg.data,'icon',pg.icon,
        'isHidden',pg.is_hidden,'order',pg."order"),pg.is_hidden,pg.title
        INTO v_current,v_old_hidden,v_label FROM public.path_groups pg WHERE pg.id=v_id; END IF;
    END IF;
    IF v_current IS NULL THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        CASE WHEN p_action='delete' THEN 'unchanged' ELSE 'rejected' END,
        CASE WHEN p_action='delete' THEN 200 ELSE 404 END,
        jsonb_build_object('version',0,v_entity_key,NULL));
    END IF;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES (p_kind,'occasion',p_occasion,v_id::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type=p_kind AND scope_type='occasion' AND scope_id=p_occasion
        AND aggregate_id=v_id::text FOR UPDATE;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      IF p_kind='place' THEN SELECT to_jsonb(p)||jsonb_build_object('aggregate_version',v_version)
        INTO v_entity FROM public.places p WHERE p.id=v_id;
      ELSIF p_kind='place_type' THEN SELECT to_jsonb(t)||jsonb_build_object('aggregate_version',v_version)
        INTO v_entity FROM public.place_types t WHERE t.id=v_id;
      ELSE SELECT to_jsonb(pg)||jsonb_build_object('aggregate_version',v_version)
        INTO v_entity FROM public.path_groups pg WHERE pg.id=v_id; END IF;
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'conflict',409,jsonb_build_object('version',v_version,
          v_entity_key,v_entity));
    END IF;
  ELSIF p_expected_version IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new map aggregate must not have expected version';
  END IF;

  IF p_action='save' AND v_current IS NOT DISTINCT FROM v_requested THEN
    IF p_kind='place' THEN SELECT to_jsonb(p)||jsonb_build_object('aggregate_version',v_version)
      INTO v_entity FROM public.places p WHERE p.id=v_id;
    ELSIF p_kind='place_type' THEN SELECT to_jsonb(t)||jsonb_build_object('aggregate_version',v_version)
      INTO v_entity FROM public.place_types t WHERE t.id=v_id;
    ELSE SELECT to_jsonb(pg)||jsonb_build_object('aggregate_version',v_version)
      INTO v_entity FROM public.path_groups pg WHERE pg.id=v_id; END IF;
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'unchanged',200,jsonb_build_object('version',v_version,
        v_entity_key,v_entity));
  END IF;

  IF p_action='delete' THEN
    IF p_kind='place' AND (EXISTS (SELECT 1 FROM public.events e WHERE e.place=v_id)
      OR EXISTS(SELECT 1 FROM public.activity_assignment_places WHERE place_id=v_id)
      OR EXISTS(SELECT 1 FROM public.activity_places WHERE place_id=v_id)
      OR EXISTS (SELECT 1 FROM public.user_group_info g WHERE g.place=v_id)
      OR EXISTS (SELECT 1 FROM public.path_groups pg,
          LATERAL jsonb_array_elements(COALESCE(pg.path_data,'[]')) segment,
          LATERAL jsonb_array_elements(segment) node
        WHERE pg.occasion=p_occasion AND jsonb_typeof(node)='number'
          AND (node#>>'{}')::bigint=v_id)) THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'rejected',409,jsonb_build_object('version',v_version,
          v_entity_key,NULL));
    END IF;
    IF p_kind='place_type' AND EXISTS (SELECT 1 FROM public.places p
      WHERE p.occasion=p_occasion AND p.type=v_current->>'code') THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'rejected',409,jsonb_build_object('version',v_version,
          v_entity_key,NULL));
    END IF;
    IF p_kind='place' THEN DELETE FROM public.places WHERE id=v_id;
    ELSIF p_kind='place_type' THEN DELETE FROM public.place_types WHERE id=v_id;
    ELSE DELETE FROM public.path_groups WHERE id=v_id; END IF;
    DELETE FROM public.client_aggregate_versions WHERE aggregate_type=p_kind
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text;
    v_entity:=NULL;
    v_affects_public:=NOT v_old_hidden;
  ELSE
    v_new_hidden:=(p_payload->>'isHidden')::boolean;
    v_affects_public:=NOT COALESCE(v_old_hidden,true) OR NOT v_new_hidden;
    IF p_kind='place' THEN
      IF v_id IS NULL THEN INSERT INTO public.places
        (title,description,type,coordinates,is_hidden,occasion,"order",icon)
        VALUES (p_payload->>'title',p_payload->>'description',p_payload->>'type',
          p_payload->'coordinates',v_new_hidden,p_occasion,(p_payload->>'order')::bigint,
          (p_payload->>'icon')::bigint) RETURNING id INTO v_id;
      ELSE UPDATE public.places SET title=p_payload->>'title',description=p_payload->>'description',
        type=p_payload->>'type',coordinates=p_payload->'coordinates',is_hidden=v_new_hidden,
        "order"=(p_payload->>'order')::bigint,icon=(p_payload->>'icon')::bigint,
        updated_at=clock_timestamp() WHERE id=v_id; END IF;
    ELSIF p_kind='place_type' THEN
      IF v_id IS NULL THEN INSERT INTO public.place_types
        (occasion,code,title,icon,"order",is_hidden,is_default)
        VALUES (p_occasion,p_payload->>'code',p_payload->>'title',(p_payload->>'icon')::bigint,
          (p_payload->>'order')::bigint,v_new_hidden,(p_payload->>'isDefault')::boolean)
        RETURNING id INTO v_id;
      ELSE UPDATE public.place_types SET code=p_payload->>'code',title=p_payload->>'title',
        icon=(p_payload->>'icon')::bigint,"order"=(p_payload->>'order')::bigint,
        is_hidden=v_new_hidden,is_default=(p_payload->>'isDefault')::boolean,
        updated_at=clock_timestamp() WHERE id=v_id; END IF;
    ELSE
      IF v_id IS NULL THEN INSERT INTO public.path_groups
        (title,path_data,data,icon,is_hidden,occasion,"order")
        VALUES (p_payload->>'title',p_payload->'pathData',p_payload->'data',
          (p_payload->>'icon')::bigint,v_new_hidden,p_occasion,
          (p_payload->>'order')::bigint) RETURNING id INTO v_id;
      ELSE UPDATE public.path_groups SET title=p_payload->>'title',
        path_data=p_payload->'pathData',data=p_payload->'data',
        icon=(p_payload->>'icon')::bigint,is_hidden=v_new_hidden,
        "order"=(p_payload->>'order')::bigint WHERE id=v_id; END IF;
    END IF;
    IF v_version IS NULL THEN v_version:=1;
      INSERT INTO public.client_aggregate_versions
        (aggregate_type,scope_type,scope_id,aggregate_id,version)
      VALUES (p_kind,'occasion',p_occasion,v_id::text,v_version);
    ELSE UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type=p_kind
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text
      RETURNING version INTO v_version; END IF;
    IF p_kind='place' THEN SELECT to_jsonb(p)||jsonb_build_object('aggregate_version',v_version),p.title
      INTO v_entity,v_label FROM public.places p WHERE p.id=v_id;
    ELSIF p_kind='place_type' THEN SELECT to_jsonb(t)||jsonb_build_object('aggregate_version',v_version),t.title
      INTO v_entity,v_label FROM public.place_types t WHERE t.id=v_id;
    ELSE SELECT to_jsonb(pg)||jsonb_build_object('aggregate_version',v_version),pg.title
      INTO v_entity,v_label FROM public.path_groups pg WHERE pg.id=v_id; END IF;
  END IF;

  IF p_kind='place' THEN
    v_impacts:=public.group_profile_impacts_internal_v1(p_occasion,ARRAY(SELECT DISTINCT ug."user" FROM public.user_groups ug JOIN public.user_group_info g ON g.id=ug."group" WHERE g.occasion=p_occasion AND g.place=v_id));
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_impacts) x WHERE x->>'userId'=v_actor::text) THEN
      v_replacements:=jsonb_build_array(jsonb_build_object('component','private_profile','userId',v_actor,'payload',public.get_private_profile_payload_v1(p_occasion,v_actor)));
    END IF;
  END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'map.'||p_kind||'.'||p_action,'map',jsonb_build_array(jsonb_build_object(
      'entityType',p_kind,'entityId',v_id,'operation',CASE WHEN p_action='delete'
        THEN 'delete' WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(v_label,240),'changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_is_publishable AND v_affects_public THEN ARRAY['map_catalog']
      ELSE '{}'::text[] END,v_impacts,'[]',
    jsonb_build_object('version',COALESCE(v_version,0),v_entity_key,v_entity),'{}','[]','user',NULL,v_replacements);
END; $function$
;
REVOKE ALL ON FUNCTION public.mutate_map_entity_internal_v1(text,text,bigint,uuid,bigint,bigint,jsonb) FROM PUBLIC,anon,authenticated;

-- Source: database/functions/groups/group_profile_read.sql
CREATE OR REPLACE FUNCTION public.get_private_profile_payload_v1(p_occasion bigint, p_user uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  SELECT jsonb_build_object(
    'user',(SELECT jsonb_build_object('id',u.id,'email',u.email_readonly,
      'name',u.name,'surname',u.surname,'sex',u.sex,'phone',u.phone,
      'birthDate',u.birth_date,'data',u.data) FROM public.user_info u
      WHERE u.id=p_user),
    'occasion',(SELECT jsonb_build_object('role',ou.role,'services',ou.services,
      'data',ou.data,'isEditor',ou.is_editor,
      'isEditorView',ou.is_editor_view,
      'isEditorOrder',ou.is_editor_order,
      'isEditorOrderView',ou.is_editor_order_view,
      'isApproved',ou.is_approved,'isApprover',ou.is_approver,
      'isManager',ou.is_manager,
      'isCleaningBlocked',ou.is_cleaning_blocked,
      'isCleaningCrew',ou.is_cleaning_crew,
      'isReceptionist',ou.is_receptionist) FROM public.occasion_users ou
      WHERE ou.occasion=p_occasion AND ou."user"=p_user),
    'companions',COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'id',ui.id,'name',ui.name,'surname',COALESCE(ui.surname,''),
      'group_title',COALESCE(groups.titles,''),'origin',uc.origin,
      'can_owner_delete',uc.origin='self_created',
      'services',COALESCE(companion_membership.services,'{}'::jsonb),
      'event_ids',COALESCE((SELECT jsonb_agg(eu.event ORDER BY eu.event)
        FROM public.event_users eu JOIN public.events e ON e.id=eu.event
        WHERE eu."user"=ui.id AND e.occasion=p_occasion),'[]'::jsonb))
      ORDER BY ui.name,ui.surname,ui.id)
      FROM public.user_companions uc
      JOIN public.user_info ui ON ui.id=uc.companion
      JOIN public.occasion_users companion_membership
        ON companion_membership.occasion=uc.occasion
       AND companion_membership."user"=uc.companion
      LEFT JOIN LATERAL (SELECT string_agg(ugi.title,', ' ORDER BY ugi.title) titles
        FROM public.user_groups ug JOIN public.user_group_info ugi ON ugi.id=ug."group"
        WHERE ug."user"=uc.companion AND ugi.occasion=p_occasion
          AND ugi.type IS NULL) groups ON true
      WHERE uc.occasion=p_occasion AND uc."user"=p_user),'[]'::jsonb),
    'groups',COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'id',g.id,'title',g.title,'description',g.description,'type',g.type,
      'data',g.data,'place',g.place,'isAdmin',mine.is_admin,
      'participants',COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'userId',members."user",'isAdmin',members.is_admin,
        'name',ui.name,'surname',ui.surname) ORDER BY members."user")
        FROM public.user_groups members JOIN public.user_info ui
          ON ui.id=members."user" WHERE members."group"=g.id),'[]'::jsonb),
      'placeData',(SELECT to_jsonb(p)||jsonb_build_object('aggregate_version',COALESCE((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='place' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p.id::text),0)) FROM public.places p WHERE p.id=g.place))
      ORDER BY g.id) FROM public.user_groups mine JOIN public.user_group_info g
        ON g.id=mine."group" WHERE mine."user"=p_user
        AND g.occasion=p_occasion),'[]'::jsonb));
$function$
;

-- Source: database/functions/groups/group_domain_helpers.sql
-- Group domain lock/impact helpers. No client EXECUTE.
CREATE OR REPLACE FUNCTION public.lock_group_occasion_internal_v1(p_occasion bigint)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
 PERFORM public.log_canonical_mutation_scope_internal_v1(p_occasion);
 PERFORM pg_catalog.pg_advisory_xact_lock(p_occasion);
 PERFORM 1 FROM public.user_group_info WHERE occasion=p_occasion ORDER BY id FOR UPDATE;
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 SELECT 'user_group','occasion',p_occasion,id::text,0 FROM public.user_group_info WHERE occasion=p_occasion ORDER BY id ON CONFLICT DO NOTHING;
 PERFORM 1 FROM public.client_aggregate_versions WHERE aggregate_type='user_group' AND scope_type='occasion' AND scope_id=p_occasion ORDER BY aggregate_id::bigint FOR UPDATE;
END $$;
CREATE OR REPLACE FUNCTION public.group_profile_impacts_internal_v1(p_occasion bigint,p_users uuid[])
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, extensions AS $$
 SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_profile','userId',u.id) ORDER BY u.id),'[]'::jsonb)
 FROM (SELECT unnest(p_users) id UNION SELECT uc."user" FROM public.user_companions uc WHERE uc.occasion=p_occasion AND uc.companion=ANY(p_users)) u
 JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=u.id;
$$;
CREATE OR REPLACE FUNCTION public.assert_group_place_owner_internal_v1(p_occasion bigint,p_group bigint,p_place bigint,p_removing boolean)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
 PERFORM 1 FROM public.places p WHERE p.id=p_place AND p.occasion=p_occasion AND p.type='group' AND p.is_hidden FOR UPDATE;
 IF NOT FOUND OR (SELECT count(*) FROM public.user_group_info WHERE place=p_place)<>1 OR NOT EXISTS(SELECT 1 FROM public.user_group_info WHERE id=p_group AND occasion=p_occasion AND place=p_place)
 OR EXISTS(SELECT 1 FROM public.activity_assignment_places WHERE place_id=p_place)
 OR EXISTS(SELECT 1 FROM public.activity_places WHERE place_id=p_place)
 OR EXISTS(SELECT 1 FROM public.events WHERE place=p_place)
 OR EXISTS(SELECT 1 FROM public.resources WHERE place=p_place)
 OR (p_removing AND (EXISTS(SELECT 1 FROM public.cleaning_reports WHERE place=p_place) OR EXISTS(SELECT 1 FROM public.cleaning_public_state WHERE place=p_place))) THEN
 RAISE invalid_parameter_value USING MESSAGE='private group place has ambiguous or external ownership'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.lock_group_occasion_internal_v1(bigint), public.group_profile_impacts_internal_v1(bigint,uuid[]), public.assert_group_place_owner_internal_v1(bigint,bigint,bigint,boolean) FROM PUBLIC,anon,authenticated;

-- Source: database/functions/activities/canonical_activity_reads.sql
CREATE OR REPLACE FUNCTION public.get_activity_editor_session_v1(p_occasion bigint)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT CASE WHEN auth.uid() IS NULL OR NOT (public.get_is_editor_view_on_occasion(p_occasion) OR public.get_is_editor_on_occasion(p_occasion)) THEN jsonb_build_object('code',403) ELSE
 jsonb_build_object('code',200,'liveVersion',COALESCE((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='activities' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_occasion::text),0),
 'latestPublishId',(SELECT id FROM public.activity_history WHERE occasion_id=p_occasion AND history_type='PUBLISH' ORDER BY id DESC LIMIT 1),
 'draftId',d.id,'draftParentHistoryId',d.parent_history_id,'draftData',CASE WHEN d.id IS NOT NULL THEN public.activity_graph_history_internal_v1(public.activity_history_graph_internal_v1(p_occasion,d.activities_data,false)) ELSE NULL END,
 'editBundle',jsonb_build_object(
 'events',COALESCE((SELECT jsonb_agg(to_jsonb(e) ORDER BY e.id) FROM public.events e WHERE e.occasion=p_occasion),'[]'),
 'places',COALESCE((SELECT jsonb_agg(to_jsonb(p) ORDER BY p."order",p.id) FROM public.places p WHERE p.occasion=p_occasion),'[]'),
 'activities',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.id) FROM public.activities a WHERE a.occasion=p_occasion),'[]'),
 'activity_assignments',COALESCE((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM public.activity_assignments x JOIN public.activities a ON a.id=x.activity_id WHERE a.occasion=p_occasion),'[]'),
 'assignment_place_links',COALESCE((SELECT jsonb_agg(to_jsonb(l)) FROM public.activity_assignment_places l JOIN public.activity_assignments x ON x.id=l.assignment_id JOIN public.activities a ON a.id=x.activity_id WHERE a.occasion=p_occasion),'[]'),
 'assignment_event_links',COALESCE((SELECT jsonb_agg(to_jsonb(l)) FROM public.activity_assignment_events l JOIN public.activity_assignments x ON x.id=l.assignment_id JOIN public.activities a ON a.id=x.activity_id WHERE a.occasion=p_occasion),'[]'),
 'user_info',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',u.id,'name',u.name,'surname',u.surname,'sex',u.sex,'email',u.email_readonly)) FROM public.user_info u JOIN public.occasion_users ou ON ou."user"=u.id WHERE ou.occasion=p_occasion AND (ou.data->>'is_volunteer')::boolean),'[]'))) END
 FROM (SELECT 1) root LEFT JOIN LATERAL (SELECT id,parent_history_id,activities_data FROM public.activity_history WHERE occasion_id=p_occasion AND user_id=auth.uid() AND history_type='AUTOSAVE' ORDER BY id DESC LIMIT 1) d ON true;
$$;
REVOKE ALL ON FUNCTION public.get_activity_editor_session_v1(bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_activity_editor_session_v1(bigint) TO authenticated;
CREATE OR REPLACE FUNCTION public.get_latest_autosave(p_occasion_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE
    autosave_record JSONB;
    v_latest_publish_id BIGINT;
BEGIN
 IF auth.uid() IS NULL OR NOT public.get_is_editor_view_on_occasion(p_occasion_id) THEN RETURN jsonb_build_object('code',403); END IF;
    -- Select the single latest autosave record for the current user
    SELECT jsonb_build_object(
        'id', id,
        'created_at', created_at,
        'activities_data', activities_data,
        'parent_history_id', parent_history_id
    )
    INTO autosave_record
    FROM public.activity_history
    WHERE occasion_id = p_occasion_id
      AND user_id = auth.uid()
      AND history_type = 'AUTOSAVE'
    ORDER BY created_at DESC
    LIMIT 1;

    -- Separately, find the ID of the absolute latest published version for the occasion
    SELECT id
    INTO v_latest_publish_id
    FROM public.activity_history
    WHERE occasion_id = p_occasion_id
      AND history_type = 'PUBLISH'
    ORDER BY created_at DESC
    LIMIT 1;

    -- Return an object containing both the autosave data (if found) and the latest publish ID (if found)
    RETURN jsonb_build_object(
        'code', 200,
        'message', 'Autosave and publish info retrieved.',
        'data', jsonb_build_object(
            'autosave', autosave_record,
            'latest_publish_id', v_latest_publish_id
        )
    );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_activity_history_version(p_history_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE
    v_occasion_id BIGINT;
    history_data JSONB;
BEGIN
    SELECT occasion_id INTO v_occasion_id FROM public.activity_history WHERE id = p_history_id AND (history_type<>'AUTOSAVE' OR user_id=auth.uid());

    IF v_occasion_id IS NULL OR (SELECT get_is_editor_on_occasion(v_occasion_id)) <> TRUE THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to view this history version');
    END IF;

    -- Select the single history record into a JSON object
    SELECT jsonb_build_object(
        'id', id,
        'created_at', created_at,
        'activities_data', public.activity_graph_history_internal_v1(public.activity_history_graph_internal_v1(v_occasion_id,activities_data,false)),
        'parent_history_id', parent_history_id
    )
    INTO history_data
    FROM public.activity_history
    WHERE id = p_history_id AND (history_type<>'AUTOSAVE' OR user_id=auth.uid());

    -- Return the object wrapped in a standard response
    RETURN jsonb_build_object(
        'code', 200,
        'message', 'History version retrieved.',
        'data', history_data
    );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.list_activity_history(p_occasion_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE
    history_data JSONB;
BEGIN
    IF (SELECT get_is_editor_on_occasion(p_occasion_id)) <> TRUE THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to view history');
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', h.id,
        'created_at', h.created_at,
        'history_type', h.history_type,
        'note', h.note,
        'user_name', u.name,
        'user_surname', u.surname
    ) ORDER BY h.created_at DESC), '[]'::jsonb)
    INTO history_data
    FROM public.activity_history h
    LEFT JOIN public.user_info u ON h.user_id = u.id
    WHERE h.occasion_id = p_occasion_id AND (h.history_type <> 'AUTOSAVE' OR (h.history_type = 'AUTOSAVE' AND h.user_id = auth.uid()));

    RETURN jsonb_build_object(
        'code', 200,
        'message', 'History retrieved successfully',
        'data', history_data
    );
END;
$function$
;

-- Source: database/functions/activities/canonical_activity_lifecycle_neighbors.sql
CREATE OR REPLACE FUNCTION public.remove_user_activity_internal_v1(p_occasion bigint,p_users uuid[])
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE impacted uuid[]; n int; impacts jsonb;
BEGIN
 PERFORM public.lock_activity_aggregate_internal_v1(p_occasion);
 SELECT ARRAY(SELECT DISTINCT aa."user" FROM public.activity_assignments aa JOIN public.activities a ON a.id=aa.activity_id WHERE a.occasion=p_occasion) INTO impacted;
 DELETE FROM public.activity_assignments aa USING public.activities a WHERE a.id=aa.activity_id AND a.occasion=p_occasion AND aa."user"=ANY(p_users);
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n=0 THEN RETURN '[]'; END IF;
 UPDATE public.client_aggregate_versions SET version=version+1,updated_at=clock_timestamp() WHERE aggregate_type='activities' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_occasion::text;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_activity','userId',id) ORDER BY id),'[]') INTO impacts FROM unnest(impacted) id JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=id WHERE NOT id=ANY(p_users);
 RETURN impacts;
END $$;
REVOKE ALL ON FUNCTION public.remove_user_activity_internal_v1(bigint,uuid[]) FROM PUBLIC,anon,authenticated;

-- Source: database/functions/activities/canonical_activity_history.sql
CREATE OR REPLACE FUNCTION public.write_activity_history_internal_v1(p_occasion bigint,p_actor uuid,p_data jsonb,p_type text,p_parent bigint,p_note text)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE hid bigint;
BEGIN
 IF p_type NOT IN ('AUTOSAVE','PUBLISH') OR (p_parent IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.activity_history WHERE id=p_parent AND occasion_id=p_occasion AND history_type='PUBLISH')) THEN RAISE invalid_parameter_value USING MESSAGE='invalid history parent or type'; END IF;
 IF p_type='AUTOSAVE' THEN PERFORM public.clear_activity_draft_internal_v1(p_occasion,p_actor,NULL,false); END IF;
 INSERT INTO public.activity_history(occasion_id,user_id,activities_data,history_type,note,parent_history_id) VALUES(p_occasion,p_actor,p_data,p_type,p_note,p_parent) RETURNING id INTO hid;
 RETURN hid;
END $$;
CREATE OR REPLACE FUNCTION public.clear_activity_draft_internal_v1(p_occasion bigint,p_actor uuid,p_parent bigint,p_check_parent boolean)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE n int;
BEGIN
 DELETE FROM public.activity_history WHERE occasion_id=p_occasion AND user_id=p_actor AND history_type='AUTOSAVE' AND (NOT p_check_parent OR parent_history_id IS NOT DISTINCT FROM p_parent);
 GET DIAGNOSTICS n=ROW_COUNT; RETURN n;
END $$;
REVOKE ALL ON FUNCTION public.write_activity_history_internal_v1(bigint,uuid,jsonb,text,bigint,text),public.clear_activity_draft_internal_v1(bigint,uuid,bigint,boolean) FROM PUBLIC,anon,authenticated;

-- A publication consumes the selected immutable draft row. Legacy publications
-- without a row token may clear only a draft containing the published graph.
CREATE OR REPLACE FUNCTION public.consume_selected_activity_draft_internal_v1(
 p_occasion bigint,p_actor uuid,p_parent bigint,p_selection jsonb,p_graph jsonb)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE n integer;
BEGIN
 DELETE FROM public.activity_history h WHERE h.occasion_id=p_occasion
  AND h.user_id=p_actor AND h.history_type='AUTOSAVE'
  AND CASE WHEN p_selection IS NULL THEN
   h.parent_history_id IS NOT DISTINCT FROM p_parent AND
   public.activity_history_graph_internal_v1(p_occasion,h.activities_data)=p_graph
  ELSE h.id=(p_selection->>'id')::bigint
   AND (p_selection->>'created_at' IS NULL OR h.created_at=(p_selection->>'created_at')::timestamptz)
  END;
 GET DIAGNOSTICS n=ROW_COUNT;
 RETURN n;
END $$;
REVOKE ALL ON FUNCTION public.consume_selected_activity_draft_internal_v1(bigint,uuid,bigint,jsonb,jsonb)
 FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/activities/canonical_activity_graph.sql
-- Activity graph domain: one implementation shared by publish and G3 compatibility.
CREATE OR REPLACE FUNCTION public.activity_time_internal_v1(p_value text,p_occasion bigint,p_utc boolean)
RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE zone text; instant timestamptz;
BEGIN
 IF p_value IS NULL THEN RETURN NULL; END IF;
 SELECT COALESCE(data->>'timezone','Europe/Prague') INTO zone FROM public.occasions WHERE id=p_occasion;
 IF NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=zone) THEN zone:='Europe/Prague'; END IF;
 IF p_value ~ '(Z|[+-][0-9]{2}:[0-9]{2})$' THEN instant:=p_value::timestamptz;
 ELSE instant:=p_value::timestamp AT TIME ZONE CASE WHEN p_utc THEN 'UTC' ELSE zone END; END IF;
 RETURN to_char(instant AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
END $$;
CREATE OR REPLACE FUNCTION public.normalize_activity_graph_internal_v1(p_occasion bigint,p_graph jsonb,p_utc boolean DEFAULT true,p_validate boolean DEFAULT true)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE a jsonb; x jsonb; result jsonb:='[]'; assignments jsonb; seen uuid[]:='{}'; seen_assignments uuid[]:='{}'; aid uuid; xid uuid; places jsonb; events jsonb;
BEGIN
 IF p_graph IS NULL OR jsonb_typeof(p_graph)<>'array' OR jsonb_array_length(p_graph)>2000 OR octet_length(p_graph::text)>2097152 THEN RAISE invalid_parameter_value USING MESSAGE='invalid activity graph'; END IF;
 FOR a IN SELECT value FROM jsonb_array_elements(p_graph) ORDER BY value->>'id' LOOP
  IF jsonb_typeof(a)<>'object' OR NOT(a ?& ARRAY['id','title','is_hidden','order','assignments']) OR EXISTS(SELECT 1 FROM jsonb_object_keys(a) k WHERE k NOT IN('id','title','description','type','unit','is_hidden','order','data','assignments')) OR jsonb_typeof(a->'assignments')<>'array' THEN RAISE invalid_parameter_value USING MESSAGE='invalid activity'; END IF;
  aid:=(a->>'id')::uuid;
  IF aid IS NULL OR aid=ANY(seen) OR (p_validate AND EXISTS(SELECT 1 FROM public.activities WHERE id=aid AND occasion<>p_occasion)) OR (p_validate AND a->>'unit' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=p_occasion AND unit=(a->>'unit')::bigint)) THEN RAISE invalid_parameter_value USING MESSAGE='duplicate or foreign activity'; END IF;
  seen:=array_append(seen,aid); assignments:='[]';
  FOR x IN SELECT value FROM jsonb_array_elements(a->'assignments') ORDER BY value->>'id' LOOP
   IF jsonb_typeof(x)<>'object' OR NOT(x ?& ARRAY['id','linked_place_ids','linked_event_ids']) OR EXISTS(SELECT 1 FROM jsonb_object_keys(x) k WHERE k NOT IN('id','user','start_time','end_time','title','description','data','linked_place_ids','linked_event_ids')) OR jsonb_typeof(x->'linked_place_ids')<>'array' OR jsonb_typeof(x->'linked_event_ids')<>'array' THEN RAISE invalid_parameter_value USING MESSAGE='invalid assignment'; END IF;
   xid:=(x->>'id')::uuid;
   IF xid IS NULL OR xid=ANY(seen_assignments) OR (p_validate AND EXISTS(SELECT 1 FROM public.activity_assignments aa JOIN public.activities ac ON ac.id=aa.activity_id WHERE aa.id=xid AND ac.occasion<>p_occasion)) OR (p_validate AND x->>'user' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=p_occasion AND "user"=(x->>'user')::uuid)) THEN RAISE invalid_parameter_value USING MESSAGE='duplicate or foreign assignment'; END IF;
   IF p_validate AND (x->>'user' IS NULL OR x->>'start_time' IS NULL OR x->>'end_time' IS NULL OR public.activity_time_internal_v1(x->>'end_time',p_occasion,p_utc)::timestamptz < public.activity_time_internal_v1(x->>'start_time',p_occasion,p_utc)::timestamptz) THEN RAISE invalid_parameter_value USING MESSAGE='assignment user and ordered times required'; END IF;
   seen_assignments:=array_append(seen_assignments,xid);
   IF p_validate AND (EXISTS(SELECT 1 FROM jsonb_array_elements_text(x->'linked_place_ids') id WHERE NOT EXISTS(SELECT 1 FROM public.places WHERE public.places.id=id::bigint AND occasion=p_occasion)) OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(x->'linked_event_ids') id WHERE NOT EXISTS(SELECT 1 FROM public.events WHERE public.events.id=id::bigint AND occasion=p_occasion))) THEN RAISE invalid_parameter_value USING MESSAGE='foreign assignment reference'; END IF;
   SELECT COALESCE(jsonb_agg(id::bigint ORDER BY id::bigint),'[]') INTO places FROM jsonb_array_elements_text(x->'linked_place_ids') id;
   SELECT COALESCE(jsonb_agg(id::bigint ORDER BY id::bigint),'[]') INTO events FROM jsonb_array_elements_text(x->'linked_event_ids') id;
   IF jsonb_array_length(places)<>(SELECT count(DISTINCT v) FROM jsonb_array_elements(places) v) OR jsonb_array_length(events)<>(SELECT count(DISTINCT v) FROM jsonb_array_elements(events) v) THEN RAISE invalid_parameter_value USING MESSAGE='duplicate assignment links'; END IF;
   assignments:=assignments||jsonb_build_array(jsonb_build_object('id',xid,'user',(x->>'user')::uuid,'start_time',public.activity_time_internal_v1(x->>'start_time',p_occasion,p_utc),'end_time',public.activity_time_internal_v1(x->>'end_time',p_occasion,p_utc),'title',x->>'title','description',x->>'description','data',x->'data','linked_place_ids',places,'linked_event_ids',events));
  END LOOP;
  result:=result||jsonb_build_array(jsonb_build_object('id',aid,'title',a->>'title','description',a->>'description','type',a->>'type','unit',(a->>'unit')::bigint,'is_hidden',(a->>'is_hidden')::boolean,'order',(a->>'order')::bigint,'data',a->'data','assignments',assignments));
 END LOOP;
 RETURN result;
END $$;
CREATE OR REPLACE FUNCTION public.activity_history_graph_internal_v1(p_occasion bigint,p_history jsonb,p_validate boolean DEFAULT true)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE graph jsonb;
BEGIN
 IF p_history IS NULL OR jsonb_typeof(p_history)<>'object' OR octet_length(p_history::text)>2097152 OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_history) k WHERE k NOT IN('id','parent_history_id','aggregate_version','activities','activity_assignments','assignmentPlaceLinks','assignmentEventLinks','schemaVersion','timeBasis')) OR (p_history ? 'schemaVersion' AND (p_history->>'schemaVersion'<>'1' OR p_history->>'timeBasis'<>'UTC')) THEN RAISE invalid_parameter_value USING MESSAGE='invalid activity history'; END IF;
 IF p_validate THEN
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_history->'activities','[]')) a,LATERAL jsonb_object_keys(a) k WHERE k NOT IN('id','created_at','updated_at','title','description','type','occasion','unit','is_hidden','order','data','activity_assignments')) OR EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_history->'activity_assignments','[]')) x,LATERAL jsonb_object_keys(x) k WHERE k NOT IN('id','activity_id','user','start_time','end_time','title','description','data','user_info','activity_assignment_places','activity_assignment_events','created_at','updated_at')) THEN RAISE invalid_parameter_value USING MESSAGE='unknown activity history field'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_history->'activities','[]')) a WHERE jsonb_typeof(a->'activity_assignments')='array' AND (
    jsonb_array_length(a->'activity_assignments')<>(SELECT count(*) FROM jsonb_array_elements(COALESCE(p_history->'activity_assignments','[]')) x WHERE x->>'activity_id'=a->>'id') OR EXISTS(
      SELECT 1 FROM jsonb_array_elements(a->'activity_assignments') nx WHERE EXISTS(SELECT 1 FROM jsonb_object_keys(nx) k WHERE k NOT IN('id','activity_id','user','start_time','end_time','title','description','data','user_info','activity_assignment_places','activity_assignment_events','created_at','updated_at')) OR NOT EXISTS(
        SELECT 1 FROM jsonb_array_elements(COALESCE(p_history->'activity_assignments','[]')) x WHERE x->>'id'=nx->>'id' AND x->>'activity_id'=a->>'id' AND (x->'user',x->'title',x->'description',x->'data') IS NOT DISTINCT FROM (nx->'user',nx->'title',nx->'description',nx->'data') AND public.activity_time_internal_v1(x->>'start_time',p_occasion,p_history->>'timeBasis'='UTC') IS NOT DISTINCT FROM public.activity_time_internal_v1(nx->>'start_time',p_occasion,p_history->>'timeBasis'='UTC') AND public.activity_time_internal_v1(x->>'end_time',p_occasion,p_history->>'timeBasis'='UTC') IS NOT DISTINCT FROM public.activity_time_internal_v1(nx->>'end_time',p_occasion,p_history->>'timeBasis'='UTC'))))) THEN RAISE invalid_parameter_value USING MESSAGE='inconsistent nested history assignments'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_history->'assignmentPlaceLinks','[]')) l WHERE EXISTS(SELECT 1 FROM jsonb_object_keys(l) k WHERE k NOT IN('assignment_id','place_id')) OR l->>'place_id' IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_history->'activity_assignments','[]')) x WHERE x->>'id'=l->>'assignment_id')) OR EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_history->'assignmentEventLinks','[]')) l WHERE EXISTS(SELECT 1 FROM jsonb_object_keys(l) k WHERE k NOT IN('assignment_id','event_id')) OR l->>'event_id' IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_history->'activity_assignments','[]')) x WHERE x->>'id'=l->>'assignment_id')) THEN RAISE invalid_parameter_value USING MESSAGE='orphan or invalid history link'; END IF;
 END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',a->'id','title',a->'title','description',a->'description','type',a->'type','unit',a->'unit','is_hidden',a->'is_hidden','order',a->'order','data',a->'data','assignments',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',x->'id','user',x->'user','start_time',x->'start_time','end_time',x->'end_time','title',x->'title','description',x->'description','data',x->'data','linked_place_ids',COALESCE((SELECT jsonb_agg(l->'place_id') FROM jsonb_array_elements(COALESCE(p_history->'assignmentPlaceLinks','[]')) l WHERE l->>'assignment_id'=x->>'id'),'[]'),'linked_event_ids',COALESCE((SELECT jsonb_agg(l->'event_id') FROM jsonb_array_elements(COALESCE(p_history->'assignmentEventLinks','[]')) l WHERE l->>'assignment_id'=x->>'id'),'[]'))) FROM jsonb_array_elements(COALESCE(p_history->'activity_assignments','[]')) x WHERE x->>'activity_id'=a->>'id'),'[]'))),'[]') INTO graph FROM jsonb_array_elements(COALESCE(NULLIF(p_history->'activities','null'),'[]')) a;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_history->'activity_assignments','[]')) x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_history->'activities','[]')) a WHERE a->>'id'=x->>'activity_id')) THEN RAISE invalid_parameter_value USING MESSAGE='orphan history assignment'; END IF;
 RETURN public.normalize_activity_graph_internal_v1(p_occasion,graph,p_history->>'timeBasis'='UTC',p_validate);
END $$;
CREATE OR REPLACE FUNCTION public.activity_graph_history_internal_v1(p_graph jsonb)
RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public,extensions AS $$
 SELECT jsonb_build_object('schemaVersion',1,'timeBasis','UTC','activities',COALESCE((SELECT jsonb_agg(a-'assignments') FROM jsonb_array_elements(p_graph) a),'[]'),'activity_assignments',COALESCE((SELECT jsonb_agg((x-'linked_place_ids'-'linked_event_ids')||jsonb_build_object('activity_id',a->'id')) FROM jsonb_array_elements(p_graph) a,LATERAL jsonb_array_elements(a->'assignments') x),'[]'),'assignmentPlaceLinks',COALESCE((SELECT jsonb_agg(jsonb_build_object('assignment_id',x->'id','place_id',p)) FROM jsonb_array_elements(p_graph) a,LATERAL jsonb_array_elements(a->'assignments') x,LATERAL jsonb_array_elements(x->'linked_place_ids') p),'[]'),'assignmentEventLinks',COALESCE((SELECT jsonb_agg(jsonb_build_object('assignment_id',x->'id','event_id',e)) FROM jsonb_array_elements(p_graph) a,LATERAL jsonb_array_elements(a->'assignments') x,LATERAL jsonb_array_elements(x->'linked_event_ids') e),'[]'));
$$;
CREATE OR REPLACE FUNCTION public.current_activity_graph_internal_v1(p_occasion bigint)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT public.normalize_activity_graph_internal_v1(p_occasion,COALESCE(jsonb_agg(jsonb_build_object('id',a.id,'title',a.title,'description',a.description,'type',a.type,'unit',a.unit,'is_hidden',a.is_hidden,'order',a."order",'data',a.data,'assignments',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',x.id,'user',x."user",'start_time',x.start_time,'end_time',x.end_time,'title',x.title,'description',x.description,'data',x.data,'linked_place_ids',COALESCE((SELECT jsonb_agg(place_id) FROM public.activity_assignment_places WHERE assignment_id=x.id),'[]'),'linked_event_ids',COALESCE((SELECT jsonb_agg(event_id) FROM public.activity_assignment_events WHERE assignment_id=x.id),'[]'))) FROM public.activity_assignments x WHERE x.activity_id=a.id),'[]'))),'[]'),true) FROM public.activities a WHERE a.occasion=p_occasion;
$$;
CREATE OR REPLACE FUNCTION public.replace_activities_graph_internal_v1(p_occasion bigint,p_graph jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE a jsonb; x jsonb; graph jsonb; changed int;
BEGIN
 graph:=public.normalize_activity_graph_internal_v1(p_occasion,p_graph,true);
 DELETE FROM public.activity_assignments aa USING public.activities a WHERE aa.activity_id=a.id AND a.occasion=p_occasion AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(graph) g,LATERAL jsonb_array_elements(g->'assignments') assignment WHERE assignment->>'id'=aa.id::text);
 DELETE FROM public.activities WHERE occasion=p_occasion AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(graph) g WHERE g->>'id'=public.activities.id::text);
 FOR a IN SELECT value FROM jsonb_array_elements(graph) LOOP
  INSERT INTO public.activities(id,title,description,type,unit,occasion,is_hidden,"order",data) VALUES((a->>'id')::uuid,a->>'title',a->>'description',a->>'type',(a->>'unit')::bigint,p_occasion,(a->>'is_hidden')::boolean,(a->>'order')::bigint,a->'data') ON CONFLICT(id) DO UPDATE SET title=excluded.title,description=excluded.description,type=excluded.type,unit=excluded.unit,is_hidden=excluded.is_hidden,"order"=excluded."order",data=excluded.data WHERE public.activities.occasion=p_occasion;
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE invalid_parameter_value USING MESSAGE='global activity UUID collision'; END IF;
  FOR x IN SELECT value FROM jsonb_array_elements(a->'assignments') LOOP
   INSERT INTO public.activity_assignments(id,activity_id,"user",start_time,end_time,title,description,data) VALUES((x->>'id')::uuid,(a->>'id')::uuid,(x->>'user')::uuid,(x->>'start_time')::timestamptz,(x->>'end_time')::timestamptz,x->>'title',x->>'description',x->'data') ON CONFLICT(id) DO UPDATE SET activity_id=excluded.activity_id,"user"=excluded."user",start_time=excluded.start_time,end_time=excluded.end_time,title=excluded.title,description=excluded.description,data=excluded.data WHERE EXISTS(SELECT 1 FROM public.activities owner WHERE owner.id=public.activity_assignments.activity_id AND owner.occasion=p_occasion);
   GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE invalid_parameter_value USING MESSAGE='global assignment UUID collision'; END IF;
   DELETE FROM public.activity_assignment_places WHERE assignment_id=(x->>'id')::uuid;
   INSERT INTO public.activity_assignment_places(assignment_id,place_id) SELECT (x->>'id')::uuid,value::bigint FROM jsonb_array_elements_text(x->'linked_place_ids');
   DELETE FROM public.activity_assignment_events WHERE assignment_id=(x->>'id')::uuid;
   INSERT INTO public.activity_assignment_events(assignment_id,event_id) SELECT (x->>'id')::uuid,value::bigint FROM jsonb_array_elements_text(x->'linked_event_ids');
  END LOOP;
 END LOOP;
END $$;

REVOKE ALL ON FUNCTION public.activity_time_internal_v1(text,bigint,boolean),public.normalize_activity_graph_internal_v1(bigint,jsonb,boolean,boolean),public.activity_history_graph_internal_v1(bigint,jsonb,boolean),public.activity_graph_history_internal_v1(jsonb),public.current_activity_graph_internal_v1(bigint),public.replace_activities_graph_internal_v1(bigint,jsonb) FROM PUBLIC,anon,authenticated;

-- Source: database/functions/inventory/lock_product_order_dependencies_internal_v1.sql
CREATE OR REPLACE FUNCTION public.lock_product_order_dependencies_internal_v1(p_product bigint)
RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE ids bigint[];
BEGIN
 SELECT ARRAY(SELECT DISTINCT "order" FROM eshop.order_product_ticket WHERE product=p_product ORDER BY "order") INTO ids;
 PERFORM public.lock_order_capacity_scope_internal(ids);
 PERFORM 1 FROM eshop.products WHERE id=p_product FOR UPDATE;
 IF EXISTS(SELECT 1 FROM eshop.order_product_ticket WHERE product=p_product AND NOT "order"=ANY(ids)) THEN
  RAISE serialization_failure USING MESSAGE='product order parents changed; retry the same command'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.lock_product_order_dependencies_internal_v1(bigint) FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/speakers/lock_speaker_event_dependencies_internal_v1.sql
CREATE OR REPLACE FUNCTION public.lock_speaker_event_dependencies_internal_v1(p_speaker bigint)
RETURNS bigint[] LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE ids bigint[]; current_ids bigint[];
BEGIN
 SELECT ARRAY(SELECT event FROM public.event_speakers WHERE speaker=p_speaker ORDER BY event) INTO ids;
 PERFORM 1 FROM public.events WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.speakers WHERE id=p_speaker FOR UPDATE;
 SELECT ARRAY(SELECT event FROM public.event_speakers WHERE speaker=p_speaker ORDER BY event) INTO current_ids;
 IF ids IS DISTINCT FROM current_ids THEN RAISE serialization_failure USING MESSAGE='speaker event links changed; retry the same command'; END IF;
 RETURN ids;
END $$;
REVOKE ALL ON FUNCTION public.lock_speaker_event_dependencies_internal_v1(bigint) FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/events/event_deletion_domain.sql
CREATE OR REPLACE FUNCTION public.lock_event_deletion_scope_internal_v1(p_occasion bigint,p_ids bigint[])
RETURNS bigint[] LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE children bigint[]; current_children bigint[];
BEGIN
 SELECT ARRAY(SELECT DISTINCT event_child FROM public.event_groups WHERE event_parent=ANY(p_ids) AND NOT event_child=ANY(p_ids) ORDER BY event_child) INTO children;
 IF EXISTS(SELECT 1 FROM public.events WHERE id=ANY(children) AND occasion<>p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='event child outside occasion'; END IF;
 PERFORM 1 FROM public.events WHERE occasion=p_occasion AND id=ANY(p_ids||children) ORDER BY id FOR UPDATE;
 SELECT ARRAY(SELECT DISTINCT event_child FROM public.event_groups WHERE event_parent=ANY(p_ids) AND NOT event_child=ANY(p_ids) ORDER BY event_child) INTO current_children;
 IF children IS DISTINCT FROM current_children THEN RAISE serialization_failure USING MESSAGE='event links changed; retry the same command'; END IF;
 RETURN children;
END $$;

-- Shared teardown for ordinary events and empty counseling slots. Callers own
-- admission/receipts; every removed link invalidates its surviving aggregate.
CREATE OR REPLACE FUNCTION public.delete_events_domain_internal_v1(p_occasion bigint,p_ids bigint[])
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE children bigint[]; groups bigint[]; had_speakers boolean; deleted integer;
BEGIN
 IF EXISTS(SELECT 1 FROM public.events WHERE id=ANY(p_ids) AND occasion<>p_occasion) THEN
  RAISE insufficient_privilege USING MESSAGE='event deletion outside occasion'; END IF;
 children:=public.lock_event_deletion_scope_internal_v1(p_occasion,p_ids);
 SELECT ARRAY(SELECT DISTINCT "group" FROM public.exclusive_events WHERE event=ANY(p_ids) ORDER BY "group") INTO groups;
 IF EXISTS(SELECT 1 FROM public.exclusive_groups WHERE id=ANY(groups) AND occasion<>p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='exclusive group outside occasion'; END IF;
 PERFORM 1 FROM public.exclusive_groups WHERE id=ANY(groups) ORDER BY id FOR UPDATE;
 SELECT EXISTS(SELECT 1 FROM public.event_speakers WHERE event=ANY(p_ids)) INTO had_speakers;
 DELETE FROM public.event_users WHERE event=ANY(p_ids);
 DELETE FROM public.event_users_saved WHERE event=ANY(p_ids);
 DELETE FROM public.exclusive_events WHERE event=ANY(p_ids);
 DELETE FROM public.event_roles WHERE event=ANY(p_ids);
 DELETE FROM public.event_groups WHERE event_parent=ANY(p_ids) OR event_child=ANY(p_ids);
 DELETE FROM public.event_speakers WHERE event=ANY(p_ids);
 DELETE FROM public.events WHERE id=ANY(p_ids) AND occasion=p_occasion;
 GET DIAGNOSTICS deleted=ROW_COUNT;
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 SELECT 'event','occasion',p_occasion,id::text,1 FROM unnest(children) id
 ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
 SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 SELECT 'exclusive_group','occasion',p_occasion,id::text,1 FROM unnest(groups) id
 ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
 SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
 DELETE FROM public.client_aggregate_versions WHERE aggregate_type='event' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=ANY(ARRAY(SELECT id::text FROM unnest(p_ids) id));
 RETURN jsonb_build_object('deleted',deleted,'childIds',to_jsonb(children),'exclusiveGroupIds',to_jsonb(groups),'hadSpeakers',had_speakers);
END $$;
REVOKE ALL ON FUNCTION public.lock_event_deletion_scope_internal_v1(bigint,bigint[]),public.delete_events_domain_internal_v1(bigint,bigint[]) FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/users/publish_user_profile_change_internal_v1.sql
-- Global identity columns appear in every occasion profile. The caller holds
-- user_info before any membership/version locks, and owns its origin receipt.
CREATE OR REPLACE FUNCTION public.publish_user_profile_change_internal_v1(p_user uuid,p_origin bigint,p_before jsonb)
RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE oc bigint;
BEGIN
 IF p_before IS NOT DISTINCT FROM (SELECT to_jsonb(ui) FROM public.user_info ui WHERE id=p_user) THEN RETURN; END IF;
 FOR oc IN SELECT occasion FROM public.occasion_users WHERE "user"=p_user AND occasion IS DISTINCT FROM p_origin ORDER BY occasion LOOP
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES('occasion_user','occasion',oc,p_user::text,1)
  ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
  SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
  PERFORM public.impact_private_profile_users_v1(oc,ARRAY[p_user],'profile.global.changed');
  PERFORM public.impact_companion_owners_v1(oc,ARRAY[p_user],'profile.companion_identity.changed');
 END LOOP;
END $$;
REVOKE ALL ON FUNCTION public.publish_user_profile_change_internal_v1(uuid,bigint,jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/eshop/authoring_versions.sql
-- Private aggregate metadata plumbing; callers own authorization and parent locks.
CREATE OR REPLACE FUNCTION public.advance_ticketing_authoring_version_internal_v1(p_kind text,p_occasion bigint,p_id bigint)
RETURNS bigint LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE result bigint;
BEGIN
 IF p_kind NOT IN ('product','product_type','inventory_pool') OR p_occasion IS NULL OR p_id IS NULL THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid ticketing aggregate identity'; END IF;
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 VALUES(p_kind,'occasion',p_occasion,p_id::text,1)
 ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
 SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp()
 RETURNING version INTO result;
 RETURN result;
END $$;
CREATE OR REPLACE FUNCTION public.get_ticketing_product_versions_internal_v1(p_occasion bigint,p_kind text)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public,extensions AS $$
 SELECT coalesce(jsonb_object_agg(ids.id::text,coalesce(v.version,0)),'{}') FROM (
  SELECT id FROM eshop.products WHERE occasion=p_occasion AND p_kind='product'
  UNION ALL SELECT id FROM eshop.product_types WHERE occasion=p_occasion AND p_kind='product_type'
 ) ids LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type=p_kind
 AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=ids.id::text;
$$;
REVOKE ALL ON FUNCTION public.advance_ticketing_authoring_version_internal_v1(text,bigint,bigint),
 public.get_ticketing_product_versions_internal_v1(bigint,text) FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/inventory/lock_pool_product_dependencies_internal_v1.sql
-- Match allocation order: forms/orders, products, pool, contexts/resources, spots.
-- A concurrent new link discovered after locking the pool forces a clean retry.
CREATE OR REPLACE FUNCTION public.lock_pool_product_dependencies_internal_v1(p_pool bigint)
RETURNS bigint[] LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE v_product_ids bigint[];
BEGIN
 SELECT coalesce(array_agg(DISTINCT pic.product ORDER BY pic.product),'{}') INTO v_product_ids
 FROM eshop.product_inventory_contexts pic JOIN public.inventory_contexts ic ON ic.id=pic.inventory_context WHERE ic.inventory_pool=p_pool;
 PERFORM public.lock_order_capacity_scope_internal(ARRAY(SELECT DISTINCT "order" FROM eshop.order_product_ticket WHERE product=ANY(v_product_ids)));
 PERFORM 1 FROM eshop.products WHERE id=ANY(v_product_ids) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.inventory_pools WHERE id=p_pool FOR UPDATE;
 IF EXISTS(SELECT 1 FROM eshop.product_inventory_contexts pic JOIN public.inventory_contexts ic ON ic.id=pic.inventory_context
   WHERE ic.inventory_pool=p_pool AND NOT pic.product=ANY(v_product_ids)) THEN
  RAISE serialization_failure USING MESSAGE='inventory product dependencies changed; retry the same command'; END IF;
 RETURN v_product_ids;
END $$;
REVOKE ALL ON FUNCTION public.lock_pool_product_dependencies_internal_v1(bigint) FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/inventory/lock_resource_pools_internal_v1.sql
-- Lock both sides of a resource move before the resource, in deterministic order.
CREATE OR REPLACE FUNCTION public.lock_resource_pools_internal_v1(p_resource bigint,p_target bigint DEFAULT NULL)
RETURNS bigint LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE origin bigint; current_pool bigint;
BEGIN
 SELECT inventory_pool INTO origin FROM public.resources WHERE id=p_resource;
 PERFORM 1 FROM public.inventory_pools WHERE id=ANY(ARRAY[origin,p_target]) ORDER BY id FOR UPDATE;
 SELECT inventory_pool INTO current_pool FROM public.resources WHERE id=p_resource FOR UPDATE;
 IF current_pool IS DISTINCT FROM origin THEN
  RAISE serialization_failure USING MESSAGE='resource pool changed; retry the same command'; END IF;
 RETURN origin;
END $$;
REVOKE ALL ON FUNCTION public.lock_resource_pools_internal_v1(bigint,bigint) FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/information/validate_information_content_internal_v1.sql
-- Shared field validation. Unit games have no valid hidden-answer authority.
CREATE OR REPLACE FUNCTION public.validate_information_content_internal_v1(p_information jsonb,p_unit boolean)
RETURNS void LANGUAGE plpgsql IMMUTABLE SET search_path=public,extensions AS $$
BEGIN
 IF p_information IS NULL OR jsonb_typeof(p_information)<>'object' OR octet_length(p_information::text)>786432
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_information) k WHERE k NOT IN
 ('id','title','description','type','isHidden','order','data','hiddenData'))
 OR jsonb_typeof(p_information->'isHidden') IS DISTINCT FROM 'boolean'
 OR length(coalesce(p_information->>'title',''))>500 OR length(coalesce(p_information->>'type',''))>100
 OR octet_length(coalesce(p_information->>'description',''))>524288
 OR octet_length(coalesce((p_information->'data')::text,''))>131072
 OR octet_length(coalesce((p_information->'hiddenData')::text,''))>65536
 OR ((p_information->>'type') IS DISTINCT FROM 'game' AND coalesce(p_information->'hiddenData','null')<>'null')
 OR (p_unit AND (p_information->>'type'='game' OR coalesce(p_information->'hiddenData','null')<>'null'))
 THEN RAISE invalid_parameter_value USING MESSAGE='invalid information aggregate or unsupported unit game'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.validate_information_content_internal_v1(jsonb,boolean) FROM PUBLIC,anon,authenticated;

-- Source: database/functions/units/complete_unit_mutation_internal_v1.sql
CREATE OR REPLACE FUNCTION public.complete_unit_mutation_internal_v1(
 p_command_id uuid,p_unit bigint,p_source text,p_entity_type text,p_entity_id bigint,p_operation text,p_data jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE c public.client_commits%ROWTYPE;
BEGIN
 INSERT INTO public.client_commits(unit,actor_id,actor_display,actor_kind,source,change_class)
 SELECT p_unit,auth.uid(),nullif(concat_ws(' ',u.name,u.surname),''),'user',p_source,'configuration'
 FROM public.user_info u WHERE u.id=auth.uid() RETURNING * INTO c;
 INSERT INTO public.client_commit_items(commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
 VALUES(c.commit_id,0,p_entity_type,p_entity_id::text,p_operation,'Unit configuration',ARRAY['aggregate']);
 PERFORM public.fanout_unit_catalog_v1(c.commit_id,p_unit);
 RETURN public.finish_client_mutation_v1(p_command_id,jsonb_build_object('status','applied','code',200,'data',p_data,
  'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,'commitId',c.commit_id,
  'replayed',false,'occurredAt',c.occurred_at),'sync',jsonb_build_object('replacements','[]'::jsonb)),c.commit_id);
END $$;
REVOKE ALL ON FUNCTION public.complete_unit_mutation_internal_v1(uuid,bigint,text,text,bigint,text,jsonb) FROM PUBLIC,anon,authenticated;

-- Source: database/functions/units/begin_unit_client_mutation_v1.sql
CREATE OR REPLACE FUNCTION public.begin_unit_client_mutation_v1(p_command_id uuid, p_command_name text, p_unit bigint, p_actor_id uuid, p_request_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_receipt public.client_mutation_receipts%ROWTYPE; v_inserted integer;
BEGIN
  IF p_actor_id IS NULL OR p_actor_id IS DISTINCT FROM auth.uid()
     OR p_command_id IS NULL OR p_unit IS NULL
     OR p_command_name !~ '^[a-z][a-z0-9_.]{2,95}$'
     OR p_request_sha256 !~ '^[0-9a-f]{64}$'
     OR NOT (public.get_is_manager_on_unit(p_unit) OR (public.get_is_editor_on_unit(p_unit)
       AND p_command_name IN ('unit.information.save','unit.information.delete','unit.icon.save','unit.icon.delete'))) THEN
    RAISE insufficient_privilege USING MESSAGE='invalid unit mutation receipt claim';
  END IF;
  INSERT INTO public.client_mutation_receipts
    (command_id,command_name,unit,actor_id,request_sha256)
  VALUES (p_command_id,p_command_name,p_unit,p_actor_id,p_request_sha256)
  ON CONFLICT (command_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted=ROW_COUNT;
  SELECT * INTO STRICT v_receipt FROM public.client_mutation_receipts
    WHERE command_id=p_command_id FOR UPDATE;
  IF v_receipt.command_name IS DISTINCT FROM p_command_name
     OR v_receipt.occasion IS NOT NULL OR v_receipt.unit IS DISTINCT FROM p_unit
     OR v_receipt.actor_id IS DISTINCT FROM p_actor_id OR v_receipt.actor_client_id IS NOT NULL
     OR v_receipt.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
    RAISE invalid_parameter_value USING MESSAGE='command id was already used with different request data';
  END IF;
  IF v_receipt.status='completed' THEN
    RETURN jsonb_build_object('disposition','replay','response',v_receipt.response);
  ELSIF v_receipt.status='expired' THEN
    RETURN jsonb_build_object('disposition','replay',
      'response',public.expired_client_mutation_response_v1(v_receipt));
  END IF;
  IF v_inserted<>1 THEN RAISE serialization_failure
    USING MESSAGE='incomplete mutation receipt cannot be resumed'; END IF;
  RETURN jsonb_build_object('disposition','claimed');
END; $function$
;
REVOKE ALL ON FUNCTION public.begin_unit_client_mutation_v1(p_command_id uuid, p_command_name text, p_unit bigint, p_actor_id uuid, p_request_sha256 text) FROM PUBLIC,anon,authenticated;

-- Source: database/functions/abuse/auth_contracts.sql
-- Reusable Auth contracts. Historical budget adoption is immutable migration history.
-- Hash the former stable SHA identity with the protected key. This permits a
-- lossless migration of already consumed budgets without storing raw IP/email.
CREATE OR REPLACE FUNCTION public.consume_auth_abuse_v1(p_family text,p_key_hash text)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.require_service_role();
 IF p_family IS NULL OR p_family NOT IN ('reset.source','reset.account','google.source','google.client','google.global','google.attempt','google.proof')
  OR p_key_hash IS NULL OR p_key_hash !~ '^[0-9a-f]{64}$' THEN RETURN false; END IF;
 RETURN public.abuse_charge_v1(public.abuse_effective_rules_v1('auth.'||p_family,NULL,NULL),
  jsonb_build_object('recipient',public.abuse_recipient_key_v1(p_key_hash),'global','all'),'{}',true);
END $$;
REVOKE ALL ON FUNCTION public.consume_auth_abuse_v1(text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.consume_auth_abuse_v1(text,text) TO service_role;

-- Compatibility signatures use the same canonical counters, never client limits.
CREATE OR REPLACE FUNCTION public.consume_password_reset_rate_limit_v1(p_key_hash text,p_limit integer,p_window_seconds integer)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR p_limit IS NULL OR p_limit NOT IN (3,20) OR p_window_seconds IS DISTINCT FROM 900 THEN RETURN false; END IF;
 RETURN public.consume_auth_abuse_v1(CASE p_limit WHEN 20 THEN 'reset.source' ELSE 'reset.account' END,p_key_hash);
END $$;
REVOKE ALL ON FUNCTION public.consume_password_reset_rate_limit_v1(text,integer,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.consume_password_reset_rate_limit_v1(text,integer,integer) TO service_role;
CREATE OR REPLACE FUNCTION public.google_auth_rate_limit_v1(p_key text,p_limit integer)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.require_service_role();
 RETURN public.consume_auth_abuse_v1(CASE p_limit WHEN 20 THEN 'google.source' WHEN 30 THEN 'google.client'
  WHEN 100 THEN 'google.global' WHEN 10 THEN 'google.attempt' WHEN 5 THEN 'google.proof' END,p_key);
END $$;
REVOKE ALL ON FUNCTION public.google_auth_rate_limit_v1(text,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.google_auth_rate_limit_v1(text,integer) TO service_role;

CREATE OR REPLACE FUNCTION public.cleanup_external_login_v1()
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.require_service_role();
 DELETE FROM public.external_login_attempts WHERE expires_at<clock_timestamp();
 DELETE FROM public.existing_user_session_leases WHERE expires_at<clock_timestamp();
 PERFORM public.cleanup_abuse_usage_v1();
END $$;
REVOKE ALL ON FUNCTION public.cleanup_external_login_v1() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.cleanup_external_login_v1() TO service_role;

-- Source: database/functions/abuse/auth.sql
-- GoTrue explicitly invokes this PostgreSQL hook in its own committed transaction
-- BEFORE session issuance. This is not a database trigger. Returning reject keeps
-- consumption even when GoTrue subsequently rejects credentials or session work.
CREATE OR REPLACE FUNCTION public.password_verification_attempt_v1(event jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE actor uuid; allowed boolean;
BEGIN
 actor:=(event->>'user_id')::uuid;
 IF actor IS NULL OR jsonb_typeof(event->'valid') IS DISTINCT FROM 'boolean'
  OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=actor) THEN
  RETURN jsonb_build_object('decision','reject','message','Invalid login attempt','should_logout_user',false);
 END IF;
 allowed:=public.abuse_charge_v1(public.abuse_effective_rules_v1('auth.password',NULL,NULL),
  jsonb_build_object('actor',actor::text),'{}',true);
 RETURN jsonb_build_object('decision',CASE WHEN allowed THEN 'continue' ELSE 'reject' END,
  'message',CASE WHEN allowed THEN '' ELSE 'Too many login attempts. Try again later.' END,
  'should_logout_user',false);
END $$;
REVOKE ALL ON FUNCTION public.password_verification_attempt_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.password_verification_attempt_v1(jsonb) TO supabase_auth_admin;

-- Source: database/functions/groups/remove_occasion_user_domain.sql
-- One occasion-user teardown handler. Authorization and receipt belong to its callers.
CREATE OR REPLACE FUNCTION public.remove_occasion_user_domain_internal_v1(p_occasion bigint,p_user uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE groups bigint[]; impacts jsonb;
BEGIN
 PERFORM public.lock_activity_aggregate_internal_v1(p_occasion);
 SELECT COALESCE(array_agg(DISTINCT g.id),'{}') INTO groups FROM public.user_group_info g LEFT JOIN public.user_groups ug ON g.id=ug."group" WHERE g.occasion=p_occasion AND (ug."user"=p_user OR g.leader=p_user);
 impacts:=public.group_profile_impacts_internal_v1(p_occasion,ARRAY(SELECT "user" FROM public.user_groups WHERE "group"=ANY(groups))||ARRAY[p_user]);
 impacts:=(SELECT COALESCE(jsonb_agg(x),'[]') FROM jsonb_array_elements(impacts) x WHERE x->>'userId'<>p_user::text)||public.remove_user_activity_internal_v1(p_occasion,ARRAY[p_user]);
 UPDATE public.news SET created_by=NULL WHERE created_by=p_user AND occasion=p_occasion;
 UPDATE public.user_group_info SET leader=NULL WHERE occasion=p_occasion AND leader=p_user;
 DELETE FROM public.user_groups WHERE "user"=p_user AND "group"=ANY(groups);
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 SELECT 'user_group','occasion',p_occasion,id::text,1 FROM unnest(groups) id
 ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
 SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
 DELETE FROM public.event_users WHERE "user"=p_user AND event IN(SELECT id FROM public.events WHERE occasion=p_occasion);
 DELETE FROM public.event_users_saved WHERE "user"=p_user AND event IN(SELECT id FROM public.events WHERE occasion=p_occasion);
 DELETE FROM public.user_news WHERE "user"=p_user AND occasion=p_occasion;
 DELETE FROM public.occasion_users WHERE "user"=p_user AND occasion=p_occasion;
 DELETE FROM public.client_sync_private_scopes WHERE occasion=p_occasion AND user_id=p_user;
 DELETE FROM public.client_aggregate_versions WHERE aggregate_type='occasion_user' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_user::text;
 RETURN impacts;
END $$;
REVOKE ALL ON FUNCTION public.remove_occasion_user_domain_internal_v1(bigint,uuid) FROM PUBLIC,anon,authenticated;

-- Source: database/functions/eshop_orders/get_order_deletion_context_v1.sql
-- Public metadata only. Credentials stay in the service-role external-services RPC.
CREATE OR REPLACE FUNCTION public.get_order_deletion_context_v1(
  p_order bigint, p_command_id uuid DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = public, extensions AS $$
DECLARE
  v_occasion bigint; v_unit bigint; v_state text; v_vs bigint;
  v_command text; v_response jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager, editor or organization admin required';
  END IF;
  -- Deletion removes the order, so a lost response is recovered from its receipt.
  IF p_command_id IS NOT NULL THEN
    SELECT CASE WHEN r.status='expired' THEN public.expired_client_mutation_response_v1(r)
      ELSE r.response END INTO v_response FROM public.client_mutation_receipts r
    JOIN public.occasions oc ON oc.id=r.occasion
    WHERE r.command_id=p_command_id AND r.actor_id=auth.uid()
      AND r.command_name='inventory.order.delete' AND r.status IN ('completed','expired')
      AND r.request_sha256=encode(extensions.digest(convert_to(
        jsonb_build_object('order',p_order)::text,'UTF8'),'sha256'),'hex')
      AND (public.get_is_manager_on_unit(oc.unit) OR public.get_is_editor_on_unit(oc.unit)
        OR public.get_is_admin_on_occasion(oc.id));
    IF FOUND THEN RETURN jsonb_build_object('response',v_response); END IF;
    IF EXISTS(SELECT 1 FROM public.client_mutation_receipts WHERE command_id=p_command_id) THEN
      RAISE insufficient_privilege USING MESSAGE='command id unavailable';
    END IF;
  END IF;
  SELECT o.occasion,oc.unit,o.state,pi.variable_symbol
    INTO v_occasion,v_unit,v_state,v_vs
  FROM eshop.orders o JOIN public.occasions oc ON oc.id=o.occasion
    LEFT JOIN eshop.payment_info pi ON pi.id=o.payment_info WHERE o.id=p_order;
  IF v_occasion IS NULL OR NOT (public.get_is_manager_on_unit(v_unit)
      OR public.get_is_editor_on_unit(v_unit)
      OR public.get_is_admin_on_occasion(v_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager, editor or organization admin required';
  END IF;
  PERFORM public.check_occasion_writable(v_occasion);
  IF v_state IN ('waitlisted','preparing_payment')
    OR EXISTS(SELECT 1 FROM eshop.waitlist_offers WHERE order_id=p_order)
    OR EXISTS(SELECT 1 FROM eshop.orders WHERE source_waitlist_order_id=p_order)
    OR EXISTS(SELECT 1 FROM eshop.waitlist_acceptance_attempts
      WHERE target_order_id=p_order OR source_order_id=p_order) THEN
    RAISE EXCEPTION 'ORDER_HAS_WAITLIST_HISTORY';
  END IF;
  -- Metadata reads do not charge. External deletion attempts share the order
  -- mutation burst budget before credentials/provider work; final SQL charges
  -- its own mutation and item count through the existing command boundary.
  IF p_command_id IS NOT NULL THEN
    PERFORM public.admit_order_mutation_v1(v_occasion,0);
  END IF;
  SELECT m.data->>'command_id' INTO v_command FROM public.email_messages m
    WHERE m.order_id=p_order AND m.code='TICKET_ORDER_CONFIRMATION'
    ORDER BY m.id DESC LIMIT 1;
  RETURN jsonb_build_object('hasFakturoid',EXISTS(
    SELECT 1 FROM eshop.external_services WHERE unit=v_unit AND type='FAKTUROID'),
    'commandId',v_command,'variableSymbol',v_vs);
END; $$;
REVOKE ALL ON FUNCTION public.get_order_deletion_context_v1(bigint,uuid)
  FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.get_order_deletion_context_v1(bigint,uuid)
  TO authenticated;

-- Source: database/functions/eshop_orders/delete_order.sql
CREATE OR REPLACE FUNCTION public.delete_order_internal_v1(order_id BIGINT)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  payment_info_id BIGINT;
  order_product_ticket_ids BIGINT[];
  ticket_ids BIGINT[];
  order_oc BIGINT;
  unit_id BIGINT;
  ou_record RECORD;
  form_id BIGINT;
  related_orders BIGINT[];
  offer_ids UUID[];
  v_activity_impacts jsonb := '[]'::jsonb;
BEGIN
  -- Retrieve the order's occasion and payment_info.
  SELECT occasion, payment_info, form
    INTO order_oc, payment_info_id, form_id
    FROM eshop.orders
   WHERE id = delete_order_internal_v1.order_id;

  IF order_oc IS NULL THEN
    RAISE EXCEPTION 'Order not found.';
  END IF;

  -- Deletion belongs to scoped unit managers/editors and organization admins.
  SELECT unit
  INTO unit_id
  FROM public.occasions
  WHERE id = order_oc;

  IF auth.uid() IS NULL OR NOT (public.get_is_manager_on_unit(unit_id)
      OR public.get_is_editor_on_unit(unit_id) OR public.get_is_admin_on_occasion(order_oc)) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager, editor or organization admin required';
  END IF;
  -- The queue send gate locks global capacity before an order. Deletion must
  -- acquire that outer lock before the form/order helper to avoid inversion.
  PERFORM 1 FROM public.email_capacity FOR UPDATE;
  -- Form serialization fences offer issuance, acceptance, expiry and recovery.
  -- Lock every directly related order in ID order before changing any links.
  PERFORM 1 FROM public.forms WHERE id=form_id FOR UPDATE;
  SELECT array_agg(DISTINCT id ORDER BY id) INTO related_orders FROM (
    SELECT o.id FROM eshop.orders o WHERE o.id=delete_order_internal_v1.order_id OR o.source_waitlist_order_id=delete_order_internal_v1.order_id
      OR o.id=(SELECT source_waitlist_order_id FROM eshop.orders WHERE id=delete_order_internal_v1.order_id)
    UNION SELECT a.source_order_id FROM eshop.waitlist_acceptance_attempts a WHERE a.source_order_id=delete_order_internal_v1.order_id OR a.target_order_id=delete_order_internal_v1.order_id
    UNION SELECT a.target_order_id FROM eshop.waitlist_acceptance_attempts a WHERE a.source_order_id=delete_order_internal_v1.order_id OR a.target_order_id=delete_order_internal_v1.order_id
  ) related;
  IF EXISTS(SELECT 1 FROM eshop.orders o WHERE o.id=ANY(related_orders)
      AND (o.occasion<>order_oc OR o.form IS DISTINCT FROM form_id)) THEN
    RAISE EXCEPTION 'ORDER_WAITLIST_SCOPE_MISMATCH'; END IF;
  PERFORM public.lock_order_capacity_scope_internal(related_orders);
  IF EXISTS(SELECT 1 FROM eshop.orders WHERE id=delete_order_internal_v1.order_id AND state='preparing_payment')
    OR EXISTS(SELECT 1 FROM eshop.waitlist_acceptance_attempts a
      WHERE (a.target_order_id=delete_order_internal_v1.order_id OR a.source_order_id=delete_order_internal_v1.order_id) AND a.state='preparing') THEN
    RAISE EXCEPTION 'WAITLIST_ACCEPTANCE_IN_PROGRESS'; END IF;
  UPDATE public.forms SET capacity_revision=capacity_revision+1 WHERE id IN(SELECT form FROM eshop.orders WHERE id=delete_order_internal_v1.order_id);
  PERFORM public.lock_activity_aggregate_internal_v1(order_oc);
  IF auth.uid() IS NULL OR NOT (public.get_is_manager_on_unit(unit_id)
      OR public.get_is_editor_on_unit(unit_id) OR public.get_is_admin_on_occasion(order_oc)) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager, editor or organization admin required';
  END IF;

  -- After authorization, match the worker lock order (capacity, order,
  -- attempts, message). Recheck the order after locking against concurrent edits.
  PERFORM 1 FROM public.email_capacity FOR UPDATE;
  SELECT o.payment_info INTO payment_info_id
    FROM eshop.orders o
   WHERE o.id = delete_order_internal_v1.order_id AND o.occasion = order_oc
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found or occasion changed.';
  END IF;

  -- Remove every queued/reminder/provider record for this order. log_emails
  -- and address suppressions are independent audit/safety records and remain.
  DELETE FROM public.email_delivery_events e
   WHERE e.message_id IN (SELECT m.message_id FROM public.email_messages m
                           WHERE m.order_id = delete_order_internal_v1.order_id)
      OR e.attempt_id IN (SELECT a.attempt_id FROM public.email_attempts a
                          JOIN public.email_messages m USING (message_id)
                         WHERE m.order_id = delete_order_internal_v1.order_id)
      OR e.provider_message_id IN (
           SELECT m.provider_message_id FROM public.email_messages m
            WHERE m.order_id = delete_order_internal_v1.order_id
           UNION
           SELECT a.provider_message_id FROM public.email_attempts a
           JOIN public.email_messages m USING (message_id)
            WHERE m.order_id = delete_order_internal_v1.order_id);

  DELETE FROM public.email_confirmation_receipts r
   WHERE r.message_id IN (SELECT m.message_id FROM public.email_messages m
                          WHERE m.order_id = delete_order_internal_v1.order_id);
  DELETE FROM public.email_attempts a
   WHERE a.message_id IN (SELECT m.message_id FROM public.email_messages m
                          WHERE m.order_id = delete_order_internal_v1.order_id);
  DELETE FROM public.email_messages m
   WHERE m.order_id = delete_order_internal_v1.order_id;

  -- Collect all order_product_ticket IDs for the order.
  SELECT ARRAY(SELECT id FROM eshop.order_product_ticket WHERE "order" = delete_order_internal_v1.order_id)
    INTO order_product_ticket_ids;

  -- Collect all ticket IDs from the order_product_ticket rows.
  SELECT ARRAY(SELECT ticket
                 FROM eshop.order_product_ticket
                WHERE "order" = delete_order_internal_v1.order_id
                  AND ticket IS NOT NULL)
    INTO ticket_ids;

  IF EXISTS(SELECT 1 FROM eshop.order_product_ticket x WHERE x.ticket=ANY(ticket_ids) AND x."order"<>delete_order_internal_v1.order_id) THEN
    RAISE EXCEPTION 'TICKET_LINKED_TO_ANOTHER_ORDER'; END IF;

  -- Remove only this order's capability/offer evidence. Accepted children are
  -- independent orders: detach their source FK, never their tickets or finance.
  SELECT coalesce(array_agg(w.id),'{}') INTO offer_ids FROM eshop.waitlist_offers w WHERE w.order_id=delete_order_internal_v1.order_id;
  PERFORM 1 FROM eshop.waitlist_acceptance_attempts a
    WHERE a.source_order_id=delete_order_internal_v1.order_id OR a.target_order_id=delete_order_internal_v1.order_id ORDER BY a.command_id FOR UPDATE;
  PERFORM 1 FROM eshop.waitlist_offers w WHERE w.id=ANY(offer_ids) ORDER BY w.id FOR UPDATE;
  PERFORM 1 FROM eshop.waitlist_offer_slots x
    WHERE x.offer_id=ANY(offer_ids) OR x.ticket_id=ANY(ticket_ids) OR x.resulting_order_id=delete_order_internal_v1.order_id ORDER BY x.id FOR UPDATE;
  DELETE FROM eshop.waitlist_capabilities c WHERE c.order_id=delete_order_internal_v1.order_id OR c.offer_id=ANY(offer_ids);
  DELETE FROM eshop.waitlist_acceptance_attempts a WHERE a.source_order_id=delete_order_internal_v1.order_id OR a.target_order_id=delete_order_internal_v1.order_id;
  UPDATE eshop.waitlist_offer_slots x SET resulting_order_id=NULL,updated_at=clock_timestamp() WHERE x.resulting_order_id=delete_order_internal_v1.order_id;
  DELETE FROM eshop.waitlist_offer_slots x WHERE x.offer_id=ANY(offer_ids) OR x.ticket_id=ANY(ticket_ids);
  DELETE FROM eshop.waitlist_offers w WHERE w.id=ANY(offer_ids);
  UPDATE eshop.orders o SET source_waitlist_order_id=NULL,updated_at=clock_timestamp() WHERE o.source_waitlist_order_id=delete_order_internal_v1.order_id;

  -- Free any spots that reference these order_product_ticket rows:
  -- set order_product_ticket, secret, and secret_expiration_time to NULL.
  UPDATE eshop.spots
     SET order_product_ticket      = NULL,
         secret                  = NULL,
         secret_expiration_time  = NULL,
         updated_at              = NOW()
   WHERE order_product_ticket = ANY(order_product_ticket_ids);

  -- Delete the related order_product_ticket entries.
  DELETE FROM eshop.order_product_ticket WHERE "order" = delete_order_internal_v1.order_id;

  -- Ticket-bound membership teardown has one domain owner, independent of
  -- the retired public RPC. Authorization remains the order's manager boundary.
  IF EXISTS(SELECT 1 FROM public.occasion_users WHERE ticket=ANY(ticket_ids) AND occasion<>order_oc) THEN
    RAISE invalid_parameter_value USING MESSAGE='ticket membership belongs to another occasion';
  END IF;
  FOR ou_record IN SELECT "user",occasion FROM public.occasion_users
    WHERE ticket=ANY(ticket_ids) AND occasion=order_oc ORDER BY "user"
  LOOP
    v_activity_impacts:=v_activity_impacts || public.remove_occasion_user_domain_internal_v1(order_oc,ou_record."user");
  END LOOP;
  -- The canonical order facade already invalidates profiles for remaining members.
  -- Teardown must also invalidate affected activity projections in sorted order.
  INSERT INTO public.client_sync_private_scopes(component,occasion,user_id,source_revision)
  SELECT DISTINCT x->>'component',order_oc,(x->>'userId')::uuid,1
  FROM jsonb_array_elements(v_activity_impacts) x
  JOIN public.occasion_users ou ON ou.occasion=order_oc AND ou."user"=(x->>'userId')::uuid
  WHERE x->>'component'='private_activity' ORDER BY 1,3
  ON CONFLICT(component,occasion,user_id) DO UPDATE
    SET source_revision=public.client_sync_private_scopes.source_revision+1,updated_at=clock_timestamp();

  -- Delete the related tickets.
  -- This is now safe, as any occasion_users foreign key constraints
  -- should be resolved by the loop above.
  DELETE FROM eshop.tickets WHERE id = ANY(ticket_ids);

  -- Delete order history rows.
  DELETE FROM eshop.orders_history WHERE "order" = delete_order_internal_v1.order_id;

  -- Order-specific bank requests must not keep the order alive through their FK.
  DELETE FROM eshop.bank_account_requests WHERE "order" = delete_order_internal_v1.order_id;

  -- If a payment_info row exists, first free it from the order reference, then delete it.
  IF payment_info_id IS NOT NULL THEN
    UPDATE eshop.orders
       SET payment_info = NULL
     WHERE id = delete_order_internal_v1.order_id;

    -- Retain imported/manual bank transactions while removing their payment link.
    UPDATE eshop.transactions
       SET payment_info = NULL
     WHERE payment_info = payment_info_id;

    DELETE FROM eshop.payment_info WHERE id = payment_info_id;
  END IF;

  -- Finally, delete the order record.
  DELETE FROM eshop.orders WHERE id = delete_order_internal_v1.order_id;

END;
$$;

REVOKE ALL ON FUNCTION public.delete_order_internal_v1(bigint) FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public.delete_order_221(order_id bigint)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
  PERFORM public.delete_order_client_sync_v1(
    order_id,extensions.gen_random_uuid());
END; $$;
REVOKE ALL ON FUNCTION public.delete_order_221(bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.delete_order_221(bigint) TO authenticated;

-- Source: database/functions/eshop_orders/delete_order_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.delete_order_client_sync_v1(
  p_order bigint,p_command_id uuid
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_unit bigint;
  v_begin jsonb; v_hash text; v_removed_users uuid[]; v_remaining_users uuid[];
  v_public text[]:='{}'; v_dirty jsonb:='[]'::jsonb;
BEGIN
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'order',p_order)::text,'UTF8'),'sha256'),'hex');
  SELECT o.occasion,oc.unit INTO v_occasion,v_unit FROM eshop.orders o
    JOIN public.occasions oc ON oc.id=o.occasion WHERE o.id=p_order;
  -- Successful deletion removes the order. Exact retries retain their verified
  -- scope in the existing receipt, and still require current scoped rights.
  IF v_occasion IS NULL THEN
    SELECT r.occasion,oc.unit INTO v_occasion,v_unit FROM public.client_mutation_receipts r
    JOIN public.occasions oc ON oc.id=r.occasion
    WHERE r.command_id=p_command_id AND r.command_name='inventory.order.delete'
      AND r.actor_id=v_actor AND r.request_sha256=v_hash AND r.status IN ('completed','expired');
  END IF;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR NOT (public.get_is_manager_on_unit(v_unit) OR public.get_is_editor_on_unit(v_unit)
      OR public.get_is_admin_on_occasion(v_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager, editor or organization admin required'; END IF;
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.order.delete',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM public.admit_order_mutation_v1(v_occasion,(SELECT count(*) FROM eshop.order_product_ticket WHERE "order"=p_order));
  -- Match the email worker's outer send fence before form/order locks.
  PERFORM 1 FROM public.email_capacity FOR UPDATE;
  PERFORM 1 FROM public.forms WHERE id=(SELECT form FROM eshop.orders WHERE id=p_order) FOR UPDATE;
  SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_removed_users
  FROM eshop.order_product_ticket opt JOIN public.occasion_users ou
    ON ou.ticket=opt.ticket AND ou.occasion=v_occasion
  WHERE opt."order"=p_order;
  PERFORM public.delete_order_internal_v1(p_order);
  DELETE FROM public.client_sync_private_scopes s WHERE s.occasion=v_occasion
    AND s.user_id=ANY(v_removed_users);
  DELETE FROM public.client_aggregate_versions v
    WHERE v.aggregate_type='occasion_user' AND v.scope_type='occasion'
      AND v.scope_id=v_occasion AND v.aggregate_id=ANY(
        ARRAY(SELECT id::text FROM unnest(v_removed_users) id));
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_remaining_users
    FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  IF cardinality(v_removed_users)>0 THEN
    v_public:=ARRAY['live_public'];
    SELECT COALESCE(jsonb_agg(jsonb_build_object('component','live_public',
      'entityId',e.id)),'[]'::jsonb) INTO v_dirty
      FROM public.events e WHERE e.occasion=v_occasion;
  END IF;
  RETURN public.complete_private_profile_mutation_v1(p_command_id,v_occasion,
    'inventory.order.delete',jsonb_build_array(jsonb_build_object(
      'entityType','order','entityId',p_order,'operation','delete',
      'safeLabel','Order','changedFields',jsonb_build_array(
        'tickets','membership','allocations'))),v_remaining_users,v_public,v_dirty,
    jsonb_build_object('orderId',p_order,'removedUsers',cardinality(v_removed_users)));
END; $$;
REVOKE ALL ON FUNCTION public.delete_order_client_sync_v1(bigint,uuid)
  FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.delete_order_client_sync_v1(bigint,uuid)
  TO authenticated;

-- Source: database/functions/emails/email_domain.sql
-- Invoker-only helper. Its ACL prevents public use; public domain commands own permissions.
CREATE OR REPLACE FUNCTION public.enqueue_order_email(p_code text,p_data jsonb,p_org bigint,p_occ bigint,p_unit bigint,p_time timestamptz DEFAULT now(),p_request text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE v_order eshop.orders; v_pi eshop.payment_info; v_kind text; v_version bigint; v_key text; v_recipient text; v_existing public.email_messages; v_base_key text;
BEGIN
 IF current_user NOT IN ('postgres','service_role') THEN PERFORM public.require_service_role(); END IF;
 SELECT * INTO v_order FROM eshop.orders WHERE id=coalesce((p_data->>'order_id')::bigint,(p_data#>>'{ticket_order,order,id}')::bigint) FOR UPDATE;
 SELECT * INTO v_pi FROM eshop.payment_info WHERE id=v_order.payment_info;
 IF v_order.id IS NULL OR v_order.occasion<>p_occ THEN RAISE EXCEPTION 'invalid_order_email'; END IF;
 IF v_order.state='storno' AND p_code<>'TICKET_ORDER_STORNO' THEN
  RAISE EXCEPTION 'ORDER_CANCELLED: Cancelled orders are read-only' USING ERRCODE='55000';
 END IF;
 v_kind:=CASE p_code WHEN 'TICKET_ORDER_CONFIRMATION' THEN 'order_confirmation' WHEN 'TICKET_ORDER_PAYMENT_DONE' THEN 'order_payment_notice'
  WHEN 'TICKET_ORDER_REMINDER' THEN 'order_reminder' WHEN 'TICKET_ORDER_STORNO' THEN 'order_storno' WHEN 'TICKET_ORDER_UPDATE' THEN 'order_update'
  WHEN 'ORDER_TICKETS' THEN 'order_tickets' END;
 IF v_kind IS NULL THEN RAISE EXCEPTION 'unsupported_order_email'; END IF;
 v_version:=CASE WHEN v_kind='order_reminder' THEN v_pi.email_reminder_version ELSE v_order.email_payment_version END;
 v_recipient:=coalesce(p_data->>'recipient',v_order.data->>'email');
 v_key:=coalesce(p_request,p_data->>'command_id',v_order.id||':'||v_version||':'||coalesce(v_recipient,'')||':'||coalesce(p_data->>'is_deposit_reminder','false'));
 IF v_kind='order_storno' AND coalesce(p_request,'') NOT LIKE 'manual:%' THEN
  -- requested_by is audit metadata, never proof of an explicit resend.
  v_recipient:=v_order.data->>'email';
  p_data:=jsonb_build_object('order_id',v_order.id);
  v_key:=v_order.id||':'||v_version||':'||coalesce(v_recipient,'')||':storno';
  -- Older Edge follow-ups carried requested_by but no explicit resend ID and
  -- used the generic :false key. Reuse that committed identity rather than
  -- manufacture a second automatic message, including cancelled/expired rows.
  SELECT * INTO v_existing FROM public.email_messages
    WHERE organization=p_org AND order_id=v_order.id AND message_kind='order_storno'
      AND recipient=v_recipient AND source_version=v_version
      AND dedupe_key IN (v_key,v_order.id||':'||v_version||':'||coalesce(v_recipient,'')||':false')
    ORDER BY (dedupe_key=v_key) DESC,id LIMIT 1;
  IF v_existing.id IS NOT NULL THEN v_key:=v_existing.dedupe_key; END IF;
 END IF;
 IF v_kind='order_tickets' THEN
  SELECT * INTO v_existing FROM public.email_messages WHERE order_id=v_order.id AND message_kind=v_kind AND recipient=v_recipient AND source_version=v_version
    AND workflow_state IN ('pending','preparing','sending','retry_wait','unknown') ORDER BY id DESC LIMIT 1;
  IF v_existing.id IS NOT NULL THEN
   IF p_data->>'requested_by' IS NOT NULL THEN UPDATE public.email_messages SET post_action=post_action||jsonb_build_object('last_manual_request',jsonb_build_object('actor',p_data->>'requested_by','request',p_request,'at',now())) WHERE id=v_existing.id; END IF;
   RETURN jsonb_build_object('message_id',v_existing.message_id,'state',v_existing.workflow_state,'replayed',true);END IF;
  v_base_key:=v_order.id||':'||v_version||':'||coalesce(v_recipient,'')||':false';
  IF p_request IS NULL OR NOT EXISTS(SELECT 1 FROM public.email_messages WHERE order_id=v_order.id AND message_kind=v_kind AND recipient=v_recipient AND source_version=v_version) THEN v_key:=v_base_key;END IF;
 END IF;
 RETURN public.enqueue_email(v_kind,jsonb_build_object('organization',p_org,'occasion',p_occ,'unit',p_unit),v_recipient,p_data,v_key,
 CASE WHEN p_code='ORDER_TICKETS' THEN 'TICKET_ORDER_PAYMENT_DONE' ELSE p_code END,p_time,
 CASE WHEN v_kind='order_reminder' THEN p_time+interval '7 days' ELSE NULL END,v_order.id,v_version);
END $$;

CREATE OR REPLACE FUNCTION public.enqueue_paid_order_tickets(p_order bigint) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE v_order eshop.orders; v_occ public.occasions;
BEGIN
 IF current_user NOT IN ('postgres','service_role') THEN PERFORM public.require_service_role(); END IF;
 SELECT * INTO v_order FROM eshop.orders WHERE id=p_order FOR UPDATE;
 SELECT * INTO v_occ FROM public.occasions WHERE id=v_order.occasion;
 IF v_order.state='paid' AND v_occ.is_order_synchronization_enabled AND v_order.data ? 'email'
 AND (coalesce(v_order.price,0)<>0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_occ.features) f WHERE f->>'code'='ticket' AND (f->>'is_enabled')::boolean)) THEN
  PERFORM public.enqueue_order_email('ORDER_TICKETS',jsonb_build_object('order_id',p_order),v_occ.organization,v_occ.id,v_occ.unit);
 END IF;
END $$;

CREATE OR REPLACE FUNCTION public.cancel_order_email_intents(p_order bigint) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
BEGIN
 IF current_user NOT IN ('postgres','service_role') THEN PERFORM public.require_service_role(); END IF;
 UPDATE public.email_messages SET workflow_state='cancelled',last_error='payment_changed',lease_token=NULL,lease_until=NULL
 WHERE order_id=p_order AND message_kind IN ('order_payment_notice','order_tickets','order_reminder') AND workflow_state IN ('pending','retry_wait','blocked','preparing');
END $$;

CREATE OR REPLACE FUNCTION public.apply_email_post_actions(p_message uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE m record; v_result jsonb;
BEGIN
 PERFORM public.require_service_role();
 PERFORM 1 FROM public.email_capacity FOR UPDATE;
 FOR m IN SELECT * FROM public.email_messages WHERE workflow_state='accepted' AND post_action_state='pending'
 AND (p_message IS NULL OR message_id=p_message) ORDER BY id LIMIT 20 LOOP
  -- Domain producers lock order before message; follow that order before owning the projection.
  IF m.order_id IS NOT NULL THEN PERFORM 1 FROM eshop.orders WHERE id=m.order_id FOR UPDATE; END IF;
  SELECT * INTO m FROM public.email_messages WHERE id=m.id AND workflow_state='accepted' AND post_action_state='pending' FOR UPDATE SKIP LOCKED;
  IF NOT FOUND THEN CONTINUE; END IF;
  BEGIN
   IF m.message_kind='order_tickets' THEN
    -- Never resurrect a used/storno ticket or a reverted/cancelled order.
    UPDATE eshop.orders SET state='sent',updated_at=now() WHERE id=m.order_id AND state='paid' AND email_payment_version=m.source_version;
    IF FOUND THEN
     UPDATE eshop.tickets t SET state='sent',updated_at=now()
     FROM eshop.order_product_ticket opt WHERE opt.ticket=t.id AND opt."order"=m.order_id AND t.state='paid'
      AND t.id IN (SELECT jsonb_array_elements_text(m.post_action->'ticket_ids')::bigint);
     INSERT INTO eshop.orders_history("order",data,state,price,currency_code) SELECT id,data,state,price,currency_code FROM eshop.orders WHERE id=m.order_id;
    END IF;
   END IF;
   IF m.message_kind='app_links' AND m.recipient_user IS NOT NULL THEN PERFORM public.mark_app_links_sent(m.occasion,m.recipient_user); END IF;
   IF m.message_kind='deletion_confirm' AND m.post_action ? 'deletion_request' THEN PERFORM public.set_account_deletion_email_state((m.post_action->>'deletion_request')::uuid,true); END IF;
   IF m.post_action ? 'history_id' THEN PERFORM public.add_sent_to_customer_flag((m.post_action->>'history_id')::bigint); END IF;
   IF m.message_kind='order_reminder' THEN
    UPDATE eshop.payment_info SET data=coalesce(data,'{}')||'{"current_version_reminded":true}'::jsonb
    WHERE id=(m.post_action->>'payment_info_id')::bigint AND email_reminder_version=m.source_version;
   END IF;
   UPDATE public.email_messages SET post_action_state='done',last_error=CASE WHEN last_error='post_action_failed' THEN NULL ELSE last_error END WHERE id=m.id;
  EXCEPTION WHEN OTHERS THEN UPDATE public.email_messages SET last_error='post_action_failed' WHERE id=m.id; END;
 END LOOP;
END $$;

-- Account-domain writes and their durable intent are one DB transaction.
CREATE OR REPLACE FUNCTION public.enqueue_account_email(p_operation text,p_domain jsonb,p_context jsonb,p_recipient text,p_sealed jsonb,p_content_hash text,p_dedupe text,p_code text,p_expires timestamptz)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_context jsonb:=p_context; v_kind text; v_result jsonb; v_domain_result jsonb; v_user uuid:=(p_domain->>'user_id')::uuid; v_source jsonb:='{}'; v_message uuid;
BEGIN
 PERFORM public.require_service_role();
 PERFORM pg_advisory_xact_lock(hashtextextended('email-account:'||(p_context->>'organization')||':'||coalesce(v_user::text,p_dedupe)||':'||p_operation,0));
 -- Command replay is checked before generating/replacing the domain proof.
 SELECT message_id INTO v_message FROM public.email_messages WHERE organization=(p_context->>'organization')::bigint AND dedupe_key=p_dedupe;
 IF v_message IS NOT NULL THEN RETURN jsonb_build_object('message_id',v_message,'replayed',true,'domain',
  CASE WHEN p_operation='register' THEN (SELECT jsonb_build_object('code',200,'id',recipient_user) FROM public.email_messages WHERE message_id=v_message) ELSE NULL END); END IF;
 -- Older clients have no stable request ID. Join any unresolved proof instead of rotating it on a timeout retry.
 IF p_operation IN ('reset_token','deletion_confirm') AND v_user IS NOT NULL THEN
  SELECT message_id INTO v_message FROM public.email_messages WHERE organization=(p_context->>'organization')::bigint AND recipient_user=v_user
   AND message_kind=CASE WHEN p_operation='reset_token' THEN 'reset_password' ELSE 'deletion_confirm' END
   AND (workflow_state IN ('pending','preparing','sending','retry_wait','unknown') OR (p_operation='reset_token' AND workflow_state='accepted')) AND expires_at>now() ORDER BY id DESC LIMIT 1;
  IF v_message IS NOT NULL THEN RETURN jsonb_build_object('message_id',v_message,'replayed',true);END IF;
 END IF;
 IF p_operation='reset_token' THEN
  v_kind:='reset_password';
  IF NOT EXISTS(SELECT 1 FROM public.user_info WHERE id=v_user AND organization=(p_context->>'organization')::bigint) THEN RAISE EXCEPTION 'email_account_scope_mismatch'; END IF;
  INSERT INTO public.user_reset_token("user",token,created_at) VALUES(v_user,(p_domain->>'token')::uuid,now()) ON CONFLICT("user") DO UPDATE SET token=excluded.token,created_at=excluded.created_at;
  v_source:=jsonb_build_object('reset_hash',encode(extensions.digest(p_domain->>'token','sha256'),'hex'));
 ELSIF p_operation='register' THEN
  v_kind:='registration';
  v_domain_result:=public.create_user_from_registration((p_context->>'organization')::bigint,p_recipient,coalesce(p_domain->>'password',p_domain->>'invitation_code'),p_domain->'data',p_domain->>'unit_title');
  IF v_domain_result->>'code'<>'200' THEN RETURN jsonb_build_object('domain',v_domain_result); END IF;
  v_user:=(v_domain_result->>'id')::uuid;
  -- The delivery deadline expires the message, never the reusable password.
  v_source:=jsonb_build_object('password_version',(SELECT encode(extensions.digest(encrypted_password,'sha256'),'hex') FROM auth.users WHERE id=v_user));
 ELSIF p_operation='deletion_confirm' THEN
  v_kind:='deletion_confirm';
  v_domain_result:=public.create_account_deletion_request(v_user,(p_context->>'organization')::bigint,p_domain->>'token_hash',p_expires,p_domain->>'masked_email');
  v_source:=jsonb_build_object('deletion_request',v_domain_result->>'requestId');
 ELSIF p_operation='google_mailbox' THEN
  v_kind:='google_mailbox';
  v_domain_result:=public.google_auth_transition_v1('mailbox_send',(p_domain->>'attempt_id')::uuid,p_domain->>'secret_hash',p_domain->'payload');
  IF (v_domain_result->>'organization')::bigint IS DISTINCT FROM (p_context->>'organization')::bigint OR v_domain_result->>'email' IS DISTINCT FROM p_recipient THEN RAISE EXCEPTION 'email_account_scope_mismatch'; END IF;
  v_source:=jsonb_build_object('google_attempt',p_domain->>'attempt_id','mailbox_hash',p_domain#>>'{payload,mailboxHash}');
 ELSE RAISE EXCEPTION 'invalid_account_email_operation'; END IF;
 IF v_user IS NOT NULL THEN v_context:=v_context||jsonb_build_object('recipient_user',v_user); END IF;
 v_result:=public.enqueue_email(v_kind,v_context,p_recipient,v_source||jsonb_build_object('content_hash',p_content_hash),p_dedupe,p_code,now(),p_expires);
 UPDATE public.email_messages SET prepared=p_sealed,prepared_hash=encode(extensions.digest(p_sealed::text,'sha256'),'hex'),prepared_at=now(),post_action=v_source WHERE message_id=(v_result->>'message_id')::uuid;
 PERFORM public.admit_email_intent_v1((SELECT id FROM public.email_messages WHERE message_id=(v_result->>'message_id')::uuid),true);
 RETURN v_result||jsonb_build_object('domain',v_domain_result);
END $$;
REVOKE ALL ON FUNCTION public.enqueue_account_email(text,jsonb,jsonb,text,jsonb,text,text,text,timestamptz) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.enqueue_account_email(text,jsonb,jsonb,text,jsonb,text,text,text,timestamptz) TO service_role;

CREATE OR REPLACE FUNCTION public.reset_password_and_enqueue_email(p_user uuid,p_password text,p_occasion bigint,p_sealed jsonb,p_content_hash text,p_dedupe text,p_expires timestamptz)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_answer jsonb; v_context jsonb; v_email text; v_result jsonb; v_existing public.email_messages; v_password_version text;
BEGIN
 -- Reuse the existing hierarchical permission check, including elevated-account protections.
 IF auth.uid() IS NULL OR NOT coalesce(public.get_can_reset_user_password(p_user),false) THEN RAISE EXCEPTION 'password_reset_denied'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sign-in:'||p_user::text||':'||p_occasion::text,0));
 SELECT * INTO v_existing FROM public.email_messages WHERE recipient_user=p_user AND occasion=p_occasion AND message_kind='sign_in' AND (dedupe_key=p_dedupe OR (workflow_state IN ('pending','preparing','sending','retry_wait','unknown','accepted') AND expires_at>now())) ORDER BY id DESC LIMIT 1;
 IF v_existing.id IS NOT NULL THEN
  RETURN jsonb_build_object('message_id',v_existing.message_id,'replayed',true);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=p_occasion AND "user"=p_user) THEN RAISE EXCEPTION 'user_not_in_occasion'; END IF;
 v_answer:=public.reset_user_password(p_user,p_password);
 IF v_answer->>'code'<>'200' THEN RAISE EXCEPTION 'password_reset_denied'; END IF;
 SELECT jsonb_build_object('organization',organization,'occasion',id,'unit',unit,'recipient_user',p_user) INTO v_context FROM public.occasions WHERE id=p_occasion;
 v_email:=public.get_user_delivery_email(p_user);
 SELECT encode(extensions.digest(encrypted_password,'sha256'),'hex') INTO v_password_version FROM auth.users WHERE id=p_user;
 v_result:=public.enqueue_email('sign_in',v_context,v_email,jsonb_build_object('password_version',v_password_version,'content_hash',p_content_hash),p_dedupe,'SIGN_IN_CODE',now(),p_expires);
 UPDATE public.email_messages SET prepared=p_sealed,prepared_hash=encode(extensions.digest(p_sealed::text,'sha256'),'hex'),prepared_at=now() WHERE message_id=(v_result->>'message_id')::uuid;
 PERFORM public.admit_email_intent_v1((SELECT id FROM public.email_messages WHERE message_id=(v_result->>'message_id')::uuid),true);
 RETURN v_result;
END $$;
REVOKE ALL ON FUNCTION public.reset_password_and_enqueue_email(uuid,text,bigint,jsonb,text,text,timestamptz) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.reset_password_and_enqueue_email(uuid,text,bigint,jsonb,text,text,timestamptz) TO authenticated;

-- Compatibility name for older clients; both names own the same permanent password transition.
CREATE OR REPLACE FUNCTION public.enqueue_sign_in_code_v1(p_user uuid,p_password text,p_occasion bigint,p_sealed jsonb,p_content_hash text,p_dedupe text,p_expires timestamptz)
RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT public.reset_password_and_enqueue_email(p_user,p_password,p_occasion,p_sealed,p_content_hash,p_dedupe,p_expires);
$$;
REVOKE ALL ON FUNCTION public.enqueue_sign_in_code_v1(uuid,text,bigint,jsonb,text,text,timestamptz) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.enqueue_sign_in_code_v1(uuid,text,bigint,jsonb,text,text,timestamptz) TO authenticated;

-- Source: database/functions/eshop_orders/update_order_and_tickets_to_storno.sql
CREATE OR REPLACE FUNCTION public.cancel_order_domain_internal_v1(order_id BIGINT,p_notify boolean)
RETURNS VOID
LANGUAGE plpgsql
SET search_path = public, extensions
AS $$
DECLARE
    ticket_ids BIGINT[];
    updated_order_data jsonb;
    v_order eshop.orders;
    v_occasion public.occasions;
    v_notice jsonb;
BEGIN
    PERFORM public.lock_order_capacity_scope_internal(ARRAY[order_id]);
    SELECT * INTO v_order FROM eshop.orders WHERE id=order_id FOR UPDATE;
    IF v_order.id IS NULL THEN RAISE EXCEPTION 'Order not found'; END IF;
    IF v_order.state='storno' THEN RETURN; END IF;
    PERFORM public.check_order_is_mutable(order_id);
    PERFORM public.cancel_order_email_intents(order_id);
    -- Retrieve all ticket ids associated with the order
    SELECT ARRAY_AGG(t.id) INTO ticket_ids
    FROM eshop.tickets t
    JOIN eshop.order_product_ticket opt ON opt.ticket = t.id
    WHERE opt."order" = order_id;

    -- Check if the order exists and has associated tickets
    IF ticket_ids IS NULL THEN
        -- This is not an error, just an order with no tickets yet.
        -- But we can still storno the order itself.
        RAISE NOTICE 'No tickets found for order %, proceeding to storno order shell.', order_id;
    END IF;

    -- Call the helper to storno all tickets and their relations
    -- The helper function gracefully handles an empty/NULL array
    PERFORM internal_storno_tickets_221(ticket_ids);

    -- Set the order state to 'storno', price to 0, and update the data field
    UPDATE eshop.orders
    SET state = 'storno',
        price = 0,
        data = COALESCE(data, '{}'::jsonb) || jsonb_build_object('tickets', '[]'::jsonb),
        updated_at = NOW()
    WHERE id = order_id
    RETURNING data INTO updated_order_data;

    -- Save the change to orders_history by inserting the updated order row
    INSERT INTO eshop.orders_history (
        "order",
        state,
        price,
        data,
        created_at
    )
    VALUES (
        order_id,
        'storno',
        0,
        updated_order_data,
        NOW()
    );

    -- The full transition owns the durable automatic commitment for every caller.
    SELECT * INTO v_occasion FROM public.occasions WHERE id=v_order.occasion;
    IF p_notify AND position('@' in v_order.data->>'email')>0
      AND length(v_order.data->>'email')<=320 THEN
      v_notice:=public.enqueue_order_email('TICKET_ORDER_STORNO',
        jsonb_build_object('order_id',order_id),v_occasion.organization,
        v_occasion.id,v_occasion.unit);
    END IF;
END;
$$;
REVOKE ALL ON FUNCTION public.cancel_order_domain_internal_v1(bigint,boolean)
 FROM PUBLIC,anon,authenticated,service_role;
-- Compatibility for trusted SQL callers; domain logic exists only above.
CREATE OR REPLACE FUNCTION public.update_order_and_tickets_to_storno_221(order_id bigint)
RETURNS void LANGUAGE sql SET search_path=public,extensions AS $$
 SELECT public.cancel_order_domain_internal_v1(order_id,true);
$$;
REVOKE ALL ON FUNCTION public.update_order_and_tickets_to_storno_221(bigint)
 FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/eshop_orders/update_order_and_tickets_to_storno_ws.sql
CREATE OR REPLACE FUNCTION public.update_order_and_tickets_to_storno_ws_internal_v1(order_id bigint)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    occasion_id bigint;
BEGIN
    -- Retrieve the occasion associated with the order
    SELECT occasion INTO occasion_id FROM eshop.orders WHERE id = order_id;

    -- Check if the order exists and has an associated occasion
    IF occasion_id IS NULL THEN
        RAISE EXCEPTION 'Order not found or no associated occasion.';
    END IF;

    -- Verify if the user is an editor on the occasion
    IF (SELECT get_is_editor_order_on_occasion(occasion_id)) <> TRUE THEN
        RAISE EXCEPTION 'User is not editor.';
    END IF;

    PERFORM public.lock_order_capacity_scope_internal(ARRAY[order_id]);
    -- Use the same parent lock order as ticket cancellation.
    PERFORM 1 FROM eshop.orders WHERE id=order_id FOR UPDATE;

    -- Call the original function to update the order and tickets
    PERFORM update_order_and_tickets_to_storno_221(order_id);
END;
$$;
REVOKE ALL ON FUNCTION public.update_order_and_tickets_to_storno_ws_internal_v1(bigint) FROM PUBLIC,anon,authenticated;

-- Source: database/functions/eshop_orders/storno_tickets_bulk.sql
CREATE OR REPLACE FUNCTION public.storno_tickets_bulk_internal_v1(p_ticket_ids BIGINT[])
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_order_id BIGINT;
    v_occasion_id BIGINT;
    v_tickets_in_order BIGINT[];
    v_tickets_to_cancel_in_order BIGINT[];
    v_remaining_count INT;
    v_ticket_id_to_remove BIGINT;
    v_original_data JSONB;
    v_updated_tickets_json JSONB;
    v_ticket_elem JSONB;
    v_product_elem JSONB;
    v_removed_price NUMERIC(10, 2);
    v_current_price NUMERIC(10, 2);
BEGIN
    PERFORM public.lock_order_capacity_scope_internal(ARRAY(SELECT DISTINCT "order" FROM eshop.order_product_ticket WHERE ticket=ANY(p_ticket_ids)));
    -- 1. Identify all unique orders involved in this batch AND their occasion
    -- We need the occasion ID to perform the security check
    FOR v_order_id, v_occasion_id IN
        SELECT DISTINCT o.id, o.occasion
        FROM eshop.tickets t
        JOIN eshop.order_product_ticket opt ON t.id = opt.ticket
        JOIN eshop.orders o ON opt."order" = o.id
        WHERE t.id = ANY(p_ticket_ids)
        ORDER BY o.id
    LOOP
        -- 2. SECURITY CHECK
        -- Verify that the current user has editor permissions on the occasion associated with the order.
        IF NOT public.get_is_editor_order_on_occasion(v_occasion_id) THEN
            RAISE EXCEPTION 'Permission denied to storno tickets for order % on occasion %', v_order_id, v_occasion_id;
        END IF;

        -- Repeated selected tickets in an otherwise active order are a no-op.
        IF NOT EXISTS(SELECT 1 FROM eshop.order_product_ticket opt JOIN eshop.tickets t ON t.id=opt.ticket
          WHERE opt."order"=v_order_id AND t.id=ANY(p_ticket_ids) AND t.state IS DISTINCT FROM 'storno') THEN
          CONTINUE;
        END IF;
        PERFORM public.check_order_is_mutable(v_order_id);
        -- Serialize cancellations on the same order before counting survivors.
        PERFORM 1 FROM eshop.orders WHERE id = v_order_id FOR UPDATE;

        -- 3. Get all active tickets currently in this order
        SELECT ARRAY_AGG(t.id)
        INTO v_tickets_in_order
        FROM eshop.tickets t
        JOIN eshop.order_product_ticket opt ON t.id = opt.ticket
        WHERE opt."order" = v_order_id
        AND (t.state IS NULL OR t.state != 'storno');

        -- 4. Get intersection: Tickets in this order that we want to cancel
        SELECT ARRAY_AGG(id)
        INTO v_tickets_to_cancel_in_order
        FROM UNNEST(v_tickets_in_order) AS id
        WHERE id = ANY(p_ticket_ids);

        -- A replay or a selection containing only cancelled tickets has no effect.
        IF coalesce(cardinality(v_tickets_to_cancel_in_order), 0) = 0 THEN
            CONTINUE;
        END IF;

        -- 5. Calculate how many would remain
        v_remaining_count := array_length(v_tickets_in_order, 1) - array_length(v_tickets_to_cancel_in_order, 1);

        -- -----------------------------------------------------
        -- SCENARIO A: Full Order Cancellation
        -- -----------------------------------------------------
        IF v_remaining_count <= 0 THEN
            -- Helper function to cancel the entire order
            PERFORM update_order_and_tickets_to_storno_ws_internal_v1(v_order_id);

        -- -----------------------------------------------------
        -- SCENARIO B: Partial Cancellation (Modify Order)
        -- -----------------------------------------------------
        ELSE
            -- 1. Mark specific tickets as storno in DB
            PERFORM internal_storno_tickets_221(v_tickets_to_cancel_in_order);

            -- 2. Fetch Order Data
            SELECT data, price INTO v_original_data, v_current_price
            FROM eshop.orders WHERE id = v_order_id;

            v_updated_tickets_json := '[]'::JSONB;
            v_removed_price := 0;

            -- 3. Rebuild JSON data, filtering out cancelled tickets and summing price to remove
            FOR v_ticket_elem IN SELECT * FROM jsonb_array_elements(v_original_data->'tickets')
            LOOP
                v_ticket_id_to_remove := (v_ticket_elem->>'id')::BIGINT;

                -- If this ticket is one of the ones being cancelled
                IF v_ticket_id_to_remove = ANY(v_tickets_to_cancel_in_order) THEN
                    -- Sum up price to deduct
                    FOR v_product_elem IN SELECT * FROM jsonb_array_elements(v_ticket_elem->'products')
                    LOOP
                        v_removed_price := v_removed_price + COALESCE((v_product_elem->>'price')::NUMERIC, 0);
                    END LOOP;
                ELSE
                    -- Keep this ticket in the new JSON
                    v_updated_tickets_json := v_updated_tickets_json || v_ticket_elem;
                END IF;
            END LOOP;

            -- Fence unsent snapshots of the previous ticket set, and keep the
            -- payment amount aligned with the new order total.
            PERFORM public.cancel_order_email_intents(v_order_id);
            UPDATE eshop.payment_info SET amount=GREATEST(0, COALESCE(v_current_price,0)-v_removed_price)
            WHERE id=(SELECT payment_info FROM eshop.orders WHERE id=v_order_id);

            -- 4. Update Order (Data & Price)
            UPDATE eshop.orders
            SET
                data = v_original_data || JSONB_BUILD_OBJECT('tickets', v_updated_tickets_json),
                price = GREATEST(0, COALESCE(v_current_price, 0) - v_removed_price),
                email_payment_version = email_payment_version + 1,
                updated_at = NOW()
            WHERE id = v_order_id;

            -- Refresh only this order's existing reminder schedule for its new amount.
            PERFORM public.set_payment_deadline(pi.id,pi.deadline)
            FROM eshop.payment_info pi JOIN eshop.orders o ON o.payment_info=pi.id
            WHERE o.id=v_order_id AND o.state='ordered' AND pi.deadline IS NOT NULL;

            -- Existing delivery policy prepares the surviving tickets if their
            -- paid order has not finished sending yet; sent orders stay untouched.
            PERFORM public.enqueue_paid_order_tickets(v_order_id);

            -- 5. Insert ONE history record for this modification
            INSERT INTO eshop.orders_history (
                "order",
                data,
                state,
                price,
                created_at
            )
            VALUES (
                v_order_id,
                v_original_data || JSONB_BUILD_OBJECT('tickets', v_updated_tickets_json),
                (SELECT state FROM eshop.orders WHERE id=v_order_id),
                GREATEST(0, COALESCE(v_current_price, 0) - v_removed_price),
                NOW()
            );
        END IF;
    END LOOP;
END;
$$;

REVOKE ALL ON FUNCTION public.storno_tickets_bulk_internal_v1(bigint[]) FROM PUBLIC, anon, authenticated;

-- Source: database/functions/eshop_orders/storno_order_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.storno_order_client_sync_v1(p_order bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path = public, extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_before_users uuid[]; v_unchanged boolean:=false;
BEGIN
  SELECT o.occasion INTO v_occasion FROM eshop.orders o WHERE o.id=p_order;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'order',p_order)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.order.cancel',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  -- A committed cancellation needs only a receipt, without another admission.
  IF (SELECT state FROM eshop.orders WHERE id=p_order)='storno' THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('orderId',p_order));
  END IF;
  BEGIN
    -- Preserve admission -> domain locks, also relative to deletion. If another
    -- cancellation wins while waiting, roll back this attempt's admission.
    PERFORM public.admit_order_mutation_v1(v_occasion,(SELECT count(*) FROM eshop.order_product_ticket WHERE "order"=p_order));
    PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order]);
    IF (SELECT state FROM eshop.orders WHERE id=p_order)='storno' THEN
      RAISE SQLSTATE 'P0C01' USING MESSAGE='cancellation already committed'; END IF;
    SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
      FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
    PERFORM public.update_order_and_tickets_to_storno_ws_internal_v1(p_order);
  EXCEPTION WHEN SQLSTATE 'P0C01' THEN v_unchanged:=true;
  END;
  IF v_unchanged THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('orderId',p_order));
  END IF;
  RETURN public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,v_occasion,'inventory.order.cancel',
    jsonb_build_array(jsonb_build_object('entityType','order','entityId',p_order,
      'operation','update','safeLabel','Order cancellation',
      'changedFields',jsonb_build_array('state','tickets','membership','allocations'))),
    v_before_users,jsonb_build_object('orderId',p_order));
END; $function$;

REVOKE ALL ON FUNCTION public.storno_order_client_sync_v1(bigint,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.storno_order_client_sync_v1(bigint,uuid) TO authenticated;

-- Source: database/functions/eshop_orders/storno_tickets_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.storno_tickets_client_sync_v1(
  p_tickets bigint[],p_command_id uuid
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE v_request_tickets bigint[]:=p_tickets; v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_unchanged boolean:=false; v_before_users uuid[]; v_changed_orders bigint[]; v_cancelled jsonb; v_updated jsonb;
BEGIN
  p_tickets:=ARRAY(SELECT DISTINCT id FROM unnest(p_tickets) id ORDER BY id);
  IF cardinality(p_tickets)>(SELECT hard_cap FROM public.abuse_policy_rules WHERE rule_key='order.mutation.items') THEN RAISE SQLSTATE 'PT429' USING MESSAGE='abuse_limit_exceeded'; END IF;
  SELECT min(t.occasion) INTO v_occasion FROM eshop.tickets t
    WHERE t.id=ANY(p_tickets);
  IF v_actor IS NULL OR v_occasion IS NULL OR cardinality(p_tickets)=0
    OR (SELECT count(*) FROM eshop.tickets t
      WHERE t.id=ANY(p_tickets) AND t.occasion=v_occasion)
      <>cardinality(ARRAY(SELECT DISTINCT id FROM unnest(p_tickets) id))
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'tickets',v_request_tickets)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.tickets.cancel',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF NOT EXISTS(SELECT 1 FROM eshop.tickets WHERE id=ANY(p_tickets) AND state IS DISTINCT FROM 'storno') THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('ticketIds',to_jsonb(p_tickets),'cancelledOrderIds','[]'::jsonb,'updatedOrders','[]'::jsonb));
  END IF;
  BEGIN
  PERFORM public.admit_order_mutation_v1(v_occasion,cardinality(p_tickets));
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
    FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  PERFORM public.lock_order_capacity_scope_internal(ARRAY(SELECT DISTINCT "order" FROM eshop.order_product_ticket WHERE ticket=ANY(p_tickets)));
  -- Lock in the same order as the bulk mutation, then capture only actual changes.
  PERFORM o.id FROM eshop.orders o WHERE o.id IN (
    SELECT opt."order" FROM eshop.order_product_ticket opt
    JOIN eshop.tickets t ON t.id=opt.ticket
    WHERE t.id=ANY(p_tickets)) ORDER BY o.id FOR UPDATE;
  SELECT array_agg(DISTINCT opt."order") INTO v_changed_orders
    FROM eshop.order_product_ticket opt JOIN eshop.tickets t ON t.id=opt.ticket
    WHERE t.id=ANY(p_tickets) AND t.state IS DISTINCT FROM 'storno';
  IF coalesce(cardinality(v_changed_orders),0)=0 THEN
    RAISE SQLSTATE 'P0C01' USING MESSAGE='cancellation already committed'; END IF;
  PERFORM public.storno_tickets_bulk_internal_v1(p_tickets);
  SELECT coalesce(jsonb_agg(o.id ORDER BY o.id) FILTER(WHERE o.state='storno'),'[]'::jsonb),
    coalesce(jsonb_agg(jsonb_build_object('id',o.id,'email',o.data->>'email') ORDER BY o.id)
      FILTER(WHERE o.state IS DISTINCT FROM 'storno'),'[]'::jsonb)
    INTO v_cancelled,v_updated FROM eshop.orders o WHERE o.id=ANY(v_changed_orders);
  EXCEPTION WHEN SQLSTATE 'P0C01' THEN v_unchanged:=true;
  END;
  IF v_unchanged THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('ticketIds',to_jsonb(p_tickets),'cancelledOrderIds','[]'::jsonb,'updatedOrders','[]'::jsonb));
  END IF;
  RETURN public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,v_occasion,'inventory.tickets.cancel',
    jsonb_build_array(jsonb_build_object('entityType','ticket','entityId',NULL,
      'operation','update','safeLabel','Ticket cancellation',
      'changedFields',jsonb_build_array('state','membership','allocations'))),
    v_before_users,jsonb_build_object('ticketIds',to_jsonb(p_tickets),
      'cancelledOrderIds',v_cancelled,'updatedOrders',v_updated));
END; $$;
REVOKE ALL ON FUNCTION public.storno_tickets_client_sync_v1(bigint[],uuid)
  FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.storno_tickets_client_sync_v1(bigint[],uuid)
  TO authenticated;

-- Source: database/functions/abuse/legacy_order_facades.sql
-- The unversioned historical JSON facades previously retained an old separate
-- cancellation implementation. Keep their result shape, route through the same
-- authorized receipt-bearing domain command as the current _221 facade.
CREATE OR REPLACE FUNCTION public.update_order_and_tickets_to_storno(order_id bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.storno_order_client_sync_v1(order_id,extensions.gen_random_uuid());
 RETURN jsonb_build_object('code',200,'message','Order and all associated tickets successfully cancelled',
  'order_id',order_id,'tickets_updated',(SELECT jsonb_agg(ticket) FROM eshop.order_product_ticket WHERE "order"=order_id));
END $$;
CREATE OR REPLACE FUNCTION public.update_order_and_tickets_to_storno_ws(order_id bigint)
RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT public.update_order_and_tickets_to_storno(order_id);
$$;
REVOKE ALL ON FUNCTION public.update_order_and_tickets_to_storno(bigint),public.update_order_and_tickets_to_storno_ws(bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_order_and_tickets_to_storno(bigint),public.update_order_and_tickets_to_storno_ws(bigint) TO authenticated;
REVOKE ALL ON FUNCTION public.storno_tickets_bulk_internal_v1(bigint[]),public.update_order_and_tickets_to_storno_ws_internal_v1(bigint),public.delete_order_internal_v1(bigint) FROM service_role;

-- Source: database/functions/emails/fakturoid_email_gate.sql
-- A Fakturoid checkout is not an accepted order until its proforma exists.
-- Keep its confirmation out of the email worker until checkout finalizes it.
CREATE OR REPLACE FUNCTION public.enqueue_ticket_order_confirmation_v1(
  p_command_id uuid, p_occasion bigint, p_order_payload jsonb, p_language text
) RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = public, extensions AS $$
DECLARE
  v_organization bigint;
  v_unit bigint;
  v_order_id bigint := (p_order_payload#>>'{order,id}')::bigint;
  v_await_fakturoid boolean;
BEGIN
  SELECT o.organization, o.unit INTO v_organization, v_unit
  FROM public.occasions o WHERE o.id = p_occasion;
  IF v_organization IS NULL OR p_command_id IS NULL OR v_order_id IS NULL
     OR p_order_payload IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid ticket order effect';
  END IF;
  SELECT (coalesce((p_order_payload#>>'{order,payment_info,amount}')::numeric,0)>0)
    AND EXISTS (SELECT 1 FROM eshop.external_services es
                WHERE es.unit=v_unit AND es.type='FAKTUROID')
  INTO v_await_fakturoid;
  IF v_await_fakturoid THEN
    UPDATE eshop.orders SET state='preparing_payment', updated_at=now()
    WHERE id=v_order_id AND occasion=p_occasion AND state='ordered';
    IF NOT FOUND THEN
      RAISE check_violation USING MESSAGE='Fakturoid order is not ready for preparation';
    END IF;
  END IF;
  PERFORM public.enqueue_order_email('TICKET_ORDER_CONFIRMATION',jsonb_build_object(
    'command_id',p_command_id,'ticket_order',p_order_payload,'lang',coalesce(nullif(p_language,''),'cs'),
    'fakturoid_pending',v_await_fakturoid),v_organization,p_occasion,v_unit,
    CASE WHEN v_await_fakturoid THEN 'infinity'::timestamptz ELSE now() END);

END;
$$;
REVOKE ALL ON FUNCTION public.enqueue_ticket_order_confirmation_v1(uuid,bigint,jsonb,text)
  FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public.get_fakturoid_ticket_order_state_v1(p_order_id bigint)
RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, extensions AS $$
DECLARE v_state text;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  SELECT o.state INTO v_state FROM eshop.orders o WHERE o.id=p_order_id;
  IF v_state IS NULL THEN
    RAISE no_data_found USING MESSAGE='ticket order not found';
  END IF;
  RETURN v_state;
END;
$$;
REVOKE ALL ON FUNCTION public.get_fakturoid_ticket_order_state_v1(bigint)
  FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_fakturoid_ticket_order_state_v1(bigint)
  TO service_role;

CREATE OR REPLACE FUNCTION public.complete_fakturoid_ticket_order_v1(
  p_order_id bigint, p_command_id uuid, p_variable_symbol bigint
) RETURNS bigint LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = public, extensions AS $$
DECLARE
  v_state text;
  v_currency text;
  v_payment_id bigint;
  v_existing_vs bigint;
  v_occasion bigint;
  v_queue_id bigint;
  v_impacts jsonb;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order_id]);
  IF EXISTS(SELECT 1 FROM eshop.waitlist_acceptance_attempts WHERE target_order_id=p_order_id AND command_id=p_command_id AND state='aborted') THEN
    RAISE EXCEPTION 'Acceptance attempt aborted'; END IF;
  SELECT o.state,trim(o.currency_code),o.payment_info,o.occasion,pi.variable_symbol
  INTO v_state,v_currency,v_payment_id,v_occasion,v_existing_vs
  FROM eshop.orders o JOIN eshop.payment_info pi ON pi.id=o.payment_info
  WHERE o.id=p_order_id FOR UPDATE OF o,pi;
  IF v_state IS NULL OR p_command_id IS NULL OR p_variable_symbol NOT BETWEEN 1 AND 9999999999 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid Fakturoid completion';
  END IF;
  IF v_state IN ('ordered','paid') THEN
    RETURN v_existing_vs;
  END IF;
  IF v_state<>'preparing_payment' THEN
    RAISE check_violation USING MESSAGE='Fakturoid order is not pending';
  END IF;
  SELECT q.id INTO v_queue_id FROM public.email_messages q
  WHERE q.code='TICKET_ORDER_CONFIRMATION'
    AND q.data->>'command_id'=p_command_id::text
    AND (q.data#>>'{ticket_order,order,id}')::bigint=p_order_id
    AND q.data->>'fakturoid_pending'='true'
  FOR UPDATE;
  IF v_queue_id IS NULL THEN
    RAISE check_violation USING MESSAGE='Fakturoid order confirmation claim missing';
  END IF;
  IF v_currency NOT IN ('CZK','EUR') OR v_existing_vs IS DISTINCT FROM p_variable_symbol THEN
    RAISE check_violation USING MESSAGE='Fakturoid symbol differs from application payment reference';
  END IF;
  UPDATE eshop.waitlist_acceptance_attempts SET state='completed',updated_at=clock_timestamp()
   WHERE target_order_id=p_order_id AND command_id=p_command_id AND state='preparing';
  UPDATE eshop.orders SET state='ordered',updated_at=now() WHERE id=p_order_id;
  UPDATE public.email_messages SET target_time=now(),workflow_state='pending',
    data=jsonb_set(data-'fakturoid_pending','{ticket_order,order,payment_info,variable_symbol}',to_jsonb(p_variable_symbol))
  WHERE id=v_queue_id;
  PERFORM public.wake_email_worker();
  SELECT coalesce(jsonb_agg(jsonb_build_object('component',component,
    'userId',ou."user")),'[]'::jsonb) INTO v_impacts
  FROM public.occasion_users ou CROSS JOIN unnest(
    ARRAY['private_profile','private_inventory']) component
  WHERE ou.occasion=v_occasion;
  PERFORM public.record_client_sync_commit_v1(v_occasion,
    'fakturoid.order.complete','inventory',jsonb_build_array(jsonb_build_object(
      'entityType','order','entityId',p_order_id,'operation','update',
      'safeLabel','Order payment ready','changedFields',
      jsonb_build_array('state','payment_info'))),'{}',v_impacts,'[]',
    'service',NULL);
  RETURN p_variable_symbol;
END;
$$;
REVOKE ALL ON FUNCTION public.complete_fakturoid_ticket_order_v1(bigint,uuid,bigint)
  FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.complete_fakturoid_ticket_order_v1(bigint,uuid,bigint)
  TO service_role;

CREATE OR REPLACE FUNCTION public.abort_fakturoid_ticket_order_v1(
  p_order_id bigint, p_command_id uuid
) RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = public, extensions AS $$
DECLARE
  v_state text;
  v_occasion bigint;
  v_queue_id bigint;
  v_before_users uuid[];
  v_abort_command uuid := extensions.gen_random_uuid();
  v_hash text;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order_id]);
  IF EXISTS(SELECT 1 FROM eshop.waitlist_acceptance_attempts WHERE command_id=p_command_id AND target_order_id=p_order_id AND state='aborted') THEN RETURN; END IF;
  SELECT o.state,o.occasion INTO v_state,v_occasion
  FROM eshop.orders o WHERE o.id=p_order_id FOR UPDATE;
  IF v_state='storno' THEN RETURN; END IF;
  IF v_state IS DISTINCT FROM 'preparing_payment' OR p_command_id IS NULL THEN
    RAISE check_violation USING MESSAGE='Fakturoid order is not pending';
  END IF;
  SELECT q.id INTO v_queue_id FROM public.email_messages q
  WHERE q.code='TICKET_ORDER_CONFIRMATION'
    AND q.data->>'command_id'=p_command_id::text
    AND (q.data#>>'{ticket_order,order,id}')::bigint=p_order_id
    AND q.data->>'fakturoid_pending'='true'
  FOR UPDATE;
  IF v_queue_id IS NULL THEN
    RAISE check_violation USING MESSAGE='Fakturoid order confirmation claim missing';
  END IF;
  SELECT coalesce(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
  FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'order',p_order_id,'reason','fakturoid_failed')::text,'UTF8'),'sha256'),'hex');
  PERFORM public.begin_anonymous_client_mutation_v1(v_abort_command,
    'inventory.order.fakturoid_abort',v_occasion,extensions.gen_random_uuid(),v_hash);
  UPDATE public.email_messages SET workflow_state='cancelled',last_error='fakturoid_aborted' WHERE id=v_queue_id;
  IF NOT public.abort_waitlist_acceptance_internal(p_order_id,p_command_id) THEN
    UPDATE eshop.orders SET state='ordered' WHERE id=p_order_id;
    PERFORM public.cancel_order_domain_internal_v1(p_order_id,false);
  END IF;
  PERFORM public.complete_profile_inventory_membership_mutation_v1(
    v_abort_command,v_occasion,'inventory.order.fakturoid_abort',
    jsonb_build_array(jsonb_build_object('entityType','order',
      'entityId',p_order_id,'operation','update','safeLabel','Failed order',
      'changedFields',jsonb_build_array('state','tickets','allocations'))),
    v_before_users,jsonb_build_object('orderId',p_order_id),'service');
END;
$$;
REVOKE ALL ON FUNCTION public.abort_fakturoid_ticket_order_v1(bigint,uuid)
  FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.abort_fakturoid_ticket_order_v1(bigint,uuid)
  TO service_role;

-- Source: database/functions/others/ticket_layout.sql
-- Layout writes are accepted only through the explicit occasion-save boundary.
CREATE OR REPLACE FUNCTION public.can_edit_ticket_layout(p_occasion bigint)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public, extensions AS $$
  SELECT auth.uid() IS NOT NULL AND COALESCE((SELECT public.get_is_editor_on_unit(o.unit)
    FROM public.occasions o WHERE o.id=p_occasion),false);
$$;
REVOKE ALL ON FUNCTION public.can_edit_ticket_layout(bigint) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_edit_ticket_layout(bigint) TO authenticated;

CREATE OR REPLACE FUNCTION public.validate_ticket_layout(p_layout jsonb)
RETURNS void LANGUAGE plpgsql STABLE
SET search_path = public, extensions AS $$
DECLARE t jsonb; e jsonb; b jsonb; s jsonb; a jsonb; q jsonb; kind text; k text; ids text[]; bindings text[]; luminance double precision; background_luminance double precision;
BEGIN
  IF p_layout IS NULL OR jsonb_typeof(p_layout) <> 'object' OR p_layout->'schemaVersion' IS DISTINCT FROM '3'::jsonb OR NOT (p_layout ? 'schemaVersion')
    OR jsonb_typeof(p_layout->'templates') IS DISTINCT FROM 'object' OR p_layout->'templates'='{}'::jsonb OR octet_length(p_layout::text)>32768
  THEN RAISE EXCEPTION 'Invalid ticket layout'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_layout) AS keys(key) WHERE keys.key NOT IN ('schemaVersion','templates')) THEN RAISE EXCEPTION 'Invalid layout metadata'; END IF;
  IF (SELECT count(DISTINCT id) FROM (
    SELECT value->>'fontId' id FROM jsonb_each(p_layout->'templates')
    UNION ALL SELECT elem.value->'style'->>'fontId' FROM jsonb_each(p_layout->'templates') tmpl CROSS JOIN LATERAL jsonb_array_elements(tmpl.value->'elements') elem
  ) fonts WHERE id IS NOT NULL)>12 THEN RAISE EXCEPTION 'Too many ticket fonts'; END IF;
  FOR kind,t IN SELECT * FROM jsonb_each(p_layout->'templates') LOOP
    IF EXISTS(SELECT 1 FROM jsonb_object_keys(t) AS keys(key) WHERE keys.key NOT IN ('canvasColor','canvasOpacity','backgroundCrop','pageMargin','backgroundTransform','fontId','flow','flowStep','qrAppearance','border','pageFit','page','ticketArea','elements')) THEN RAISE EXCEPTION 'Invalid template metadata'; END IF;
    IF kind NOT IN ('wide','named') OR jsonb_typeof(t->'elements') IS DISTINCT FROM 'array'
      OR jsonb_array_length(t->'elements') NOT BETWEEN 2 AND 32
      OR (t ? 'pageFit' AND t->'pageFit' IS DISTINCT FROM '"ticket"'::jsonb)
      OR (NOT (t ? 'pageFit')
          AND t->'page' IS DISTINCT FROM '{"width":595.28,"height":841.89}'::jsonb
          AND t->'page' IS DISTINCT FROM '{"width":212.5,"height":387.5}'::jsonb)
    THEN RAISE EXCEPTION 'Invalid ticket template'; END IF;
    IF t ? 'canvasOpacity' AND (jsonb_typeof(t->'canvasOpacity') IS DISTINCT FROM 'number'
      OR (t->>'canvasOpacity')::numeric NOT BETWEEN 0 AND 1)
    THEN RAISE EXCEPTION 'Invalid ticket canvas opacity'; END IF;
    IF t ? 'canvasColor' AND (jsonb_typeof(t->'canvasColor') IS DISTINCT FROM 'string'
      OR (t->>'canvasColor' <> 'transparent' AND t->>'canvasColor' !~ '^[a-fA-F0-9]{6}$'))
    THEN RAISE EXCEPTION 'Invalid ticket canvas color'; END IF;
    IF t ? 'pageMargin' THEN
      IF t->>'pageFit' IS DISTINCT FROM 'ticket' OR jsonb_typeof(t->'pageMargin') IS DISTINCT FROM 'number'
      THEN RAISE EXCEPTION 'Invalid ticket page margin'; END IF;
      IF (t->>'pageMargin')::numeric NOT BETWEEN 0 AND 72 THEN RAISE EXCEPTION 'Invalid ticket page margin'; END IF;
    END IF;
    IF t->>'pageFit'='ticket' THEN
      IF jsonb_typeof(t->'page'->'width') IS DISTINCT FROM 'number'
        OR jsonb_typeof(t->'page'->'height') IS DISTINCT FROM 'number'
      THEN RAISE EXCEPTION 'Invalid ticket page'; END IF;
      IF (t->'page'->>'width')::numeric NOT BETWEEN 60 AND 842
        OR (t->'page'->>'height')::numeric NOT BETWEEN 60 AND 842
        OR t->'ticketArea'->'x' IS DISTINCT FROM COALESCE(t->'pageMargin','0'::jsonb)
        OR t->'ticketArea'->'y' IS DISTINCT FROM COALESCE(t->'pageMargin','0'::jsonb)
        OR abs((t->'ticketArea'->>'width')::numeric+2*COALESCE((t->>'pageMargin')::numeric,0)-(t->'page'->>'width')::numeric)>.001
        OR abs((t->'ticketArea'->>'height')::numeric+2*COALESCE((t->>'pageMargin')::numeric,0)-(t->'page'->>'height')::numeric)>.001
      THEN RAISE EXCEPTION 'Ticket page must match ticket area'; END IF;
    END IF;
    IF t ? 'font' AND COALESCE(t->>'font','') NOT IN ('futura','robotoSlab','roboto','russoOne') THEN RAISE EXCEPTION 'Invalid ticket font'; END IF;
    IF t ? 'border' AND jsonb_typeof(t->'border') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Invalid ticket border'; END IF;
    IF t ? 'flowStep' AND (jsonb_typeof(t->'flowStep') IS DISTINCT FROM 'number' OR (t->>'flowStep')::numeric NOT BETWEEN 1 AND 842) THEN RAISE EXCEPTION 'Invalid ticket flow spacing'; END IF;
    IF t ? 'flow' THEN
      IF jsonb_typeof(t->'flow') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid ticket flow'; END IF;
      IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(t->'flow') AS flow_item(value) WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(t->'elements') AS flow_element(value) WHERE flow_element.value->>'id'=flow_item.value AND flow_element.value->>'binding' NOT IN ('qr','logo')))
        OR (SELECT count(*)<>count(DISTINCT flow_item.value) FROM jsonb_array_elements_text(t->'flow') AS flow_item(value))
      THEN RAISE EXCEPTION 'Invalid ticket flow'; END IF;
    END IF;
    IF t ? 'qrAppearance' THEN
      IF jsonb_typeof(t->'qrAppearance') IS DISTINCT FROM 'object'
        OR COALESCE(t->'qrAppearance'->>'background','') !~ '^[a-fA-F0-9]{6}$'
        OR jsonb_typeof(t->'qrAppearance'->'opacity') IS DISTINCT FROM 'number'
        OR jsonb_typeof(t->'qrAppearance'->'margin') IS DISTINCT FROM 'number'
      THEN RAISE EXCEPTION 'Invalid QR appearance'; END IF;
      IF (t->'qrAppearance'->>'opacity')::numeric NOT BETWEEN 0 AND 1 OR (t->'qrAppearance'->>'margin')::numeric NOT BETWEEN 0 AND 8 THEN RAISE EXCEPTION 'Invalid QR appearance'; END IF;
    END IF;
    IF t ? 'font' THEN RAISE EXCEPTION 'Legacy font field in schema 2'; END IF;
    IF t ? 'fontId' THEN
      IF jsonb_typeof(t->'fontId')<>'string'
        OR NOT EXISTS(SELECT 1 FROM public.ticket_font_assets WHERE id=t->>'fontId')
      THEN RAISE EXCEPTION 'Invalid ticket font'; END IF;
    END IF;
    IF t ? 'backgroundCrop' THEN
      b:=t->'backgroundCrop';
      IF jsonb_typeof(b) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Invalid background crop'; END IF;
      FOREACH k IN ARRAY ARRAY['x','y','width','height'] LOOP
        IF jsonb_typeof(b->k) IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'Invalid background crop'; END IF;
      END LOOP;
      IF (b->>'x')::numeric<0 OR (b->>'y')::numeric<0
        OR (b->>'width')::numeric<.001 OR (b->>'height')::numeric<.001
        OR (b->>'x')::numeric+(b->>'width')::numeric>1.000001
        OR (b->>'y')::numeric+(b->>'height')::numeric>1.000001
      THEN RAISE EXCEPTION 'Invalid background crop'; END IF;
    END IF;
    IF t ? 'backgroundTransform' THEN
      b:=t->'backgroundTransform';
      IF jsonb_typeof(b) IS DISTINCT FROM 'object'
        OR jsonb_typeof(b->'scale') IS DISTINCT FROM 'number'
        OR jsonb_typeof(b->'x') IS DISTINCT FROM 'number'
        OR jsonb_typeof(b->'y') IS DISTINCT FROM 'number'
      THEN RAISE EXCEPTION 'Invalid background transform'; END IF;
      IF (b->>'scale')::numeric NOT BETWEEN .1 AND 10
        OR abs((b->>'x')::numeric)>10 OR abs((b->>'y')::numeric)>10
      THEN RAISE EXCEPTION 'Invalid background transform'; END IF;
    END IF;
    a:=t->'ticketArea'; ids:='{}'; bindings:='{}';
    FOR b IN SELECT a UNION ALL SELECT value->'box' FROM jsonb_array_elements(t->'elements') LOOP
      FOR k IN SELECT unnest(ARRAY['x','y','width','height']) LOOP
        IF jsonb_typeof(b->k) IS DISTINCT FROM 'number' OR (b->>k)::numeric<0 OR (b->>k)::numeric>842
        THEN RAISE EXCEPTION 'Invalid layout box'; END IF;
      END LOOP;
      IF (b->>'width')::numeric<1 OR (b->>'height')::numeric<1 THEN RAISE EXCEPTION 'Empty layout box'; END IF;
    END LOOP;
    IF (a->>'x')::numeric+(a->>'width')::numeric>(t->'page'->>'width')::numeric+.001
      OR (a->>'y')::numeric+(a->>'height')::numeric>(t->'page'->>'height')::numeric+.001
    THEN RAISE EXCEPTION 'Ticket outside page'; END IF;
    FOR e IN SELECT * FROM jsonb_array_elements(t->'elements') LOOP
      b:=e->'box'; s:=e->'style';
      IF s ? 'fontId' THEN
        IF e->>'binding' IN ('qr','logo') OR jsonb_typeof(s->'fontId')<>'string'
          OR NOT EXISTS(SELECT 1 FROM public.ticket_font_assets WHERE id=s->>'fontId')
        THEN RAISE EXCEPTION 'Invalid ticket font'; END IF;
      END IF;
      IF e->>'binding' IS NULL OR e->>'binding' NOT IN ('qr','ticketSymbol','spotGroup','productType','note','price','occasionTitle','occasionDatePlace','occasionStartTime','occasionPlace','orderName','logo','footer','text')
        OR (e->>'binding' NOT IN ('productType','text') AND e->>'binding'=ANY(bindings)) OR e->>'id'=ANY(ids) OR COALESCE(e->>'id','') !~ '^[a-zA-Z0-9_-]{1,40}$'
        OR jsonb_typeof(e->'visible') IS DISTINCT FROM 'boolean' OR jsonb_typeof(e->'locked') IS DISTINCT FROM 'boolean'
        OR (b->>'x')::numeric+(b->>'width')::numeric>(a->>'width')::numeric+.001
        OR (b->>'y')::numeric+(b->>'height')::numeric>(a->>'height')::numeric+.001
      THEN RAISE EXCEPTION 'Invalid layout element'; END IF;
      IF EXISTS(SELECT 1 FROM jsonb_object_keys(e) AS keys(key) WHERE keys.key NOT IN ('id','binding','productTypeId','label','text','box','visible','locked','style')) THEN RAISE EXCEPTION 'Invalid element metadata'; END IF;
      IF e->>'binding'='productType' THEN
        IF jsonb_typeof(e->'productTypeId') IS DISTINCT FROM 'number' OR jsonb_typeof(e->'label') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'Invalid product field'; END IF;
        IF (e->>'productTypeId')::numeric NOT BETWEEN 1 AND 9007199254740991 OR trunc((e->>'productTypeId')::numeric)<>(e->>'productTypeId')::numeric
          OR e->>'label'<>btrim(e->>'label',U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF') OR length(e->>'label')>120
          OR (SELECT count(*) FROM jsonb_array_elements(t->'elements') x WHERE x->'productTypeId'=e->'productTypeId')<>1
        THEN RAISE EXCEPTION 'Invalid product field'; END IF;
      ELSIF e ? 'productTypeId' OR e ? 'label' THEN RAISE EXCEPTION 'Invalid product metadata'; END IF;
      IF e->>'binding'='text' THEN
        IF jsonb_typeof(e->'text') IS DISTINCT FROM 'string' OR length(e->>'text')>2000 THEN RAISE EXCEPTION 'Invalid free text'; END IF;
      ELSIF e ? 'text' THEN RAISE EXCEPTION 'Unexpected free text'; END IF;
      ids:=array_append(ids,e->>'id'); bindings:=array_append(bindings,e->>'binding');
      IF jsonb_typeof(s->'fontSize') IS DISTINCT FROM 'number' OR jsonb_typeof(s->'minFontSize') IS DISTINCT FROM 'number'
        OR jsonb_typeof(s->'maxLines') IS DISTINCT FROM 'number' OR COALESCE(s->>'color','') !~ '^[a-fA-F0-9]{6}$'
        OR COALESCE(s->>'align','') NOT IN ('left','center','right')
        OR (s ? 'bold' AND jsonb_typeof(s->'bold') IS DISTINCT FROM 'boolean')
        OR (s ? 'italic' AND jsonb_typeof(s->'italic') IS DISTINCT FROM 'boolean')
        OR (s ? 'underline' AND jsonb_typeof(s->'underline') IS DISTINCT FROM 'boolean')
      THEN RAISE EXCEPTION 'Invalid layout style'; END IF;
      IF (s->>'fontSize')::numeric NOT BETWEEN 6 AND 72 OR (s->>'minFontSize')::numeric NOT BETWEEN 6 AND (s->>'fontSize')::numeric
        OR (s->>'maxLines')::numeric NOT BETWEEN 1 AND 12 OR (s->>'maxLines')::numeric<>trunc((s->>'maxLines')::numeric)
      THEN RAISE EXCEPTION 'Invalid text size'; END IF;
      IF e->>'binding' IN ('qr','ticketSymbol') AND e->'visible'<>'true'::jsonb THEN RAISE EXCEPTION 'Required ticket element hidden'; END IF;
      IF e->>'binding'='qr' THEN
        q:=b;
        SELECT sum((CASE WHEN channel<=.04045 THEN channel/12.92 ELSE power((channel+.055)/1.055,2.4) END)*weight)
          INTO luminance FROM (SELECT get_byte(decode(s->>'color','hex'),i)/255.0 AS channel, weight
            FROM (VALUES (0,.2126),(1,.7152),(2,.0722)) AS rgb(i,weight)) AS linear;
        SELECT sum((CASE WHEN channel<=.04045 THEN channel/12.92 ELSE power((channel+.055)/1.055,2.4) END)*weight)
          INTO background_luminance FROM (SELECT get_byte(decode(COALESCE(t->'qrAppearance'->>'background','FFFFFF'),'hex'),i)/255.0 AS channel, weight
            FROM (VALUES (0,.2126),(1,.7152),(2,.0722)) AS rgb(i,weight)) AS linear;
        IF b->'width'<>b->'height' OR (b->>'width')::numeric<60 OR (greatest(luminance,background_luminance)+.05)/(least(luminance,background_luminance)+.05)<4.5 THEN RAISE EXCEPTION 'Invalid QR dimensions or contrast'; END IF;
      END IF;
    END LOOP;
    IF NOT bindings @> ARRAY['qr','ticketSymbol'] THEN RAISE EXCEPTION 'Missing required ticket elements'; END IF;
    FOR e IN SELECT * FROM jsonb_array_elements(t->'elements') LOOP
      b:=e->'box';
      IF e->'visible'='true'::jsonb AND e->>'binding' NOT IN ('qr','logo')
        AND (b->>'x')::numeric<(q->>'x')::numeric+(q->>'width')::numeric
        AND (b->>'x')::numeric+(b->>'width')::numeric>(q->>'x')::numeric
        AND (b->>'y')::numeric<(q->>'y')::numeric+(q->>'height')::numeric
        AND (b->>'y')::numeric+(b->>'height')::numeric>(q->>'y')::numeric
      THEN RAISE EXCEPTION 'Text overlaps QR quiet zone'; END IF;
    END LOOP;
  END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION public.merge_ticket_layout_features(p_old jsonb,p_next jsonb,p_change jsonb DEFAULT NULL,p_create boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql STABLE
SET search_path = public, extensions AS $$
DECLARE old_layout jsonb; next_layout jsonb; f jsonb; result jsonb:='[]'; found_ticket boolean:=false;
BEGIN
  IF jsonb_typeof(p_next) IS DISTINCT FROM 'array' OR (SELECT count(*) FROM jsonb_array_elements(p_next) e WHERE e->>'code'='ticket')>1
  THEN RAISE EXCEPTION 'Invalid features'; END IF;
  SELECT value->'layout' INTO old_layout FROM jsonb_array_elements(COALESCE(p_old,'[]')) WHERE value->>'code'='ticket';
  next_layout:=old_layout;
  IF p_change IS NOT NULL THEN
    IF jsonb_typeof(p_change)<>'object' OR NOT (p_change ? 'expected' AND p_change ? 'next')
      OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_change) k WHERE k NOT IN ('expected','next','appearance')) THEN RAISE EXCEPTION 'Invalid ticket layout change'; END IF;
    IF COALESCE(old_layout,'null') IS DISTINCT FROM p_change->'expected' THEN
      RAISE EXCEPTION 'ticket_layout_conflict' USING ERRCODE='40001';
    END IF;
    -- A client must not downgrade a schema it does not understand.
    IF old_layout IS NOT NULL AND old_layout->'schemaVersion' IS DISTINCT FROM '3'::jsonb THEN RAISE EXCEPTION 'Unsupported ticket layout'; END IF;
    next_layout:=p_change->'next';
    IF next_layout IS NULL OR next_layout='null'::jsonb THEN RAISE EXCEPTION 'Ticket layout reset rejected'; END IF;
    PERFORM public.validate_ticket_layout(next_layout);
  END IF;
  FOR f IN SELECT * FROM jsonb_array_elements(p_next) LOOP
    IF f->>'code'='ticket' THEN
      found_ticket:=true;
      IF p_create AND p_change IS NULL THEN next_layout:=f->'layout'; IF next_layout IS NOT NULL THEN PERFORM public.validate_ticket_layout(next_layout); END IF; END IF;
      f:=f-'layout'; IF next_layout IS NOT NULL THEN f:=f||jsonb_build_object('layout',next_layout); END IF;
    END IF;
    result:=result||jsonb_build_array(f);
  END LOOP;
  IF NOT found_ticket AND next_layout IS NOT NULL THEN result:=result||jsonb_build_array(jsonb_build_object('code','ticket','is_enabled',false,'layout',next_layout)); END IF;
  RETURN result;
END;
$$;

CREATE OR REPLACE FUNCTION public.validate_ticket_layout_references(p_occasion bigint,p_layout jsonb)
RETURNS void LANGUAGE plpgsql STABLE SET search_path = public, extensions AS $$
BEGIN
  PERFORM public.validate_ticket_layout(p_layout);
  IF EXISTS(SELECT 1 FROM jsonb_each(p_layout->'templates') t CROSS JOIN LATERAL jsonb_array_elements(t.value->'elements') e
    WHERE e->>'binding'='productType' AND NOT EXISTS(SELECT 1 FROM eshop.product_types pt WHERE pt.id=(e->>'productTypeId')::bigint AND pt.occasion=p_occasion))
  THEN RAISE EXCEPTION 'ticket_product_type_missing'; END IF;
END; $$;
REVOKE ALL ON FUNCTION public.validate_ticket_layout_references(bigint,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.validate_ticket_layout_references(bigint,jsonb) TO service_role;

CREATE OR REPLACE FUNCTION public.ticket_layout_uses_product_type(p_occasion bigint,p_type bigint)
RETURNS boolean LANGUAGE sql STABLE SET search_path = public, extensions AS $$
 SELECT EXISTS(SELECT 1 FROM public.occasions o CROSS JOIN LATERAL jsonb_array_elements(o.features) f
 CROSS JOIN LATERAL jsonb_each(COALESCE(f->'layout'->'templates','{}')) t
 CROSS JOIN LATERAL jsonb_array_elements(t.value->'elements') e
 WHERE o.id=p_occasion AND f->>'code'='ticket' AND e->>'binding'='productType' AND (e->>'productTypeId')::bigint=p_type);
$$;
REVOKE ALL ON FUNCTION public.ticket_layout_uses_product_type(bigint,bigint) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ticket_layout_uses_product_type(bigint,bigint) TO service_role;

-- Only appearance fields may be copied from the ticket editor. Owned image metadata
-- is the authority for new backgrounds; no network resource is fetched by SQL.
CREATE OR REPLACE FUNCTION public.merge_ticket_appearance_internal_v1(p_occasion bigint,p_features jsonb,p_appearance jsonb)
RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=public,extensions AS $$
DECLARE result jsonb:='[]'; feature jsonb; background text; old_background text;
BEGIN
 IF p_appearance IS NULL THEN RETURN p_features; END IF;
 IF jsonb_typeof(p_appearance) IS DISTINCT FROM 'object'
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_appearance) k WHERE k NOT IN ('background','ticket_type'))
  OR (p_appearance ? 'ticket_type' AND p_appearance->>'ticket_type' IS NOT NULL
    AND p_appearance->>'ticket_type' NOT IN ('wide','named')) THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid ticket appearance'; END IF;
 SELECT f->>'background' INTO old_background FROM jsonb_array_elements(p_features) f WHERE f->>'code'='ticket';
 background:=p_appearance->>'background';
 IF background IS NOT NULL AND background IS DISTINCT FROM old_background AND NOT EXISTS(
  SELECT 1 FROM public.images i JOIN public.occasions o ON o.id=p_occasion
  WHERE i.link=background AND (i.occasion=o.id OR i.unit=o.unit)) THEN
  RAISE insufficient_privilege USING MESSAGE='ticket background must belong to this occasion or unit'; END IF;
 FOR feature IN SELECT value FROM jsonb_array_elements(p_features) LOOP
  IF feature->>'code'='ticket' THEN feature:=feature||p_appearance; END IF;
  result:=result||jsonb_build_array(feature);
 END LOOP;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.merge_ticket_appearance_internal_v1(bigint,jsonb,jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/others/update_occasion.sql
CREATE OR REPLACE FUNCTION public.update_occasion_internal_v1(input_data JSONB)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
SET search_path = public, extensions
 AS $$
 DECLARE
     updated_occ public.occasions;
     occ_id BIGINT;
     now TIMESTAMPTZ := NOW();
     final_unit BIGINT;

     -- Variable for the determined support flag
     is_app_supported BOOLEAN;

     -- Variable to help find the organization to check settings
     v_org_id BIGINT;

     -- Variables for feature handling
     new_blueprint_id BIGINT;
     v_form_id BIGINT;
     v_form_blueprint BIGINT;
     v_form_settings JSONB;
     v_form_link TEXT;
     v_reminder_interval_seconds BIGINT;
     v_email_order record;

     input_features JSONB;
     old_features JSONB;
     processed_features JSONB;
     feature JSONB;
     form_feature_found BOOLEAN;
 BEGIN
     -- Validate input data. Raise an exception if it's missing or empty.
     IF input_data IS NULL OR input_data = '{}'::jsonb THEN
         RAISE EXCEPTION 'Input data is missing or empty';
     END IF;

     -- 1. Identify the Organization ID
     IF (input_data->>'id') IS NOT NULL THEN
         -- Case A: UPDATE - Get organization from the existing occasion
         SELECT organization INTO v_org_id
         FROM public.occasions
         WHERE id = (input_data->>'id')::BIGINT;
     ELSE
         -- Case B: INSERT - Try to get organization from input
         v_org_id := (input_data->>'organization')::BIGINT;

         -- Case C: INSERT fallback - If org is missing, try to get it via the Unit
         IF v_org_id IS NULL AND (input_data->>'unit') IS NOT NULL THEN
            SELECT organization INTO v_org_id
            FROM public.units
            WHERE id = (input_data->>'unit')::BIGINT;
         END IF;
     END IF;

     -- 2. Fetch the setting from public.organizations.data
     -- Defaults to TRUE if the organization or the key is not found to ensure backward compatibility
     IF v_org_id IS NOT NULL THEN
         SELECT COALESCE((data->>'IS_APP_SUPPORTED')::BOOLEAN, false)
         INTO is_app_supported
         FROM public.organizations
         WHERE id = v_org_id;
     ELSE
         is_app_supported := false;
     END IF;

     -- Ensure is_app_supported is not null (redundant safety check)
     is_app_supported := COALESCE(is_app_supported, false);

     --
     -- Prepare features based on is_app_supported flag
     --
     input_features := COALESCE(input_data->'features', '[]'::jsonb);
     processed_features := '[]'::jsonb;

     IF NOT is_app_supported THEN
         -- If the app is not supported, we must enable the 'form' feature.
         form_feature_found := false;
         -- Loop through existing features to find and enable the form feature
         FOR feature IN SELECT * FROM jsonb_array_elements(input_features)
         LOOP
             IF feature->>'code' = 'form' THEN
                 -- If form feature exists, ensure it is enabled
                 feature := feature || '{"is_enabled": true}';
                 form_feature_found := true;
             END IF;
             processed_features := processed_features || feature;
         END LOOP;

         -- If the form feature was not found in the original array, add it.
         IF NOT form_feature_found THEN
             processed_features := processed_features || '{"code": "form", "is_enabled": true}';
         END IF;
     ELSE
         -- If app is supported, use features as they were provided.
         processed_features := input_features;
     END IF;

     -- Determine if this is an UPDATE or INSERT based on the presence of an 'id'
     occ_id := (input_data->>'id')::BIGINT;

     IF occ_id IS NOT NULL THEN
         PERFORM public.check_occasion_writable(occ_id);
         -- This is an UPDATE operation

         -- Check for the existence of the occasion and get its current unit
         SELECT unit, features INTO final_unit, old_features FROM public.occasions WHERE id = occ_id FOR UPDATE;
         IF NOT FOUND THEN
             RAISE EXCEPTION 'Occasion with ID % not found', occ_id;
         END IF;

         IF NOT public.get_is_editor_on_unit(final_unit) THEN
             RAISE insufficient_privilege USING MESSAGE = 'unit editor required';
         END IF;
         processed_features := public.merge_ticket_layout_features(old_features, processed_features, input_data->'ticket_layout_change');
         PERFORM public.validate_ticket_layout_references(occ_id, f->'layout') FROM jsonb_array_elements(processed_features) f WHERE f->>'code'='ticket' AND f ? 'layout';

         -- Determine the final unit, allowing it to be updated.
         final_unit := COALESCE((input_data->>'unit')::BIGINT, final_unit);

         -- Security check: ensure the current user has editor rights on the target unit.
         IF NOT public.get_is_editor_on_unit(final_unit) THEN
             RAISE insufficient_privilege USING MESSAGE = 'unit editor required';
         END IF;

         IF (input_data ? 'organization' AND (input_data->>'organization')::bigint IS DISTINCT FROM v_org_id)
           OR NOT EXISTS(SELECT 1 FROM public.units WHERE id=final_unit AND organization=v_org_id) THEN
           RAISE insufficient_privilege USING MESSAGE='Occasion tenant cannot change'; END IF;

         UPDATE public.occasions
            SET updated_at  = now,
                title       = COALESCE(input_data->>'title', title),
                description = COALESCE(input_data->>'description', description),
                link        = public.reserve_public_link_internal('occasion',occ_id,input_data->>'link',false),
                data        = COALESCE(input_data->'data', data),
                is_hidden   = COALESCE((input_data->>'is_hidden')::BOOLEAN, is_hidden),
                is_open     = COALESCE((input_data->>'is_open')::BOOLEAN, is_open),
                is_promoted = COALESCE((input_data->>'is_promoted')::BOOLEAN, is_promoted),
                start_time  = COALESCE((input_data->>'start_time')::TIMESTAMPTZ, start_time),
                end_time    = COALESCE((input_data->>'end_time')::TIMESTAMPTZ, end_time),
                organization = COALESCE((input_data->>'organization')::BIGINT, organization),
                services    = COALESCE(input_data->'services', services),
                unit        = final_unit,
                is_order_synchronization_enabled=COALESCE((input_data->>'is_order_synchronization_enabled')::boolean,is_order_synchronization_enabled),
                features    = processed_features -- Use the processed features
          WHERE id = occ_id
          RETURNING * INTO updated_occ;

     ELSE
         -- This is an INSERT operation

         -- For new occasions, the 'unit' field is mandatory.
         final_unit := (input_data->>'unit')::BIGINT;
         IF final_unit IS NULL THEN
             RAISE EXCEPTION 'The "unit" field is required for new occasions';
         END IF;

         -- Security check for the new occasion's unit.
         IF NOT public.get_is_editor_on_unit(final_unit) THEN
             RAISE insufficient_privilege USING MESSAGE = 'unit editor required';
         END IF;

         -- We still need to default 'reminder_is_enabled' for the 'form' feature if not specified.
         -- We do this on the already processed_features array.
         input_features := processed_features; -- Use the result from the is_app_supported logic
         processed_features := '[]'::jsonb;
         FOR feature IN SELECT * FROM jsonb_array_elements(input_features)
         LOOP
             -- If the current feature is the 'form' feature
             IF feature->>'code' = 'form' THEN
                 -- And if 'reminder_is_enabled' is NOT specified, default it to true.
                 IF NOT (feature ? 'reminder_is_enabled') THEN
                     feature := feature || '{"reminder_is_enabled": true}';
                 END IF;
             END IF;
             processed_features := processed_features || feature::jsonb;
         END LOOP;

         processed_features := public.merge_ticket_layout_features('[]', processed_features, input_data->'ticket_layout_change', true);

         INSERT INTO public.occasions(
             created_at, updated_at, title, description, link, data,
             is_hidden, is_open, is_promoted, start_time, end_time, organization,
             services, unit, features
         )
         VALUES(
             now, now,
             COALESCE(input_data->>'title', ''),
             COALESCE(input_data->>'description', ''),
             '',
             COALESCE(input_data->'data', '{}'::jsonb),
             COALESCE((input_data->>'is_hidden')::BOOLEAN, false),
             COALESCE((input_data->>'is_open')::BOOLEAN, true),
             COALESCE((input_data->>'is_promoted')::BOOLEAN, false),
             (input_data->>'start_time')::TIMESTAMPTZ,
             (input_data->>'end_time')::TIMESTAMPTZ,
             (input_data->>'organization')::BIGINT,
             COALESCE(input_data->'services', '{}'::jsonb),
             final_unit,
             processed_features
         )
         RETURNING * INTO updated_occ;

         -- Set the occ_id from the newly created record for subsequent logic
         occ_id := updated_occ.id;
         UPDATE public.occasions SET link=public.reserve_public_link_internal('occasion',occ_id,input_data->>'link',true) WHERE id=occ_id RETURNING * INTO updated_occ;
     END IF;

     -- Enabling the blueprint feature must not bypass form capacity/waitlist guards,
     -- including when the stored blueprint already exists.
     IF jsonb_path_exists(updated_occ.features, '$[*] ? (@.code == "blueprint" && @.is_enabled == true)') THEN
       FOR v_form_id IN SELECT id FROM public.forms WHERE occasion=occ_id ORDER BY id LOOP
         PERFORM public.check_form_capacity_settings_internal(v_form_id, '{"blueprint":1}'::jsonb);
       END LOOP;
     END IF;

     PERFORM public.validate_ticket_layout_references(occ_id, f->'layout') FROM jsonb_array_elements(processed_features) f WHERE f->>'code'='ticket' AND f ? 'layout';
     --
     -- Post-update/insert feature handling
     --

     -- Check if form feature is enabled and handle related logic.
     -- This will now be triggered if is_app_supported was false (based on organization settings).
     IF jsonb_path_exists(updated_occ.features, '$[*] ? (@.code == "form" && @.is_enabled == true)') THEN
         -- Extract the settings for the 'form' feature from the newly saved data
         SELECT elem INTO v_form_settings
         FROM jsonb_array_elements(updated_occ.features) AS elem
         WHERE elem->>'code' = 'form';

         -- Create a default form if one doesn't exist for the occasion
         IF NOT EXISTS (SELECT 1 FROM public.forms WHERE occasion = occ_id) THEN
             v_form_link := NULLIF(btrim(input_data->>'form_link'), '');
             PERFORM create_form(occ_id, v_form_link, 'Registration');
         END IF;

         -- Check if reminders are enabled within the form feature
         IF (v_form_settings->>'reminder_is_enabled')::boolean IS TRUE THEN
             -- Get the reminder interval, defaulting to 1 day (86400 seconds) if not specified
             v_reminder_interval_seconds := COALESCE(
                 (v_form_settings->>'reminder_interval_seconds')::bigint,
                 86400
             );
             -- Call the function to queue payment reminders for all relevant orders

         END IF;
     END IF;

     -- Revalidate in-flight reminders after every relevant occasion update.
     PERFORM public.queue_payment_reminders(occ_id,coalesce(v_reminder_interval_seconds,86400));
     IF updated_occ.is_order_synchronization_enabled THEN
       FOR v_email_order IN SELECT id FROM eshop.orders WHERE occasion=occ_id AND state='paid' LOOP
         PERFORM public.enqueue_paid_order_tickets(v_email_order.id);
       END LOOP;
     END IF;
     -- Check if the blueprint feature is enabled in the final, saved state
     IF jsonb_path_exists(updated_occ.features, '$[*] ? (@.code == "blueprint" && @.is_enabled == true)') THEN
         -- Find the associated form to attach the blueprint to
         SELECT id, blueprint INTO v_form_id, v_form_blueprint
           FROM public.forms
          WHERE occasion = occ_id
          LIMIT 1;

         -- If a form exists and it doesn't already have a blueprint, create one.
         IF FOUND AND v_form_blueprint IS NULL THEN
             INSERT INTO eshop.blueprints(configuration, occasion, organization, created_at, updated_at)
             VALUES ('{"dimensions": {"width": 28, "height": 52}}'::jsonb, occ_id, COALESCE(updated_occ.organization, 1), now, now)
             RETURNING id INTO new_blueprint_id;

             UPDATE public.forms
                SET blueprint = new_blueprint_id,
                    updated_at = now
              WHERE id = v_form_id;
             INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
             VALUES('form','occasion',occ_id,v_form_id::text,1)
             ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
             SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
         END IF;
     END IF;
 END;
 $$;

CREATE OR REPLACE FUNCTION public.update_occasion_203(input_data jsonb)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE v_occasion bigint; v_version bigint;
BEGIN
  v_occasion:=NULLIF(input_data->>'id','')::bigint;
  IF v_occasion IS NULL THEN
    PERFORM public.create_occasion_client_sync_v1(
      extensions.gen_random_uuid(),input_data);
    RETURN;
  END IF;
  PERFORM 1 FROM public.forms WHERE occasion=v_occasion ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.occasions WHERE id=v_occasion FOR UPDATE;
  SELECT COALESCE(v.version,0) INTO v_version
    FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
      ON v.aggregate_type='occasion' AND v.scope_type='occasion'
      AND v.scope_id=v_occasion AND v.aggregate_id=v_occasion::text;
  PERFORM public.save_occasion_client_sync_v1(v_occasion,
    extensions.gen_random_uuid(),v_version,input_data);
END; $$;
REVOKE ALL ON FUNCTION public.update_occasion_203(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_occasion_203(jsonb) TO authenticated;

-- Source: database/functions/others/save_occasion_domain_command_internal_v1.sql

-- The public save wrapper and the settings UI allow unit editors. The renamed
-- canonical domain command retained its older occasion-only guard, so it must
-- accept the same role before it reaches update_occasion_internal_v1.
CREATE OR REPLACE FUNCTION public.save_occasion_domain_command_internal_v1(
  p_occasion bigint,
  p_command_id uuid,
  p_expected_version bigint,
  p_config jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_version bigint;
  v_begin jsonb;
  v_hash text;
  v_entity jsonb;
  v_old_hidden boolean;
  v_new_hidden boolean;
  v_old_unit bigint;
  v_new_unit bigint;
  v_features jsonb;
  v_fanout_units bigint[] := '{}';
BEGIN
  SELECT o.unit INTO v_old_unit
  FROM public.occasions o
  WHERE o.id = p_occasion;

  IF v_actor IS NULL OR NOT (
    public.get_is_editor_on_occasion(p_occasion)
    OR public.get_is_admin_on_occasion(p_occasion)
    OR (v_old_unit IS NOT NULL AND public.get_is_editor_on_unit(v_old_unit))
  ) THEN
    RAISE insufficient_privilege USING MESSAGE = 'occasion editor required';
  END IF;

  IF p_config IS NULL OR jsonb_typeof(p_config) <> 'object'
    OR octet_length(p_config::text) > 1048576
    OR (p_config->>'id')::bigint IS DISTINCT FROM p_occasion
    OR EXISTS (
      SELECT 1
      FROM jsonb_object_keys(p_config) key
      WHERE key NOT IN (
        'id', 'start_time', 'end_time', 'is_open', 'is_hidden', 'is_promoted',
        'link', 'title', 'description', 'data', 'services', 'organization',
        'unit', 'features', 'form_link', 'has_orders', 'stats', 'ticket_layout_change'
      )
    )
  THEN
    RAISE invalid_parameter_value USING MESSAGE = 'invalid occasion aggregate';
  END IF;

  v_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion', p_occasion,
    'expectedVersion', p_expected_version,
    'config', p_config
  )::text, 'UTF8'), 'sha256'), 'hex');
  v_begin := public.begin_client_mutation_v1(
    p_command_id,
    'occasion.config.save',
    p_occasion,
    v_actor,
    v_hash
  );
  IF v_begin->>'disposition' = 'replay' THEN
    RETURN v_begin->'response';
  END IF;

  IF NOT (p_config ? 'ticket_layout_change' AND p_config-ARRAY['id','ticket_layout_change']='{}'::jsonb) THEN
    PERFORM 1 FROM public.forms WHERE occasion=p_occasion ORDER BY id FOR UPDATE;
  END IF;

  SELECT o.is_hidden, o.unit INTO v_old_hidden, v_old_unit
  FROM public.occasions o
  WHERE o.id = p_occasion
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,
      'rejected',
      404,
      jsonb_build_object('version', 0, 'occasion', NULL)
    );
  END IF;

  INSERT INTO public.client_aggregate_versions(
    aggregate_type, scope_type, scope_id, aggregate_id, version
  ) VALUES ('occasion', 'occasion', p_occasion, p_occasion::text, 0)
  ON CONFLICT DO NOTHING;
  SELECT version INTO v_version
  FROM public.client_aggregate_versions
  WHERE aggregate_type = 'occasion'
    AND scope_type = 'occasion'
    AND scope_id = p_occasion
    AND aggregate_id = p_occasion::text
  FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    SELECT to_jsonb(o) || jsonb_build_object('aggregate_version', v_version)
    INTO v_entity
    FROM public.occasions o
    WHERE o.id = p_occasion;
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,
      'conflict',
      409,
      jsonb_build_object('version', v_version, 'occasion', v_entity)
    );
  END IF;

  IF p_config ? 'ticket_layout_change' AND p_config - ARRAY['id','ticket_layout_change']='{}'::jsonb THEN
    IF NOT public.can_edit_ticket_layout(p_occasion) THEN
      RAISE insufficient_privilege USING MESSAGE='unit editor required';
    END IF;
    SELECT features INTO v_features FROM public.occasions WHERE id=p_occasion;
    v_features:=public.merge_ticket_layout_features(v_features,v_features,p_config->'ticket_layout_change');
    v_features:=public.merge_ticket_appearance_internal_v1(p_occasion,v_features,p_config#>'{ticket_layout_change,appearance}');
    PERFORM public.validate_ticket_layout_references(p_occasion,f->'layout')
      FROM jsonb_array_elements(v_features) f WHERE f->>'code'='ticket' AND f ? 'layout';
    UPDATE public.occasions SET features=v_features,updated_at=clock_timestamp() WHERE id=p_occasion;
  ELSE
    PERFORM public.update_occasion_internal_v1(p_config);
  END IF;
  UPDATE public.client_aggregate_versions
  SET version = version + 1, updated_at = clock_timestamp()
  WHERE aggregate_type = 'occasion'
    AND scope_type = 'occasion'
    AND scope_id = p_occasion
    AND aggregate_id = p_occasion::text
  RETURNING version INTO v_version;
  SELECT to_jsonb(o) || jsonb_build_object('aggregate_version', v_version)
  INTO v_entity
  FROM public.occasions o
  WHERE o.id = p_occasion;

  v_new_hidden := (v_entity->>'is_hidden')::boolean;
  v_new_unit := (v_entity->>'unit')::bigint;
  IF NOT v_old_hidden THEN
    v_fanout_units := array_append(v_fanout_units, v_old_unit);
  END IF;
  IF NOT v_new_hidden AND v_new_unit IS DISTINCT FROM v_old_unit THEN
    v_fanout_units := array_append(v_fanout_units, v_new_unit);
  ELSIF NOT v_new_hidden AND v_old_hidden THEN
    v_fanout_units := array_append(v_fanout_units, v_new_unit);
  END IF;

  RETURN public.complete_client_mutation_applied_v1(
    p_command_id,
    p_occasion,
    'occasion.config.save',
    'configuration',
    jsonb_build_array(jsonb_build_object(
      'entityType', 'occasion',
      'entityId', p_occasion,
      'operation', 'update',
      'safeLabel', left(v_entity->>'title', 240),
      'changedFields', jsonb_build_array('configuration')
    )),
    CASE WHEN v_old_hidden AND NOT v_new_hidden THEN ARRAY[
      'occasion_config', 'program_catalog', 'map_catalog', 'content_catalog',
      'live_public'
    ] ELSE ARRAY['occasion_config'] END,
    '[]',
    '[]',
    jsonb_build_object('version', v_version, 'occasion', v_entity),
    CASE WHEN NOT v_new_hidden THEN ARRAY['occasion_config'] ELSE '{}'::text[] END,
    '[]',
    'user',
    NULL,
    '[]',
    v_fanout_units
  );
END;
$$;

REVOKE ALL ON FUNCTION public.save_occasion_domain_command_internal_v1(
  bigint, uuid, bigint, jsonb
) FROM PUBLIC, anon, authenticated;

-- Source: database/functions/others/save_occasion_client_sync_v1.sql

-- Occasion settings are edited from the unit workspace. Keep the explicit
-- wrapper authorization aligned with both that UI contract and the trusted
-- update_occasion_internal_v1 implementation, which authorizes the target
-- unit editor before changing the aggregate.
CREATE OR REPLACE FUNCTION public.save_occasion_client_sync_v1(
  p_occasion bigint,
  p_command_id uuid,
  p_expected_version bigint,
  p_config jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_config jsonb;
  v_data jsonb;
  v_enabled boolean;
  v_hidden boolean;
  v_unit bigint;
BEGIN
  SELECT
    COALESCE((o.data->>'client_sync_v1')::boolean, false),
    o.is_hidden,
    o.unit
  INTO v_enabled, v_hidden, v_unit
  FROM public.occasions o
  WHERE o.id = p_occasion;

  IF auth.uid() IS NULL OR NOT (
    public.get_is_editor_on_occasion(p_occasion)
    OR public.get_is_admin_on_occasion(p_occasion)
    OR (v_unit IS NOT NULL AND public.get_is_editor_on_unit(v_unit))
  ) THEN
    RAISE insufficient_privilege USING MESSAGE = 'occasion editor required';
  END IF;

  IF v_enabled
    AND NOT v_hidden
    AND COALESCE((p_config->>'is_hidden')::boolean, false)
  THEN
    RAISE object_not_in_prerequisite_state
      USING MESSAGE = 'disable client_sync_v1 before hiding occasion';
  END IF;

  -- A layout-only command must not manufacture data/features or run general settings effects.
  IF p_config ? 'ticket_layout_change' AND p_config - ARRAY['id','ticket_layout_change']='{}'::jsonb THEN
    IF NOT public.can_edit_ticket_layout(p_occasion) THEN
      RAISE insufficient_privilege USING MESSAGE='unit editor required';
    END IF;
    RETURN public.save_occasion_domain_command_internal_v1(
      p_occasion,p_command_id,p_expected_version,p_config);
  END IF;

  v_data := CASE
    WHEN jsonb_typeof(p_config->'data') = 'object' THEN p_config->'data'
    ELSE '{}'::jsonb
  END;
  v_config := jsonb_set(
    p_config,
    '{data}',
    jsonb_set(
      v_data,
      '{client_sync_v1}',
      to_jsonb(COALESCE(v_enabled, false)),
      true
    ),
    true
  );

  RETURN public.save_occasion_domain_command_internal_v1(
    p_occasion,
    p_command_id,
    p_expected_version,
    v_config
  );
END;
$$;

REVOKE ALL ON FUNCTION public.save_occasion_client_sync_v1(
  bigint,
  uuid,
  bigint,
  jsonb
) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.save_occasion_client_sync_v1(
  bigint,
  uuid,
  bigint,
  jsonb
) TO authenticated;

-- Source: database/functions/others/get_ticket_layout_for_authoring_v1.sql
-- Minimal authoring projection. No orders, buyers, QR or hold secrets.
CREATE OR REPLACE FUNCTION public.get_ticket_layout_for_authoring_v1(p_occasion bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE result jsonb;
BEGIN
 IF NOT public.can_edit_ticket_layout(p_occasion) THEN
  RAISE insufficient_privilege USING MESSAGE='unit editor required'; END IF;
 SELECT jsonb_build_object('occasion',o.id,'aggregate_version',coalesce(v.version,0),
  'schemaVersion',3,'appearance',coalesce((SELECT jsonb_build_object('layout',f->'layout',
    'background',f->'background','ticket_type',f->'ticket_type') FROM jsonb_array_elements(o.features) f WHERE f->>'code'='ticket'),'{}'),
  'images',coalesce((SELECT jsonb_agg(i.link ORDER BY i.id) FROM public.images i WHERE i.occasion=o.id OR i.unit=o.unit),'[]'))
 INTO result FROM public.occasions o LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='occasion' AND v.scope_type='occasion' AND v.scope_id=o.id AND v.aggregate_id=o.id::text
 WHERE o.id=p_occasion;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.get_ticket_layout_for_authoring_v1(bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_ticket_layout_for_authoring_v1(bigint) TO authenticated;

-- Source: database/functions/eshop/update_blueprint.sql
-- Domain effects are called only inside the receipted command's rollback block.
CREATE OR REPLACE FUNCTION public.update_blueprint_internal_v1(input_data jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE bp bigint:=nullif(input_data->>'id','')::bigint; oc bigint:=(input_data->>'occasion')::bigint;
 org bigint; item jsonb; v_objects jsonb:='[]'; ids bigint[]:='{}'; sid bigint; product_id bigint;
 old eshop.spots; replacements jsonb:='{}'; form_id bigint:=nullif(input_data->>'form','')::bigint;
BEGIN
 IF auth.uid() IS NULL OR public.get_is_editor_order_on_occasion(oc) IS NOT TRUE THEN
  RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 SELECT organization INTO org FROM public.occasions WHERE id=oc;
 IF org IS NULL OR org IS DISTINCT FROM (input_data->>'organization')::bigint THEN
  RETURN jsonb_build_object('code',403,'message','Blueprint organization mismatch'); END IF;
 IF form_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.forms WHERE id=form_id AND occasion=oc) THEN
  RETURN jsonb_build_object('code',403,'message','Foreign form'); END IF;
 IF bp IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.blueprints WHERE id=bp AND occasion=oc AND organization=org) THEN
  RETURN jsonb_build_object('code',403,'message','Foreign blueprint'); END IF;
 IF input_data ? 'objects' THEN
  IF jsonb_typeof(input_data->'objects') IS DISTINCT FROM 'array' OR jsonb_array_length(input_data->'objects')>10000 THEN
   RETURN jsonb_build_object('code',400,'message','Invalid blueprint objects'); END IF;
  -- Scope and all references validate before the first domain effect.
  FOR item IN SELECT value FROM jsonb_array_elements(input_data->'objects') LOOP
   IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item ?| ARRAY['secret','secret_expiration_time','order_product_ticket','state'] THEN
    RETURN jsonb_build_object('code',400,'message','Occupancy is server owned'); END IF;
   IF item->>'type'='spot' THEN
    sid:=nullif(item->>'id','')::bigint; product_id:=nullif(item->>'product','')::bigint;
    IF product_id IS NULL OR NOT EXISTS(SELECT 1 FROM eshop.products p JOIN eshop.product_types t ON t.id=p.product_type
     WHERE p.id=product_id AND p.occasion=oc AND t.occasion=oc AND t.type='spot') THEN
     RETURN jsonb_build_object('code',4004,'message','Invalid seat product'); END IF;
    IF sid IS NOT NULL AND (sid<=0 OR bp IS NULL OR NOT EXISTS(SELECT 1 FROM eshop.spots WHERE id=sid AND blueprint=bp AND occasion=oc)) THEN
     RETURN jsonb_build_object('code',403,'message','Foreign seat'); END IF;
    IF sid=ANY(ids) THEN RETURN jsonb_build_object('code',400,'message','Duplicate seat'); END IF;
    IF sid IS NOT NULL THEN ids:=array_append(ids,sid); END IF;
   END IF;
  END LOOP;
  IF (SELECT count(*) FROM jsonb_array_elements(input_data->'objects') o WHERE o ? 'client_id') <>
     (SELECT count(DISTINCT o->>'client_id') FROM jsonb_array_elements(input_data->'objects') o WHERE o ? 'client_id') THEN
   RETURN jsonb_build_object('code',400,'message','Duplicate temporary seat identity'); END IF;
 END IF;
 IF bp IS NULL THEN
  INSERT INTO eshop.blueprints(occasion,organization) VALUES(oc,org) RETURNING id INTO bp;
 END IF;
 -- The command already holds form and product parents. Hold/allocation writers
 -- also lock these actual seats; preview data cannot approve removal.
 PERFORM 1 FROM eshop.spots WHERE blueprint=bp AND occasion=oc ORDER BY id FOR UPDATE;
 IF input_data ? 'objects' THEN
  FOR old IN SELECT * FROM eshop.spots WHERE blueprint=bp AND occasion=oc ORDER BY id LOOP
   IF (old.order_product_ticket IS NOT NULL OR (old.secret IS NOT NULL AND old.secret_expiration_time>clock_timestamp())) THEN
    IF NOT old.id=ANY(ids) THEN
     RETURN jsonb_build_object('code',4031,'message','Seat is allocated or held','spot_id',old.id); END IF;
    SELECT (o->>'product')::bigint INTO product_id FROM jsonb_array_elements(input_data->'objects') o WHERE (o->>'id')::bigint=old.id AND o->>'type'='spot';
    IF product_id IS DISTINCT FROM old.product THEN
     RETURN jsonb_build_object('code',409,'message','Allocated seat product cannot change','spot_id',old.id); END IF;
   END IF;
  END LOOP;
  FOR item IN SELECT value FROM jsonb_array_elements(input_data->'objects') LOOP
   IF item->>'type'='spot' THEN
    sid:=nullif(item->>'id','')::bigint;
    IF sid IS NULL THEN
     INSERT INTO eshop.spots(occasion,blueprint,title,product) VALUES(oc,bp,item->>'title',(item->>'product')::bigint) RETURNING id INTO sid;
     IF item ? 'client_id' THEN replacements:=replacements||jsonb_build_object(item->>'client_id',sid); END IF;
     ids:=array_append(ids,sid);
    ELSE
     UPDATE eshop.spots SET title=item->>'title',product=(item->>'product')::bigint,updated_at=clock_timestamp()
     WHERE id=sid AND blueprint=bp AND occasion=oc;
    END IF;
    item:=jsonb_set(item-'title'-'product'-'client_id','{id}',to_jsonb(sid));
   END IF;
   v_objects:=v_objects||jsonb_build_array(item);
  END LOOP;
  DELETE FROM eshop.spots WHERE blueprint=bp AND occasion=oc AND NOT id=ANY(ids);
 END IF;
 UPDATE eshop.blueprints SET
  title=CASE WHEN input_data ? 'title' THEN input_data->>'title' ELSE title END,
  data=CASE WHEN input_data ? 'data' THEN input_data->'data' ELSE data END,
  configuration=CASE WHEN input_data ? 'configuration' THEN input_data->'configuration' ELSE configuration END,
  groups=CASE WHEN input_data ? 'groups' THEN input_data->'groups' ELSE groups END,
  background_svg=CASE WHEN input_data ? 'background_svg' THEN input_data->>'background_svg' ELSE background_svg END,
  objects=CASE WHEN input_data ? 'objects' THEN v_objects ELSE eshop.blueprints.objects END,
  updated_at=clock_timestamp() WHERE id=bp AND occasion=oc;
 IF form_id IS NOT NULL THEN
  PERFORM public.check_form_capacity_settings_internal(form_id,jsonb_build_object('blueprint',bp));
  UPDATE public.forms SET blueprint=bp,capacity_revision=capacity_revision+1,updated_at=clock_timestamp() WHERE id=form_id AND occasion=oc;
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
   VALUES('form','occasion',oc,form_id::text,1) ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id)
   DO UPDATE SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
 END IF;
 RETURN jsonb_build_object('code',200,'blueprint_id',bp,'updated_objects',v_objects,'seat_replacements',replacements);
END $$;
REVOKE ALL ON FUNCTION public.update_blueprint_internal_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- Published clients used the admin serialization. Only this mechanical boundary
-- strips read-only fields; the command never accepts occupancy as an instruction.
CREATE OR REPLACE FUNCTION public.update_blueprint(input_data jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE result jsonb; normalized jsonb:=input_data-ARRAY['products','tickets','orders','order_product_ticket','created_at'];
BEGIN
 IF normalized ? 'objects' THEN
  normalized:=jsonb_set(normalized,'{objects}',coalesce((SELECT jsonb_agg(o-ARRAY['state','secret','secret_expiration_time','order_product_ticket']) FROM jsonb_array_elements(normalized->'objects') o),'[]'));
 END IF;
 result:=public.update_blueprint_client_sync_v1(normalized,extensions.gen_random_uuid());
 RETURN jsonb_build_object('code',result->'code')||result->'data';
END $$;
REVOKE ALL ON FUNCTION public.update_blueprint(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_blueprint(jsonb) TO authenticated;

-- Source: database/functions/eshop/update_blueprint_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.update_blueprint_client_sync_v1(p_blueprint jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path = public, extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_blueprint bigint;
  v_begin jsonb; v_hash text; v_version bigint; v_expected bigint; v_users uuid[]; v_result jsonb;
BEGIN
  IF p_blueprint IS NULL OR jsonb_typeof(p_blueprint)<>'object'
    OR octet_length(p_blueprint::text)>8388608 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid blueprint aggregate'; END IF;
  v_occasion:=NULLIF(p_blueprint->>'occasion','')::bigint;
  v_blueprint:=NULLIF(p_blueprint->>'id','')::bigint;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',v_occasion,'blueprint',p_blueprint)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.blueprint.save',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF v_blueprint IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.blueprints WHERE id=v_blueprint AND occasion=v_occasion) THEN RAISE insufficient_privilege USING MESSAGE='foreign blueprint'; END IF;
  -- Parent order matches checkout: form, product, blueprint, then seats.
  PERFORM 1 FROM public.forms WHERE occasion=v_occasion AND
    (blueprint=v_blueprint OR id=nullif(p_blueprint->>'form','')::bigint) ORDER BY id FOR UPDATE;
  IF p_blueprint->>'form' IS NOT NULL THEN
    IF NOT EXISTS(SELECT 1 FROM public.forms WHERE id=(p_blueprint->>'form')::bigint AND occasion=v_occasion) THEN
      RAISE insufficient_privilege USING MESSAGE='foreign form'; END IF;
    INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES('form','occasion',v_occasion,p_blueprint->>'form',0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_expected FROM public.client_aggregate_versions WHERE aggregate_type='form'
      AND scope_type='occasion' AND scope_id=v_occasion AND aggregate_id=p_blueprint->>'form' FOR UPDATE;
    IF (p_blueprint->>'expected_form_version')::bigint IS DISTINCT FROM v_expected THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
        jsonb_build_object('form_version',v_expected)); END IF;
  END IF;
  PERFORM 1 FROM eshop.products WHERE occasion=v_occasion ORDER BY id FOR UPDATE;
  PERFORM 1 FROM eshop.blueprints WHERE id=v_blueprint AND occasion=v_occasion FOR UPDATE;
  IF v_blueprint IS NOT NULL THEN
    INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES('blueprint','occasion',v_occasion,v_blueprint::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='blueprint' AND scope_type='occasion' AND scope_id=v_occasion AND aggregate_id=v_blueprint::text FOR UPDATE;
  ELSE v_version:=0; END IF;
  -- Missing baseline remains an installed-client adapter, explicitly not MCP-ready.
  v_expected:=CASE WHEN p_blueprint ? 'expected_aggregate_version' THEN (p_blueprint->>'expected_aggregate_version')::bigint ELSE v_version END;
  IF v_expected IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('aggregate_version',v_version)); END IF;
  SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
  FROM public.occasion_users ou JOIN eshop.order_product_ticket opt
    ON opt.ticket=ou.ticket JOIN eshop.spots s
    ON s.order_product_ticket=opt.id
  WHERE ou.occasion=v_occasion AND s.occasion=v_occasion;
  BEGIN
    v_result:=public.update_blueprint_internal_v1(p_blueprint-ARRAY['expected_aggregate_version','expected_form_version']);
    IF coalesce((v_result->>'code')::integer,500)<>200 THEN
      RAISE SQLSTATE 'P0F01' USING MESSAGE='authoring domain rejected'; END IF;
  EXCEPTION WHEN SQLSTATE 'P0F01' THEN NULL;
  END;
  IF coalesce((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      CASE WHEN (v_result->>'code')::integer BETWEEN 100 AND 599 THEN (v_result->>'code')::integer ELSE 400 END,v_result); END IF;
  v_blueprint:=(v_result->>'blueprint_id')::bigint;
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES('blueprint','occasion',v_occasion,v_blueprint::text,1)
    ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp()
    RETURNING version INTO v_version;
  v_result:=v_result||jsonb_build_object('aggregate_version',v_version);
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.blueprint.save',jsonb_build_array(jsonb_build_object(
      'entityType','blueprint','entityId',v_result->>'blueprint_id',
      'operation',CASE WHEN p_blueprint->>'id' IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_blueprint->>'title',240),'changedFields',jsonb_build_array(
        'spots','configuration'))),v_users,v_result);
END; $function$;

REVOKE ALL ON FUNCTION public.update_blueprint_client_sync_v1(jsonb,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_blueprint_client_sync_v1(jsonb,uuid) TO authenticated;

-- Source: database/functions/eshop_forms/update_form.sql
CREATE OR REPLACE FUNCTION public.update_form_internal_v1(input_data JSONB)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    ----------------------------------------------------------------------------
    -- Declarations
    ----------------------------------------------------------------------------
    result JSONB;
    deleted_fields BIGINT[];
    deleted_products BIGINT[];
    deletion_reason TEXT;
    deletion_row RECORD;

    form_id          BIGINT;               -- ID of the form being created/updated
    occasion_id      BIGINT;               -- ID of the occasion to which the form belongs
    now_ts           TIMESTAMPTZ := NOW(); -- Current timestamp for record updates

    link_param           TEXT;         -- Unique link for the form, must not conflict within the same org
    occasion_org         BIGINT;       -- Organization stored in the occasions table
    occasion_unit        BIGINT;       -- The 'unit' that must match for bank accounts
    conflict_check       INT;          -- Used for verifying uniqueness constraints
    deadline_val         BIGINT;       -- Field for validating form deadlines
    price_val            NUMERIC;      -- Field for validating product price

    bank_account_val     BIGINT;       -- Bank account from input_data
    bank_account_unit    BIGINT;       -- Unit of the bank account, must match occasion_unit

    v_seconds_before_deadline BIGINT; -- For calling the reminder queue function

    ----------------------------------------------------------------------------
    -- Since product_type data is now inside form_fields, we no longer read from
    -- a top-level product_types array. Instead, we will parse product_type objects
    -- directly from each form_field (if present).
    ----------------------------------------------------------------------------

    product_type_data    JSONB;        -- The JSONB data for product_type within a form_field
    product_type_id      BIGINT;       -- ID (new or existing) of the product_type
    product_type_occ     BIGINT;       -- For checking product_type's occasion

    products_data        JSONB;        -- JSONB array of products inside a product_type
    product_array_data   JSONB;        -- Rebuilt array of products
    product_data         JSONB;        -- Each product object from the products array
    product_id           BIGINT;       -- ID for a product (new or existing)
    product_occ          BIGINT;       -- Occasion check for an existing product

    ----------------------------------------------------------------------------
    -- form_fields data
    ----------------------------------------------------------------------------
    form_fields_data     JSONB := '[]'::JSONB; -- Final array of form_fields for the response
    field_data           JSONB;                -- Each form_field from input
    field_id             BIGINT;               -- ID for a form_field (new or existing)
    field_product_type   BIGINT;               -- Will store the final product_type.id for the form_field
    field_occ            BIGINT;               -- Verify product_type's occasion if referenced
BEGIN
    BEGIN
        /* All logic is inside this sub-block so we can catch exceptions similarly
           to how it's done in create_ticket_order, with a single EXCEPTION WHEN OTHERS THEN.
           We raise exceptions in JSON form, and if it's JSON, we return it as-is; otherwise,
           we build a default JSON error response. */

        ----------------------------------------------------------------------------
        -- Begin main logic
        ----------------------------------------------------------------------------

        -- Validate that input_data and essential fields exist
        IF input_data IS NULL THEN
            RAISE EXCEPTION '%',
                JSONB_BUILD_OBJECT('code', 4001, 'message', 'Input data is missing')::TEXT;
        END IF;

        IF input_data->>'occasion' IS NULL THEN
            RAISE EXCEPTION '%',
                JSONB_BUILD_OBJECT('code', 4002, 'message', 'Missing occasion ID in input data')::TEXT;
        END IF;

        occasion_id := (input_data->>'occasion')::BIGINT;
        IF occasion_id IS NULL THEN
            RAISE EXCEPTION '%',
                JSONB_BUILD_OBJECT('code', 4002, 'message', 'Invalid or missing occasion ID')::TEXT;
        END IF;

        -- Ensure user is authorized to edit this occasion
        IF NOT COALESCE(get_is_editor_order_on_occasion(occasion_id), false) THEN
            RAISE EXCEPTION '%',
                JSONB_BUILD_OBJECT('code', 403, 'message', 'User is not authorized to edit this occasion')::TEXT;
        END IF;

        -- Retrieve the occasion's organization and unit
        SELECT o.organization, o.unit
          INTO occasion_org, occasion_unit
          FROM public.occasions o
         WHERE o.id = occasion_id
         LIMIT 1;

        IF occasion_org IS NULL OR occasion_unit IS NULL THEN
            RAISE EXCEPTION '%',
                JSONB_BUILD_OBJECT('code', 4017, 'message', 'Occasion not found or missing required fields')::TEXT;
        END IF;

        IF NOT public.is_service_role() AND NOT (public.get_is_editor_on_unit(occasion_unit) OR public.get_is_editor_on_occasion(occasion_id)) THEN RAISE insufficient_privilege USING MESSAGE='form editor required'; END IF;
        form_id := NULLIF(input_data->>'id','')::bigint;
        IF form_id IS NULL THEN
          INSERT INTO public.forms(created_at,occasion) VALUES(now_ts,occasion_id) RETURNING id INTO form_id;
          link_param := public.reserve_public_link_internal('form',form_id,input_data->>'link',true);
        ELSE
          IF NOT EXISTS (SELECT 1 FROM public.forms WHERE id=form_id AND occasion=occasion_id) THEN
            RAISE invalid_parameter_value USING MESSAGE='Form does not match occasion'; END IF;
          link_param := public.reserve_public_link_internal('form',form_id,input_data->>'link',false);
        END IF;

        -- Explicit removals are part of this save transaction, never inferred from
        -- omitted fields in partial/older-client payloads. Exceptions roll back the save.
        SELECT COALESCE(array_agg(value::bigint), '{}'::bigint[]) INTO deleted_fields
        FROM jsonb_array_elements_text(COALESCE(input_data->'deleted_field_ids', '[]'::jsonb));
        SELECT COALESCE(array_agg(value::bigint), '{}'::bigint[]) INTO deleted_products
        FROM jsonb_array_elements_text(COALESCE(input_data->'deleted_product_ids', '[]'::jsonb));

        IF EXISTS (SELECT 1 FROM unnest(deleted_fields) AS removed(id) WHERE NOT EXISTS (
            SELECT 1 FROM public.form_fields ff WHERE ff.id = removed.id AND ff.form = form_id))
          OR EXISTS (SELECT 1 FROM unnest(deleted_products) AS removed(id) WHERE NOT EXISTS (
            SELECT 1 FROM eshop.products p JOIN public.form_fields ff ON ff.product_type = p.product_type
            WHERE p.id = removed.id AND ff.form = form_id)) THEN
            RAISE EXCEPTION 'FORM_DELETE_changed';
        END IF;

        -- Removing the ticket container also removes its nested fields.
        IF EXISTS (SELECT 1 FROM public.form_fields ff WHERE ff.id = ANY(deleted_fields) AND ff.type = 'ticket') THEN
            SELECT deleted_fields || COALESCE(array_agg(ff.id), '{}'::bigint[]) INTO deleted_fields
            FROM public.form_fields ff WHERE ff.form = form_id AND ff.is_ticket_field;
        END IF;

        -- Serialize product-type references and product FK insertions before checking
        -- usage, including ON DELETE CASCADE inventory links.
        PERFORM 1 FROM eshop.product_types pt WHERE pt.id IN (
            SELECT ff.product_type FROM public.form_fields ff WHERE ff.id = ANY(deleted_fields)
            UNION SELECT p.product_type FROM eshop.products p WHERE p.id = ANY(deleted_products)
        ) ORDER BY pt.id FOR UPDATE;
        SELECT deleted_products || COALESCE(array_agg(p.id), '{}'::bigint[]) INTO deleted_products
        FROM eshop.products p JOIN public.form_fields ff ON ff.product_type = p.product_type
        WHERE ff.id = ANY(deleted_fields);
        PERFORM 1 FROM eshop.products p WHERE p.id = ANY(deleted_products) ORDER BY p.id FOR UPDATE;

        FOR deletion_row IN SELECT ff.* FROM public.form_fields ff WHERE ff.id = ANY(deleted_fields)
        LOOP
            SELECT CASE WHEN EXISTS (
          SELECT 1 FROM (
            SELECT current_order.id, current_order.form, current_order.data FROM eshop.orders current_order WHERE current_order.form = ff.form
          ) o
          WHERE o.form = ff.form AND (
            EXISTS (SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(o.data->'fields') = 'array' THEN o.data->'fields' ELSE '[]'::jsonb END) answer
              WHERE answer ? ff.id::text AND answer->(ff.id::text) NOT IN ('null'::jsonb, '""'::jsonb, '[]'::jsonb, '{}'::jsonb))
            OR (ff.type = 'ticket' AND jsonb_path_exists(o.data, '$.tickets[*]'))
            OR (ff.type = 'note' AND ff.is_ticket_field AND jsonb_path_exists(o.data, '$.tickets[*] ? (@.note != null && @.note != "")'))
            OR (ff.type = 'ticket' AND EXISTS (SELECT 1 FROM eshop.order_product_ticket opt WHERE opt."order" = o.id AND opt.ticket IS NOT NULL))
            OR (ff.type = 'note' AND ff.is_ticket_field AND EXISTS (
              SELECT 1 FROM eshop.order_product_ticket opt JOIN eshop.tickets t ON t.id = opt.ticket
              WHERE opt."order" = o.id AND NULLIF(t.note, '') IS NOT NULL))
          )) OR EXISTS(SELECT 1 FROM eshop.tickets person CROSS JOIN LATERAL jsonb_array_elements(
            CASE WHEN jsonb_typeof(person.data->'fields')='array' THEN person.data->'fields' ELSE '[]' END) answer
            WHERE EXISTS(SELECT 1 FROM eshop.order_product_ticket x JOIN eshop.orders q ON q.id=x."order" WHERE x.ticket=person.id AND q.form=ff.form) AND answer ? ff.id::text AND answer->(ff.id::text) NOT IN ('null'::jsonb,'""'::jsonb,'[]'::jsonb,'{}'::jsonb))
           OR (ff.type='ticket' AND EXISTS(SELECT 1 FROM eshop.order_product_ticket x JOIN eshop.orders q ON q.id=x."order" WHERE x.ticket IS NOT NULL AND q.form=ff.form)) THEN 'responses'
        ELSE (
          SELECT reason FROM public.form_fields member
          JOIN eshop.products p ON p.product_type = member.product_type
          CROSS JOIN LATERAL (SELECT CASE
          WHEN EXISTS (SELECT 1 FROM eshop.order_product_ticket opt WHERE opt.product = p.id)
            OR EXISTS (SELECT 1 FROM eshop.orders o WHERE o.occasion = p.occasion
              AND jsonb_path_exists(o.data, '$.tickets[*].products[*] ? (@.id == $id)', jsonb_build_object('id', p.id))) THEN 'orders'
          WHEN EXISTS (SELECT 1 FROM eshop.spots s WHERE s.product = p.id) THEN 'blueprint'
          WHEN EXISTS (SELECT 1 FROM eshop.product_inventory_contexts pic WHERE pic.product = p.id) THEN 'inventory'
          WHEN (SELECT count(*) FROM public.form_fields ref WHERE ref.product_type = p.product_type) > 1 THEN 'shared'
        END AS reason) usage
          WHERE (member.id = ff.id OR (ff.type = 'ticket' AND member.form = ff.form AND member.is_ticket_field))
            AND reason IS NOT NULL
          ORDER BY p.id LIMIT 1
        ) END INTO deletion_reason
            FROM public.form_fields ff WHERE ff.id = deletion_row.id;
            IF deletion_reason IS NOT NULL THEN
                RAISE EXCEPTION 'FORM_DELETE_%', deletion_reason;
            END IF;
        END LOOP;
        FOR deletion_row IN SELECT p.* FROM eshop.products p WHERE p.id = ANY(deleted_products)
        LOOP
            SELECT CASE
          WHEN EXISTS (SELECT 1 FROM eshop.order_product_ticket opt WHERE opt.product = p.id)
            OR EXISTS (SELECT 1 FROM eshop.orders o WHERE o.occasion = p.occasion
              AND jsonb_path_exists(o.data, '$.tickets[*].products[*] ? (@.id == $id)', jsonb_build_object('id', p.id))) THEN 'orders'
          WHEN EXISTS (SELECT 1 FROM eshop.spots s WHERE s.product = p.id) THEN 'blueprint'
          WHEN EXISTS (SELECT 1 FROM eshop.product_inventory_contexts pic WHERE pic.product = p.id) THEN 'inventory'
          WHEN (SELECT count(*) FROM public.form_fields ref WHERE ref.product_type = p.product_type) > 1 THEN 'shared'
        END INTO deletion_reason
            FROM eshop.products p WHERE p.id = deletion_row.id;
            IF deletion_reason IS NOT NULL THEN
                RAISE EXCEPTION 'FORM_DELETE_%', deletion_reason;
            END IF;
        END LOOP;
        IF EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(input_data->'form_fields', '[]'::jsonb)) f
            WHERE (f->>'id')::bigint = ANY(deleted_fields))
          OR EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(input_data->'form_fields', '[]'::jsonb)) f,
            jsonb_array_elements(COALESCE(NULLIF(f->'product_type'->'products', 'null'::jsonb), '[]'::jsonb)) p
            WHERE (p->>'id')::bigint = ANY(deleted_products)) THEN
            RAISE EXCEPTION 'FORM_DELETE_changed';
        END IF;
        DELETE FROM public.form_fields ff WHERE ff.id = ANY(deleted_fields);
        DELETE FROM eshop.planned_changes WHERE subject_id=ANY(deleted_products) AND change_type IN('products.price','products.is_hidden') AND NOT applied;
        DELETE FROM eshop.products p WHERE p.id = ANY(deleted_products);
        DELETE FROM public.client_aggregate_versions WHERE aggregate_type='product' AND scope_type='occasion'
          AND scope_id=occasion_id AND aggregate_id=ANY(ARRAY(SELECT id::text FROM unnest(deleted_products) id));

        ----------------------------------------------------------------------------
        -- Process form_fields array from input_data if present
        -- Each form_field may contain a product_type object. If so, we insert/update
        -- the product_type and its products, then set the resulting product_type.id
        -- in the form_field.
        ----------------------------------------------------------------------------
        IF (input_data->'form_fields') IS NOT NULL THEN
            form_fields_data := '[]'::JSONB;

            FOR field_data IN SELECT * FROM JSONB_ARRAY_ELEMENTS(input_data->'form_fields')
            LOOP
                field_id := NULLIF(field_data->>'id', '')::BIGINT;

                ----------------------------------------------------------------------------
                -- product_type logic now lives here, inside each form_field
                ----------------------------------------------------------------------------
                product_type_data := field_data->'product_type';  -- This is JSONB (could be null)
                IF field_data->>'type' = 'ticket' AND field_data#>>'{data,max_tickets}' IS NOT NULL THEN
                    IF (field_data#>>'{data,max_tickets}')::numeric < 1 OR
                       (field_data#>>'{data,max_tickets}')::numeric > public.ticket_order_limit() OR
                       trunc((field_data#>>'{data,max_tickets}')::numeric) <> (field_data#>>'{data,max_tickets}')::numeric THEN
                        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT('code', 400,
                            'message', 'Invalid maximum tickets per order',
                            'limit', public.ticket_order_limit())::TEXT;
                    END IF;
                END IF;
                field_product_type := NULL;                        -- We'll store numeric ID here if we have a product_type

                IF product_type_data IS NOT NULL AND product_type_data::TEXT <> 'null' THEN
                    -- Attempt to parse the product_type.id if it exists
                    product_type_id := NULLIF(product_type_data->>'id', '')::BIGINT;

                    IF product_type_id IS NULL THEN
                        ----------------------------------------------------------------------------
                        -- New product_type
                        ----------------------------------------------------------------------------
                        INSERT INTO eshop.product_types (
                            created_at,
                            updated_at,
                            occasion,
                            title,
                            description,
                            type,
                            data
                        )
                        VALUES (
                            now_ts,
                            now_ts,
                            occasion_id,
                            product_type_data->>'title',
                            product_type_data->>'description',
                            product_type_data->>'type',
                            product_type_data->'data'
                        )
                        RETURNING id INTO product_type_id;

                        product_type_data := jsonb_set(
                            product_type_data,
                            '{id}',
                            TO_JSONB(product_type_id)
                        );
                    ELSE
                        ----------------------------------------------------------------------------
                        -- Existing product_type: check existence and occasion
                        ----------------------------------------------------------------------------
                        SELECT pt.occasion
                          INTO product_type_occ
                          FROM eshop.product_types pt
                         WHERE pt.id = product_type_id
                         LIMIT 1;

                        IF NOT FOUND THEN
                            RAISE EXCEPTION '%',
                                JSONB_BUILD_OBJECT(
                                    'code', 4006,
                                    'message', 'Product type not found',
                                    'details', product_type_data
                                )::TEXT;
                        END IF;

                        IF product_type_occ <> occasion_id THEN
                            RAISE EXCEPTION '%',
                                JSONB_BUILD_OBJECT(
                                    'code', 4007,
                                    'message', 'product_type occasion does not match form occasion',
                                    'product_type_occasion', product_type_occ,
                                    'form_occasion', occasion_id,
                                    'details', product_type_data
                                )::TEXT;
                        END IF;

                        PERFORM 1 FROM public.occasions WHERE id=occasion_id FOR UPDATE;
                        UPDATE eshop.product_types
                           SET
                               updated_at = now_ts,
                               title = product_type_data->>'title',
                               description = product_type_data->>'description',
                               type = product_type_data->>'type',
                               data = product_type_data->'data'
                         WHERE id = product_type_id;
                    END IF;

                    ----------------------------------------------------------------------------
                    -- Process products within this product_type, if any
                    ----------------------------------------------------------------------------
                    PERFORM public.advance_ticketing_authoring_version_internal_v1('product_type',occasion_id,product_type_id);
                    products_data := product_type_data->'products';
                    IF products_data IS NOT NULL AND products_data::TEXT <> 'null' THEN
                        product_array_data := '[]'::JSONB;

                        FOR product_data IN SELECT * FROM JSONB_ARRAY_ELEMENTS(products_data)
                        LOOP
                            product_id := NULLIF(product_data->>'id', '')::BIGINT;

                            -- Validate product price must be > 0
                            price_val := COALESCE(NULLIF(product_data->>'price',''), '0')::NUMERIC;
                            IF price_val < 0 THEN
                                RAISE EXCEPTION '%',
                                    JSONB_BUILD_OBJECT(
                                        'code', 4015,
                                        'message', 'Product price must be greater or equal to zero',
                                        'details', product_data
                                    )::TEXT;
                            END IF;

                            IF product_id IS NULL THEN
                                ----------------------------------------------------------------------------
                                -- New product
                                ----------------------------------------------------------------------------
                                PERFORM public.validate_product_price(price_val,product_data->'data',left(product_data->>'currency_code',3));
                                INSERT INTO eshop.products (
                                    created_at,
                                    updated_at,
                                    product_type,
                                    occasion,
                                    title,
                                    description,
                                    price,
                                    currency_code,
                                    data,
                                    is_hidden,
                                    "order",
                                    maximum
                                )
                                VALUES (
                                    now_ts,
                                    now_ts,
                                    product_type_id,
                                    occasion_id,
                                    product_data->>'title',
                                    product_data->>'description',
                                    price_val,
                                    left(product_data->>'currency_code', 3),
                                    product_data->'data',
                                    COALESCE((product_data->>'is_hidden')::BOOLEAN, false),
                                    NULLIF(product_data->>'order','')::BIGINT,
                                    NULLIF(product_data->>'maximum','')::BIGINT
                                )
                                RETURNING id INTO product_id;

                                product_data := jsonb_set(product_data, '{id}', TO_JSONB(product_id));
                            ELSE
                                ----------------------------------------------------------------------------
                                -- Existing product: must match the same occasion and product_type
                                ----------------------------------------------------------------------------
                                SELECT p.occasion
                                  INTO product_occ
                                  FROM eshop.products p
                                 WHERE p.id = product_id
                                   AND p.product_type = product_type_id
                                 LIMIT 1;

                                IF NOT FOUND THEN
                                    RAISE EXCEPTION '%',
                                        JSONB_BUILD_OBJECT(
                                            'code', 4008,
                                            'message', 'Product not found or does not match product_type',
                                            'details', product_data
                                        )::TEXT;
                                END IF;

                                IF product_occ <> occasion_id THEN
                                    RAISE EXCEPTION '%',
                                        JSONB_BUILD_OBJECT(
                                            'code', 4009,
                                            'message', 'Product occasion does not match form occasion',
                                            'product_occasion', product_occ,
                                            'form_occasion', occasion_id,
                                            'details', product_data
                                        )::TEXT;
                                END IF;

                                PERFORM public.validate_product_price_update(product_id,price_val,product_data->'data',left(product_data->>'currency_code',3));
                                UPDATE eshop.products
                                   SET
                                       updated_at = now_ts,
                                       title = product_data->>'title',
                                       description = product_data->>'description',
                                       price = price_val,
                                       currency_code = left(product_data->>'currency_code', 3),
                                       data = product_data->'data',
                                       is_hidden = COALESCE((product_data->>'is_hidden')::BOOLEAN, false),
                                       "order" = NULLIF(product_data->>'order','')::BIGINT,
                                       maximum = NULLIF(product_data->>'maximum','')::BIGINT
                                 WHERE id = product_id
                                   AND product_type = product_type_id;
                            END IF;

                            PERFORM public.advance_ticketing_authoring_version_internal_v1('product',occasion_id,product_id);
                            product_array_data := product_array_data || product_data;
                        END LOOP;

                        product_type_data := jsonb_set(
                            product_type_data,
                            '{products}',
                            product_array_data
                        );
                    END IF;

                    ----------------------------------------------------------------------------
                    -- Store product_type_id in field_product_type for the form_fields table
                    ----------------------------------------------------------------------------
                    field_product_type := product_type_id;

                    ----------------------------------------------------------------------------
                    -- Merge updated product_type_data back into the field_data
                    ----------------------------------------------------------------------------
                    field_data := jsonb_set(field_data, '{product_type}', product_type_data);
                END IF;

                ----------------------------------------------------------------------------
                -- Insert or update the form_field itself
                ----------------------------------------------------------------------------
                IF field_id IS NOT NULL THEN
                    -- Update existing form_field
                    UPDATE public.form_fields
                       SET
                           title = field_data->>'title',
                           description = field_data->>'description',
                           data = field_data->'data',
                           type = field_data->>'type',
                           is_required = COALESCE((field_data->>'is_required')::BOOLEAN, false),
                           is_hidden = COALESCE((field_data->>'is_hidden')::BOOLEAN, false),
                           "order" = NULLIF(field_data->>'order','')::BIGINT,
                           product_type = field_product_type,
                           is_ticket_field = COALESCE((field_data->>'is_ticket_field')::BOOLEAN, false),
                           form = form_id
                     WHERE id = field_id
                       AND form = form_id;

                    IF NOT FOUND THEN
                        RAISE EXCEPTION '%',
                            JSONB_BUILD_OBJECT(
                                'code', 4012,
                                'message', 'No matching form_field found to update (or does not belong to this form)',
                                'details', field_data
                            )::TEXT;
                    END IF;
                ELSE
                    -- Insert new form_field
                    INSERT INTO public.form_fields (
                        created_at,
                        title,
                        description,
                        data,
                        type,
                        is_required,
                        form,
                        is_hidden,
                        "order",
                        product_type,
                        is_ticket_field
                    )
                    VALUES (
                        now_ts,
                        field_data->>'title',
                        field_data->>'description',
                        field_data->'data',
                        field_data->>'type',
                        COALESCE((field_data->>'is_required')::BOOLEAN, false),
                        form_id,
                        COALESCE((field_data->>'is_hidden')::BOOLEAN, false),
                        NULLIF(field_data->>'order','')::BIGINT,
                        field_product_type,
                        COALESCE((field_data->>'is_ticket_field')::BOOLEAN, false)
                    )
                    RETURNING id INTO field_id;

                    field_data := jsonb_set(field_data, '{id}', TO_JSONB(field_id));
                END IF;

                form_fields_data := form_fields_data || field_data;
            END LOOP;
        END IF;

        ----------------------------------------------------------------------------
        -- Validate that deadline_duration_seconds is zero, positive, or null
        ----------------------------------------------------------------------------
        IF (input_data->'data'->>'reminder_interval_seconds')::bigint < 0 THEN
            RAISE EXCEPTION 'reminder_interval_seconds must be zero or higher or null';
        END IF;
        deadline_val := NULLIF(input_data->>'deadline_duration_seconds','')::BIGINT;
        IF deadline_val IS NOT NULL AND deadline_val < 0 THEN
            RAISE EXCEPTION '%',
                JSONB_BUILD_OBJECT(
                    'code', 4016,
                    'message', 'deadline_duration_seconds must be zero or higher or null'
                )::TEXT;
        END IF;

        ----------------------------------------------------------------------------
        -- Validate bank_account belongs to the same unit as the occasion, if provided
        ----------------------------------------------------------------------------
        bank_account_val := NULLIF(input_data->>'bank_account','')::BIGINT;
        IF bank_account_val IS NOT NULL THEN
            SELECT ba.unit
              INTO bank_account_unit
              FROM eshop.unit_bank_accounts ba
             WHERE ba.bank_account = bank_account_val
               AND ba.unit = occasion_unit
             LIMIT 1;

            IF NOT FOUND THEN
                RAISE EXCEPTION '%',
                    JSONB_BUILD_OBJECT(
                        'code', 4020,
                        'message', 'Bank account not found',
                        'bank_account', bank_account_val
                    )::TEXT;
            END IF;

            IF bank_account_unit <> occasion_unit THEN
                RAISE EXCEPTION '%',
                    JSONB_BUILD_OBJECT(
                        'code', 4021,
                        'message', 'Bank account does not belong to the same unit as the occasion',
                        'bank_account_unit', bank_account_unit,
                        'occasion_unit', occasion_unit
                    )::TEXT;
            END IF;
        END IF;

        ----------------------------------------------------------------------------
        -- Update the main form record with all validated fields
        ----------------------------------------------------------------------------
        IF input_data->>'blueprint' IS NOT NULL AND NOT EXISTS(
          SELECT 1 FROM eshop.blueprints WHERE id=(input_data->>'blueprint')::bigint AND occasion=occasion_id) THEN
          RAISE EXCEPTION '%',jsonb_build_object('code',403,'message','Foreign blueprint')::text; END IF;
        PERFORM public.check_form_capacity_settings_internal(form_id,input_data);
        UPDATE public.forms
           SET
               participant_capacity = CASE WHEN input_data ? 'participant_capacity' THEN (input_data->>'participant_capacity')::integer ELSE participant_capacity END,
               waitlist_enabled = CASE WHEN input_data ? 'waitlist_enabled' THEN (input_data->>'waitlist_enabled')::boolean ELSE waitlist_enabled END,
               show_remaining_capacity = CASE WHEN input_data ? 'show_remaining_capacity' THEN (input_data->>'show_remaining_capacity')::boolean ELSE show_remaining_capacity END,
               waitlist_offer_duration_seconds = CASE WHEN input_data ? 'waitlist_offer_duration_seconds' THEN (input_data->>'waitlist_offer_duration_seconds')::integer ELSE waitlist_offer_duration_seconds END,
               capacity_revision = capacity_revision+1,
               title = CASE WHEN input_data ? 'title' THEN input_data->>'title' ELSE title END,
               data = CASE WHEN input_data ? 'data' THEN input_data->'data' ELSE data END,
               header = CASE WHEN input_data ? 'header' THEN input_data->>'header' ELSE header END,
               header_off = CASE WHEN input_data ? 'header_off' THEN input_data->>'header_off' ELSE header_off END,
               link = link_param,
               blueprint = CASE WHEN input_data ? 'blueprint' THEN NULLIF(input_data->>'blueprint','')::BIGINT ELSE blueprint END,
               bank_account = CASE WHEN input_data ? 'bank_account' THEN bank_account_val ELSE bank_account END,
               deadline_duration_seconds = CASE WHEN input_data ? 'deadline_duration_seconds' THEN deadline_val ELSE deadline_duration_seconds END,
               is_open = CASE WHEN input_data ? 'is_open' THEN (input_data->>'is_open')::boolean ELSE is_open END
         WHERE id = form_id;

        ----------------------------------------------------------------------------
        -- After updating the form, requeue payment reminders for the whole occasion
        -- as the form's settings (e.g., is_reminder_enabled) might have changed.
        ----------------------------------------------------------------------------
        -- First, find the 'seconds_before_deadline' setting from the occasion's 'form' feature.
        SELECT (elem->>'reminder_interval_seconds')::BIGINT
          INTO v_seconds_before_deadline
          FROM public.occasions, jsonb_array_elements(features) AS elem
         WHERE id = occasion_id
           AND elem->>'code' = 'form'
         LIMIT 1;

        -- If the setting is found, call the function to rebuild the reminder queue.
        PERFORM public.queue_payment_reminders(occasion_id, COALESCE(v_seconds_before_deadline,86400));

        ----------------------------------------------------------------------------
        -- Prepare a success response
        ----------------------------------------------------------------------------
        result := JSONB_BUILD_OBJECT(
            'code', 200,
            'message', 'Form updated successfully',
            'form_id', form_id,
            'link', link_param,
            'form_fields', form_fields_data
        );

    EXCEPTION WHEN raise_exception THEN
        -- Catch any exception and attempt to parse it as JSON; if not JSON, wrap it in our own JSON.
        result := CASE
            WHEN left(SQLERRM, 1) = '{' THEN SQLERRM::JSONB
            ELSE JSONB_BUILD_OBJECT('code', 5001, 'message', SQLERRM)
        END;
    END;

    RETURN result;
END;
$$;

REVOKE ALL ON FUNCTION public.update_form_internal_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/eshop_forms/update_form_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.update_form_client_sync_v1(p_form jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path = public, extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_form bigint;
  v_begin jsonb; v_hash text; v_version bigint; v_expected bigint; v_users uuid[]; v_result jsonb; v_check record; v_current bigint;
BEGIN
  IF p_form IS NULL OR jsonb_typeof(p_form)<>'object'
    OR octet_length(p_form::text)>4194304 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid form aggregate'; END IF;
  v_occasion:=NULLIF(p_form->>'occasion','')::bigint;
  v_form:=NULLIF(p_form->>'id','')::bigint;
  IF v_actor IS NULL OR v_occasion IS NULL OR v_form IS NULL
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',v_occasion,'form',p_form)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.form.save',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.forms WHERE id=v_form AND occasion=v_occasion) THEN RAISE insufficient_privilege USING MESSAGE='foreign form'; END IF;
  -- Parent order matches checkout: form, product, blueprint, then seats.
  PERFORM 1 FROM public.forms WHERE id=v_form AND occasion=v_occasion FOR UPDATE;
  PERFORM 1 FROM eshop.product_types WHERE occasion=v_occasion ORDER BY id FOR UPDATE;
  PERFORM 1 FROM eshop.products WHERE occasion=v_occasion ORDER BY id FOR UPDATE;
  IF v_form IS NOT NULL THEN
    INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES('form','occasion',v_occasion,v_form::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='form' AND scope_type='occasion' AND scope_id=v_occasion AND aggregate_id=v_form::text FOR UPDATE;
  ELSE v_version:=0; END IF;
  -- Missing baseline remains an installed-client adapter, explicitly not MCP-ready.
  v_expected:=CASE WHEN p_form ? 'expected_aggregate_version' THEN (p_form->>'expected_aggregate_version')::bigint ELSE v_version END;
  IF v_expected IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('aggregate_version',v_version)); END IF;
  -- These maps were frozen when the editor loaded. No read-before-write rebasing.
  -- Missing maps are the bounded released-client facade, not MCP-ready authoring.
  IF p_form ? 'expected_product_versions' OR p_form ? 'expected_product_type_versions' THEN
    IF jsonb_typeof(p_form->'expected_product_versions') IS DISTINCT FROM 'object'
      OR jsonb_typeof(p_form->'expected_product_type_versions') IS DISTINCT FROM 'object' THEN
      RAISE invalid_parameter_value USING MESSAGE='original product versions required'; END IF;
    FOR v_check IN
      SELECT DISTINCT 'product'::text kind, (p->>'id')::bigint id FROM jsonb_array_elements(coalesce(p_form->'form_fields','[]')) f
        CROSS JOIN LATERAL jsonb_array_elements(coalesce(nullif(f#>'{product_type,products}','null'),'[]')) p WHERE p->>'id' IS NOT NULL
      UNION SELECT 'product',value::bigint FROM jsonb_array_elements_text(coalesce(p_form->'deleted_product_ids','[]'))
      UNION SELECT DISTINCT 'product',p.id FROM eshop.products p JOIN public.form_fields ff ON ff.product_type=p.product_type
        WHERE ff.form=v_form AND ff.id IN (SELECT value::bigint FROM jsonb_array_elements_text(coalesce(p_form->'deleted_field_ids','[]')))
      UNION SELECT DISTINCT 'product_type',(f#>>'{product_type,id}')::bigint FROM jsonb_array_elements(coalesce(p_form->'form_fields','[]')) f
        WHERE f#>>'{product_type,id}' IS NOT NULL
      ORDER BY 1,2
    LOOP
      IF NOT (CASE v_check.kind WHEN 'product' THEN p_form->'expected_product_versions'
        ELSE p_form->'expected_product_type_versions' END) ? v_check.id::text THEN
        RAISE invalid_parameter_value USING MESSAGE='missing original product baseline'; END IF;
      IF (v_check.kind='product' AND NOT EXISTS(SELECT 1 FROM eshop.products WHERE id=v_check.id AND occasion=v_occasion))
        OR (v_check.kind='product_type' AND NOT EXISTS(SELECT 1 FROM eshop.product_types WHERE id=v_check.id AND occasion=v_occasion)) THEN
        RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('entity_type',v_check.kind,'entity_id',v_check.id,'deleted',true)); END IF;
      SELECT coalesce(v.version,0) INTO v_current FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
        ON v.aggregate_type=v_check.kind AND v.scope_type='occasion' AND v.scope_id=v_occasion AND v.aggregate_id=v_check.id::text;
      IF ((CASE v_check.kind WHEN 'product' THEN p_form->'expected_product_versions' ELSE p_form->'expected_product_type_versions' END)->>v_check.id::text)::bigint IS DISTINCT FROM v_current THEN
        RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
          jsonb_build_object('aggregate_version',v_version,'entity_type',v_check.kind,'entity_id',v_check.id,'entity_version',v_current));
      END IF;
    END LOOP;
  END IF;
  SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
  FROM public.occasion_users ou JOIN eshop.order_product_ticket opt
    ON opt.ticket=ou.ticket JOIN eshop.products p ON p.id=opt.product
  WHERE ou.occasion=v_occasion AND p.occasion=v_occasion;
  BEGIN
    v_result:=public.update_form_internal_v1(p_form-'expected_aggregate_version'-'expected_product_versions'-'expected_product_type_versions');
    IF coalesce((v_result->>'code')::integer,500)<>200 THEN
      RAISE SQLSTATE 'P0F01' USING MESSAGE='authoring domain rejected'; END IF;
  EXCEPTION WHEN SQLSTATE 'P0F01' THEN NULL;
  END;
  IF coalesce((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      CASE WHEN (v_result->>'code')::integer BETWEEN 100 AND 599 THEN (v_result->>'code')::integer ELSE 400 END,v_result); END IF;
  v_form:=(v_result->>'form_id')::bigint;
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES('form','occasion',v_occasion,v_form::text,1)
    ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp()
    RETURNING version INTO v_version;
  v_result:=v_result||jsonb_build_object('aggregate_version',v_version,
    'product_versions',public.get_ticketing_product_versions_internal_v1(v_occasion,'product'),
    'product_type_versions',public.get_ticketing_product_versions_internal_v1(v_occasion,'product_type'));
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.form.save',jsonb_build_array(jsonb_build_object(
      'entityType','form','entityId',v_form,'operation','update',
      'safeLabel',left(p_form->>'title',240),'changedFields',jsonb_build_array(
        'configuration','products'))),v_users,v_result);
END; $function$;

REVOKE ALL ON FUNCTION public.update_form_client_sync_v1(jsonb,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_form_client_sync_v1(jsonb,uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.update_form(input_data jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE result jsonb;
BEGIN
 result:=public.update_form_client_sync_v1(input_data,extensions.gen_random_uuid());
 RETURN jsonb_build_object('code',result->'code')||result->'data';
END $$;
REVOKE ALL ON FUNCTION public.update_form(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_form(jsonb) TO authenticated;

-- Source: database/functions/eshop_forms/create_form_internal_v1.sql
CREATE OR REPLACE FUNCTION public.create_form_internal_v1(p_occasion_id bigint, p_link text, p_title text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    new_form_id BIGINT;
    new_form JSONB;
    new_product_type_id BIGINT;
    now TIMESTAMPTZ := NOW();
BEGIN
    PERFORM public.check_occasion_writable(p_occasion_id);
    IF auth.uid() IS NULL OR NOT (public.get_is_editor_on_occasion(p_occasion_id)
      OR public.get_is_editor_on_unit((SELECT unit FROM public.occasions WHERE id=p_occasion_id))) THEN
      RAISE insufficient_privilege USING MESSAGE='form editor required'; END IF;
    -- Create the new form
    INSERT INTO public.forms(
        title,
        is_open,
        link,
        occasion,
        created_at,
        updated_at,
        deadline_duration_seconds,
        data
    )
    VALUES (
        p_title,
        false,
        NULL,
        p_occasion_id,
        now,
        now,
        604800, -- Default to 7 days
        '{"is_reminder_enabled": true}'::jsonb -- Default reminder setting
    )
    RETURNING to_jsonb(public.forms.*) INTO new_form;

    new_form_id := (new_form->>'id')::BIGINT;

    UPDATE public.forms SET link=public.reserve_public_link_internal('form',new_form_id,p_link,true) WHERE id=new_form_id;
    SELECT to_jsonb(f) INTO new_form FROM public.forms f WHERE id=new_form_id;

    -- Create default 'email' and 'ticket' fields
    INSERT INTO public.form_fields(title, type, is_required, form, "order")
    VALUES ('', 'email', true, new_form_id, 0),
           ('', 'ticket', true, new_form_id, 1);

    -- Ensure 'spot' product type exists for the occasion
    IF NOT EXISTS (SELECT 1 FROM eshop.product_types WHERE occasion = p_occasion_id AND type = 'spot') THEN
        INSERT INTO eshop.product_types(title, type, occasion)
        VALUES ('Spot', 'spot', p_occasion_id)
        RETURNING id INTO new_product_type_id;
    ELSE
        SELECT id INTO new_product_type_id FROM eshop.product_types WHERE occasion = p_occasion_id AND type = 'spot' LIMIT 1;
    END IF;

    -- Ensure the 'spot' product type has at least one product
    IF NOT EXISTS (SELECT 1 FROM eshop.products WHERE occasion = p_occasion_id AND product_type = new_product_type_id) THEN
        INSERT INTO eshop.products(title, price, product_type, occasion, currency_code, "order")
        VALUES ('Variant 1', 100, new_product_type_id, p_occasion_id, 'CZK', 0);
    END IF;

    -- Create the 'product_type' form field linked to 'spot'
    INSERT INTO public.form_fields(title, type, is_required, form, "order", product_type, is_ticket_field)
    VALUES ('Spot', 'product_type', false, new_form_id, 2, new_product_type_id, true);

    -- Return the raw data of the newly created form
    RETURN new_form;
END;
$function$;
REVOKE ALL ON FUNCTION public.create_form_internal_v1(bigint,text,text) FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/eshop_forms/create_form_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.create_form_client_sync_v1(
  p_occasion_link text,p_link text,p_title text,p_command_id uuid
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_unit bigint;
  v_begin jsonb; v_hash text; v_form jsonb;
BEGIN
  SELECT o.id,o.unit INTO v_occasion,v_unit FROM public.occasions o
    WHERE o.id=public.resolve_occasion_link_internal(p_occasion_link);
  IF v_actor IS NULL OR v_occasion IS NULL
    OR length(p_link)>80 OR length(COALESCE(p_title,''))>500
    OR NOT (public.get_is_editor_on_unit(v_unit)
      OR public.get_is_editor_on_occasion(v_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',v_occasion,'link',p_link,'title',p_title)::text,'UTF8'),
    'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.form.create',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  v_form:=public.create_form_internal_v1(v_occasion,p_link,p_title);
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.form.create',jsonb_build_array(jsonb_build_object(
      'entityType','form','entityId',v_form->>'id','operation','insert',
      'safeLabel',left(p_title,240),'changedFields',jsonb_build_array(
        'configuration','fields','products'))),'{}'::uuid[],
    jsonb_build_object('form',v_form));
END; $$;
REVOKE ALL ON FUNCTION public.create_form_client_sync_v1(text,text,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_form_client_sync_v1(text,text,text,uuid) TO authenticated;

-- Source: database/functions/eshop/get_blueprint_for_edit.sql
CREATE OR REPLACE FUNCTION public.get_blueprint_for_edit(
    occasion_link TEXT
)
RETURNS JSONB
LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    blueprint_id BIGINT;
    blueprintData JSONB;
    spotsData JSONB;
    productsData JSONB;
    ticketsData JSONB;
    ordersData JSONB;
    orderProductTicketsData JSONB;
    valid_spots JSONB;
    occasion_id BIGINT;
BEGIN
    -- Resolve occasion_id using occasion_link
    SELECT id
    INTO occasion_id
    FROM public.occasions
    WHERE id = public.resolve_occasion_link_internal(occasion_link);

    -- Check if occasion_link is valid
    IF occasion_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Occasion link does not exist');
    END IF;

    -- Authorization check
    IF (SELECT get_is_editor_order_view_on_occasion(occasion_id)) <> TRUE THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to edit this occasion');
    END IF;

    -- Fetch the first blueprint_id for the occasion
    SELECT id
    INTO blueprint_id
    FROM eshop.blueprints
    WHERE occasion = occasion_id
    ORDER BY id
    LIMIT 1;

    -- Check if a blueprint exists for the occasion
    IF blueprint_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'No blueprint found for this occasion');
    END IF;

    -- Fetch blueprint details
    SELECT jsonb_build_object(
        'id', b.id,
        'aggregate_version',coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='blueprint' AND scope_type='occasion' AND scope_id=b.occasion AND aggregate_id=b.id::text),0),
        'created_at', b.created_at,
        'data', b.data,
        'title', b.title,
        'occasion', b.occasion,
        'organization', b.organization,
        'configuration', b.configuration,
        'objects', b.objects,
        'groups', b.groups,
        'background_svg', b.background_svg
    )
    INTO blueprintData
    FROM eshop.blueprints b
    WHERE b.id = blueprint_id;

    -- Fetch valid spot IDs
    SELECT jsonb_agg((obj->>'id')::BIGINT)
    INTO valid_spots
    FROM jsonb_array_elements(
        (SELECT objects FROM eshop.blueprints WHERE id = blueprint_id)
    ) obj
    WHERE obj->>'type' = 'spot'
      AND obj->>'id' IS NOT NULL;

    -- Fetch enriched spots data
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', s.id,
        'title', s.title,
        'product', s.product,
        'order_product_ticket', s.order_product_ticket,
        'state', CASE
          WHEN t.state = 'used' THEN 'used'
          WHEN s.order_product_ticket IS NOT NULL THEN 'ordered'
          WHEN s.secret IS NOT NULL AND s.secret_expiration_time > now() THEN 'selected'
          ELSE 'available'
        END
      )
    )
    INTO spotsData
    FROM eshop.spots s
    LEFT JOIN eshop.order_product_ticket opt ON s.order_product_ticket = opt.id
    LEFT JOIN eshop.tickets t ON opt.ticket = t.id
    WHERE s.id = ANY(SELECT jsonb_array_elements_text(valid_spots)::BIGINT)
      AND s.occasion = occasion_id;

    -- Fetch all products of type "spot", "taxi", "food"
    SELECT jsonb_agg(jsonb_build_object(
        'id', p.id,
            'aggregate_version',coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='product' AND scope_type='occasion' AND scope_id=p.occasion AND aggregate_id=p.id::text),0),
        'title', p.title,
        'price', p.price,
        'type', pt.type,
        'description', pt.description,
        'product_type', p.product_type,
        'currency_code', p.currency_code
    ))
    INTO productsData
    FROM eshop.products p
    JOIN eshop.product_types pt ON pt.id = p.product_type
    WHERE pt.occasion = occasion_id;

    -- Fetch relevant tickets associated with the order_product_ticket in spots
    SELECT jsonb_agg(jsonb_build_object(
        'id', t.id,
        'ticket_symbol', t.ticket_symbol,
        'state', t.state,
        'note', t.note,
        'note_hidden', t.note_hidden
    ))
    INTO ticketsData
    FROM eshop.tickets t
    JOIN eshop.order_product_ticket opt ON opt.ticket = t.id
    JOIN eshop.spots s ON s.order_product_ticket = opt.id
    WHERE s.id = ANY(SELECT jsonb_array_elements_text(valid_spots)::BIGINT)
      AND t.occasion = occasion_id;

    -- Fetch relevant orders associated with the order_product_ticket in spots
    SELECT jsonb_agg(jsonb_build_object(
        'id', o.id,
        'order_symbol', o.order_symbol,
        'order_sequence', o.order_sequence,
        'created_at', o.created_at,
        'updated_at', o.updated_at,
        'price', o.price,
        'state', o.state,
        'currency_code', o.currency_code,
        'data', jsonb_build_object('name', o.data->>'name', 'surname', o.data->>'surname', 'email', o.data->>'email', 'note', o.data->>'note')
    ))
    INTO ordersData
    FROM eshop.orders o
    JOIN eshop.order_product_ticket opt ON opt."order" = o.id
    JOIN eshop.spots s ON s.order_product_ticket = opt.id
    WHERE s.id = ANY(SELECT jsonb_array_elements_text(valid_spots)::BIGINT)
      AND o.occasion = occasion_id;

    -- Extract order IDs from ordersData JSONB
    WITH order_ids AS (
        SELECT (order_obj->>'id')::BIGINT AS id
        FROM jsonb_array_elements(ordersData) order_obj
    )
    -- Fetch relevant order-product-ticket data based on extracted order IDs
    SELECT jsonb_agg(jsonb_build_object(
            'id', opt.id,
            'order', opt."order",
            'product', opt.product,
            'ticket', opt.ticket,
            'created_at', opt.created_at
        ))
    INTO orderProductTicketsData
    FROM eshop.order_product_ticket opt
    WHERE opt."order" IN (SELECT id FROM order_ids);

    -- Add spots data to the blueprint object
    blueprintData = jsonb_set(
        blueprintData,
        '{spots}',
        COALESCE(spotsData, '[]'::jsonb)
    );

    -- Add products data to the blueprint object
    blueprintData = jsonb_set(
        blueprintData,
        '{products}',
        COALESCE(productsData, '[]'::jsonb)
    );

    -- Add relevant tickets data to the blueprint object
    blueprintData = jsonb_set(
        blueprintData,
        '{tickets}',
        COALESCE(ticketsData, '[]'::jsonb)
    );

    -- Add relevant orders data to the blueprint object
    blueprintData = jsonb_set(
        blueprintData,
        '{orders}',
        COALESCE(ordersData, '[]'::jsonb)
    );

    -- Add relevant order-product-ticket data to the blueprint object
    blueprintData = jsonb_set(
        blueprintData,
        '{order_product_ticket}',
        COALESCE(orderProductTicketsData, '[]'::jsonb)
    );

    -- Return combined data
    RETURN jsonb_build_object(
        'code', 200,
        'data', blueprintData
    );
END;
$$;

-- Source: database/functions/eshop_forms/get_form_for_edit.sql
-- Fix get_form_for_edit: Remove bigint = uuid comparison and add can_delete
CREATE OR REPLACE FUNCTION public.get_form_for_edit(form_link text)
 RETURNS jsonb
 LANGUAGE plpgsql STABLE
 SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_form_id BIGINT;
    v_occasion_id BIGINT;
    v_unit_id BIGINT;
    formData JSONB;
    formFieldsData JSONB;
    productTypesData JSONB;
    productsData JSONB;
    availableBankAccountsData JSONB;
    canDelete BOOLEAN;
BEGIN
    SELECT
        f.id,
        f.occasion,
        o.unit
    INTO
        v_form_id,
        v_occasion_id,
        v_unit_id
    FROM public.forms f
    JOIN public.occasions o ON f.occasion = o.id
    WHERE f.id = public.resolve_form_link_internal(form_link);

    IF v_form_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Form not found for the provided link.');
    END IF;

    PERFORM check_is_editor_order_view_via_form_link(form_link);

    -- Calculate can_delete
    -- FIXED: Compare form (bigint) with v_form_id (bigint) directly
    SELECT NOT EXISTS (
        SELECT 1 FROM eshop.orders WHERE form = v_form_id
    ) INTO canDelete;

    SELECT jsonb_build_object(
        'aggregate_version',coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='form' AND scope_type='occasion' AND scope_id=f.occasion AND aggregate_id=f.id::text),0),
        'id', f.id,'participant_capacity',f.participant_capacity,'waitlist_enabled',f.waitlist_enabled,
        'show_remaining_capacity',f.show_remaining_capacity,'waitlist_offer_duration_seconds',f.waitlist_offer_duration_seconds,
        'organizationIdentity',(SELECT CASE WHEN o.organization=u.organization THEN public.get_verified_unit_identity_internal(u.id) END FROM public.occasions o JOIN public.units u ON u.id=o.unit WHERE o.id=f.occasion),
        'capacity',public.get_form_capacity_snapshot_internal(f.id),'registrationMode',public.get_form_registration_mode_internal(f.id),
        'key', f.key,
        'is_open', f.is_open,
        'created_at', f.created_at,
        'data', f.data,
        'type', f.type,
        'title', f.title,
        'header', f.header,
        'header_off', f.header_off,
        'occasion', f.occasion,
        'blueprint', f.blueprint,
        'link', f.link,
        'bank_account', f.bank_account,
        'deadline_duration_seconds', f.deadline_duration_seconds,
        'can_delete', canDelete -- Added field
    )
    INTO formData
    FROM public.forms f
    WHERE f.id = v_form_id;

    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', pt.id,
            'aggregate_version',coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='product_type' AND scope_type='occasion' AND scope_id=pt.occasion AND aggregate_id=pt.id::text),0),
            'title', pt.title,
            'description', pt.description,
            'type', pt.type,
            'data', pt.data,
            'occasion', pt.occasion
        ) ORDER BY pt.title
    ), '[]'::jsonb)
    INTO productTypesData
    FROM eshop.product_types pt
    WHERE pt.occasion = v_occasion_id;

    -- Materialize occasion history once rather than scanning it for every
    -- product and every field. Only current orders and current references determine eligibility.
    WITH occasion_orders AS MATERIALIZED (
      SELECT id, data FROM eshop.orders WHERE occasion = v_occasion_id
    ), snapshots AS MATERIALIZED (
      SELECT data FROM occasion_orders
    ), used_products AS MATERIALIZED (
      SELECT opt.product::text AS product FROM eshop.order_product_ticket opt
      JOIN eshop.products p ON p.id = opt.product WHERE p.occasion = v_occasion_id
      UNION
      SELECT value #>> '{}' FROM snapshots s
      CROSS JOIN LATERAL jsonb_path_query(s.data, '$.tickets[*].products[*].id') ids(value)
    )
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', p.id,
            'aggregate_version',coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='product' AND scope_type='occasion' AND scope_id=p.occasion AND aggregate_id=p.id::text),0),
            'can_delete', usage.reason IS NULL,
            'delete_blocked_reason', usage.reason,
            'occasion', p.occasion,
            'title', p.title,
            'description', p.description,
            'price', p.price,
            'currency_code', p.currency_code,
            'is_hidden', p.is_hidden,
            'order', p."order",
            'product_type', p.product_type,
            'ordered_count', (
                SELECT count(*)
                FROM eshop.order_product_ticket opt
                JOIN eshop.orders o ON opt."order" = o.id
                WHERE opt.product = p.id AND o.state <> 'storno'
            ),
            'maximum', p.maximum,
            'data', p.data
        ) ORDER BY COALESCE(p."order", 0)
    ), '[]'::jsonb)
    INTO productsData
    FROM eshop.products p
    CROSS JOIN LATERAL (SELECT CASE
      WHEN EXISTS (SELECT 1 FROM used_products u WHERE u.product = p.id::text) THEN 'orders'
      WHEN EXISTS (SELECT 1 FROM eshop.spots s WHERE s.product = p.id) THEN 'blueprint'
      WHEN EXISTS (SELECT 1 FROM eshop.product_inventory_contexts pic WHERE pic.product = p.id) THEN 'inventory'
      WHEN (SELECT count(*) FROM public.form_fields ref WHERE ref.product_type = p.product_type) > 1 THEN 'shared'
    END AS reason) usage
    WHERE p.product_type IN (SELECT id FROM eshop.product_types WHERE occasion = v_occasion_id);

    WITH form_orders AS MATERIALIZED (
      SELECT id, data FROM eshop.orders WHERE form = v_form_id
    ), form_snapshots AS MATERIALIZED (
      SELECT data FROM form_orders
    ), form_tickets AS MATERIALIZED (
      SELECT t.note FROM eshop.order_product_ticket opt
      JOIN form_orders o ON o.id = opt."order"
      JOIN eshop.tickets t ON t.id = opt.ticket
    )
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', ff.id,
            'can_delete', usage.reason IS NULL,
            'delete_blocked_reason', usage.reason,
            'form', ff.form,
            'title', ff.title,
            'description', ff.description,
            'data', ff.data,
            'type', ff.type,
            'is_required', ff.is_required,
            'is_hidden', ff.is_hidden,
            'is_ticket_field', ff.is_ticket_field,
            'order', ff."order",
            'product_type', ff.product_type
        ) ORDER BY COALESCE(ff."order", 0)
    ), '[]'::jsonb)
    INTO formFieldsData
    FROM public.form_fields ff
    CROSS JOIN LATERAL (SELECT CASE WHEN EXISTS (
      SELECT 1 FROM form_snapshots s WHERE
        EXISTS (SELECT 1 FROM jsonb_array_elements(
          CASE WHEN jsonb_typeof(s.data->'fields') = 'array' THEN s.data->'fields' ELSE '[]'::jsonb END) answer
          WHERE answer ? ff.id::text AND answer->(ff.id::text) NOT IN ('null'::jsonb, '""'::jsonb, '[]'::jsonb, '{}'::jsonb))
        OR (ff.type = 'ticket' AND jsonb_path_exists(s.data, '$.tickets[*]'))
        OR (ff.type = 'note' AND ff.is_ticket_field AND jsonb_path_exists(s.data, '$.tickets[*] ? (@.note != null && @.note != "")'))
    ) OR (ff.type = 'ticket' AND EXISTS (SELECT 1 FROM form_tickets))
      OR (ff.type = 'note' AND ff.is_ticket_field AND EXISTS (SELECT 1 FROM form_tickets WHERE NULLIF(note, '') IS NOT NULL))
      OR EXISTS(SELECT 1 FROM eshop.tickets person CROSS JOIN LATERAL jsonb_array_elements(
        CASE WHEN jsonb_typeof(person.data->'fields')='array' THEN person.data->'fields' ELSE '[]' END) answer
        WHERE EXISTS(SELECT 1 FROM eshop.order_product_ticket x JOIN eshop.orders q ON q.id=x."order" WHERE x.ticket=person.id AND q.form=ff.form) AND answer ? ff.id::text AND answer->(ff.id::text) NOT IN ('null'::jsonb,'""'::jsonb,'[]'::jsonb,'{}'::jsonb))
      OR (ff.type='ticket' AND EXISTS(SELECT 1 FROM eshop.order_product_ticket x JOIN eshop.orders q ON q.id=x."order" WHERE x.ticket IS NOT NULL AND q.form=ff.form))
    THEN 'responses' ELSE (
      SELECT p->>'delete_blocked_reason' FROM public.form_fields member
      JOIN jsonb_array_elements(productsData) p ON (p->>'product_type')::bigint = member.product_type
      WHERE (member.id = ff.id OR (ff.type = 'ticket' AND member.form = ff.form AND member.is_ticket_field))
        AND p->>'delete_blocked_reason' IS NOT NULL
      ORDER BY (p->>'id')::bigint LIMIT 1
    ) END AS reason) usage
    WHERE ff.form = v_form_id;

    -- FIX: Exclude CASH accounts and ensure deterministic sorting by Priority
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', ba.id,
            'account_number', ba.account_number,
            'account_number_human_readable', ba.account_number_human_readable,
            'title', ba.title,
            'supported_currencies', ba.supported_currencies,
            'type', ba.type
        ) ORDER BY uba.priority ASC, ba.id ASC
    ), '[]'::jsonb)
    INTO availableBankAccountsData
    FROM eshop.unit_bank_accounts uba
    JOIN eshop.bank_accounts ba ON uba.bank_account = ba.id
    WHERE uba.unit = v_unit_id
      AND (ba.type IS DISTINCT FROM 'CASH'); -- EXCLUDE CASH ACCOUNTS

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'form', formData,
            'form_fields', formFieldsData,
            'product_types', productTypesData,
            'products', productsData,
            'available_bank_accounts', availableBankAccountsData
        )
    );
END;
$$;

-- Source: database/functions/eshop/ticketing_authoring_reads.sql
CREATE OR REPLACE FUNCTION public.get_blueprint_for_authoring_v1(p_blueprint bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE oc bigint; result jsonb;
BEGIN
 SELECT occasion INTO oc FROM eshop.blueprints WHERE id=p_blueprint;
 IF auth.uid() IS NULL OR oc IS NULL OR public.get_is_editor_order_view_on_occasion(oc) IS NOT TRUE THEN
  RAISE insufficient_privilege USING MESSAGE='order editor view required'; END IF;
 SELECT jsonb_build_object('id',b.id,'occasion',b.occasion,'organization',b.organization,'title',b.title,
  'aggregate_version',coalesce(v.version,0),'configuration',b.configuration,'groups',b.groups,'background_svg',b.background_svg,
  'objects',coalesce((SELECT jsonb_agg(o-ARRAY['secret','secret_expiration_time','order_product_ticket','state']) FROM jsonb_array_elements(b.objects) o),'[]'),
  'spots',coalesce((SELECT jsonb_agg(jsonb_build_object('id',s.id,'product',s.product,'title',s.title,
   'occupied',s.order_product_ticket IS NOT NULL,'held',s.secret IS NOT NULL AND s.secret_expiration_time>statement_timestamp()) ORDER BY s.id)
   FROM eshop.spots s WHERE s.blueprint=b.id AND s.occasion=oc),'[]')) INTO result
 FROM eshop.blueprints b LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='blueprint'
 AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=b.id::text WHERE b.id=p_blueprint;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.get_blueprint_for_authoring_v1(bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_blueprint_for_authoring_v1(bigint) TO authenticated;

CREATE OR REPLACE FUNCTION public.get_form_for_authoring_v1(p_form bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE result jsonb; link text;
BEGIN
 SELECT f.link INTO link FROM public.forms f WHERE f.id=p_form;
 IF link IS NULL THEN RAISE insufficient_privilege USING MESSAGE='form unavailable'; END IF;
 -- Reuse field/product eligibility and permission rules; omit form capabilities.
 result:=public.get_form_for_edit(link);
 IF result->>'code'<>'200' THEN RETURN result; END IF;
 RETURN jsonb_set(result,'{data,form}',(result#>'{data,form}')-ARRAY['key','secret']);
END $$;
REVOKE ALL ON FUNCTION public.get_form_for_authoring_v1(bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_form_for_authoring_v1(bigint) TO authenticated;

-- Source: database/functions/inventory/update_product_inventory_contexts.sql
CREATE OR REPLACE FUNCTION public.update_product_inventory_contexts_internal_v1(p_product_id bigint, p_contexts jsonb)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions AS $$
DECLARE
  v_occasion_id BIGINT;
  v_order_id BIGINT;
BEGIN
    -- Get the occasion ID from the product that is being modified.
    SELECT pt.occasion INTO v_occasion_id
    FROM eshop.products p
    JOIN eshop.product_types pt ON p.product_type = pt.id
    WHERE p.id = p_product_id;

    -- If the product is not found, raise an error.
    IF NOT FOUND THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'code', 'PI404',
            'message', 'Product with ID ' || p_product_id || ' not found.'
        )::text;
    END IF;

    -- Permission check. This function is expected to throw on failure.
    PERFORM public.check_is_editor_order_on_occasion(v_occasion_id);

    -- Every caller, including aggregate saves, uses this validation owner.
    IF p_contexts IS NULL OR jsonb_typeof(p_contexts) IS DISTINCT FROM 'array'
      OR jsonb_array_length(p_contexts)>1000 OR octet_length(p_contexts::text)>1048576
      OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_contexts) c
        LEFT JOIN public.inventory_contexts ic ON ic.id=(c->>'inventory_context_id')::bigint
        LEFT JOIN public.inventory_pools pool ON pool.id=ic.inventory_pool
        WHERE pool.occasion IS DISTINCT FROM v_occasion_id OR (c->>'quantity')::integer IS NULL
          OR (c->>'quantity')::integer<0
          OR EXISTS(SELECT 1 FROM jsonb_object_keys(c) k WHERE k NOT IN ('inventory_context_id','quantity')))
      OR (SELECT count(*) FROM jsonb_array_elements(p_contexts))<>
        (SELECT count(DISTINCT (c->>'inventory_context_id')::bigint) FROM jsonb_array_elements(p_contexts) c)
    THEN RAISE invalid_parameter_value USING MESSAGE='invalid or foreign inventory contexts'; END IF;
    PERFORM public.lock_product_order_dependencies_internal_v1(p_product_id);
    PERFORM 1 FROM eshop.products WHERE id=p_product_id FOR UPDATE;
    PERFORM 1 FROM public.inventory_pools WHERE id IN(SELECT inventory_pool FROM public.inventory_contexts WHERE id IN
      (SELECT inventory_context FROM eshop.product_inventory_contexts WHERE product=p_product_id UNION SELECT (x->>'inventory_context_id')::bigint FROM jsonb_array_elements(p_contexts) x)) ORDER BY id FOR UPDATE;
    PERFORM 1 FROM public.inventory_contexts WHERE id IN
      (SELECT inventory_context FROM eshop.product_inventory_contexts WHERE product=p_product_id UNION SELECT (x->>'inventory_context_id')::bigint FROM jsonb_array_elements(p_contexts) x) ORDER BY id FOR UPDATE;
    -- If permission check passes, proceed with the update.
    -- First, remove all existing inventory context associations.
    DELETE FROM eshop.product_inventory_contexts
    WHERE product = p_product_id;

    -- Then, insert the new associations from the provided JSON array.
    IF jsonb_array_length(p_contexts) > 0 THEN
      INSERT INTO eshop.product_inventory_contexts (product, inventory_context, quantity)
      SELECT
        p_product_id,
        (context ->> 'inventory_context_id')::bigint,
        (context ->> 'quantity')::integer
      FROM jsonb_array_elements(p_contexts) AS context;
    END IF;


    -- After updating the product's context associations, re-run allocations
    -- for all orders that contain this product.
    FOR v_order_id IN
      SELECT DISTINCT opt."order"
      FROM eshop.order_product_ticket opt
      WHERE opt.product = p_product_id ORDER BY opt."order"
    LOOP
      -- This will re-evaluate spot allocations for each affected order.
      PERFORM apply_allocations(v_order_id);
    END LOOP;

    PERFORM public.advance_ticketing_authoring_version_internal_v1('product',v_occasion_id,p_product_id);

END;
$$;
REVOKE ALL ON FUNCTION public.update_product_inventory_contexts_internal_v1(bigint,jsonb) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.update_product_inventory_contexts(p_product_id bigint,p_contexts jsonb)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.update_product_inventory_contexts_client_sync_v1(p_product_id,p_contexts,extensions.gen_random_uuid());
END $$;
REVOKE ALL ON FUNCTION public.update_product_inventory_contexts(bigint,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_product_inventory_contexts(bigint,jsonb) TO authenticated;

-- Source: database/functions/eshop/update_product.sql

CREATE OR REPLACE FUNCTION public.update_product_internal_v1(p_input JSONB)
RETURNS BIGINT LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, extensions AS $$
DECLARE
  v_product_id BIGINT;
  v_occasion_id BIGINT;
  v_product_type_id BIGINT;
  v_existing_price NUMERIC;
  v_input_price NUMERIC;
  v_effective_price NUMERIC;
  v_input_deposit NUMERIC;
BEGIN
  -- Extract product id from the input JSON
  v_product_id := (p_input->>'id')::BIGINT;

  -- Try to find the product to determine if we are updating or creating.
  -- This also gets the *current* occasion for the permission check on UPDATE.
  IF v_product_id IS NOT NULL THEN
    SELECT pt.occasion, p.price
    INTO v_occasion_id, v_existing_price
    FROM eshop.products p
    JOIN eshop.product_types pt ON p.product_type = pt.id
    WHERE p.id = v_product_id FOR UPDATE OF p;
  END IF;

  -- CASE 1: Product was found (v_product_id was not null and existed)
  IF FOUND THEN
    -- We are UPDATING.

    -- Ensure the caller has permission to edit this product's *current* occasion.
    -- This function is expected to raise an exception on failure.
    PERFORM public.check_is_editor_order_on_occasion(v_occasion_id);

    -- VALIDATION: deposit amount must be less than effective price (input price overrides existing)
    v_input_price := NULLIF(p_input->>'price', '')::NUMERIC;
    v_effective_price := COALESCE(v_input_price, v_existing_price);
    v_input_deposit := NULLIF(p_input->'data'->'deposit'->>'amount', '')::NUMERIC;
    IF v_input_deposit IS NOT NULL AND v_input_deposit > 0
       AND v_effective_price IS NOT NULL AND v_input_deposit >= v_effective_price THEN
      RAISE EXCEPTION '%', jsonb_build_object(
          'code', 'DEPOSIT_AMOUNT_TOO_HIGH',
          'message', 'Deposit amount (' || v_input_deposit || ') must be less than price (' || v_effective_price || ').'
      )::text;
    END IF;

    PERFORM public.validate_product_price_update(v_product_id,v_effective_price,
      COALESCE(p_input->'data',(SELECT data FROM eshop.products WHERE id=v_product_id)),
      COALESCE(p_input->>'currency_code',(SELECT currency_code FROM eshop.products WHERE id=v_product_id)));
    -- A product with schedules cannot silently move to another occasion/type.
    IF EXISTS (SELECT 1 FROM eshop.planned_changes WHERE subject_id=v_product_id
      AND change_type IN('products.price','products.is_hidden') AND NOT applied) AND (
      NULLIF(p_input->>'occasion','')::bigint IS DISTINCT FROM v_occasion_id AND p_input->>'occasion' IS NOT NULL
      OR NULLIF(p_input->>'product_type','')::bigint IS DISTINCT FROM
        (SELECT product_type FROM eshop.products WHERE id=v_product_id) AND p_input->>'product_type' IS NOT NULL
    ) THEN RAISE EXCEPTION 'CANCEL_PRICE_CHANGES_BEFORE_PRODUCT_MOVE'; END IF;

    IF p_input->>'product_type' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.product_types WHERE id=(p_input->>'product_type')::bigint AND occasion=v_occasion_id) THEN RAISE EXCEPTION 'Product type occasion mismatch'; END IF;
    IF p_input->>'occasion' IS NOT NULL AND (p_input->>'occasion')::bigint<>v_occasion_id THEN RAISE EXCEPTION 'Product occasion cannot change'; END IF;
    -- Update only the fields that are provided in the input JSON.
    -- COALESCE is used to keep the existing value if a new one isn't provided.
    -- NULLIF is added to safely handle empty strings '' during casting.
    PERFORM 1 FROM public.occasions WHERE id=v_occasion_id FOR UPDATE;
    IF p_input ? 'product_type' AND NULLIF(p_input->>'product_type','')::bigint IS DISTINCT FROM (SELECT product_type FROM eshop.products WHERE id=v_product_id)
      AND EXISTS(SELECT 1 FROM eshop.order_product_ticket WHERE product=v_product_id)
    THEN RAISE EXCEPTION 'Purchased product type cannot change'; END IF;
    IF nullif(p_input->>'maximum','')::integer>0 AND
      nullif(p_input->>'maximum','')::integer<(SELECT count(*) FROM eshop.order_product_ticket WHERE product=v_product_id) THEN
      RAISE EXCEPTION 'PRODUCT_CAPACITY_BELOW_COMMITTED'; END IF;
    UPDATE eshop.products p
    SET
      occasion      = COALESCE(NULLIF(p_input->>'occasion', '')::BIGINT, p.occasion),
      title         = COALESCE(p_input->>'title',         p.title),
      description   = COALESCE(p_input->>'description',   p.description),
      price         = COALESCE(NULLIF(p_input->>'price', '')::NUMERIC, p.price),
      currency_code = COALESCE(p_input->>'currency_code', p.currency_code),
      data          = COALESCE(p_input->'data',           p.data),
      product_type  = COALESCE(NULLIF(p_input->>'product_type', '')::BIGINT, p.product_type),
      "order"       = COALESCE(NULLIF(p_input->>'order', '')::INT,  p."order"),
      maximum       = COALESCE(NULLIF(p_input->>'maximum', '')::INT, p.maximum),
      is_hidden     = COALESCE(NULLIF(p_input->>'is_hidden', '')::BOOLEAN, p.is_hidden),
      updated_at    = NOW()
    WHERE p.id = v_product_id;

    -- Return the ID of the updated product on success.
    IF p_input ? 'inventory_contexts' THEN
      PERFORM public.update_product_inventory_contexts_internal_v1(v_product_id,p_input->'inventory_contexts');
    END IF;
    IF NOT (p_input ? 'inventory_contexts') THEN
      PERFORM public.advance_ticketing_authoring_version_internal_v1('product',v_occasion_id,v_product_id);
    END IF;
    RETURN v_product_id;

  -- CASE 2: Product was NOT found (v_product_id was NULL or was an ID that doesn't exist)
  ELSE
    -- We are CREATING, as per the request.

    -- 1. Get the product_type from the JSON.
    v_product_type_id := (p_input->>'product_type')::BIGINT;

    -- 2. Validate product_type is provided (it's required for creation).
    IF v_product_type_id IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
          'code', 'PRD422',
          'message', 'Field "product_type" is required when creating a new product.'
      )::text;
    END IF;

    -- 3. Find the occasion for the *new* product_type to check permissions.
    SELECT occasion
    INTO v_occasion_id
    FROM eshop.product_types
    WHERE id = v_product_type_id;

    -- 4. Handle invalid product_type.
    IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object(
          'code', 'PTY404',
          'message', 'Product type with ID ' || v_product_type_id || ' not found.'
      )::text;
    END IF;

    -- 5. Ensure the caller has permission to create a product on this occasion.
    PERFORM public.check_is_editor_order_on_occasion(v_occasion_id);

    -- 6. VALIDATION: deposit amount must be less than price (both from input on CREATE)
    v_input_price := NULLIF(p_input->>'price', '')::NUMERIC;
    v_input_deposit := NULLIF(p_input->'data'->'deposit'->>'amount', '')::NUMERIC;
    IF v_input_deposit IS NOT NULL AND v_input_deposit > 0
       AND v_input_price IS NOT NULL AND v_input_deposit >= v_input_price THEN
      RAISE EXCEPTION '%', jsonb_build_object(
          'code', 'DEPOSIT_AMOUNT_TOO_HIGH',
          'message', 'Deposit amount (' || v_input_deposit || ') must be less than price (' || v_input_price || ').'
      )::text;
    END IF;

    PERFORM public.validate_product_price(v_input_price,p_input->'data',p_input->>'currency_code');

    -- 7. Insert the new product.
    -- We ignore the `id` from the JSON (v_product_id) and let the sequence generate a new one.
    -- We use NULLIF to safely cast potentially empty strings.
    INSERT INTO eshop.products (
      occasion,
      title,
      description,
      price,
      currency_code,
      data,
      product_type,
      "order",
      maximum,
      is_hidden
      -- created_at and updated_at are assumed to have defaults (e.g., NOW())
    )
    VALUES (
      v_occasion_id,
      p_input->>'title',
      p_input->>'description',
      NULLIF(p_input->>'price', '')::NUMERIC,
      p_input->>'currency_code',
      p_input->'data',
      v_product_type_id, -- We already extracted and validated this
      NULLIF(p_input->>'order', '')::INT,
      NULLIF(p_input->>'maximum', '')::INT,
      -- Default to 'false' if is_hidden is not provided on create
      COALESCE(NULLIF(p_input->>'is_hidden', '')::BOOLEAN, false)
    )
    RETURNING id INTO v_product_id; -- Get the newly created ID

    -- Return the ID of the newly created product.
    IF p_input ? 'inventory_contexts' THEN
      PERFORM public.update_product_inventory_contexts_internal_v1(v_product_id,p_input->'inventory_contexts');
    END IF;
    IF NOT (p_input ? 'inventory_contexts') THEN
      PERFORM public.advance_ticketing_authoring_version_internal_v1('product',v_occasion_id,v_product_id);
    END IF;
    RETURN v_product_id;

  END IF;
END;
$$;
REVOKE ALL ON FUNCTION public.update_product_internal_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.update_product(p_input jsonb)
RETURNS bigint LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 RETURN (public.update_product_client_sync_v1(p_input,extensions.gen_random_uuid())->'data'->>'productId')::bigint;
END $$;
REVOKE ALL ON FUNCTION public.update_product(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_product(jsonb) TO authenticated;

-- Source: database/functions/eshop/update_product_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.update_product_client_sync_v1(p_product jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_product bigint; v_occasion bigint;
  v_begin jsonb; v_hash text; v_users uuid[]; v_version bigint; v_expected bigint;
BEGIN
  IF p_product IS NULL OR jsonb_typeof(p_product)<>'object'
    OR octet_length(p_product::text)>524288 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid product aggregate'; END IF;
  v_product:=NULLIF(p_product->>'id','')::bigint;
  SELECT occasion INTO v_occasion FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=v_actor AND command_name='inventory.product.save';
  IF NOT FOUND THEN
  IF v_product IS NOT NULL THEN
    SELECT p.occasion INTO v_occasion FROM eshop.products p WHERE p.id=v_product;
  ELSE
    SELECT pt.occasion INTO v_occasion FROM eshop.product_types pt
      WHERE pt.id=NULLIF(p_product->>'product_type','')::bigint;
  END IF;
  END IF;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  IF jsonb_typeof(p_product->'inventory_contexts')='array' THEN
    p_product:=jsonb_set(p_product,'{inventory_contexts}',coalesce((SELECT jsonb_agg(c ORDER BY (c->>'inventory_context_id')::bigint)
      FROM jsonb_array_elements(p_product->'inventory_contexts') c),'[]')); END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',v_occasion,'product',p_product)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.product.save',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF v_product IS NOT NULL THEN
    SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
    FROM eshop.order_product_ticket opt JOIN public.occasion_users ou
      ON ou.ticket=opt.ticket AND ou.occasion=v_occasion
    WHERE opt.product=v_product;
  ELSE v_users:='{}'::uuid[]; END IF;
  -- Context replacement recalculates allocations: acquire the same outer order
  -- parents before saving a product, never product then order in this command.
  PERFORM public.lock_product_order_dependencies_internal_v1(v_product);
  IF v_product IS NOT NULL THEN
    PERFORM 1 FROM eshop.products WHERE id=v_product AND occasion=v_occasion FOR UPDATE;
    SELECT coalesce(v.version,0) INTO v_version FROM (SELECT 1) seed
    LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='product'
    AND v.scope_type='occasion' AND v.scope_id=v_occasion AND v.aggregate_id=v_product::text;
    -- Released scalar facades may omit this control until their explicit upgrade gate.
    v_expected:=CASE WHEN p_product ? 'expected_aggregate_version'
      THEN (p_product->>'expected_aggregate_version')::bigint ELSE v_version END;
    IF v_expected IS DISTINCT FROM v_version THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
        jsonb_build_object('productId',v_product,'aggregate_version',v_version)); END IF;
  ELSIF p_product->>'expected_aggregate_version' IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new product cannot have expected version';
  END IF;
  v_product:=public.update_product_internal_v1(p_product-'expected_aggregate_version');
  SELECT version INTO v_version FROM public.client_aggregate_versions WHERE aggregate_type='product'
    AND scope_type='occasion' AND scope_id=v_occasion AND aggregate_id=v_product::text;
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.product.save',jsonb_build_array(jsonb_build_object(
      'entityType','product','entityId',v_product,'operation',
      CASE WHEN p_product->>'id' IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_product->>'title',240),'changedFields',jsonb_build_array(
        'configuration','contexts'))),v_users,jsonb_build_object('productId',v_product,'aggregate_version',v_version));
END; $function$;
REVOKE ALL ON FUNCTION public.update_product_client_sync_v1(jsonb,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_product_client_sync_v1(jsonb,uuid) TO authenticated;

-- Source: database/functions/inventory/update_product_inventory_contexts_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.update_product_inventory_contexts_client_sync_v1(p_product_id bigint, p_contexts jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_users uuid[]; v_expected bigint; v_version bigint; v_versioned boolean:=false;
BEGIN
  IF jsonb_typeof(p_contexts)='object' THEN
    IF jsonb_typeof(p_contexts->'contexts') IS DISTINCT FROM 'array'
      OR NOT p_contexts ? 'expected_aggregate_version'
      OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_contexts) k WHERE k NOT IN ('contexts','expected_aggregate_version')) THEN
      RAISE invalid_parameter_value USING MESSAGE='invalid context revision envelope'; END IF;
    v_versioned:=true;v_expected:=(p_contexts->>'expected_aggregate_version')::bigint;
    p_contexts:=p_contexts->'contexts';
  END IF;
  SELECT occasion INTO v_occasion FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=v_actor AND command_name='inventory.product.contexts';
  IF NOT FOUND THEN
  SELECT p.occasion INTO v_occasion FROM eshop.products p WHERE p.id=p_product_id;
  END IF;
  IF v_actor IS NULL OR v_occasion IS NULL OR p_contexts IS NULL
    OR jsonb_typeof(p_contexts)<>'array' OR jsonb_array_length(p_contexts)>1000
    OR octet_length(p_contexts::text)>1048576
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='inventory editor required'; END IF;
  SELECT coalesce(jsonb_agg(c ORDER BY (c->>'inventory_context_id')::bigint),'[]') INTO p_contexts FROM jsonb_array_elements(p_contexts) c;
  v_hash:=encode(extensions.digest(convert_to((jsonb_build_object(
    'productId',p_product_id,'contexts',p_contexts) || CASE WHEN v_versioned THEN jsonb_build_object('expectedVersion',v_expected) ELSE '{}'::jsonb END)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.product.contexts',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_contexts) c
      LEFT JOIN public.inventory_contexts ic
        ON ic.id=(c->>'inventory_context_id')::bigint
      LEFT JOIN public.inventory_pools ip ON ip.id=ic.inventory_pool
      WHERE ip.occasion IS DISTINCT FROM v_occasion
        OR COALESCE((c->>'quantity')::integer,0)<0)
 THEN RAISE insufficient_privilege USING MESSAGE='foreign inventory context'; END IF;

  SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
  FROM eshop.order_product_ticket opt JOIN public.occasion_users ou
    ON ou.ticket=opt.ticket AND ou.occasion=v_occasion
  WHERE opt.product=p_product_id;
  PERFORM public.lock_product_order_dependencies_internal_v1(p_product_id);
  PERFORM 1 FROM eshop.products WHERE id=p_product_id AND occasion=v_occasion FOR UPDATE;
  SELECT coalesce(v.version,0) INTO v_version FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
    ON v.aggregate_type='product' AND v.scope_type='occasion' AND v.scope_id=v_occasion AND v.aggregate_id=p_product_id::text;
  IF v_versioned AND v_expected IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('productId',p_product_id,'aggregate_version',v_version)); END IF;
  PERFORM public.update_product_inventory_contexts_internal_v1(
    p_product_id,p_contexts);
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.product.contexts',jsonb_build_array(jsonb_build_object(
      'entityType','product_inventory_context','entityId',p_product_id,
      'operation','update','safeLabel','Product inventory contexts',
      'changedFields',jsonb_build_array('contexts'))),v_users,
    jsonb_build_object('productId',p_product_id,'aggregate_version',v_version+1));
END; $function$;
REVOKE ALL ON FUNCTION public.update_product_inventory_contexts_client_sync_v1(bigint,jsonb,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_product_inventory_contexts_client_sync_v1(bigint,jsonb,uuid) TO authenticated;

-- Source: database/functions/eshop/product_price_waves.sql
-- Shared terms only. The existing planned_changes queue remains the executor input.
CREATE TABLE IF NOT EXISTS eshop.product_price_waves (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  occasion bigint NOT NULL REFERENCES public.occasions(id) ON DELETE CASCADE,
  change_time timestamptz NOT NULL,
  revision bigint NOT NULL DEFAULT 1,
  UNIQUE(occasion,change_time)
);
ALTER TABLE eshop.product_price_waves ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE eshop.product_price_waves FROM PUBLIC,anon,authenticated;
REVOKE ALL ON SEQUENCE eshop.product_price_waves_id_seq FROM PUBLIC,anon,authenticated;
ALTER TABLE eshop.planned_changes ADD COLUMN IF NOT EXISTS wave_id bigint
  REFERENCES eshop.product_price_waves(id) ON DELETE SET NULL;
CREATE UNIQUE INDEX IF NOT EXISTS planned_product_wave_target_unique
  ON eshop.planned_changes(wave_id,subject_id,change_type)
  WHERE wave_id IS NOT NULL AND NOT applied;

CREATE OR REPLACE FUNCTION public.check_product_wave_editor(p_occasion bigint)
RETURNS void LANGUAGE plpgsql SET search_path=public,extensions AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.occasions o
    JOIN public.user_info ui ON ui.organization=o.organization
    WHERE o.id=p_occasion AND ui.id=auth.uid()) THEN
    RAISE insufficient_privilege USING MESSAGE='ORDER_EDITOR_REQUIRED';
  END IF;
  PERFORM public.check_is_editor_order_on_occasion(p_occasion);
END; $$;
REVOKE ALL ON FUNCTION public.check_product_wave_editor(bigint) FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public.create_product_price_wave(p_occasion_link text,p_change_time timestamptz)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_occasion bigint; v_wave eshop.product_price_waves%ROWTYPE;
BEGIN
  SELECT o.id INTO STRICT v_occasion FROM public.occasions o JOIN public.user_info ui
    ON ui.organization=o.organization WHERE o.id=public.resolve_occasion_link_internal(p_occasion_link) AND ui.id=auth.uid();
  PERFORM public.check_product_wave_editor(v_occasion);
  IF p_change_time IS NULL OR NOT isfinite(p_change_time) OR p_change_time<=clock_timestamp() THEN
    RAISE invalid_parameter_value USING MESSAGE='FUTURE_TIME_REQUIRED'; END IF;
  INSERT INTO eshop.product_price_waves(occasion,change_time) VALUES(v_occasion,p_change_time)
    ON CONFLICT(occasion,change_time) DO NOTHING;
  SELECT * INTO STRICT v_wave FROM eshop.product_price_waves
    WHERE occasion=v_occasion AND change_time=p_change_time FOR UPDATE;
  -- Adopt existing unambiguous targets at this shared term without repricing.
  PERFORM 1 FROM eshop.products p WHERE p.occasion=v_occasion AND EXISTS(
    SELECT 1 FROM eshop.planned_changes pc WHERE pc.subject_id=p.id AND pc.occasion=v_occasion
      AND pc.change_time=p_change_time AND pc.change_type IN('products.price','products.is_hidden') AND NOT pc.applied)
    ORDER BY p.id FOR UPDATE;
  UPDATE eshop.planned_changes pc SET wave_id=v_wave.id
    WHERE pc.occasion=v_occasion AND pc.change_time=p_change_time AND NOT pc.applied AND pc.wave_id IS NULL
      AND pc.change_type IN('products.price','products.is_hidden') AND EXISTS(
        SELECT 1 FROM eshop.products p JOIN eshop.product_types pt ON pt.id=p.product_type
        WHERE p.id=pc.subject_id AND p.occasion=v_occasion AND pt.occasion=v_occasion)
      AND (SELECT count(*) FROM eshop.planned_changes other WHERE other.subject_id=pc.subject_id
        AND other.change_type=pc.change_type AND other.change_time=pc.change_time AND NOT other.applied)=1;
  IF p_change_time<=clock_timestamp() THEN RAISE invalid_parameter_value USING MESSAGE='FUTURE_TIME_REQUIRED'; END IF;
  RETURN to_jsonb(v_wave);
END; $$;
REVOKE ALL ON FUNCTION public.create_product_price_wave(text,timestamptz) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_product_price_wave(text,timestamptz) TO authenticated;

CREATE OR REPLACE FUNCTION public.save_product_wave_target(
  p_wave_id bigint,p_product_id bigint,p_expected_wave_revision bigint,p_price numeric,p_is_hidden boolean,
  p_expected_price_revision bigint DEFAULT NULL,p_expected_visibility_revision bigint DEFAULT NULL
) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_wave eshop.product_price_waves%ROWTYPE; v_product eshop.products%ROWTYPE;
  v_price eshop.planned_changes%ROWTYPE; v_visibility eshop.planned_changes%ROWTYPE;
BEGIN
  SELECT * INTO STRICT v_wave FROM eshop.product_price_waves WHERE id=p_wave_id FOR UPDATE;
  PERFORM public.check_product_wave_editor(v_wave.occasion);
  IF v_wave.revision IS DISTINCT FROM p_expected_wave_revision THEN RAISE serialization_failure USING MESSAGE='PRICE_CHANGE_CONFLICT'; END IF;
  IF v_wave.change_time<=clock_timestamp() THEN RAISE invalid_parameter_value USING MESSAGE='FUTURE_TIME_REQUIRED'; END IF;
  SELECT * INTO STRICT v_product FROM eshop.products WHERE id=p_product_id FOR UPDATE;
  IF v_product.occasion IS DISTINCT FROM v_wave.occasion OR NOT EXISTS(
    SELECT 1 FROM eshop.product_types WHERE id=v_product.product_type AND occasion=v_wave.occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='PRODUCT_OCCASION_MISMATCH'; END IF;
  IF v_wave.change_time<=clock_timestamp() THEN RAISE invalid_parameter_value USING MESSAGE='FUTURE_TIME_REQUIRED'; END IF;
  -- Lock in the same subject/plan order as the executor and single-product editor.
  PERFORM 1 FROM eshop.planned_changes WHERE subject_id=p_product_id AND wave_id=p_wave_id
    AND NOT applied ORDER BY id FOR UPDATE;
  SELECT * INTO v_price FROM eshop.planned_changes WHERE subject_id=p_product_id
    AND wave_id=p_wave_id AND change_type='products.price' AND NOT applied;
  SELECT * INTO v_visibility FROM eshop.planned_changes WHERE subject_id=p_product_id
    AND wave_id=p_wave_id AND change_type='products.is_hidden' AND NOT applied;
  IF v_price.revision IS DISTINCT FROM p_expected_price_revision OR
    v_visibility.revision IS DISTINCT FROM p_expected_visibility_revision THEN
    RAISE serialization_failure USING MESSAGE='PRICE_CHANGE_CONFLICT'; END IF;
  -- Seat products must not become unorderable while seats remain selectable.
  -- Keep an existing target on a price-only save; NULL explicitly cancels it.
  IF p_is_hidden IS NOT NULL AND EXISTS (
    SELECT 1 FROM eshop.spots s WHERE s.product=p_product_id AND s.occasion=v_wave.occasion
  ) AND (v_visibility.id IS NULL OR v_visibility.new_value IS DISTINCT FROM p_is_hidden::text) THEN
    RAISE invalid_parameter_value USING MESSAGE='BLUEPRINT_PRODUCT_VISIBILITY_NOT_SUPPORTED';
  END IF;
  IF EXISTS(SELECT 1 FROM eshop.planned_changes WHERE subject_id=p_product_id
    AND change_time=v_wave.change_time AND NOT applied AND wave_id IS DISTINCT FROM p_wave_id
    AND ((change_type='products.price' AND p_price IS NOT NULL) OR
         (change_type='products.is_hidden' AND p_is_hidden IS NOT NULL))) THEN
    RAISE serialization_failure USING MESSAGE='PRICE_CHANGE_CONFLICT'; END IF;
  IF p_price IS NOT NULL THEN
    PERFORM public.validate_product_price(p_price,v_product.data,v_product.currency_code);
    IF v_price.id IS NULL THEN
      INSERT INTO eshop.planned_changes(change_type,subject_id,new_value,change_time,occasion,wave_id)
        VALUES('products.price',p_product_id,p_price::text,v_wave.change_time,v_wave.occasion,p_wave_id);
    ELSE
      UPDATE eshop.planned_changes SET new_value=p_price::text,failed_at=NULL,failure_code=NULL,revision=revision+1 WHERE id=v_price.id;
    END IF;
  ELSIF v_price.id IS NOT NULL THEN DELETE FROM eshop.planned_changes WHERE id=v_price.id;
  END IF;
  IF p_is_hidden IS NOT NULL THEN
    IF v_visibility.id IS NULL THEN
      INSERT INTO eshop.planned_changes(change_type,subject_id,new_value,change_time,occasion,wave_id)
        VALUES('products.is_hidden',p_product_id,p_is_hidden::text,v_wave.change_time,v_wave.occasion,p_wave_id);
    ELSE
      UPDATE eshop.planned_changes SET new_value=p_is_hidden::text,failed_at=NULL,failure_code=NULL,revision=revision+1 WHERE id=v_visibility.id;
    END IF;
  ELSIF v_visibility.id IS NOT NULL THEN DELETE FROM eshop.planned_changes WHERE id=v_visibility.id;
  END IF;
END; $$;
REVOKE ALL ON FUNCTION public.save_product_wave_target(bigint,bigint,bigint,numeric,boolean,bigint,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_product_wave_target(bigint,bigint,bigint,numeric,boolean,bigint,bigint) TO authenticated;

CREATE OR REPLACE FUNCTION public.move_product_price_wave(p_wave_id bigint,p_expected_revision bigint,p_change_time timestamptz)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_wave eshop.product_price_waves%ROWTYPE;
BEGIN
  SELECT * INTO STRICT v_wave FROM eshop.product_price_waves WHERE id=p_wave_id FOR UPDATE;
  PERFORM public.check_product_wave_editor(v_wave.occasion);
  IF v_wave.revision IS DISTINCT FROM p_expected_revision THEN RAISE serialization_failure USING MESSAGE='PRICE_CHANGE_CONFLICT'; END IF;
  IF p_change_time IS NULL OR NOT isfinite(p_change_time) OR p_change_time<=clock_timestamp() THEN
    RAISE invalid_parameter_value USING MESSAGE='FUTURE_TIME_REQUIRED'; END IF;
  IF EXISTS(SELECT 1 FROM eshop.planned_changes WHERE wave_id=p_wave_id AND applied) THEN
    RAISE invalid_parameter_value USING MESSAGE='WAVE_ALREADY_APPLIED'; END IF;
  PERFORM 1 FROM eshop.products WHERE id IN(SELECT subject_id FROM eshop.planned_changes
    WHERE wave_id=p_wave_id AND NOT applied) ORDER BY id FOR UPDATE;
  PERFORM 1 FROM eshop.planned_changes WHERE wave_id=p_wave_id AND NOT applied ORDER BY subject_id,id FOR UPDATE;
  IF EXISTS(SELECT 1 FROM eshop.planned_changes target JOIN eshop.planned_changes other
    ON other.subject_id=target.subject_id AND other.change_type=target.change_type
    WHERE target.wave_id=p_wave_id AND NOT target.applied AND NOT other.applied
      AND other.wave_id IS DISTINCT FROM p_wave_id AND other.change_time=p_change_time) THEN
    RAISE serialization_failure USING MESSAGE='PRICE_CHANGE_CONFLICT'; END IF;
  IF EXISTS(SELECT 1 FROM eshop.planned_changes WHERE wave_id=p_wave_id AND applied) THEN
    RAISE invalid_parameter_value USING MESSAGE='WAVE_ALREADY_APPLIED'; END IF;
  IF p_change_time<=clock_timestamp() THEN RAISE invalid_parameter_value USING MESSAGE='FUTURE_TIME_REQUIRED'; END IF;
  UPDATE eshop.product_price_waves SET change_time=p_change_time,revision=revision+1 WHERE id=p_wave_id RETURNING * INTO v_wave;
  UPDATE eshop.planned_changes SET change_time=p_change_time,revision=revision+1,failed_at=NULL,failure_code=NULL
    WHERE wave_id=p_wave_id AND NOT applied;
  RETURN to_jsonb(v_wave);
END; $$;
REVOKE ALL ON FUNCTION public.move_product_price_wave(bigint,bigint,timestamptz) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.move_product_price_wave(bigint,bigint,timestamptz) TO authenticated;

CREATE OR REPLACE FUNCTION public.cancel_product_price_wave(p_wave_id bigint,p_expected_revision bigint)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_wave eshop.product_price_waves%ROWTYPE;
BEGIN
  SELECT * INTO STRICT v_wave FROM eshop.product_price_waves WHERE id=p_wave_id FOR UPDATE;
  PERFORM public.check_product_wave_editor(v_wave.occasion);
  IF v_wave.revision IS DISTINCT FROM p_expected_revision THEN RAISE serialization_failure USING MESSAGE='PRICE_CHANGE_CONFLICT'; END IF;
  PERFORM 1 FROM eshop.products WHERE id IN(SELECT subject_id FROM eshop.planned_changes
    WHERE wave_id=p_wave_id AND NOT applied) ORDER BY id FOR UPDATE;
  DELETE FROM eshop.planned_changes WHERE wave_id=p_wave_id AND NOT applied;
  DELETE FROM eshop.product_price_waves WHERE id=p_wave_id;
END; $$;
REVOKE ALL ON FUNCTION public.cancel_product_price_wave(bigint,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.cancel_product_price_wave(bigint,bigint) TO authenticated;

-- Source: database/functions/eshop/save_product_wave_target_client_sync_v1.sql
-- One intention: resolve/create the wave and save its target, including adoption.
CREATE OR REPLACE FUNCTION public.save_product_wave_target_client_sync_v1(p_target jsonb,p_command_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE oc bigint; actor uuid:=auth.uid(); begin_result jsonb; hash text; wave jsonb; wave_id bigint; users uuid[];
BEGIN
 IF p_target IS NULL OR jsonb_typeof(p_target) IS DISTINCT FROM 'object' OR octet_length(p_target::text)>8192
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_target) k WHERE k NOT IN ('occasion_link','product_id','wave_id','change_time',
    'expected_wave_revision','price','is_hidden','expected_price_revision','expected_visibility_revision'))
  OR ((p_target->>'wave_id' IS NOT NULL)::integer+(p_target->>'change_time' IS NOT NULL)::integer)<>1
  OR NOT p_target ?& ARRAY['occasion_link','product_id','price','is_hidden','expected_price_revision','expected_visibility_revision']
 THEN RAISE invalid_parameter_value USING MESSAGE='invalid wave target'; END IF;
 oc:=public.resolve_occasion_link_internal(p_target->>'occasion_link');
 IF actor IS NULL OR oc IS NULL THEN RAISE insufficient_privilege USING MESSAGE='wave editor required'; END IF;
 PERFORM public.check_product_wave_editor(oc);
 IF NOT EXISTS(SELECT 1 FROM eshop.products WHERE id=(p_target->>'product_id')::bigint AND occasion=oc) THEN
  RAISE insufficient_privilege USING MESSAGE='PRODUCT_OCCASION_MISMATCH'; END IF;
 hash:=encode(extensions.digest(convert_to(p_target::text,'UTF8'),'sha256'),'hex');
 begin_result:=public.begin_client_mutation_v1(p_command_id,'inventory.wave.target.save',oc,actor,hash);
 IF begin_result->>'disposition'='replay' THEN RETURN begin_result->'response'; END IF;
 IF p_target->>'wave_id' IS NULL THEN
  wave:=public.create_product_price_wave(p_target->>'occasion_link',(p_target->>'change_time')::timestamptz);
  wave_id:=(wave->>'id')::bigint;
 ELSE
  wave_id:=(p_target->>'wave_id')::bigint;
  SELECT to_jsonb(w) INTO wave FROM eshop.product_price_waves w WHERE id=wave_id AND occasion=oc FOR UPDATE;
  IF wave IS NULL THEN RAISE insufficient_privilege USING MESSAGE='foreign wave'; END IF;
  IF p_target->>'expected_wave_revision' IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='wave revision required'; END IF;
 END IF;
 PERFORM public.save_product_wave_target(wave_id,(p_target->>'product_id')::bigint,
  CASE WHEN p_target->>'wave_id' IS NULL THEN (wave->>'revision')::bigint ELSE (p_target->>'expected_wave_revision')::bigint END,
  (p_target->>'price')::numeric,(p_target->>'is_hidden')::boolean,
  (p_target->>'expected_price_revision')::bigint,(p_target->>'expected_visibility_revision')::bigint);
 SELECT coalesce(array_agg(DISTINCT ou."user"),'{}') INTO users FROM public.occasion_users ou
 JOIN eshop.order_product_ticket opt ON opt.ticket=ou.ticket WHERE ou.occasion=oc AND opt.product=(p_target->>'product_id')::bigint;
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,oc,'inventory.wave.target.save',
  jsonb_build_array(jsonb_build_object('entityType','product_price_wave','entityId',wave_id,'operation','update',
   'safeLabel','Product price wave','changedFields',jsonb_build_array('targets'))),users,jsonb_build_object('wave',wave,'productId',p_target->'product_id'));
END $$;
REVOKE ALL ON FUNCTION public.save_product_wave_target_client_sync_v1(jsonb,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_product_wave_target_client_sync_v1(jsonb,uuid) TO authenticated;

-- Source: database/functions/groups/group_members_internal_v1.sql
-- Shared by aggregate replacement and additive membership. Authorization belongs
-- to the surrounding command; this private invoker never grants extra rights.
CREATE OR REPLACE FUNCTION public.write_user_group_members_internal_v1(p_occasion bigint,p_group bigint,p_members jsonb,p_replace boolean)
RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE affected integer;
BEGIN
 PERFORM 1 FROM public.user_group_info WHERE id=p_group AND occasion=p_occasion FOR UPDATE;
 IF NOT FOUND THEN RAISE invalid_parameter_value USING MESSAGE='foreign group'; END IF;
 IF p_members IS NULL OR jsonb_typeof(p_members) IS DISTINCT FROM 'array' OR jsonb_array_length(p_members)>5000
  OR EXISTS(SELECT 1 FROM jsonb_to_recordset(p_members) x(user_id uuid,is_admin boolean)
   LEFT JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=x.user_id WHERE ou."user" IS NULL)
  OR jsonb_array_length(p_members)<>(SELECT count(DISTINCT x.user_id) FROM jsonb_to_recordset(p_members) x(user_id uuid)) THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid group members'; END IF;
 IF p_replace THEN DELETE FROM public.user_groups WHERE "group"=p_group; END IF;
 INSERT INTO public.user_groups("group","user",is_admin)
 SELECT p_group,x.user_id,coalesce(x.is_admin,false) FROM jsonb_to_recordset(p_members) x(user_id uuid,is_admin boolean)
 ON CONFLICT("group","user") DO NOTHING;
 GET DIAGNOSTICS affected=ROW_COUNT;
 RETURN affected;
END $$;
REVOKE ALL ON FUNCTION public.write_user_group_members_internal_v1(bigint,bigint,jsonb,boolean) FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/groups/save_user_group_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_user_group_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_group jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_id bigint; v_version bigint; v_begin jsonb;
  v_hash text; v_current jsonb; v_requested jsonb; v_entity jsonb;
  v_participants jsonb; v_current_participants jsonb;
  v_old_users uuid[]; v_new_users uuid[];
  v_old_place bigint; v_old_private boolean:=false; v_place_id bigint;
  v_private_place jsonb; v_place_version bigint; v_private_impacts jsonb;
  v_current_place jsonb; v_requested_place jsonb; v_place_changed boolean:=false;
  v_actor_replacements jsonb:='[]'::jsonb;
BEGIN
 PERFORM public.assert_canonical_mutation_write_release_internal_v1(p_occasion);
  v_id:=(p_group->>'id')::bigint;
  IF v_actor IS NULL OR NOT (public.get_is_editor_on_occasion(p_occasion)
    OR (v_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.user_groups ug
      JOIN public.user_group_info g ON g.id=ug."group"
      WHERE ug."group"=v_id AND ug."user"=v_actor AND ug.is_admin
        AND g.occasion=p_occasion))) THEN
    RAISE insufficient_privilege USING MESSAGE='group editor required';
  END IF;
  IF p_group IS NULL OR jsonb_typeof(p_group)<>'object'
    OR octet_length(p_group::text)>524288
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_group) key WHERE key NOT IN
      ('id','title','description','type','placeId','privatePlace','participants'))
    OR NOT (p_group ?& ARRAY['title','participants'])
    OR jsonb_typeof(p_group->'participants')<>'array'
    OR jsonb_array_length(p_group->'participants')>5000
    OR length(btrim(COALESCE(p_group->>'title',''))) NOT BETWEEN 1 AND 500
    OR octet_length(COALESCE(p_group->>'description',''))>262144 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid group aggregate';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('userId',x.user_id,
    'isAdmin',COALESCE(x.is_admin,false)) ORDER BY x.user_id),'[]'::jsonb),
    COALESCE(array_agg(x.user_id ORDER BY x.user_id),'{}'::uuid[])
    INTO v_participants,v_new_users
  FROM jsonb_to_recordset(p_group->'participants') x(user_id uuid,is_admin boolean);
  IF jsonb_array_length(p_group->'participants')<>cardinality(v_new_users)
    OR cardinality(v_new_users)<>cardinality(ARRAY(SELECT DISTINCT unnest(v_new_users)))
    OR EXISTS (SELECT 1 FROM unnest(v_new_users) id LEFT JOIN public.occasion_users ou
      ON ou."user"=id AND ou.occasion=p_occasion WHERE ou."user" IS NULL) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid group participants';
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_group->'participants') x WHERE jsonb_typeof(x)<>'object' OR x->>'user_id' IS NULL OR EXISTS(SELECT 1 FROM jsonb_object_keys(x) k WHERE k NOT IN ('user_id','is_admin')))
    OR (p_group->>'placeId' IS NOT NULL AND p_group->'privatePlace' IS NOT NULL AND p_group->'privatePlace'<>'null'::jsonb) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid group participants or place choice'; END IF;
  v_private_place:=p_group->'privatePlace';
  IF v_private_place IS NOT NULL AND v_private_place<>'null'::jsonb AND (
    jsonb_typeof(v_private_place)<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(v_private_place) key WHERE key NOT IN
      ('id','title','description','coordinates','order','icon'))
    OR length(btrim(COALESCE(v_private_place->>'title',''))) NOT BETWEEN 1 AND 500
    OR jsonb_typeof(v_private_place->'coordinates')<>'object'
    OR octet_length(v_private_place::text)>131072) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid private group place';
  END IF;
  IF v_private_place IS NOT NULL AND v_private_place<>'null'::jsonb THEN
    IF jsonb_typeof(v_private_place#>'{coordinates,latLng,lat}') IS DISTINCT FROM 'number'
      OR jsonb_typeof(v_private_place#>'{coordinates,latLng,lng}') IS DISTINCT FROM 'number'
      OR (v_private_place#>>'{coordinates,latLng,lat}')::double precision NOT BETWEEN -90 AND 90
      OR (v_private_place#>>'{coordinates,latLng,lng}')::double precision NOT BETWEEN -180 AND 180
      OR (v_private_place->>'icon' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.icons i JOIN public.occasions o ON o.id=p_occasion AND i.organization=o.organization WHERE i.id=(v_private_place->>'icon')::bigint AND (i.unit=o.unit OR i.unit IS NULL))) THEN
      RAISE invalid_parameter_value USING MESSAGE='invalid private coordinates or icon'; END IF;
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'expectedVersion',p_expected_version,'group',p_group)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.group.save',
    p_occasion,v_actor,v_hash);
  PERFORM public.lock_group_occasion_internal_v1(p_occasion);
  IF v_actor IS NULL OR NOT (public.get_is_editor_on_occasion(p_occasion)
    OR (v_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.user_groups ug
      JOIN public.user_group_info g ON g.id=ug."group"
      WHERE ug."group"=v_id AND ug."user"=v_actor AND ug.is_admin
        AND g.occasion=p_occasion))) THEN
    RAISE insufficient_privilege USING MESSAGE='group editor required';
  END IF;
  IF EXISTS(SELECT 1 FROM unnest(v_new_users) id LEFT JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=id WHERE ou."user" IS NULL) THEN RAISE invalid_parameter_value USING MESSAGE='invalid group participants after lock'; END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF v_id IS NOT NULL THEN
    PERFORM 1 FROM public.user_group_info g WHERE g.id=v_id
      AND g.occasion=p_occasion FOR UPDATE;
    IF NOT FOUND THEN RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'rejected',404,jsonb_build_object('version',0,'group',NULL)); END IF;
    SELECT g.place,COALESCE(p.is_hidden AND p.type='group',false),
      public.get_user_group_command_data_v1(g.id)
      INTO v_old_place,v_old_private,v_current
    FROM public.user_group_info g LEFT JOIN public.places p ON p.id=g.place
    WHERE g.id=v_id;
    SELECT COALESCE(array_agg(ug."user" ORDER BY ug."user"),'{}'::uuid[]),
      COALESCE(jsonb_agg(jsonb_build_object('userId',ug."user",
        'isAdmin',ug.is_admin) ORDER BY ug."user"),'[]'::jsonb)
      INTO v_old_users,v_current_participants FROM public.user_groups ug
      WHERE ug."group"=v_id;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('user_group','occasion',p_occasion,v_id::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='user_group' AND scope_type='occasion'
      AND scope_id=p_occasion AND aggregate_id=v_id::text FOR UPDATE;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
        jsonb_build_object('version',v_version,'group',v_current)); END IF;
  ELSIF p_expected_version IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new group must not have expected version';
  END IF;
  IF v_private_place IS NOT NULL AND v_private_place<>'null'::jsonb THEN
    v_place_id:=(v_private_place->>'id')::bigint;
    IF v_place_id IS NULL THEN
      INSERT INTO public.places(title,description,type,coordinates,is_hidden,"order",icon,occasion)
      VALUES (v_private_place->>'title',v_private_place->>'description','group',
        v_private_place->'coordinates',true,(v_private_place->>'order')::bigint,
        (v_private_place->>'icon')::bigint,p_occasion) RETURNING id INTO v_place_id;
      v_place_version:=1;
      v_place_changed:=true;
      INSERT INTO public.client_aggregate_versions
        (aggregate_type,scope_type,scope_id,aggregate_id,version)
      VALUES ('place','occasion',p_occasion,v_place_id::text,v_place_version);
    ELSE
      PERFORM 1 FROM public.places p WHERE p.id=v_place_id AND p.occasion=p_occasion
        AND p.type='group' AND p.is_hidden FOR UPDATE;
      IF NOT FOUND OR v_id IS NULL OR NOT v_old_private
        OR v_place_id IS DISTINCT FROM v_old_place THEN
        RAISE invalid_parameter_value USING MESSAGE='private place is not owned by group';
      END IF;
      PERFORM public.assert_group_place_owner_internal_v1(p_occasion,v_id,v_place_id,false);
      INSERT INTO public.client_aggregate_versions
        (aggregate_type,scope_type,scope_id,aggregate_id,version)
      VALUES ('place','occasion',p_occasion,v_place_id::text,0) ON CONFLICT DO NOTHING;
      SELECT jsonb_build_object('id',p.id,'title',p.title,
        'description',p.description,'coordinates',p.coordinates,
        'order',p."order",'icon',p.icon) INTO v_current_place
      FROM public.places p WHERE p.id=v_place_id;
      v_requested_place:=jsonb_build_object('id',v_place_id,
        'title',v_private_place->>'title','description',v_private_place->>'description',
        'coordinates',v_private_place->'coordinates',
        'order',(v_private_place->>'order')::bigint,
        'icon',(v_private_place->>'icon')::bigint);
      v_place_changed:=v_current_place IS DISTINCT FROM v_requested_place;
      IF v_place_changed THEN
        UPDATE public.places SET title=v_private_place->>'title',
          description=v_private_place->>'description',coordinates=v_private_place->'coordinates',
          "order"=(v_private_place->>'order')::bigint,icon=(v_private_place->>'icon')::bigint
          WHERE id=v_place_id;
        UPDATE public.client_aggregate_versions SET version=version+1,
          updated_at=clock_timestamp() WHERE aggregate_type='place'
          AND scope_type='occasion' AND scope_id=p_occasion
          AND aggregate_id=v_place_id::text RETURNING version INTO v_place_version;
      ELSE
        SELECT version INTO v_place_version FROM public.client_aggregate_versions
        WHERE aggregate_type='place' AND scope_type='occasion'
          AND scope_id=p_occasion AND aggregate_id=v_place_id::text;
      END IF;
    END IF;
  ELSE
    v_place_id:=(p_group->>'placeId')::bigint;
    IF v_place_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.places p
      WHERE p.id=v_place_id AND p.occasion=p_occasion
        AND (NOT p.is_hidden OR (p.id=v_old_place AND p.type='group' AND v_old_private))) THEN
      RAISE invalid_parameter_value USING MESSAGE='invalid shared group place';
    END IF;
  END IF;
  v_requested:=jsonb_build_object('id',v_id,'title',p_group->>'title',
    'description',p_group->>'description','type',p_group->>'type',
    'place',v_place_id,'participants',v_participants);
  IF v_current IS NOT NULL AND jsonb_build_object('id',v_id,
      'title',v_current->>'title','description',v_current->>'description',
      'type',v_current->>'type','place',(v_current->>'place')::bigint,
      'participants',v_current_participants)=v_requested
      AND NOT v_place_changed THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('version',v_version,'group',v_current));
  END IF;
  IF v_old_private AND v_old_place IS DISTINCT FROM v_place_id THEN
    PERFORM public.assert_group_place_owner_internal_v1(p_occasion,v_id,v_old_place,true);
  END IF;
  IF v_id IS NULL THEN
    INSERT INTO public.user_group_info(title,description,type,place,occasion)
    VALUES (p_group->>'title',p_group->>'description',p_group->>'type',v_place_id,p_occasion)
    RETURNING id INTO v_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('user_group','occasion',p_occasion,v_id::text,v_version);
  ELSE
    UPDATE public.user_group_info SET title=p_group->>'title',
      description=p_group->>'description',type=p_group->>'type',place=v_place_id
      WHERE id=v_id;
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='user_group'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text
      RETURNING version INTO v_version;
  END IF;
  PERFORM public.write_user_group_members_internal_v1(p_occasion,v_id,p_group->'participants',true);
  IF v_old_private AND v_old_place IS DISTINCT FROM v_place_id THEN
    IF EXISTS (SELECT 1 FROM public.user_group_info g WHERE g.id<>v_id
      AND g.place=v_old_place) THEN
      RAISE foreign_key_violation USING MESSAGE='private group place has another owner';
    END IF;
    DELETE FROM public.places WHERE id=v_old_place;
    DELETE FROM public.client_aggregate_versions WHERE aggregate_type='place'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_old_place::text;
  END IF;
  v_private_impacts:=public.group_profile_impacts_internal_v1(p_occasion,COALESCE(v_old_users,'{}'::uuid[])||v_new_users);
  v_entity:=public.get_user_group_command_data_v1(v_id)||
    jsonb_build_object('aggregate_version',v_version);
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_private_impacts) x WHERE x->>'userId'=v_actor::text) THEN
    v_actor_replacements:=jsonb_build_array(jsonb_build_object(
      'component','private_profile','userId',v_actor,
      'payload',public.get_private_profile_payload_v1(p_occasion,v_actor)));
  END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.group.save','profile',jsonb_build_array(jsonb_build_object(
      'entityType','user_group','entityId',v_id,
      'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_group->>'title',240),'changedFields',jsonb_build_array('aggregate'))),
    '{}',v_private_impacts,'[]',jsonb_build_object('version',v_version,'group',v_entity),
    '{}','[]','user',NULL,v_actor_replacements);
END; $function$
;
REVOKE ALL ON FUNCTION public.save_user_group_client_sync_v1(bigint,uuid,bigint,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_user_group_client_sync_v1(bigint,uuid,bigint,jsonb) TO authenticated;

-- Source: database/functions/groups/add_user_group_members_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.add_user_group_members_client_sync_v1(p_occasion bigint,p_group bigint,p_users uuid[],p_command_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE actor uuid:=auth.uid(); begin_result jsonb; hash text; members jsonb; users uuid[]; v_version bigint; changed integer;
BEGIN
 PERFORM public.assert_canonical_mutation_write_release_internal_v1(p_occasion);
 IF cardinality(p_users)>5000 THEN RAISE invalid_parameter_value USING MESSAGE='too many members'; END IF;
 p_users:=ARRAY(SELECT DISTINCT id FROM unnest(p_users) id ORDER BY id);
 IF actor IS NULL OR cardinality(p_users) NOT BETWEEN 1 AND 5000 THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid selected members'; END IF;
 IF NOT public.get_is_editor_on_occasion(p_occasion) AND NOT EXISTS(SELECT 1 FROM public.user_groups m
  JOIN public.user_group_info g ON g.id=m."group" WHERE g.id=p_group AND g.occasion=p_occasion AND m."user"=actor AND m.is_admin) THEN
  RAISE insufficient_privilege USING MESSAGE='group editor required'; END IF;
 hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,'group',p_group,'users',p_users)::text,'UTF8'),'sha256'),'hex');
 begin_result:=public.begin_client_mutation_v1(p_command_id,'profile.group.members.add',p_occasion,actor,hash);
 PERFORM public.lock_group_occasion_internal_v1(p_occasion);
 IF begin_result->>'disposition'='replay' THEN RETURN begin_result->'response'; END IF;
 PERFORM 1 FROM public.user_group_info WHERE id=p_group AND occasion=p_occasion FOR UPDATE;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='group unavailable'; END IF;
 IF NOT public.get_is_editor_on_occasion(p_occasion) AND NOT EXISTS(SELECT 1 FROM public.user_groups WHERE "group"=p_group AND "user"=actor AND is_admin) THEN
  RAISE insufficient_privilege USING MESSAGE='group editor required'; END IF;
 SELECT jsonb_agg(jsonb_build_object('user_id',id,'is_admin',false)) INTO members FROM unnest(p_users) id;
 changed:=public.write_user_group_members_internal_v1(p_occasion,p_group,members,false);
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 VALUES('user_group','occasion',p_occasion,p_group::text,0) ON CONFLICT DO NOTHING;
 UPDATE public.client_aggregate_versions SET version=version+CASE WHEN changed>0 THEN 1 ELSE 0 END,updated_at=clock_timestamp()
 WHERE aggregate_type='user_group' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_group::text RETURNING version INTO v_version;
 IF changed=0 THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
  jsonb_build_object('version',v_version,'group',public.get_user_group_command_data_v1(p_group))); END IF;
 SELECT array_agg("user") INTO users FROM public.user_groups WHERE "group"=p_group;
 RETURN public.complete_private_profile_mutation_v1(p_command_id,p_occasion,'profile.group.members.add',
  jsonb_build_array(jsonb_build_object('entityType','user_group','entityId',p_group,'operation','update','safeLabel','Group members',
    'changedFields',jsonb_build_array('participants'))),users,'{}','[]',
  jsonb_build_object('version',v_version,'group',public.get_user_group_command_data_v1(p_group)));
END $$;
REVOKE ALL ON FUNCTION public.add_user_group_members_client_sync_v1(bigint,bigint,uuid[],uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.add_user_group_members_client_sync_v1(bigint,bigint,uuid[],uuid) TO authenticated;

-- Source: database/functions/groups/group_member_read.sql
CREATE OR REPLACE FUNCTION public.get_user_group_info_with_users(p_group_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path = public, extensions
AS $function$
DECLARE
    v_occasion_id bigint;
    v_is_member boolean;
    v_is_editor_view boolean;
    v_current_user_is_admin boolean;
    result_json jsonb;
BEGIN
    -- Check if the group exists and get its occasion for permission checks.
    SELECT occasion INTO v_occasion_id FROM public.user_group_info WHERE id = p_group_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'USER_GROUP_NOT_FOUND';
    END IF;

    -- Authorization Check: User must be a member or have editor view permissions on the occasion.
    SELECT EXISTS (SELECT 1 FROM public.user_groups WHERE "group" = p_group_id AND "user" = auth.uid()) INTO v_is_member;
    v_is_editor_view := public.get_is_editor_view_on_occasion(v_occasion_id)
      OR public.get_is_editor_on_occasion(v_occasion_id);

    IF NOT v_is_member AND NOT v_is_editor_view THEN
        RAISE EXCEPTION 'NOT_AUTHORIZED';
    END IF;

    -- Get the current user's admin status for this specific group.
    SELECT is_admin INTO v_current_user_is_admin FROM public.user_groups WHERE "group" = p_group_id AND "user" = auth.uid();

    -- If authorized, build the final JSON object.
    SELECT
        jsonb_build_object(
            'id', ugi.id,
            'title', ugi.title,
            'description', ugi.description,
            'type', ugi.type,
            'data', ugi.data,
            'place', ugi.place, -- This is placeId
            'is_admin', COALESCE(v_current_user_is_admin, false),
            'places', (SELECT row_to_json(p)::jsonb||jsonb_build_object('aggregate_version',COALESCE((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='place' AND scope_type='occasion' AND scope_id=v_occasion_id AND aggregate_id=p.id::text),0)) FROM public.places p WHERE p.id = ugi.place),
            'user_groups', (
                SELECT COALESCE(jsonb_agg(
                    jsonb_build_object(
                        'is_admin', ug.is_admin,
                        'user_info', jsonb_build_object('id',p_ui.id,'name',p_ui.name,'surname',p_ui.surname)
                    )
                ), '[]'::jsonb)
                FROM public.user_groups ug
                JOIN public.user_info p_ui ON ug."user" = p_ui.id
                WHERE ug."group" = ugi.id
            )
        )
    INTO result_json
    FROM public.user_group_info ugi
    WHERE ugi.id = p_group_id;

    RETURN result_json;
END;
$function$
;

-- Source: database/functions/inventory/get_inventory_pool_bundle.sql
CREATE OR REPLACE FUNCTION public.get_inventory_pool_bundle(p_inventory_pool_id bigint)
RETURNS jsonb
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_occasion_id bigint;
    v_pool_data jsonb;
    v_occasion_data jsonb;
    v_resources_data jsonb;
    v_contexts_data jsonb;
    v_places_data jsonb;
    v_products_data jsonb;
    v_product_inventory_contexts_data jsonb; -- New variable for the join table data
    result jsonb;
BEGIN
    -- Get occasion for permission check from the inventory pool
    SELECT occasion INTO v_occasion_id
    FROM public.inventory_pools
    WHERE id = p_inventory_pool_id;

    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Inventory Pool not found.';
    END IF;

    -- Permission check
    IF NOT get_is_editor_order_view_on_occasion(v_occasion_id) THEN
        RAISE EXCEPTION 'User is not authorized to view this occasion.';
    END IF;

    -- Get the main inventory pool details
    SELECT to_jsonb(ip) INTO v_pool_data FROM public.inventory_pools ip WHERE ip.id = p_inventory_pool_id;

    -- Get the full occasion details
    SELECT to_jsonb(o) INTO v_occasion_data
    FROM public.occasions o
    WHERE o.id = v_occasion_id;

    -- Aggregate all resources for the pool, and for each resource, aggregate its slots.
    SELECT COALESCE(jsonb_agg(resources_with_slots), '[]'::jsonb)
    INTO v_resources_data
    FROM (
        SELECT
            jsonb_build_object(
                'id', r.id,
                'created_at', r.created_at,
                'updated_at', r.updated_at,
                'title', r.title,
                'description', r.description,
                'capacity', r.capacity,
                'booking_rules', r.booking_rules,
                'inventory_pool', r.inventory_pool,
                'place', r.place,
                'occasion', r.occasion,
                'unit', r.unit,
                'data', r.data,
                'aggregate_version', COALESCE((
                    SELECT av.version
                    FROM public.client_aggregate_versions av
                    WHERE av.aggregate_type = 'resource'
                      AND av.scope_type = 'occasion'
                      AND av.scope_id = v_occasion_id
                      AND av.aggregate_id = r.id::text
                ), 0),
                'slots', (
                    SELECT COALESCE(jsonb_agg(
                        jsonb_build_object(
                            'id', rs.id,
                            'resource', rs.resource,
                            'title', rs.title,
                            'data', rs.data
                        ) ORDER BY rs.id
                    ), '[]'::jsonb)
                    FROM public.resource_slots rs
                    WHERE rs.resource = r.id
                )
            ) AS resources_with_slots
        FROM public.resources r
        WHERE r.inventory_pool = p_inventory_pool_id
        ORDER BY r.title
    ) AS subquery;

    -- Aggregate all inventory contexts for the pool, sorted by the 'order' field
    SELECT COALESCE(jsonb_agg(to_jsonb(ic) ORDER BY ic.order), '[]'::jsonb)
    INTO v_contexts_data
    FROM public.inventory_contexts ic
    WHERE ic.inventory_pool = p_inventory_pool_id;

    -- Aggregate all places for the occasion
    SELECT COALESCE(jsonb_agg(to_jsonb(p) ORDER BY p.order), '[]'::jsonb)
    INTO v_places_data
    FROM public.places p
    WHERE p.occasion = v_occasion_id;

    -- MODIFICATION START
    -- Aggregate products that are linked to the inventory contexts of this specific pool.
    SELECT COALESCE(jsonb_agg(to_jsonb(pr)), '[]'::jsonb)
    INTO v_products_data
    FROM (
        SELECT DISTINCT pr.*
        FROM eshop.products pr
        JOIN eshop.product_inventory_contexts pic ON pr.id = pic.product
        JOIN public.inventory_contexts ic ON pic.inventory_context = ic.id
        WHERE ic.inventory_pool = p_inventory_pool_id
    ) pr;

    -- Aggregate the product <-> inventory_context join table entries for this pool's contexts.
    SELECT COALESCE(jsonb_agg(to_jsonb(pic)), '[]'::jsonb)
    INTO v_product_inventory_contexts_data
    FROM eshop.product_inventory_contexts pic
    JOIN public.inventory_contexts ic ON pic.inventory_context = ic.id
    WHERE ic.inventory_pool = p_inventory_pool_id;

    -- Construct the final bundle object, now including context-specific products and the join table data.
    result := jsonb_build_object(
        'pool', v_pool_data,
        'occasion', v_occasion_data,
        'resources', v_resources_data,
        'contexts', v_contexts_data,
        'places', v_places_data,
        'products', v_products_data,
        'product_inventory_contexts', v_product_inventory_contexts_data
        ,'aggregate_version', COALESCE((SELECT av.version
          FROM public.client_aggregate_versions av
          WHERE av.aggregate_type='inventory_pool' AND av.scope_type='occasion'
            AND av.scope_id=v_occasion_id
            AND av.aggregate_id=p_inventory_pool_id::text),0)
    );
    -- MODIFICATION END

    RETURN result;
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$ LANGUAGE plpgsql;

-- Source: database/functions/inventory/update_inventory_pool_bundle_internal_v1.sql
CREATE OR REPLACE FUNCTION public.update_inventory_pool_bundle_internal_v1(p_bundle_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_pool_data jsonb := p_bundle_data->'pool';
    v_pool_id bigint;
    v_occasion_id bigint;

    -- Context variables
    v_context_data jsonb;
    v_context_id bigint;
    v_context_ids_from_input bigint[] := ARRAY[]::bigint[];

    result jsonb;
BEGIN
    -- Resolve occasion ID from the input data. It's required for both create and update.
    v_occasion_id := (v_pool_data->>'occasion')::bigint;
    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION '%', jsonb_build_object('code', 'B001', 'message', 'Occasion ID is required.')::text;
    END IF;

    -- Permission check
    IF NOT get_is_editor_order_on_occasion(v_occasion_id) THEN
        RAISE EXCEPTION '%', jsonb_build_object('code', 403, 'message', 'User is not authorized to edit this occasion.')::text;
    END IF;

    -- 1. Upsert the main inventory_pool record
    v_pool_id := (v_pool_data->>'id')::bigint;

    IF v_pool_id IS NULL THEN
        -- Create a new pool if ID is not provided
        INSERT INTO public.inventory_pools (title, occasion, sellable_capacity, description, type, data, created_at, updated_at)
        VALUES (
            v_pool_data->>'title',
            v_occasion_id,
            (v_pool_data->>'sellable_capacity')::bigint,
            v_pool_data->>'description',
            v_pool_data->>'type',
            v_pool_data->'data',
            now(),
            now()
        ) RETURNING id INTO v_pool_id;
    ELSE
        PERFORM 1 FROM public.inventory_pools WHERE id=v_pool_id AND occasion=v_occasion_id FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'Inventory pool scope mismatch'; END IF;
        PERFORM 1 FROM public.inventory_contexts WHERE inventory_pool=v_pool_id ORDER BY id FOR UPDATE;
        IF (v_pool_data->>'sellable_capacity')::bigint < (SELECT count(*) FROM eshop.spots s JOIN public.inventory_contexts ic ON ic.id=s.inventory_context
          WHERE ic.inventory_pool=v_pool_id AND (s.order_product_ticket IS NOT NULL OR (s.secret IS NOT NULL AND s.secret_expiration_time>clock_timestamp()))) THEN
          RAISE EXCEPTION 'INVENTORY_CAPACITY_BELOW_COMMITTED'; END IF;
        -- Update the existing pool
        UPDATE public.inventory_pools
        SET
            title = v_pool_data->>'title',
            sellable_capacity = (v_pool_data->>'sellable_capacity')::bigint,
            description = v_pool_data->>'description',
            type = v_pool_data->>'type',
            data = v_pool_data->'data',
            updated_at = now()
        WHERE id = v_pool_id;
    END IF;

    -- NOTE: Resource and Slot management logic has been removed as requested.

    -- 2. Upsert/Delete Inventory Contexts
    IF jsonb_typeof(p_bundle_data->'contexts') = 'array' THEN
        FOR v_context_data IN SELECT * FROM jsonb_array_elements(p_bundle_data->'contexts')
        LOOP
            v_context_id := (v_context_data->>'id')::bigint;
            IF v_context_id IS NULL THEN
                -- Create new context, now including the 'data' field
                INSERT INTO public.inventory_contexts (inventory_pool, block_date, title, "order", data)
                VALUES (v_pool_id, (v_context_data->>'block_date')::date, v_context_data->>'title', (v_context_data->>'order')::bigint, v_context_data->'data')
                RETURNING id INTO v_context_id;
            ELSE
                -- Update existing context, now including the 'data' field
                UPDATE public.inventory_contexts
                SET
                    block_date = (v_context_data->>'block_date')::date,
                    title = v_context_data->>'title',
                    "order" = (v_context_data->>'order')::bigint,
                    data = v_context_data->'data' -- Added this line
                WHERE id = v_context_id;
            END IF;
            v_context_ids_from_input := array_append(v_context_ids_from_input, v_context_id);
        END LOOP;
        -- Deleting a context must not detach a sold or currently held spot.
        PERFORM 1 FROM eshop.spots WHERE inventory_context IN (SELECT id FROM public.inventory_contexts
          WHERE inventory_pool=v_pool_id AND id<>ALL(v_context_ids_from_input)) ORDER BY id FOR UPDATE;
        IF EXISTS(SELECT 1 FROM eshop.spots WHERE inventory_context IN (SELECT id FROM public.inventory_contexts
          WHERE inventory_pool=v_pool_id AND id<>ALL(v_context_ids_from_input))
          AND (order_product_ticket IS NOT NULL OR (secret IS NOT NULL AND secret_expiration_time>clock_timestamp()))) THEN
          RAISE check_violation USING MESSAGE='INVENTORY_CONTEXT_IN_USE'; END IF;
        -- Delete contexts that were removed in the UI for this pool
        DELETE FROM public.inventory_contexts WHERE inventory_pool = v_pool_id AND id <> ALL(v_context_ids_from_input);
    END IF;

    -- 3. Create or delete spots for the inventory pool based on its resources and contexts.
    -- The function is executed, and its integer return value is discarded.
    PERFORM adjust_spot_capacity_for_pool(v_pool_id);

    -- Return the fully updated bundle by calling the get function
    RETURN get_inventory_pool_bundle(v_pool_id);
END;
$function$;
REVOKE ALL ON FUNCTION public.update_inventory_pool_bundle_internal_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/inventory/save_inventory_pool_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_inventory_pool_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_bundle jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_pool_id bigint:=(p_bundle#>>'{pool,id}')::bigint;
  v_version bigint; v_begin jsonb; v_hash text; v_result jsonb;
  v_commit jsonb; v_response jsonb; v_private_impacts jsonb;
  v_current_command_data jsonb; v_requested_command_data jsonb;
  v_product_ids bigint[]; v_product_id bigint;
  v_actor_private_revision bigint; v_actor_private_payload jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_order_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion order editor required';
  END IF;
  IF p_bundle IS NULL OR jsonb_typeof(p_bundle)<>'object'
    OR octet_length(p_bundle::text)>1048576
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_bundle) key
      WHERE key NOT IN ('pool','contexts'))
    OR jsonb_typeof(p_bundle->'pool')<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_bundle->'pool') key
      WHERE key NOT IN ('id','title','sellable_capacity','occasion',
        'description','type','data'))
    OR (p_bundle ? 'contexts' AND p_bundle->'contexts'<>'null'::jsonb AND jsonb_typeof(p_bundle->'contexts')<>'array')
    OR jsonb_array_length(CASE WHEN jsonb_typeof(p_bundle->'contexts')='array' THEN p_bundle->'contexts' ELSE '[]'::jsonb END)>2000
    OR (p_bundle#>>'{pool,occasion}')::bigint IS DISTINCT FROM p_occasion
    OR (v_pool_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.inventory_pools ip
      WHERE ip.id=v_pool_id AND ip.occasion=p_occasion))
    OR EXISTS (SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_bundle->'contexts')='array' THEN p_bundle->'contexts' ELSE '[]'::jsonb END) c
      WHERE jsonb_typeof(c)<>'object' OR EXISTS (
        SELECT 1 FROM jsonb_object_keys(c) key
        WHERE key NOT IN ('id','inventory_pool','block_date','title','order','data'))
      OR ((c->>'id') IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.inventory_contexts ic
        WHERE ic.id=(c->>'id')::bigint AND ic.inventory_pool=v_pool_id))) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid or cross-scope inventory aggregate';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'expectedVersion',p_expected_version,'bundle',p_bundle)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'inventory.pool.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;

  IF v_pool_id IS NOT NULL THEN
    v_product_ids:=public.lock_pool_product_dependencies_internal_v1(v_pool_id);
    PERFORM 1 FROM public.inventory_pools ip WHERE ip.id=v_pool_id
      AND ip.occasion=p_occasion FOR UPDATE;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('inventory_pool','occasion',p_occasion,v_pool_id::text,0)
    ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='inventory_pool' AND scope_type='occasion'
        AND scope_id=p_occasion AND aggregate_id=v_pool_id::text FOR UPDATE;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      v_response:=jsonb_build_object('status','conflict','code',409,
        'data',jsonb_build_object('version',v_version,
          'bundle',public.get_inventory_pool_bundle(v_pool_id)),
        'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
          'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
        'sync',jsonb_build_object('replacements','[]'::jsonb));
      RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
    END IF;

    IF NOT p_bundle ? 'contexts' OR p_bundle->'contexts'='null'::jsonb THEN
      p_bundle:=jsonb_set(p_bundle,'{contexts}',coalesce((SELECT jsonb_agg(jsonb_build_object(
        'id',ic.id,'inventory_pool',ic.inventory_pool,'block_date',ic.block_date,'title',ic.title,'order',ic."order",'data',ic.data)
        ORDER BY ic."order",ic.id) FROM public.inventory_contexts ic WHERE ic.inventory_pool=v_pool_id),'[]'));
    END IF;
    SELECT jsonb_build_object(
      'pool',jsonb_build_object('id',ip.id,'title',ip.title,
        'sellable_capacity',ip.sellable_capacity,'occasion',ip.occasion,
        'description',ip.description,'type',ip.type,'data',ip.data),
      'contexts',COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'id',ic.id,'inventory_pool',ic.inventory_pool,
        'block_date',ic.block_date,'title',ic.title,'order',ic."order",
        'data',ic.data) ORDER BY ic."order",ic.id)
        FROM public.inventory_contexts ic
        WHERE ic.inventory_pool=ip.id),'[]'::jsonb))
      INTO v_current_command_data
    FROM public.inventory_pools ip WHERE ip.id=v_pool_id;
    SELECT jsonb_build_object(
      'pool',jsonb_build_object('id',(p_bundle#>>'{pool,id}')::bigint,
        'title',p_bundle#>>'{pool,title}',
        'sellable_capacity',(p_bundle#>>'{pool,sellable_capacity}')::bigint,
        'occasion',(p_bundle#>>'{pool,occasion}')::bigint,
        'description',p_bundle#>>'{pool,description}',
        'type',p_bundle#>>'{pool,type}','data',p_bundle#>'{pool,data}'),
      'contexts',COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'id',(c->>'id')::bigint,'inventory_pool',v_pool_id,
        'block_date',(c->>'block_date')::date,'title',c->>'title',
        'order',(c->>'order')::bigint,'data',c->'data')
        ORDER BY (c->>'order')::bigint,(c->>'id')::bigint)
        FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_bundle->'contexts')='array' THEN p_bundle->'contexts' ELSE '[]'::jsonb END) c),'[]'::jsonb))
      INTO v_requested_command_data;
    IF v_current_command_data = v_requested_command_data THEN
      v_response:=jsonb_build_object('status','unchanged','code',200,
        'data',jsonb_build_object('version',v_version,
          'bundle',public.get_inventory_pool_bundle(v_pool_id)),
        'mutation',jsonb_build_object('commandId',p_command_id,
          'receiptId',p_command_id,'commitId',NULL,'replayed',false,
          'occurredAt',clock_timestamp()),
        'sync',jsonb_build_object('replacements','[]'::jsonb));
      RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
    END IF;
  ELSIF p_expected_version IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new inventory pool must not have expected version';
  END IF;

  IF NOT p_bundle ? 'contexts' OR p_bundle->'contexts'='null'::jsonb THEN
    p_bundle:=jsonb_set(p_bundle,'{contexts}','[]'); END IF;
  v_result:=public.update_inventory_pool_bundle_internal_v1(p_bundle);
  FOREACH v_product_id IN ARRAY coalesce(v_product_ids,'{}'::bigint[]) LOOP
    PERFORM public.advance_ticketing_authoring_version_internal_v1('product',p_occasion,v_product_id);
  END LOOP;
  IF v_result ? 'code' AND COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RAISE EXCEPTION 'inventory aggregate handler failed: %',v_result->>'message';
  END IF;
  v_pool_id:=(v_result#>>'{pool,id}')::bigint;
  IF v_pool_id IS NULL THEN RAISE EXCEPTION 'inventory handler returned no pool id'; END IF;
  IF v_version IS NULL THEN
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('inventory_pool','occasion',p_occasion,v_pool_id::text,v_version);
  ELSE
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='inventory_pool'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_pool_id::text
      RETURNING version INTO v_version;
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_inventory',
    'userId',ou."user")),'[]'::jsonb) INTO v_private_impacts
    FROM public.occasion_users ou WHERE ou.occasion=p_occasion;
  v_commit:=public.record_client_sync_commit_v1(p_occasion,'inventory.pool.save',
    'inventory',jsonb_build_array(jsonb_build_object('entityType','inventory_pool',
      'entityId',v_pool_id,'operation',CASE WHEN (p_bundle#>>'{pool,id}') IS NULL
        THEN 'insert' ELSE 'update' END,'safeLabel',left(v_result#>>'{pool,title}',240),
      'changedFields',jsonb_build_array('aggregate'))),'{}',v_private_impacts,
    '[]','user',NULL);
  SELECT s.source_revision INTO STRICT v_actor_private_revision
  FROM public.client_sync_private_scopes s
  WHERE s.component='private_inventory' AND s.occasion=p_occasion
    AND s.user_id=v_actor;
  v_actor_private_payload:=public.get_user_inventory_for_occasion_v1(p_occasion);
  v_result:=v_result||jsonb_build_object('aggregate_version',v_version);
  v_response:=jsonb_build_object('status','applied','code',200,
    'data',jsonb_build_object('version',v_version,'bundle',v_result),
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',v_commit->>'commitId','replayed',false,'occurredAt',v_commit->>'occurredAt'),
    'sync',jsonb_build_object('replacements',jsonb_build_array(
      jsonb_build_object('component','private_inventory',
        'revision',v_actor_private_revision,'payload',v_actor_private_payload))));
  RETURN public.finish_client_mutation_v1(p_command_id,v_response,
    (v_commit->>'commitId')::uuid);
END; $function$;
REVOKE ALL ON FUNCTION public.save_inventory_pool_client_sync_v1(bigint,uuid,bigint,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_inventory_pool_client_sync_v1(bigint,uuid,bigint,jsonb) TO authenticated;

-- Source: database/functions/inventory/update_inventory_pool_bundle.sql
-- Published legacy shape. Version is selected under the same parent lock.
CREATE OR REPLACE FUNCTION public.update_inventory_pool_bundle(p_bundle_data jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_id bigint:=(p_bundle_data#>>'{pool,id}')::bigint; oc bigint; v bigint; result jsonb; bundle jsonb:=p_bundle_data;
BEGIN
 oc:=(bundle#>>'{pool,occasion}')::bigint;
 IF v_id IS NOT NULL THEN SELECT occasion INTO oc FROM public.inventory_pools WHERE inventory_pools.id=v_id; END IF;
 PERFORM public.check_is_editor_order_on_occasion(oc);
 IF v_id IS NOT NULL THEN
 PERFORM public.lock_pool_product_dependencies_internal_v1(v_id);
  PERFORM 1 FROM public.inventory_pools WHERE inventory_pools.id=v_id FOR UPDATE;
  SELECT coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='inventory_pool'
   AND scope_type='occasion' AND scope_id=oc AND aggregate_id=v_id::text),0) INTO v;
  IF NOT bundle ? 'contexts' THEN bundle:=bundle||jsonb_build_object('contexts',public.get_inventory_pool_bundle(v_id)->'contexts'); END IF;
 END IF;
 result:=public.save_inventory_pool_client_sync_v1(oc,extensions.gen_random_uuid(),v,bundle);
 IF result->>'code'<>'200' THEN RAISE serialization_failure USING MESSAGE='inventory pool save rejected'; END IF;
 RETURN result#>'{data,bundle}';
END $$;
REVOKE ALL ON FUNCTION public.update_inventory_pool_bundle(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_inventory_pool_bundle(jsonb) TO authenticated;

-- Source: database/functions/inventory/lock_spot_assignment_scope_internal_v1.sql
-- Capture the parent set before locks; a changed hierarchy requires the same
-- command to retry rather than acquiring a new parent after its children.
CREATE OR REPLACE FUNCTION public.lock_spot_assignment_scope_internal_v1(p_spots bigint[],p_resources bigint[] DEFAULT '{}')
RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE before_spots jsonb; after_spots jsonb; before_resources jsonb; after_resources jsonb; resource_ids bigint[];
BEGIN
 SELECT coalesce(jsonb_agg(jsonb_build_array(s.id,s.occasion,s.product,s.blueprint,s.inventory_context,s.resource,s.resource_slot,s.order_product_ticket) ORDER BY s.id),'[]')
 INTO before_spots FROM eshop.spots s WHERE s.id=ANY(p_spots);
 SELECT ARRAY(SELECT DISTINCT id FROM (
  SELECT unnest(p_resources) id UNION SELECT s.resource FROM eshop.spots s WHERE s.id=ANY(p_spots)
  UNION SELECT rs.resource FROM public.resource_slots rs JOIN eshop.spots s ON s.resource_slot=rs.id WHERE s.id=ANY(p_spots)) r WHERE id IS NOT NULL)
 INTO resource_ids;
 SELECT coalesce(jsonb_agg(jsonb_build_array(r.id,r.inventory_pool) ORDER BY r.id),'[]') INTO before_resources FROM public.resources r WHERE r.id=ANY(resource_ids);
 PERFORM public.lock_order_capacity_scope_internal(ARRAY(SELECT DISTINCT opt."order" FROM eshop.order_product_ticket opt JOIN eshop.spots s ON s.order_product_ticket=opt.id WHERE s.id=ANY(p_spots)));
 PERFORM 1 FROM eshop.products WHERE id IN(SELECT product FROM eshop.spots WHERE id=ANY(p_spots)) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM eshop.blueprints WHERE id IN(SELECT blueprint FROM eshop.spots WHERE id=ANY(p_spots)) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.inventory_pools WHERE id IN(
  SELECT inventory_pool FROM public.resources WHERE id=ANY(resource_ids)
  UNION SELECT c.inventory_pool FROM public.inventory_contexts c JOIN eshop.spots s ON s.inventory_context=c.id WHERE s.id=ANY(p_spots)) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.resources WHERE id=ANY(resource_ids) ORDER BY id FOR UPDATE;
 SELECT coalesce(jsonb_agg(jsonb_build_array(r.id,r.inventory_pool) ORDER BY r.id),'[]') INTO after_resources FROM public.resources r WHERE r.id=ANY(resource_ids);
 IF before_resources IS DISTINCT FROM after_resources THEN RAISE serialization_failure USING MESSAGE='resource parent changed; retry the same command'; END IF;
 PERFORM 1 FROM public.resource_slots WHERE resource=ANY(resource_ids) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM eshop.spots WHERE id=ANY(p_spots) ORDER BY id FOR UPDATE;
 SELECT coalesce(jsonb_agg(jsonb_build_array(s.id,s.occasion,s.product,s.blueprint,s.inventory_context,s.resource,s.resource_slot,s.order_product_ticket) ORDER BY s.id),'[]')
 INTO after_spots FROM eshop.spots s WHERE s.id=ANY(p_spots);
 IF before_spots IS DISTINCT FROM after_spots THEN RAISE serialization_failure USING MESSAGE='spot parent changed; retry the same command'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.lock_spot_assignment_scope_internal_v1(bigint[],bigint[]) FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/inventory/update_spots_assignments.sql
CREATE OR REPLACE FUNCTION public.update_spot_assignments_internal_v1(p_changes jsonb)
RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE change jsonb; oc bigint; resource_id bigint; slot_id bigint; context_id bigint; old_id bigint; new_id bigint;
 spot_ids bigint[]; resource_ids bigint[];
BEGIN
 IF p_changes IS NULL OR jsonb_typeof(p_changes)<>'array' OR jsonb_array_length(p_changes) NOT BETWEEN 1 AND 1000 THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid spot assignment batch'; END IF;
 SELECT ARRAY(SELECT DISTINCT e.value::bigint FROM jsonb_array_elements(p_changes) c CROSS JOIN LATERAL jsonb_each_text(c) e
  WHERE e.key IN('old_spot_id','new_spot_id') AND nullif(e.value,'') IS NOT NULL),
  ARRAY(SELECT DISTINCT (c->>'resource_id')::bigint FROM jsonb_array_elements(p_changes) c) INTO spot_ids,resource_ids;
 PERFORM public.lock_spot_assignment_scope_internal_v1(spot_ids,resource_ids);
 SELECT min(occasion) INTO oc FROM public.resources WHERE id=ANY(resource_ids);
 IF oc IS NULL OR public.get_is_editor_order_on_occasion(oc) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='inventory editor required'; END IF;
 IF EXISTS(SELECT 1 FROM public.resources WHERE id=ANY(resource_ids) AND occasion<>oc)
 OR (SELECT count(*) FROM public.resources WHERE id=ANY(resource_ids))<>cardinality(resource_ids)
 OR (SELECT count(*) FROM eshop.spots WHERE id=ANY(spot_ids) AND occasion=oc)<>cardinality(spot_ids) THEN
  RAISE invalid_parameter_value USING MESSAGE='assignment outside occasion'; END IF;
 -- Validate every change before writing the first one. Old IDs are the editor's
 -- original assignment, not a fresh baseline fetched immediately before save.
 FOR change IN SELECT value FROM jsonb_array_elements(p_changes) LOOP
  resource_id:=(change->>'resource_id')::bigint;slot_id:=(change->>'resource_slot_id')::bigint;
  context_id:=(change->>'inventory_context_id')::bigint;old_id:=(change->>'old_spot_id')::bigint;new_id:=(change->>'new_spot_id')::bigint;
  IF resource_id IS NULL OR (old_id IS NULL AND new_id IS NULL)
  OR (slot_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.resource_slots WHERE id=slot_id AND resource=resource_id))
  OR EXISTS(SELECT 1 FROM eshop.spots s LEFT JOIN public.inventory_contexts c ON c.id=s.inventory_context
    JOIN public.resources r ON r.id=resource_id WHERE s.id=ANY(ARRAY[old_id,new_id])
    AND (c.inventory_pool IS DISTINCT FROM r.inventory_pool OR (context_id IS NOT NULL AND s.inventory_context IS DISTINCT FROM context_id))) THEN
   RAISE invalid_parameter_value USING MESSAGE='invalid resource, slot or inventory context'; END IF;
  IF old_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.spots WHERE id=old_id AND resource=resource_id AND resource_slot IS NOT DISTINCT FROM slot_id) THEN
   RAISE serialization_failure USING MESSAGE='original spot assignment changed; reload editor'; END IF;
  IF EXISTS(SELECT 1 FROM eshop.spots WHERE id=ANY(ARRAY[old_id,new_id]) AND secret IS NOT NULL AND secret_expiration_time>clock_timestamp()) THEN
   RAISE object_not_in_prerequisite_state USING MESSAGE='SPOT_HELD'; END IF;
 END LOOP;
 FOR change IN SELECT value FROM jsonb_array_elements(p_changes) LOOP
  UPDATE eshop.spots SET resource=NULL,resource_slot=NULL,updated_at=now() WHERE id=(change->>'old_spot_id')::bigint;
  UPDATE eshop.spots SET resource=(change->>'resource_id')::bigint,resource_slot=(change->>'resource_slot_id')::bigint,updated_at=now() WHERE id=(change->>'new_spot_id')::bigint;
 END LOOP;
 IF EXISTS(SELECT 1 FROM eshop.spots s JOIN public.resources r ON r.id=s.resource WHERE r.id=ANY(resource_ids)
  GROUP BY r.id,r.capacity,s.inventory_context HAVING count(*)>r.capacity)
 OR EXISTS(SELECT 1 FROM eshop.spots WHERE resource=ANY(resource_ids) AND resource_slot IS NOT NULL GROUP BY resource_slot,inventory_context HAVING count(*)>1) THEN
  RAISE object_not_in_prerequisite_state USING MESSAGE='RESOURCE_CAPACITY_EXCEEDED'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.update_spot_assignments_internal_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- Installed Flutter versions use the void-returning shape.
CREATE OR REPLACE FUNCTION public.update_spot_assignments(p_changes jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN PERFORM public.update_spot_assignments_client_sync_v1(p_changes,extensions.gen_random_uuid()); END $$;
REVOKE ALL ON FUNCTION public.update_spot_assignments(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_spot_assignments(jsonb) TO authenticated;

-- Source: database/functions/inventory/update_spot_assignments_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.update_spot_assignments_client_sync_v1(p_changes jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path = public, extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_users uuid[]; v_spot_ids bigint[]; v_resource_ids bigint[];
BEGIN
  IF p_changes IS NULL OR jsonb_typeof(p_changes)<>'array'
    OR jsonb_array_length(p_changes)=0 OR jsonb_array_length(p_changes)>1000
    OR octet_length(p_changes::text)>1048576 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid spot assignment batch'; END IF;
  SELECT ARRAY(SELECT DISTINCT e.value::bigint FROM jsonb_array_elements(p_changes) c
    CROSS JOIN LATERAL jsonb_each_text(c) e
    WHERE e.key IN ('old_spot_id','new_spot_id') AND nullif(e.value,'') IS NOT NULL),
    ARRAY(SELECT DISTINCT (c->>'resource_id')::bigint
      FROM jsonb_array_elements(p_changes) c)
    INTO v_spot_ids,v_resource_ids;
  SELECT occasion INTO v_occasion FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=v_actor AND command_name='inventory.spots.assign';
  IF NOT FOUND THEN
  SELECT min(r.occasion) INTO v_occasion FROM public.resources r
    WHERE r.id=ANY(v_resource_ids);
  END IF;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='inventory editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',v_occasion,'changes',p_changes)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.spots.assign',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF (SELECT count(DISTINCT r.occasion) FROM public.resources r
      WHERE r.id=ANY(v_resource_ids))<>1
    OR (SELECT count(*) FROM public.resources r WHERE r.id=ANY(v_resource_ids))
      <>cardinality(v_resource_ids)
    OR (SELECT count(*) FROM eshop.spots s WHERE s.id=ANY(v_spot_ids))
      <>cardinality(v_spot_ids)
    OR EXISTS (SELECT 1 FROM eshop.spots s WHERE s.id=ANY(v_spot_ids)
      AND s.occasion<>v_occasion)
 THEN RAISE insufficient_privilege USING MESSAGE='foreign spot assignment'; END IF;

  PERFORM public.lock_spot_assignment_scope_internal_v1(v_spot_ids,v_resource_ids);
  SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
  FROM eshop.spots s JOIN eshop.order_product_ticket opt
    ON opt.id=s.order_product_ticket JOIN public.occasion_users ou
    ON ou.ticket=opt.ticket AND ou.occasion=v_occasion
  WHERE s.id=ANY(v_spot_ids);
  PERFORM public.update_spot_assignments_internal_v1(p_changes);
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.spots.assign',jsonb_build_array(jsonb_build_object(
      'entityType','spot_assignment','entityId',NULL,'operation','update',
      'safeLabel','Spot assignments','changedFields',jsonb_build_array(
        'resource','resource_slot'))),v_users,jsonb_build_object(
          'changedCount',jsonb_array_length(p_changes)));
END; $function$;

REVOKE ALL ON FUNCTION public.update_spot_assignments_client_sync_v1(jsonb,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_spot_assignments_client_sync_v1(jsonb,uuid) TO authenticated;

-- Source: database/functions/eshop/swap_spot_tickets.sql
CREATE OR REPLACE FUNCTION public._swap_spots_generate_product_json(
    p_product_id BIGINT,
    p_spot_id BIGINT
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SET search_path = public, extensions
AS $$
DECLARE
    product_data RECORD;
BEGIN
    -- This query joins product, its type, and the spot (if provided)
    -- to get all data needed for the JSON object.
    SELECT
        p.id,
        p.price,
        p.title,
        p.description,
        p.currency_code,
        pt.title AS type_title,
        pt.type AS type,
        s.title AS spot_title
    INTO
        product_data
    FROM
        eshop.products AS p
    JOIN
        eshop.product_types AS pt ON p.product_type = pt.id
    LEFT JOIN
        eshop.spots AS s ON s.id = p_spot_id -- Use p_spot_id for spot_title
    WHERE
        p.id = p_product_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Product data not found for product_id %', p_product_id;
    END IF;

    -- Build the JSON object.
    -- jsonb_strip_nulls ensures that if 'spot_title' is NULL
    -- (because p_spot_id was NULL), the key is removed entirely.
    RETURN jsonb_strip_nulls(jsonb_build_object(
        'id', product_data.id,
        'type', product_data.type,
        'price', product_data.price,
        'title', product_data.title,
        'spot_title', product_data.spot_title,
        'type_title', product_data.type_title,
        'description', product_data.description,
        'currency_code', product_data.currency_code
    ));
END;
$$;

CREATE OR REPLACE FUNCTION public._swap_spots_update_ticket(
    p_opt_id BIGINT,
    p_new_product_id BIGINT,
    p_new_spot_id BIGINT
)
RETURNS VOID
LANGUAGE plpgsql
SET search_path = public, extensions
AS $$
DECLARE
    opt RECORD;
    ord RECORD;
    original_product_id BIGINT;
    original_product_json JSONB;
    original_price NUMERIC;

    new_product_json JSONB;
    new_price NUMERIC;
    new_data JSONB;
    new_order_price NUMERIC;
    new_state TEXT;

    price_delta NUMERIC;
    history_needed BOOLEAN;
    now_time TIMESTAMP WITH TIME ZONE := NOW();
BEGIN
    -- 1. Get current ticket and order data
    SELECT * INTO opt FROM eshop.order_product_ticket WHERE id = p_opt_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Order Product Ticket % not found', p_opt_id; END IF;

    PERFORM public.check_ticket_is_mutable(opt.ticket);
    SELECT * INTO ord FROM eshop.orders WHERE id = opt."order";
    IF NOT FOUND THEN RAISE EXCEPTION 'Order % not found', opt."order"; END IF;

    original_product_id := opt.product;

    -- 2. Find the *original* product JSON and price from the orders.data
    SELECT prod, (prod->>'price')::numeric
    INTO original_product_json, original_price
    FROM jsonb_array_elements(ord.data->'tickets') tckt,
         jsonb_array_elements(tckt->'products') prod
    WHERE (tckt->>'id')::bigint = opt.ticket
      AND (prod->>'id')::bigint = original_product_id;

    IF original_price IS NULL THEN
        RAISE EXCEPTION 'Could not find original price for product % on ticket %', original_product_id, opt.ticket;
    END IF;

    -- 3. Generate the *new* product JSON
    new_product_json := public._swap_spots_generate_product_json(p_new_product_id, p_new_spot_id);
    new_price := (new_product_json->>'price')::numeric;

    -- 4. Check if an update is even needed.
    -- If the new JSON is identical to the old, nothing needs to be done.
    IF original_product_json = new_product_json THEN
        RETURN;
    END IF;

    -- 5. Calculate financials and state
    price_delta := new_price - original_price;
    history_needed := (original_product_id IS DISTINCT FROM p_new_product_id);
    new_order_price := COALESCE(ord.price, 0) + price_delta;

    -- Recalculate order state
    SELECT CASE
        WHEN COALESCE(pi.paid, 0) >= new_order_price AND new_order_price > 0 THEN 'paid'
        WHEN new_order_price <= 0 THEN 'paid'
        ELSE 'ordered'
    END INTO new_state
    FROM eshop.payment_info pi WHERE pi.id = ord.payment_info;

    -- 6. Build the new orders.data JSON
    new_data := jsonb_set(
        ord.data,
        '{tickets}',
        (SELECT jsonb_agg(
            -- Find the matching ticket
            CASE WHEN (tckt->>'id')::bigint = opt.ticket
            THEN jsonb_set(
                tckt,
                '{products}',
                (SELECT jsonb_agg(
                    -- Find the matching product and replace it
                    CASE
                        WHEN (prod->>'id')::bigint = original_product_id
                        THEN new_product_json -- Swap in the new product JSON
                        ELSE prod
                    END
                ) FROM jsonb_array_elements(tckt->'products') prod)
            )
            ELSE tckt
            END
        ) FROM jsonb_array_elements(ord.data->'tickets') tckt)
    );

    -- 7. Perform all database updates

    -- Update payment info
    IF price_delta <> 0 THEN
        UPDATE eshop.payment_info SET amount = amount + price_delta WHERE id = ord.payment_info;
    END IF;

    -- Update the order itself
    UPDATE eshop.orders
    SET
        price = new_order_price,
        data = new_data,
        state = new_state,
        updated_at = now_time
    WHERE id = ord.id;

    -- Update the link table
    UPDATE eshop.order_product_ticket
    SET
        product = p_new_product_id
    WHERE id = p_opt_id;

    -- 8. Create history log *only if* the product ID actually changed
    IF history_needed THEN
        INSERT INTO eshop.orders_history("order", data, state, price, currency_code)
        VALUES (ord.id, new_data, new_state, new_order_price, ord.currency_code);
    END IF;

END;
$$;


CREATE OR REPLACE FUNCTION public.swap_spot_tickets_internal_v1(spot_id_1 BIGINT, spot_id_2 BIGINT)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    spot1 RECORD;
    spot2 RECORD;
    occasion_id_common BIGINT;
    has_permission BOOLEAN;
    now_time TIMESTAMP WITH TIME ZONE := NOW();
BEGIN
    -- 1. Input Validation
    IF spot_id_1 IS NULL OR spot_id_2 IS NULL THEN
        RAISE EXCEPTION 'Both spot_id_1 and spot_id_2 must be provided' USING ERRCODE = '22023';
    END IF;
    IF spot_id_1 = spot_id_2 THEN
        RAISE EXCEPTION 'Cannot swap a spot with itself' USING ERRCODE = '22023';
    END IF;

    PERFORM public.lock_spot_assignment_scope_internal_v1(ARRAY[spot_id_1,spot_id_2]);

    -- 2. Fetch Spot Data
    SELECT * INTO spot1 FROM eshop.spots WHERE id = spot_id_1;
    IF NOT FOUND THEN RAISE EXCEPTION 'Spot 1 not found (ID: %)', spot_id_1 USING ERRCODE = 'P0002'; END IF;
    SELECT * INTO spot2 FROM eshop.spots WHERE id = spot_id_2;
    IF NOT FOUND THEN RAISE EXCEPTION 'Spot 2 not found (ID: %)', spot_id_2 USING ERRCODE = 'P0002'; END IF;

    -- 3. Permission and Occasion Check
    IF spot1.occasion IS NULL OR spot2.occasion IS NULL THEN
         RAISE EXCEPTION 'Spots are missing occasion information' USING ERRCODE = '22004';
    END IF;
    IF spot1.occasion <> spot2.occasion THEN
        RAISE EXCEPTION 'Spots do not belong to the same occasion (Spot1: %, Spot2: %)', spot1.occasion, spot2.occasion USING ERRCODE = 'P0001';
    END IF;
    occasion_id_common := spot1.occasion;

    -- Check permission
    BEGIN
        SELECT get_is_editor_order_on_occasion(occasion_id_common) INTO has_permission;
    EXCEPTION
        WHEN undefined_function THEN RAISE EXCEPTION 'Permission check function get_is_editor_order_on_occasion() does not exist.' USING ERRCODE = '42883';
        WHEN OTHERS THEN RAISE EXCEPTION 'Error during permission check: %', SQLERRM;
    END;
    IF has_permission <> TRUE THEN
        RAISE EXCEPTION 'User is not authorized to edit orders for this occasion' USING ERRCODE = '42501';
    END IF;

    IF EXISTS(SELECT 1 FROM eshop.spots WHERE id IN(spot_id_1,spot_id_2)
      AND secret IS NOT NULL AND secret_expiration_time>clock_timestamp()) THEN
      RAISE object_not_in_prerequisite_state USING MESSAGE='SPOT_HELD'; END IF;
    -- Ticket locks follow the already locked order parents, in a stable order.
    PERFORM 1 FROM eshop.tickets WHERE id IN(SELECT ticket FROM eshop.order_product_ticket
      WHERE id IN(spot1.order_product_ticket,spot2.order_product_ticket)) ORDER BY id FOR UPDATE;

    -- 4. Main Swap Logic: Branch based on assignment status
    -- This logic is now greatly simplified by the helper functions.

    IF spot1.order_product_ticket IS NOT NULL AND spot2.order_product_ticket IS NOT NULL THEN
        -- ----------------------------------------------------------------
        -- CASE A: BOTH SPOTS ARE ASSIGNED
        -- ----------------------------------------------------------------

        -- Ticket 1 (from spot 1) moves to Spot 2, so it must adopt Spot 2's product.
        PERFORM public._swap_spots_update_ticket(spot1.order_product_ticket, spot2.product, spot_id_2);

        -- Ticket 2 (from spot 2) moves to Spot 1, so it must adopt Spot 1's product.
        PERFORM public._swap_spots_update_ticket(spot2.order_product_ticket, spot1.product, spot_id_1);

    ELSIF spot1.order_product_ticket IS NOT NULL OR spot2.order_product_ticket IS NOT NULL THEN
        -- ----------------------------------------------------------------
        -- CASE B/C: ONE SPOT IS ASSIGNED, ONE IS UNASSIGNED
        -- ----------------------------------------------------------------

        IF spot1.order_product_ticket IS NOT NULL THEN
            -- Spot 1 is assigned, Spot 2 is unassigned.
            -- Ticket 1 moves to Spot 2 and adopts Spot 2's product.
            PERFORM public._swap_spots_update_ticket(spot1.order_product_ticket, spot2.product, spot_id_2);
        ELSE
            -- Spot 2 is assigned, Spot 1 is unassigned.
            -- Ticket 2 moves to Spot 1 and adopts Spot 1's product.
            PERFORM public._swap_spots_update_ticket(spot2.order_product_ticket, spot1.product, spot_id_1);
        END IF;

    ELSE
        -- ----------------------------------------------------------------
        -- CASE D: BOTH SPOTS ARE UNASSIGNED
        -- ----------------------------------------------------------------
        -- Nothing to do.
        RETURN;
    END IF;

    -- 5. Final Spot Update
    -- This block runs for Cases A, B, and C.
    -- We ONLY swap the 'order_product_ticket' FK. The 'product' column
    -- on the spot (spot1.product, spot2.product) never changes.
    UPDATE eshop.spots
    SET
        order_product_ticket = CASE
            WHEN id = spot_id_1 THEN spot2.order_product_ticket -- Spot 1 gets Ticket 2
            WHEN id = spot_id_2 THEN spot1.order_product_ticket -- Spot 2 gets Ticket 1
        END
    WHERE id IN (spot_id_1, spot_id_2);

END;
$$;
REVOKE ALL ON FUNCTION public.swap_spot_tickets_internal_v1(bigint,bigint)
  FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.swap_spot_tickets(spot_id_1 bigint,spot_id_2 bigint)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = public, extensions AS $$
BEGIN
  PERFORM public.swap_spot_tickets_client_sync_v1(
    spot_id_1,spot_id_2,extensions.gen_random_uuid());
END; $$;
REVOKE ALL ON FUNCTION public.swap_spot_tickets(bigint,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.swap_spot_tickets(bigint,bigint) TO authenticated;

REVOKE ALL ON FUNCTION public._swap_spots_generate_product_json(bigint,bigint),public._swap_spots_update_ticket(bigint,bigint,bigint) FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/eshop/swap_spot_tickets_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.swap_spot_tickets_client_sync_v1(p_spot_1 bigint, p_spot_2 bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path = public, extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_users uuid[];
BEGIN
  SELECT occasion INTO v_occasion FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=v_actor AND command_name='inventory.spots.swap';
  IF NOT FOUND THEN
  SELECT min(s.occasion) INTO v_occasion FROM eshop.spots s
    WHERE s.id IN (p_spot_1,p_spot_2);
  END IF;
  IF v_actor IS NULL OR p_spot_1 IS NULL OR p_spot_2 IS NULL
    OR p_spot_1=p_spot_2 OR v_occasion IS NULL
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'spot1',p_spot_1,'spot2',p_spot_2)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.spots.swap',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF (SELECT count(*) FROM eshop.spots s
      WHERE s.id IN (p_spot_1,p_spot_2) AND s.occasion=v_occasion)<>2
 THEN RAISE insufficient_privilege USING MESSAGE='foreign spot swap'; END IF;

  PERFORM public.lock_spot_assignment_scope_internal_v1(ARRAY[p_spot_1,p_spot_2]);
  SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
  FROM eshop.spots s JOIN eshop.order_product_ticket opt
    ON opt.id=s.order_product_ticket JOIN public.occasion_users ou
    ON ou.ticket=opt.ticket AND ou.occasion=v_occasion
  WHERE s.id IN (p_spot_1,p_spot_2);
  PERFORM public.swap_spot_tickets_internal_v1(p_spot_1,p_spot_2);
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.spots.swap',jsonb_build_array(jsonb_build_object(
      'entityType','spot_assignment','entityId',NULL,'operation','update',
      'safeLabel','Spot ticket swap','changedFields',jsonb_build_array(
        'order_product_ticket','product'))),v_users,jsonb_build_object(
          'spotIds',jsonb_build_array(p_spot_1,p_spot_2)));
END; $function$;

REVOKE ALL ON FUNCTION public.swap_spot_tickets_client_sync_v1(bigint,bigint,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.swap_spot_tickets_client_sync_v1(bigint,bigint,uuid) TO authenticated;

-- Source: database/functions/inventory/save_resource_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_resource_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_resource jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_id bigint:=(p_resource->>'id')::bigint;
  v_pool bigint:=(p_resource->>'inventory_pool')::bigint; v_version bigint; v_origin_pool bigint;
  v_begin jsonb; v_hash text; v_current jsonb; v_entity jsonb;
  v_impacts jsonb; v_replacements jsonb:='[]'::jsonb;
BEGIN
  -- No booking rules and an empty rule document have the same domain meaning.
  IF p_resource->'booking_rules'='null'::jsonb THEN
    p_resource:=jsonb_set(p_resource,'{booking_rules}','{}'); END IF;
  IF v_actor IS NULL OR NOT public.get_is_editor_order_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion order editor required'; END IF;
  IF p_resource IS NULL OR jsonb_typeof(p_resource)<>'object'
    OR octet_length(p_resource::text)>131072
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_resource) key WHERE key NOT IN
      ('id','title','capacity','booking_rules','inventory_pool'))
    OR v_pool IS NULL OR length(btrim(COALESCE(p_resource->>'title',''))) NOT BETWEEN 1 AND 500
    OR coalesce((p_resource->>'capacity')::integer,-1) NOT BETWEEN 0 AND 1000000
    OR jsonb_typeof(COALESCE(p_resource->'booking_rules','{}'))<>'object' THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid resource aggregate'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'expectedVersion',p_expected_version,'resource',p_resource)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'inventory.resource.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.inventory_pools WHERE id=v_pool AND occasion=p_occasion) THEN
    RAISE invalid_parameter_value USING MESSAGE='inventory pool is outside occasion'; END IF;
  IF v_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.resources WHERE id=v_id AND occasion=p_occasion) THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',404,jsonb_build_object('version',0,'resource',NULL)); END IF;
  v_origin_pool:=public.lock_resource_pools_internal_v1(v_id,v_pool);
  PERFORM 1 FROM public.inventory_pools ip WHERE ip.id=v_pool
    AND ip.occasion=p_occasion FOR UPDATE;
  IF NOT FOUND THEN RAISE invalid_parameter_value USING MESSAGE='inventory pool is outside occasion'; END IF;
  IF v_id IS NOT NULL THEN
    SELECT to_jsonb(r) INTO v_current FROM public.resources r WHERE r.id=v_id
      AND r.occasion=p_occasion FOR UPDATE;
    IF v_current IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'rejected',404,jsonb_build_object('version',0,'resource',NULL)); END IF;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('resource','occasion',p_occasion,v_id::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='resource' AND scope_type='occasion'
        AND scope_id=p_occasion AND aggregate_id=v_id::text FOR UPDATE;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
        jsonb_build_object('version',v_version,'resource',v_current||
          jsonb_build_object('aggregate_version',v_version))); END IF;
    IF jsonb_build_object('title',v_current->>'title','capacity',(v_current->>'capacity')::integer,
      'booking_rules',COALESCE(v_current->'booking_rules','{}'),
      'inventory_pool',(v_current->>'inventory_pool')::bigint)=jsonb_build_object(
      'title',p_resource->>'title','capacity',(p_resource->>'capacity')::integer,
      'booking_rules',COALESCE(p_resource->'booking_rules','{}'),
      'inventory_pool',v_pool) THEN RETURN public.complete_client_mutation_outcome_v1(
        p_command_id,'unchanged',200,jsonb_build_object('version',v_version,
          'resource',v_current||jsonb_build_object('aggregate_version',v_version))); END IF;
    PERFORM 1 FROM eshop.spots WHERE resource=v_id OR resource_slot IN(SELECT id FROM public.resource_slots WHERE resource=v_id) ORDER BY id FOR UPDATE;
    IF (v_origin_pool IS DISTINCT FROM v_pool AND EXISTS(SELECT 1 FROM eshop.spots
      WHERE (resource=v_id OR resource_slot IN(SELECT id FROM public.resource_slots WHERE resource=v_id))
      AND (order_product_ticket IS NOT NULL OR (secret IS NOT NULL AND secret_expiration_time>clock_timestamp()))))
      OR EXISTS(SELECT 1 FROM eshop.spots WHERE (resource=v_id OR resource_slot IN(SELECT id FROM public.resource_slots WHERE resource=v_id))
        AND (order_product_ticket IS NOT NULL OR (secret IS NOT NULL AND secret_expiration_time>clock_timestamp()))
        GROUP BY inventory_context HAVING count(*)>(p_resource->>'capacity')::integer) THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,
        jsonb_build_object('version',v_version,'resourceId',v_id,'message','resource capacity or move conflicts with reserved spots')); END IF;
    IF v_origin_pool IS DISTINCT FROM v_pool THEN
      DELETE FROM eshop.spots WHERE resource=v_id OR resource_slot IN(SELECT id FROM public.resource_slots WHERE resource=v_id);
    END IF;
    UPDATE public.resources SET title=p_resource->>'title',
      capacity=(p_resource->>'capacity')::integer,
      booking_rules=COALESCE(p_resource->'booking_rules','{}'),inventory_pool=v_pool,
      updated_at=clock_timestamp() WHERE id=v_id;
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='resource'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text
      RETURNING version INTO v_version;
  ELSE
    IF p_expected_version IS NOT NULL THEN
      RAISE invalid_parameter_value USING MESSAGE='new resource must not have expected version'; END IF;
    INSERT INTO public.resources(occasion,inventory_pool,title,capacity,booking_rules)
    VALUES (p_occasion,v_pool,p_resource->>'title',(p_resource->>'capacity')::integer,
      COALESCE(p_resource->'booking_rules','{}')) RETURNING id INTO v_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('resource','occasion',p_occasion,v_id::text,v_version);
  END IF;
  IF v_origin_pool IS NOT NULL AND v_origin_pool IS DISTINCT FROM v_pool THEN
    PERFORM public.adjust_spot_capacity_for_pool(v_origin_pool);
  END IF;
  PERFORM public.adjust_spot_capacity_for_pool(v_pool);
  PERFORM public.advance_ticketing_authoring_version_internal_v1('inventory_pool',p_occasion,v_pool);
  IF v_origin_pool IS NOT NULL AND v_origin_pool IS DISTINCT FROM v_pool THEN
    PERFORM public.advance_ticketing_authoring_version_internal_v1('inventory_pool',p_occasion,v_origin_pool);
  END IF;
  SELECT to_jsonb(r)||jsonb_build_object('aggregate_version',v_version)
    INTO v_entity FROM public.resources r WHERE r.id=v_id;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_inventory',
    'userId',ou."user")),'[]'::jsonb) INTO v_impacts
    FROM public.occasion_users ou WHERE ou.occasion=p_occasion;
  IF EXISTS (SELECT 1 FROM public.occasion_users ou WHERE ou.occasion=p_occasion
    AND ou."user"=v_actor) THEN v_replacements:=jsonb_build_array(jsonb_build_object(
      'component','private_inventory','userId',v_actor,
      'payload',public.get_user_inventory_for_occasion_v1(p_occasion))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'inventory.resource.save','inventory',jsonb_build_array(jsonb_build_object(
      'entityType','resource','entityId',v_id,
      'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_resource->>'title',240),'changedFields',jsonb_build_array('aggregate'))),
    '{}',v_impacts,'[]',jsonb_build_object('version',v_version,'resource',v_entity),
    '{}','[]','user',NULL,v_replacements);
END; $function$;
REVOKE ALL ON FUNCTION public.save_resource_client_sync_v1(bigint,uuid,bigint,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_resource_client_sync_v1(bigint,uuid,bigint,jsonb) TO authenticated;

-- Source: database/functions/inventory/update_resource.sql
CREATE OR REPLACE FUNCTION public.update_resource(p_input jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_id bigint:=(p_input->>'id')::bigint; pool bigint:=(p_input->>'inventory_pool')::bigint; oc bigint; v bigint; current_row jsonb:='{}'; normalized jsonb; result jsonb;
BEGIN
 SELECT occasion INTO oc FROM public.inventory_pools WHERE inventory_pools.id=pool;
 PERFORM public.check_is_editor_order_on_occasion(oc);
 PERFORM public.lock_resource_pools_internal_v1(v_id,pool);
 IF v_id IS NOT NULL THEN
  SELECT to_jsonb(r) INTO current_row FROM public.resources r WHERE r.id=v_id AND r.occasion=oc FOR UPDATE;
  IF current_row IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='resource unavailable'; END IF;
  SELECT coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='resource' AND scope_type='occasion' AND scope_id=oc AND aggregate_id=v_id::text),0) INTO v;
 END IF;
 normalized:=coalesce(current_row,'{}')||p_input;
 SELECT jsonb_object_agg(key,value) INTO normalized FROM jsonb_each(normalized)
 WHERE key IN ('id','title','capacity','booking_rules','inventory_pool');
 result:=public.save_resource_client_sync_v1(oc,extensions.gen_random_uuid(),v,normalized);
 IF result->>'code'<>'200' THEN RAISE serialization_failure USING MESSAGE='resource save rejected'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.update_resource(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_resource(jsonb) TO authenticated;

-- Source: database/functions/inventory/delete_inventory_pool_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.delete_inventory_pool_client_sync_v1(p_occasion bigint, p_pool bigint, p_command_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_version bigint; v_title text; v_begin jsonb;
  v_hash text; v_reserved bigint; v_impacts jsonb;
  v_product_ids bigint[]; v_product_id bigint;
  v_replacements jsonb:='[]'::jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_order_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'poolId',p_pool,'expectedVersion',p_expected_version)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'inventory.pool.delete',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  v_product_ids:=public.lock_pool_product_dependencies_internal_v1(p_pool);
  SELECT ip.title INTO v_title FROM public.inventory_pools ip WHERE ip.id=p_pool
    AND ip.occasion=p_occasion FOR UPDATE;
  IF v_title IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'unchanged',200,jsonb_build_object('version',0,'pool',NULL)); END IF;
  PERFORM 1 FROM public.inventory_contexts ic WHERE ic.inventory_pool=p_pool
    ORDER BY ic.id FOR UPDATE;
  PERFORM 1 FROM public.resources r WHERE r.inventory_pool=p_pool
    ORDER BY r.id FOR UPDATE;
  PERFORM 1 FROM eshop.spots s WHERE s.inventory_context IN (
    SELECT ic.id FROM public.inventory_contexts ic WHERE ic.inventory_pool=p_pool)
    OR s.resource IN (SELECT r.id FROM public.resources r WHERE r.inventory_pool=p_pool) OR s.resource_slot IN (SELECT rs.id FROM public.resource_slots rs JOIN public.resources r ON r.id=rs.resource WHERE r.inventory_pool=p_pool)
    ORDER BY s.id FOR UPDATE;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('inventory_pool','occasion',p_occasion,p_pool::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='inventory_pool' AND scope_type='occasion'
      AND scope_id=p_occasion AND aggregate_id=p_pool::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('version',v_version,'poolId',p_pool)); END IF;
  SELECT count(*) INTO v_reserved FROM eshop.spots s
    WHERE (s.order_product_ticket IS NOT NULL OR (s.secret IS NOT NULL AND s.secret_expiration_time>clock_timestamp())) AND (s.inventory_context IN (
      SELECT ic.id FROM public.inventory_contexts ic WHERE ic.inventory_pool=p_pool)
      OR s.resource IN (SELECT r.id FROM public.resources r WHERE r.inventory_pool=p_pool) OR s.resource_slot IN (SELECT rs.id FROM public.resource_slots rs JOIN public.resources r ON r.id=rs.resource WHERE r.inventory_pool=p_pool));
  IF v_reserved>0 THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'rejected',409,jsonb_build_object('version',v_version,
      'poolId',p_pool,'message','inventory pool has reserved spots')); END IF;
  DELETE FROM eshop.spots s WHERE s.order_product_ticket IS NULL AND (
    s.inventory_context IN (SELECT ic.id FROM public.inventory_contexts ic
      WHERE ic.inventory_pool=p_pool) OR s.resource IN (
      SELECT r.id FROM public.resources r WHERE r.inventory_pool=p_pool) OR s.resource_slot IN (
      SELECT rs.id FROM public.resource_slots rs JOIN public.resources r ON r.id=rs.resource WHERE r.inventory_pool=p_pool));
  DELETE FROM public.client_aggregate_versions v WHERE v.scope_type='occasion'
    AND v.scope_id=p_occasion AND ((v.aggregate_type='resource' AND v.aggregate_id IN (
      SELECT r.id::text FROM public.resources r WHERE r.inventory_pool=p_pool))
      OR (v.aggregate_type='inventory_pool' AND v.aggregate_id=p_pool::text));
  DELETE FROM public.resources WHERE inventory_pool=p_pool;
  DELETE FROM public.inventory_contexts WHERE inventory_pool=p_pool;
  DELETE FROM public.inventory_pools WHERE id=p_pool;
  FOREACH v_product_id IN ARRAY v_product_ids LOOP
    PERFORM public.advance_ticketing_authoring_version_internal_v1('product',p_occasion,v_product_id);
  END LOOP;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_inventory',
    'userId',ou."user")),'[]'::jsonb) INTO v_impacts
    FROM public.occasion_users ou WHERE ou.occasion=p_occasion;
  IF EXISTS (SELECT 1 FROM public.occasion_users ou WHERE ou.occasion=p_occasion
    AND ou."user"=v_actor) THEN v_replacements:=jsonb_build_array(jsonb_build_object(
      'component','private_inventory','userId',v_actor,
      'payload',public.get_user_inventory_for_occasion_v1(p_occasion))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'inventory.pool.delete','inventory',jsonb_build_array(jsonb_build_object(
      'entityType','inventory_pool','entityId',p_pool,'operation','delete',
      'safeLabel',left(v_title,240),'changedFields',jsonb_build_array('aggregate'))),
    '{}',v_impacts,'[]',jsonb_build_object('version',v_version,'pool',NULL),
    '{}','[]','user',NULL,v_replacements);
END; $function$;
REVOKE ALL ON FUNCTION public.delete_inventory_pool_client_sync_v1(bigint,bigint,uuid,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.delete_inventory_pool_client_sync_v1(bigint,bigint,uuid,bigint) TO authenticated;

-- Source: database/functions/inventory/delete_inventory_pool.sql
CREATE OR REPLACE FUNCTION public.delete_inventory_pool(p_inventory_pool_id bigint)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE oc bigint; v bigint; result jsonb;
BEGIN
 SELECT occasion INTO oc FROM public.inventory_pools WHERE id=p_inventory_pool_id;
 PERFORM public.check_is_editor_order_on_occasion(oc);

 PERFORM public.lock_pool_product_dependencies_internal_v1(p_inventory_pool_id);
 PERFORM 1 FROM public.inventory_pools WHERE id=p_inventory_pool_id FOR UPDATE;
 SELECT coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='inventory_pool' AND scope_type='occasion' AND scope_id=oc AND aggregate_id=p_inventory_pool_id::text),0) INTO v;
 result:=public.delete_inventory_pool_client_sync_v1(oc,p_inventory_pool_id,extensions.gen_random_uuid(),v);
 IF result->>'code'<>'200' THEN RAISE serialization_failure USING MESSAGE='inventory deletion rejected'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.delete_inventory_pool(bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.delete_inventory_pool(bigint) TO authenticated;

-- Source: database/functions/inventory/delete_resource_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.delete_resource_client_sync_v1(p_occasion bigint, p_resource bigint, p_command_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_pool bigint; v_version bigint; v_title text;
  v_begin jsonb; v_hash text; v_impacts jsonb; v_replacements jsonb:='[]'::jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_order_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'resourceId',p_resource,'expectedVersion',p_expected_version)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'inventory.resource.delete',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  v_pool:=public.lock_resource_pools_internal_v1(p_resource);
  SELECT r.inventory_pool,r.title INTO v_pool,v_title FROM public.resources r
    WHERE r.id=p_resource AND r.occasion=p_occasion FOR UPDATE;
  IF v_pool IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'unchanged',200,jsonb_build_object('version',0,'resource',NULL)); END IF;
  PERFORM 1 FROM public.inventory_pools ip WHERE ip.id=v_pool FOR UPDATE;
  PERFORM 1 FROM eshop.spots s WHERE s.resource=p_resource OR s.resource_slot IN(SELECT id FROM public.resource_slots WHERE resource=p_resource) ORDER BY s.id FOR UPDATE;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('resource','occasion',p_occasion,p_resource::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='resource' AND scope_type='occasion'
      AND scope_id=p_occasion AND aggregate_id=p_resource::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('version',v_version,'resourceId',p_resource)); END IF;
  IF EXISTS (SELECT 1 FROM eshop.spots s WHERE (s.resource=p_resource OR s.resource_slot IN(SELECT id FROM public.resource_slots WHERE resource=p_resource))
    AND (s.order_product_ticket IS NOT NULL OR (s.secret IS NOT NULL AND s.secret_expiration_time>clock_timestamp()))) THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,
      jsonb_build_object('version',v_version,'resourceId',p_resource,
        'message','resource has reserved spots')); END IF;
  DELETE FROM eshop.spots WHERE resource=p_resource OR resource_slot IN(SELECT id FROM public.resource_slots WHERE resource=p_resource);
  DELETE FROM public.resources WHERE id=p_resource;
  PERFORM public.adjust_spot_capacity_for_pool(v_pool);
  PERFORM public.advance_ticketing_authoring_version_internal_v1('inventory_pool',p_occasion,v_pool);
  DELETE FROM public.client_aggregate_versions WHERE aggregate_type='resource'
    AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_resource::text;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_inventory',
    'userId',ou."user")),'[]'::jsonb) INTO v_impacts
    FROM public.occasion_users ou WHERE ou.occasion=p_occasion;
  IF EXISTS (SELECT 1 FROM public.occasion_users ou WHERE ou.occasion=p_occasion
    AND ou."user"=v_actor) THEN v_replacements:=jsonb_build_array(jsonb_build_object(
      'component','private_inventory','userId',v_actor,
      'payload',public.get_user_inventory_for_occasion_v1(p_occasion))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'inventory.resource.delete','inventory',jsonb_build_array(jsonb_build_object(
      'entityType','resource','entityId',p_resource,'operation','delete',
      'safeLabel',left(v_title,240),'changedFields',jsonb_build_array('aggregate'))),
    '{}',v_impacts,'[]',jsonb_build_object('version',v_version,'resource',NULL),
    '{}','[]','user',NULL,v_replacements);
END; $function$;
REVOKE ALL ON FUNCTION public.delete_resource_client_sync_v1(bigint,bigint,uuid,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.delete_resource_client_sync_v1(bigint,bigint,uuid,bigint) TO authenticated;

-- Source: database/functions/inventory/delete_resource.sql
CREATE OR REPLACE FUNCTION public.delete_resource(p_resource_id bigint)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE oc bigint; v bigint; result jsonb;
BEGIN
 SELECT occasion INTO oc FROM public.resources WHERE id=p_resource_id;
 PERFORM public.check_is_editor_order_on_occasion(oc);
 PERFORM public.lock_resource_pools_internal_v1(p_resource_id);
 SELECT coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='resource' AND scope_type='occasion' AND scope_id=oc AND aggregate_id=p_resource_id::text),0) INTO v;
 result:=public.delete_resource_client_sync_v1(oc,p_resource_id,extensions.gen_random_uuid(),v);
 IF result->>'code'<>'200' THEN RAISE serialization_failure USING MESSAGE='inventory deletion rejected'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.delete_resource(bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.delete_resource(bigint) TO authenticated;

-- Source: database/functions/cleaning/report_cleaning_issue.sql
-- Cleaning service — participant reports a problem on a toilet.
-- SECURITY DEFINER: participants have no direct write access to cleaning_reports
-- or log_notifications, so all validation, insert and crew notification happen
-- here. Envelope {code, message, data} like submit_event_feedback.
--
-- Behaviour:
--   * only approved occasion participants; place must exist, belong to the
--     occasion and be of place_type "toilet"; feature "cleaning" must be
--     enabled on the occasion.
--   * dedup: an already-open report of the same (place, problem_type) is NOT
--     duplicated and sends NO extra notification — returns 200 data.duplicate=true
--     and appends the reporter's note to the existing row so it is not lost.
--   * rate limit: max 5 reports per user per 15 minutes -> 429.
--   * on a fresh report, inserts a log_notifications row addressed to the crew
--     (data.path = 'cleaning' so the push deep-links to the Cleaning page).
CREATE OR REPLACE FUNCTION public.report_cleaning_issue_internal_v1(
  place_id bigint,
  problem_type text,
  note text DEFAULT NULL
) RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public, extensions
AS $$
DECLARE
  v_user uuid := auth.uid();
  v_note text := NULLIF(btrim(COALESCE(note, '')), '');
  v_place public.places%ROWTYPE;
  v_occasion bigint;
  v_organization bigint;
  v_type_label text;
  v_existing public.cleaning_reports%ROWTYPE;
  v_report public.cleaning_reports%ROWTYPE;
  v_crew jsonb;
  v_notification_deferred boolean:=false;
  v_notification uuid;
  v_policy jsonb; v_new_data jsonb;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Sign in is required to report a cleaning issue');
  END IF;

  -- Problem types — keep in sync with: cleaning_reports.problem_type CHECK
  -- (database/tables/tables.sql), CleaningStatusHelper (cleaning_status.dart)
  -- and the report dialog (cleaning_report_dialog.dart).
  IF problem_type NOT IN ('paper', 'hygiene', 'contamination') THEN
    RETURN jsonb_build_object('code', 400, 'message', 'Invalid problem type');
  END IF;

  IF char_length(COALESCE(v_note, '')) > 2000 THEN
    RETURN jsonb_build_object('code', 413, 'message', 'Note is too long');
  END IF;

  SELECT * INTO v_place FROM public.places WHERE id = place_id;
  IF NOT FOUND OR v_place.occasion IS NULL THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Toilet not found');
  END IF;

  v_occasion := v_place.occasion;

  IF NOT EXISTS (
    SELECT 1
    FROM public.occasion_users
    WHERE occasion = v_occasion
      AND "user" = v_user
      AND is_approved = true
  ) THEN
    RETURN jsonb_build_object('code', 403, 'message', 'Approved occasion participation is required');
  END IF;

  -- Blocked reporters (anti-spam hard ban) cannot file reports on this occasion.
  -- This is the source of truth; the UI also greys the report action out via the
  -- is_blocked flag returned by get_cleaning_status.
  IF EXISTS (
    SELECT 1 FROM public.occasion_users
    WHERE occasion = v_occasion
      AND "user" = v_user
      AND is_cleaning_blocked = true
  ) THEN
    RETURN jsonb_build_object('code', 403, 'message', 'Reporting has been disabled for your account');
  END IF;

  -- Place must be flagged as a toilet (places.type = 'toilet'). This is set by
  -- the "WC / Úklid" checkbox in the admin Places grid — no place_types catalog
  -- row is required.
  IF v_place.type IS DISTINCT FROM 'toilet' THEN
    RETURN jsonb_build_object('code', 400, 'message', 'Place is not a toilet');
  END IF;

  -- Feature "cleaning" must be enabled on the occasion (occasions.features).
  IF NOT EXISTS (
    SELECT 1
    FROM public.occasions o
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(o.features, '[]'::jsonb)) feature
    WHERE o.id = v_occasion
      AND feature->>'code' = 'cleaning'
      AND LOWER(COALESCE(feature->>'is_enabled', 'false')) = 'true'
  ) THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Cleaning feature is not enabled for this occasion');
  END IF;

  -- Committed accepted work, including appended duplicate notes, shares one
  -- actor identity. Removing a report cannot replenish its rolling budget.
  BEGIN
    v_policy:=public.abuse_effective_rules_v1('cleaning.report',NULL,NULL);
    PERFORM public.abuse_charge_v1(v_policy,
      jsonb_build_object('actor',v_user),jsonb_build_object('cleaning.note.bytes',octet_length(coalesce(v_note,'')), 'cleaning.report.bytes',0));
  EXCEPTION WHEN SQLSTATE 'PT429' THEN RETURN jsonb_build_object('code',429,'message','Too many reports, please wait a moment'); END;
  PERFORM pg_advisory_xact_lock(hashtextextended('cleaning-report:'||place_id::text||':'||problem_type,0));

  -- Push-notification labels are deliberately Czech-only (the crew is Czech;
  -- localizing push messages is out of scope). Keep the type list in sync — see
  -- the problem_type check above.
  v_type_label := CASE problem_type
    WHEN 'paper'         THEN 'Nedostatek toaletního papíru'
    WHEN 'hygiene'       THEN 'Nedostatek hygienických potřeb'
    WHEN 'contamination' THEN 'Totální znečištění ☣️'
  END;

  -- Dedup: reuse an open report of the same place + type.
  SELECT cr.* INTO v_existing
  FROM public.cleaning_reports cr
  WHERE cr.place = place_id
    AND cr.problem_type = report_cleaning_issue_internal_v1.problem_type
    AND cr.resolved_at IS NULL
  ORDER BY cr.created_at ASC
  LIMIT 1;

  IF FOUND THEN
    IF v_note IS NOT NULL THEN
      v_new_data:=COALESCE(v_existing.data,'{}'::jsonb)||jsonb_build_object('extra_notes',coalesce(v_existing.data->'extra_notes','[]'::jsonb)||to_jsonb(v_note));
      IF octet_length(v_new_data::text)>(SELECT (r->>'base_limit')::bigint FROM jsonb_array_elements(v_policy->'rules') r WHERE r->>'rule_key'='cleaning.report.bytes') THEN
        RETURN jsonb_build_object('code',429,'message','Report note capacity is limited'); END IF;
      UPDATE public.cleaning_reports SET data=v_new_data WHERE id=v_existing.id;
    END IF;
    RETURN jsonb_build_object('code',200,'data',jsonb_build_object('duplicate',true,'id',v_existing.id));
  END IF;

  INSERT INTO public.cleaning_reports (occasion, place, problem_type, note, created_by)
  VALUES (v_occasion, place_id, problem_type, v_note, v_user)
  RETURNING * INTO v_report;

  -- Notify the crew (uuid array of is_cleaning_crew users on this occasion),
  -- excluding anyone who muted cleaning notifications for themselves
  -- (occasion_users.data.cleaning_notifications_off).
  SELECT jsonb_agg("user"::text) INTO v_crew
  FROM public.occasion_users
  WHERE occasion = v_occasion
    AND is_cleaning_crew = true
    AND COALESCE((data->>'cleaning_notifications_off')::boolean, false) = false;

  IF v_crew IS NOT NULL AND jsonb_array_length(v_crew) > 0 THEN
    -- organization comes straight from the occasion row (occasions.organization
    -- is NOT NULL) — no magic fallback needed.
    SELECT organization INTO v_organization FROM public.occasions WHERE id = v_occasion;

    BEGIN
      PERFORM public.charge_notification_intent_v1(v_occasion,v_user,v_crew,v_place.title || ' - ' || v_type_label,COALESCE(v_note,v_type_label));
    INSERT INTO public.log_notifications (occasion, organization, user_id, "to", heading, content, data, abuse_admitted_at)
    VALUES (
      v_occasion,
      v_organization,
      v_user,
      v_crew,
      v_place.title || ' — ' || v_type_label,
      COALESCE(v_note, v_type_label),
      jsonb_build_object('path', 'cleaning'), statement_timestamp()
    ) RETURNING id INTO v_notification;
    PERFORM public.dispatch_log_notification_v1(v_notification);
    EXCEPTION WHEN SQLSTATE 'PT429' THEN v_notification_deferred:=true; END;
  END IF;

  RETURN jsonb_build_object(
    'code', 200,
    'data', jsonb_build_object('duplicate', false, 'id', v_report.id, 'notificationDeferred',v_notification_deferred)
  );
END;
$$;

REVOKE ALL ON FUNCTION public.report_cleaning_issue_internal_v1(bigint,text,text) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.report_cleaning_issue(place_id bigint,problem_type text,note text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE result jsonb;
BEGIN
 result:=public.report_cleaning_issue_client_sync_v1(place_id,problem_type,note,extensions.gen_random_uuid());
 RETURN jsonb_build_object('code',result->'code','message',result#>'{data,message}','data',result->'data');
END $$;
REVOKE ALL ON FUNCTION public.report_cleaning_issue(bigint,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.report_cleaning_issue(bigint,text,text) TO authenticated;

-- Source: database/functions/cleaning/report_cleaning_issue_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.report_cleaning_issue_client_sync_v1(p_place bigint, p_problem_type text, p_note text, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_result jsonb; v_existing bigint; v_has_note boolean;
BEGIN
  SELECT p.occasion INTO v_occasion FROM public.places p WHERE p.id=p_place;
  IF v_actor IS NULL OR v_occasion IS NULL THEN
    RAISE insufficient_privilege USING MESSAGE='signed-in occasion participant required';
  END IF;
  v_has_note:=NULLIF(btrim(COALESCE(p_note,'')),'') IS NOT NULL;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'place',p_place,'problemType',p_problem_type,'note',p_note)::text,'UTF8'),
    'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'cleaning.report',
    v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.places p WHERE p.id=p_place FOR UPDATE;
  SELECT cr.id INTO v_existing FROM public.cleaning_reports cr
    WHERE cr.place=p_place AND cr.problem_type=p_problem_type
      AND cr.resolved_at IS NULL ORDER BY cr.created_at LIMIT 1 FOR UPDATE;
  v_result:=public.report_cleaning_issue_internal_v1(p_place,p_problem_type,p_note);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),COALESCE(v_result->'data','{}')||
      jsonb_build_object('message',v_result->>'message')); END IF;
  IF v_existing IS NOT NULL AND NOT v_has_note THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      v_result->'data'); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,v_occasion,
    'cleaning.report','cleaning',jsonb_build_array(jsonb_build_object(
      'entityType','cleaning_report','entityId',v_result#>>'{data,id}',
      'operation',CASE WHEN v_existing IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel','Cleaning report','changedFields',CASE WHEN v_existing IS NULL
        THEN jsonb_build_array('place','problemType') ELSE jsonb_build_array('note') END)),
    CASE WHEN v_existing IS NULL THEN ARRAY['live_public'] ELSE '{}'::text[] END,
    '[]',CASE WHEN v_existing IS NULL THEN jsonb_build_array(jsonb_build_object(
      'component','live_public','entityId',p_place)) ELSE '[]'::jsonb END,
    v_result->'data');
END; $function$;
REVOKE ALL ON FUNCTION public.report_cleaning_issue_client_sync_v1(bigint,text,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.report_cleaning_issue_client_sync_v1(bigint,text,text,uuid) TO authenticated;

-- Source: database/functions/cleaning/resolve_cleaning_place.sql
CREATE OR REPLACE FUNCTION public.resolve_cleaning_place_internal_v1(place_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_occasion bigint;
  v_count integer;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Sign in is required');
  END IF;

  SELECT occasion INTO v_occasion FROM public.places WHERE id = place_id;
  IF v_occasion IS NULL THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Toilet not found');
  END IF;

  IF NOT public.get_is_cleaning_crew_on_occasion(v_occasion) THEN
    RETURN jsonb_build_object('code', 403, 'message', 'Cleaning crew access required');
  END IF;

  WITH updated AS (
    UPDATE public.cleaning_reports
    SET resolved_by = v_user,
        resolved_at = now()
    WHERE place = place_id
      AND resolved_at IS NULL
    RETURNING 1
  )
  SELECT count(*) INTO v_count FROM updated;

  RETURN jsonb_build_object(
    'code', 200,
    'data', jsonb_build_object('resolved', v_count)
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.resolve_cleaning_place_internal_v1(bigint) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.resolve_cleaning_place(place_id bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE result jsonb;
BEGIN
 result:=public.resolve_cleaning_place_client_sync_v1(place_id,extensions.gen_random_uuid());
 RETURN jsonb_build_object('code',result->'code','message',result#>'{data,message}','data',result->'data');
END $$;
REVOKE ALL ON FUNCTION public.resolve_cleaning_place(bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.resolve_cleaning_place(bigint) TO authenticated;

-- Source: database/functions/cleaning/resolve_cleaning_place_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.resolve_cleaning_place_client_sync_v1(p_place bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_occasion bigint;
  v_begin jsonb;
  v_hash text;
  v_result jsonb;
  v_open integer;
BEGIN
  SELECT p.occasion INTO v_occasion
  FROM public.places p
  WHERE p.id = p_place;

  IF v_actor IS NULL OR v_occasion IS NULL THEN
    RAISE insufficient_privilege USING MESSAGE = 'cleaning crew required';
  END IF;

  v_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'place', p_place
  )::text, 'UTF8'), 'sha256'), 'hex');
  v_begin := public.begin_client_mutation_v1(
    p_command_id,
    'cleaning.resolve',
    v_occasion,
    v_actor,
    v_hash
  );
  IF v_begin->>'disposition' = 'replay' THEN
    RETURN v_begin->'response';
  END IF;

  PERFORM 1 FROM public.places p WHERE p.id = p_place FOR UPDATE;
  PERFORM 1
  FROM public.cleaning_reports cr
  WHERE cr.place = p_place AND cr.resolved_at IS NULL
  ORDER BY cr.id
  FOR UPDATE;

  SELECT count(*) INTO v_open
  FROM public.cleaning_reports cr
  WHERE cr.place = p_place AND cr.resolved_at IS NULL;

  v_result := public.resolve_cleaning_place_internal_v1(p_place);
  IF COALESCE((v_result->>'code')::integer, 500) <> 200 THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,
      'rejected',
      COALESCE((v_result->>'code')::integer, 400),
      COALESCE(v_result->'data', '{}') ||
        jsonb_build_object('message', v_result->>'message')
    );
  END IF;

  IF v_open = 0 THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,
      'unchanged',
      200,
      v_result->'data'
    );
  END IF;

  RETURN public.complete_client_mutation_applied_v1(
    p_command_id,
    v_occasion,
    'cleaning.resolve',
    'cleaning',
    jsonb_build_array(jsonb_build_object(
      'entityType', 'cleaning_place',
      'entityId', p_place,
      'operation', 'update',
      'safeLabel', 'Cleaning place',
      'changedFields', jsonb_build_array('resolvedAt')
    )),
    ARRAY['live_public'],
    '[]',
    jsonb_build_array(jsonb_build_object(
      'component', 'live_public',
      'entityId', p_place
    )),
    v_result->'data'
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.resolve_cleaning_place_client_sync_v1(bigint,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.resolve_cleaning_place_client_sync_v1(bigint,uuid) TO authenticated;

-- Source: database/functions/cleaning/set_cleaning_notifications_muted.sql
CREATE OR REPLACE FUNCTION public.set_cleaning_notifications_muted_internal_v1(p_occasion bigint, p_muted boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_found boolean;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Sign in is required');
  END IF;

  UPDATE public.occasion_users
  SET data = COALESCE(data, '{}'::jsonb)
             || jsonb_build_object('cleaning_notifications_off', COALESCE(p_muted, false))
  WHERE occasion = p_occasion AND "user" = v_user
  RETURNING true INTO v_found;

  IF NOT COALESCE(v_found, false) THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Participant not found on this occasion');
  END IF;

  RETURN jsonb_build_object(
    'code', 200,
    'data', jsonb_build_object('muted', COALESCE(p_muted, false))
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.set_cleaning_notifications_muted_internal_v1(bigint,boolean) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.set_cleaning_notifications_muted(p_occasion bigint,p_muted boolean)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE result jsonb;
BEGIN
 result:=public.set_cleaning_notifications_muted_client_sync_v1(p_occasion,p_muted,extensions.gen_random_uuid());
 RETURN jsonb_build_object('code',result->'code','message',result#>'{data,message}','data',result->'data');
END $$;
REVOKE ALL ON FUNCTION public.set_cleaning_notifications_muted(bigint,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_cleaning_notifications_muted(bigint,boolean) TO authenticated;

-- Source: database/functions/cleaning/set_cleaning_notifications_muted_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.set_cleaning_notifications_muted_client_sync_v1(p_occasion bigint, p_muted boolean, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_result jsonb;
  v_current boolean; v_impacts jsonb; v_replacements jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE insufficient_privilege USING MESSAGE='sign in required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'muted',COALESCE(p_muted,false))::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'cleaning.notifications.set',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT COALESCE((ou.data->>'cleaning_notifications_off')::boolean,false)
    INTO v_current FROM public.occasion_users ou WHERE ou.occasion=p_occasion
      AND ou."user"=v_actor FOR UPDATE;
  v_result:=public.set_cleaning_notifications_muted_internal_v1(p_occasion,p_muted);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),COALESCE(v_result->'data','{}')||
      jsonb_build_object('message',v_result->>'message')); END IF;
  IF v_current IS NOT DISTINCT FROM COALESCE(p_muted,false) THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      v_result->'data'); END IF;
  v_impacts:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',v_actor));
  v_replacements:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',v_actor,
    'payload',public.get_private_profile_payload_v1(p_occasion,v_actor)));
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'cleaning.notifications.set','profile',jsonb_build_array(jsonb_build_object(
      'entityType','cleaning_preference','entityId',v_actor,'operation','update',
      'safeLabel','Cleaning notifications','changedFields',jsonb_build_array('muted'))),
    '{}',v_impacts,'[]',v_result->'data','{}','[]','user',NULL,v_replacements);
END; $function$;
REVOKE ALL ON FUNCTION public.set_cleaning_notifications_muted_client_sync_v1(bigint,boolean,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_cleaning_notifications_muted_client_sync_v1(bigint,boolean,uuid) TO authenticated;

-- Source: database/functions/cleaning/set_cleaning_reporter_blocked.sql
CREATE OR REPLACE FUNCTION public.set_cleaning_reporter_blocked_internal_v1(p_occasion bigint, p_user uuid, p_blocked boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_caller uuid := auth.uid();
  v_found boolean;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Sign in is required');
  END IF;

  IF p_user IS NULL THEN
    RETURN jsonb_build_object('code', 400, 'message', 'Target user is required');
  END IF;

  -- Blocking needs crew rights; unblocking needs the higher editor right.
  IF p_blocked THEN
    IF NOT public.get_is_cleaning_crew_on_occasion(p_occasion) THEN
      RETURN jsonb_build_object('code', 403, 'message', 'Cleaning crew access required');
    END IF;
  ELSE
    IF NOT public.get_is_editor_on_occasion(p_occasion) THEN
      RETURN jsonb_build_object('code', 403, 'message', 'Editor access required to unblock');
    END IF;
  END IF;

  IF p_blocked THEN
    UPDATE public.occasion_users
    SET is_cleaning_blocked = true,
        data = COALESCE(data, '{}'::jsonb) || jsonb_build_object(
          'cleaning_blocked_by', v_caller::text,
          'cleaning_blocked_at', to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SSOF'))
    WHERE occasion = p_occasion AND "user" = p_user
    RETURNING true INTO v_found;
  ELSE
    UPDATE public.occasion_users
    SET is_cleaning_blocked = false,
        data = COALESCE(data, '{}'::jsonb) - 'cleaning_blocked_by' - 'cleaning_blocked_at'
    WHERE occasion = p_occasion AND "user" = p_user
    RETURNING true INTO v_found;
  END IF;

  IF NOT COALESCE(v_found, false) THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Participant not found on this occasion');
  END IF;

  RETURN jsonb_build_object(
    'code', 200,
    'data', jsonb_build_object('blocked', p_blocked)
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.set_cleaning_reporter_blocked_internal_v1(bigint,uuid,boolean) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.set_cleaning_reporter_blocked(p_occasion bigint,p_user uuid,p_blocked boolean)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE result jsonb;
BEGIN
 result:=public.set_cleaning_reporter_blocked_client_sync_v1(p_occasion,p_user,p_blocked,extensions.gen_random_uuid());
 RETURN jsonb_build_object('code',result->'code','message',result#>'{data,message}','data',result->'data');
END $$;
REVOKE ALL ON FUNCTION public.set_cleaning_reporter_blocked(bigint,uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_cleaning_reporter_blocked(bigint,uuid,boolean) TO authenticated;

-- Source: database/functions/cleaning/set_cleaning_reporter_blocked_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.set_cleaning_reporter_blocked_client_sync_v1(p_occasion bigint, p_user uuid, p_blocked boolean, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_result jsonb;
  v_current boolean; v_impacts jsonb; v_replacements jsonb:='[]'::jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE insufficient_privilege USING MESSAGE='sign in required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'userId',p_user,'blocked',p_blocked)::text,'UTF8'),
    'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'cleaning.reporter.set',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT ou.is_cleaning_blocked INTO v_current FROM public.occasion_users ou
    WHERE ou.occasion=p_occasion AND ou."user"=p_user FOR UPDATE;
  v_result:=public.set_cleaning_reporter_blocked_internal_v1(
    p_occasion,p_user,p_blocked);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),COALESCE(v_result->'data','{}')||
      jsonb_build_object('message',v_result->>'message')); END IF;
  IF v_current IS NOT DISTINCT FROM p_blocked THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      v_result->'data'); END IF;
  v_impacts:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',p_user));
  IF p_user=v_actor THEN v_replacements:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',v_actor,
    'payload',public.get_private_profile_payload_v1(p_occasion,v_actor))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'cleaning.reporter.set','profile',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_user','entityId',p_user,'operation','update',
      'safeLabel','Cleaning reporter','changedFields',jsonb_build_array('blocked'))),
    '{}',v_impacts,'[]',v_result->'data','{}','[]','user',NULL,v_replacements);
END; $function$;
REVOKE ALL ON FUNCTION public.set_cleaning_reporter_blocked_client_sync_v1(bigint,uuid,boolean,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_cleaning_reporter_blocked_client_sync_v1(bigint,uuid,boolean,uuid) TO authenticated;

-- Source: database/functions/inventory/get_inventory_pools_by_occasion_link.sql
CREATE OR REPLACE FUNCTION public.get_inventory_pools_by_occasion_link(p_occasion_link text)
RETURNS jsonb
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_occasion_id bigint;
    v_occasion_data jsonb;
    v_pools_data jsonb;
    v_inventory_contexts_data jsonb;
    v_spots_data jsonb;
    result jsonb;
BEGIN
    -- Canonical merges may contain the same legacy link in multiple tenants.
    SELECT o.id
    INTO v_occasion_id
    FROM public.occasions o
    WHERE o.id = public.resolve_occasion_link_internal(p_occasion_link)
      AND o.organization = (
        SELECT ui.organization
        FROM public.user_info ui
        WHERE ui.id = auth.uid()
      );
    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Occasion with link % not found.', p_occasion_link;
    END IF;

    -- Permission check to ensure the user can view data for this occasion.
    IF NOT COALESCE((
        SELECT ou.is_editor_order_view
        FROM public.occasion_users ou
        WHERE ou."user" = auth.uid()
          AND ou.occasion = v_occasion_id
    ), false) THEN
        RAISE EXCEPTION 'User is not authorized to view this occasion.';
    END IF;

    -- Get the full occasion object
    SELECT to_jsonb(o) INTO v_occasion_data FROM public.occasions o WHERE id = v_occasion_id;

    -- Aggregate all inventory pools for the occasion, sorted by creation date.
    SELECT COALESCE(jsonb_agg(to_jsonb(ip) ORDER BY ip.created_at), '[]'::jsonb)
    INTO v_pools_data
    FROM public.inventory_pools ip
    WHERE ip.occasion = v_occasion_id;

    -- Aggregate all inventory_contexts for all pools of the occasion, sorted by the 'order' column.
    SELECT COALESCE(jsonb_agg(to_jsonb(ic) ORDER BY ic.order), '[]'::jsonb)
    INTO v_inventory_contexts_data
    FROM public.inventory_contexts ic
    WHERE ic.inventory_pool IN (SELECT id FROM public.inventory_pools WHERE occasion = v_occasion_id);

    -- Aggregate all spots that belong to any context within the occasion's pools
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'secret', s.secret,
        'secret_expiration_time', s.secret_expiration_time,
        'order_product_ticket', s.order_product_ticket,
        'inventory_context', s.inventory_context,
        'resource', s.resource,
        'state', s.state
    ) ORDER BY s.id), '[]'::jsonb)
    INTO v_spots_data
    FROM eshop.spots s
    WHERE s.inventory_context IN (
        SELECT id FROM public.inventory_contexts WHERE inventory_pool IN (
            SELECT id FROM public.inventory_pools WHERE occasion = v_occasion_id
        )
    );

    -- Construct the final bundle object with the new data
    result := jsonb_build_object(
        'occasion', v_occasion_data,
        'pools', v_pools_data,
        'inventory_contexts', v_inventory_contexts_data,
        'spots', v_spots_data
    );

    RETURN result;
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$ LANGUAGE plpgsql;

-- Source: database/functions/inventory/get_resources_for_inventory_pool_v1.sql
CREATE OR REPLACE FUNCTION public.get_resources_for_inventory_pool_v1(p_inventory_pool_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_occasion bigint; v_result jsonb;
BEGIN
  SELECT ip.occasion INTO v_occasion FROM public.inventory_pools ip
    WHERE ip.id=p_inventory_pool_id;
  IF v_occasion IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='inventory pool not found'; END IF;
  PERFORM public.check_is_editor_order_view_on_occasion(v_occasion);
  SELECT COALESCE(jsonb_agg(to_jsonb(r)||jsonb_build_object(
    'aggregate_version',COALESCE(v.version,0)) ORDER BY r.id),'[]'::jsonb)
    INTO v_result FROM public.resources r
    LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='resource'
      AND v.scope_type='occasion' AND v.scope_id=v_occasion
      AND v.aggregate_id=r.id::text
    WHERE r.inventory_pool=p_inventory_pool_id;
  RETURN v_result;
END; $function$;
REVOKE ALL ON FUNCTION public.get_resources_for_inventory_pool_v1(bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_resources_for_inventory_pool_v1(bigint) TO authenticated;

-- Source: database/functions/activities/canonical_activity_lifecycle.sql
CREATE OR REPLACE FUNCTION public.lock_activity_aggregate_internal_v1(p_occasion bigint)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v bigint;
BEGIN
 PERFORM public.lock_group_occasion_internal_v1(p_occasion);
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version) VALUES('activities','occasion',p_occasion,p_occasion::text,0) ON CONFLICT DO NOTHING;
 SELECT version INTO v FROM public.client_aggregate_versions WHERE aggregate_type='activities' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_occasion::text FOR UPDATE;
 RETURN v;
END $$;
CREATE OR REPLACE FUNCTION public.lock_activity_editor_internal_v1(p_occasion bigint)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v bigint;
BEGIN
 v:=public.lock_activity_aggregate_internal_v1(p_occasion);
 IF auth.uid() IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
 RETURN v;
END $$;
REVOKE ALL ON FUNCTION public.lock_activity_aggregate_internal_v1(bigint) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.retain_activity_history_internal_v1(p_occasion bigint)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE protected bigint[]; depth int;
BEGIN
 WITH RECURSIVE roots AS (
 SELECT id,parent_history_id FROM public.activity_history WHERE occasion_id=p_occasion AND history_type='AUTOSAVE'
 UNION SELECT id,parent_history_id FROM (SELECT id,parent_history_id FROM public.activity_history WHERE occasion_id=p_occasion AND history_type='PUBLISH' ORDER BY id DESC LIMIT 1) latest
 ), chain AS (
 SELECT id,parent_history_id,ARRAY[id] path,1 depth FROM roots
 UNION ALL SELECT h.id,h.parent_history_id,c.path||h.id,c.depth+1 FROM chain c JOIN public.activity_history h ON h.id=c.parent_history_id AND h.occasion_id=p_occasion WHERE NOT h.id=ANY(c.path) AND c.depth<10000
 ) SELECT array_agg(DISTINCT id),max(chain.depth) INTO protected,depth FROM chain;
 -- Fail closed on unbounded history: do not silently cut a protected chain.
 IF depth>=10000 THEN RETURN; END IF;
 DELETE FROM public.activity_history WHERE occasion_id=p_occasion AND created_at<now()-interval '30 days' AND NOT id=ANY(COALESCE(protected,'{}'::bigint[]));
END $$;
CREATE OR REPLACE FUNCTION public.save_activity_draft_client_sync_v1(p_occasion bigint,p_command_id uuid,p_expected_version bigint,p_history_data jsonb,p_parent_history_id bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE actor uuid:=auth.uid(); b jsonb; v bigint; latest bigint; draft public.activity_history%rowtype; graph jsonb; history jsonb; result jsonb; hid bigint;
BEGIN
 PERFORM public.assert_canonical_mutation_write_release_internal_v1(p_occasion);
 IF actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
 IF p_history_data IS NULL OR jsonb_typeof(p_history_data)<>'object' OR octet_length(p_history_data::text)>2097152 THEN RAISE invalid_parameter_value USING MESSAGE='invalid draft'; END IF;
 b:=public.begin_client_mutation_v1(p_command_id,'activities.draft.save',p_occasion,actor,encode(extensions.digest(jsonb_build_object('occasion',p_occasion,'expectedVersion',p_expected_version,'history',p_history_data,'parent',p_parent_history_id)::text,'sha256'),'hex'));
 v:=public.lock_activity_editor_internal_v1(p_occasion);
 IF b->>'disposition'='replay' THEN RETURN b->'response'; END IF;
 SELECT id INTO latest FROM public.activity_history WHERE occasion_id=p_occasion AND history_type='PUBLISH' ORDER BY id DESC LIMIT 1;
 IF p_expected_version IS DISTINCT FROM v OR p_parent_history_id IS DISTINCT FROM latest THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('version',v,'latestPublishId',latest)); END IF;
 graph:=public.activity_history_graph_internal_v1(p_occasion,p_history_data-'_consume_autosave'); history:=public.activity_graph_history_internal_v1(graph);
 SELECT * INTO draft FROM public.activity_history WHERE occasion_id=p_occasion AND user_id=actor AND history_type='AUTOSAVE' ORDER BY id DESC LIMIT 1;
 result:=jsonb_build_object('version',v,'latestPublishId',latest,'draftId',draft.id,'draftParentHistoryId',latest);
 IF draft.id IS NOT NULL AND draft.activities_data=history AND draft.parent_history_id IS NOT DISTINCT FROM latest THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,result); END IF;
 hid:=public.write_activity_history_internal_v1(p_occasion,actor,history,'AUTOSAVE',latest,NULL);
 PERFORM public.retain_activity_history_internal_v1(p_occasion);
 RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,'activities.draft.save','activities',jsonb_build_array(jsonb_build_object('entityType','activity_draft','entityId',hid,'operation',CASE WHEN draft.id IS NULL THEN 'insert' ELSE 'update' END,'changedFields',jsonb_build_array('draft'))),'{}','[]','[]',result||jsonb_build_object('draftId',hid));
END $$;
CREATE OR REPLACE FUNCTION public.discard_activity_draft_client_sync_v1(p_occasion bigint,p_command_id uuid,p_expected_draft_id bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE actor uuid:=auth.uid(); b jsonb; v bigint; draft bigint;
BEGIN
 PERFORM public.assert_canonical_mutation_write_release_internal_v1(p_occasion);
 IF actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
 b:=public.begin_client_mutation_v1(p_command_id,'activities.draft.discard',p_occasion,actor,encode(extensions.digest(jsonb_build_object('occasion',p_occasion,'draft',p_expected_draft_id)::text,'sha256'),'hex'));
 v:=public.lock_activity_editor_internal_v1(p_occasion);
 IF b->>'disposition'='replay' THEN RETURN b->'response'; END IF;
 SELECT id INTO draft FROM public.activity_history WHERE occasion_id=p_occasion AND user_id=actor AND history_type='AUTOSAVE' ORDER BY id DESC LIMIT 1;
 IF draft IS DISTINCT FROM p_expected_draft_id THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('version',v,'draftId',draft)); END IF;
 IF draft IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,jsonb_build_object('version',v,'draftId',NULL)); END IF;
 PERFORM public.clear_activity_draft_internal_v1(p_occasion,actor,NULL,false);
 RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,'activities.draft.discard','activities',jsonb_build_array(jsonb_build_object('entityType','activity_draft','entityId',draft,'operation','delete','changedFields',jsonb_build_array('draft'))),'{}','[]','[]',jsonb_build_object('version',v,'draftId',NULL));
END $$;
CREATE OR REPLACE FUNCTION public.publish_activities_client_sync_v1(p_occasion bigint,p_command_id uuid,p_expected_version bigint,p_activities_data jsonb,p_history_data jsonb,p_parent_history_id bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE actor uuid:=auth.uid(); b jsonb; v bigint; latest bigint; graph jsonb; history jsonb; old_graph jsonb; previous_history jsonb; hid bigint; live_changed boolean; deleted int; impacts jsonb; replacements jsonb:='[]'; users uuid[];
BEGIN
 PERFORM public.assert_canonical_mutation_write_release_internal_v1(p_occasion);
 IF actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
 IF p_activities_data IS NULL OR jsonb_typeof(p_activities_data)<>'array' OR p_history_data IS NULL OR jsonb_typeof(p_history_data)<>'object' OR octet_length(p_activities_data::text)>2097152 OR octet_length(p_history_data::text)>2097152 THEN RAISE invalid_parameter_value USING MESSAGE='invalid activities aggregate'; END IF;
 b:=public.begin_client_mutation_v1(p_command_id,'activities.publish',p_occasion,actor,encode(extensions.digest(jsonb_build_object('occasion',p_occasion,'expectedVersion',p_expected_version,'activities',p_activities_data,'history',p_history_data,'parentHistoryId',p_parent_history_id)::text,'sha256'),'hex'));
 v:=public.lock_activity_editor_internal_v1(p_occasion);
 IF b->>'disposition'='replay' THEN RETURN b->'response'; END IF;
 SELECT id,activities_data INTO latest,previous_history FROM public.activity_history WHERE occasion_id=p_occasion AND history_type='PUBLISH' ORDER BY id DESC LIMIT 1;
 IF p_expected_version IS DISTINCT FROM v OR p_parent_history_id IS DISTINCT FROM latest THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('version',v,'latestPublishId',latest,'historyId',latest)); END IF;
 graph:=public.normalize_activity_graph_internal_v1(p_occasion,p_activities_data,true);
 IF graph IS DISTINCT FROM public.activity_history_graph_internal_v1(p_occasion,p_history_data-'_consume_autosave') THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',400,jsonb_build_object('version',v,'latestPublishId',latest,'reason','graph_history_mismatch')); END IF;
 history:=public.activity_graph_history_internal_v1(graph); old_graph:=public.current_activity_graph_internal_v1(p_occasion);
 live_changed:=graph IS DISTINCT FROM old_graph OR latest IS NULL;
 IF NOT live_changed AND public.activity_history_graph_internal_v1(p_occasion,previous_history)=graph THEN
  deleted:=public.consume_selected_activity_draft_internal_v1(p_occasion,actor,latest,p_history_data->'_consume_autosave',graph);
  IF deleted=0 THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,jsonb_build_object('version',v,'historyId',latest,'latestPublishId',latest,'draftId',(SELECT id FROM public.activity_history WHERE occasion_id=p_occasion AND user_id=actor AND history_type='AUTOSAVE' ORDER BY id DESC LIMIT 1),'draftConsumed',false)); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,'activities.publish','activities',jsonb_build_array(jsonb_build_object('entityType','activity_draft','entityId',NULL,'operation','delete','changedFields',jsonb_build_array('draft'))),'{}','[]','[]',jsonb_build_object('version',v,'historyId',latest,'latestPublishId',latest,'draftId',NULL,'draftConsumed',true));
 END IF;
 SELECT ARRAY(SELECT DISTINCT (x->>'user')::uuid FROM jsonb_array_elements(old_graph||graph) a,LATERAL jsonb_array_elements(a->'assignments') x WHERE x->>'user' IS NOT NULL UNION SELECT actor) INTO users;
 PERFORM public.replace_activities_graph_internal_v1(p_occasion,graph);
 hid:=public.write_activity_history_internal_v1(p_occasion,actor,history,'PUBLISH',latest,'Published via application');
 deleted:=public.consume_selected_activity_draft_internal_v1(p_occasion,actor,latest,p_history_data->'_consume_autosave',graph);
 UPDATE public.client_aggregate_versions SET version=version+1,updated_at=clock_timestamp() WHERE aggregate_type='activities' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_occasion::text RETURNING version INTO v;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_activity','userId',u) ORDER BY u),'[]') INTO impacts FROM unnest(users) u JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=u;
 replacements:=jsonb_build_array(jsonb_build_object('component','private_activity','userId',actor,'payload',(public.get_my_events_and_activities(p_occasion,true)->'data')));
 PERFORM public.retain_activity_history_internal_v1(p_occasion);
 RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,'activities.publish','activities',jsonb_build_array(jsonb_build_object('entityType','activities','entityId',p_occasion,'operation','publish','changedFields',jsonb_build_array('graph','history'))),'{}',impacts,'[]',jsonb_build_object('version',v,'historyId',hid,'latestPublishId',hid,'draftId',(SELECT id FROM public.activity_history WHERE occasion_id=p_occasion AND user_id=actor AND history_type='AUTOSAVE' ORDER BY id DESC LIMIT 1),'draftConsumed',deleted>0,'activities',graph),'{}','[]','user',NULL,replacements);
END $$;
REVOKE ALL ON FUNCTION public.lock_activity_editor_internal_v1(bigint),public.retain_activity_history_internal_v1(bigint) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.save_activity_draft_client_sync_v1(bigint,uuid,bigint,jsonb,bigint),public.discard_activity_draft_client_sync_v1(bigint,uuid,bigint),public.publish_activities_client_sync_v1(bigint,uuid,bigint,jsonb,jsonb,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_activity_draft_client_sync_v1(bigint,uuid,bigint,jsonb,bigint),public.discard_activity_draft_client_sync_v1(bigint,uuid,bigint),public.publish_activities_client_sync_v1(bigint,uuid,bigint,jsonb,jsonb,bigint) TO authenticated;

-- Source: database/functions/activities/get_activities_for_edit.sql
CREATE OR REPLACE FUNCTION public.get_activities_for_edit(
    p_occasion BIGINT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    eventsData              JSONB;
    placesData              JSONB;
    activitiesData          JSONB;
    assignmentPlaceLinksData JSONB;
    assignmentEventLinksData JSONB;
    aaData                  JSONB;
    usersData               JSONB;
BEGIN

   -- Authorization check
    IF (SELECT get_is_editor_view_on_occasion(p_occasion)) <> TRUE THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to view this occasion''s edit data');
    END IF;

    -- (a) all events
    SELECT jsonb_agg(jsonb_build_object(
        'id', e.id, 'created_at', e.created_at, 'title', e.title, 'start_time', e.start_time,
        'end_time', e.end_time, 'max_participants', e.max_participants, 'description', e.description,
        'place', e.place, 'split_for_men_women', e.split_for_men_women, 'is_group_event', e.is_group_event,
        'updated_at', e.updated_at, 'is_hidden', e.is_hidden, 'occasion', e.occasion, 'type', e.type, 'data', e.data
    )) INTO eventsData
    FROM public.events e WHERE e.occasion = p_occasion;

    -- (b) all places for this occasion, sorted by places.order
    -- The jsonb_agg function will respect the order of the rows it aggregates.
    SELECT jsonb_agg(place_obj ORDER BY place_order ASC)
    INTO placesData
    FROM (
        SELECT jsonb_build_object(
            'id', p.id, 'title', p.title, 'description', p.description, 'type', p.type, 'created_at', p.created_at,
            'coordinates', p.coordinates, 'is_hidden', p.is_hidden, 'updated_at', p.updated_at, 'occasion', p.occasion,
            'order', p."order"
        ) AS place_obj,
        p."order" AS place_order
        FROM public.places p
        WHERE p.occasion = p_occasion
    ) AS ordered_places;


    -- (c) all activities
    SELECT jsonb_agg(jsonb_build_object(
        'id', a.id, 'created_at', a.created_at, 'updated_at', a.updated_at, 'title', a.title,
        'description', a.description, 'type', a.type, 'occasion', a.occasion, 'unit', a.unit,
        'is_hidden', a.is_hidden, 'order', a."order", 'data', a.data
    )) INTO activitiesData
    FROM public.activities a WHERE a.occasion = p_occasion;

    -- (d) activity_assignment_places links (now assignment_id <-> place_id)
    SELECT jsonb_agg(jsonb_build_object(
        'assignment_id', apl.assignment_id,
        'place_id',      apl.place_id
    )) INTO assignmentPlaceLinksData
    FROM public.activity_assignment_places apl
    JOIN public.activity_assignments aa ON apl.assignment_id = aa.id
    JOIN public.activities a ON aa.activity_id = a.id
    WHERE a.occasion = p_occasion;

    -- (e) activity_assignment_events links (now assignment_id <-> event_id)
    SELECT jsonb_agg(jsonb_build_object(
        'assignment_id', ael.assignment_id,
        'event_id',      ael.event_id
    )) INTO assignmentEventLinksData
    FROM public.activity_assignment_events ael
    JOIN public.activity_assignments aa ON ael.assignment_id = aa.id
    JOIN public.activities a ON aa.activity_id = a.id
    WHERE a.occasion = p_occasion;

    -- (f) activity_assignments
    SELECT jsonb_agg(jsonb_build_object(
        'id', aa.id, 'activity_id', aa.activity_id, 'user', aa."user", 'start_time', aa.start_time,
        'end_time', aa.end_time, 'title', aa.title, 'description', aa.description, 'data', aa.data
    )) INTO aaData
    FROM public.activity_assignments aa
    JOIN public.activities a ON aa.activity_id = a.id
    WHERE a.occasion = p_occasion;

    -- (g) users for this occasion who are volunteers
    SELECT jsonb_agg(jsonb_build_object(
        'id', ui.id, 'name', ui.name, 'surname', ui.surname, 'sex', ui.sex, 'email', ui.email_readonly
    )) INTO usersData
    FROM public.user_info ui
    JOIN public.occasion_users ou ON ui.id = ou."user"
    WHERE ou.occasion = p_occasion AND (ou.data->>'is_volunteer')::boolean = TRUE;

    -- (h) assemble
    RETURN jsonb_build_object(
      'code', 200,
      'message', 'Data for editing activities retrieved successfully.',
      'data', jsonb_build_object(
        'events',                  COALESCE(eventsData, '[]'::jsonb),
        'places',                  COALESCE(placesData, '[]'::jsonb),
        'activities',              COALESCE(activitiesData, '[]'::jsonb),
        'assignment_place_links',  COALESCE(assignmentPlaceLinksData, '[]'::jsonb),
        'assignment_event_links',  COALESCE(assignmentEventLinksData, '[]'::jsonb),
        'activity_assignments',    COALESCE(aaData, '[]'::jsonb),
        'user_info',               COALESCE(usersData, '[]'::jsonb),
        'aggregate_version',       COALESCE((SELECT av.version
          FROM public.client_aggregate_versions av
          WHERE av.aggregate_type='activities' AND av.scope_type='occasion'
            AND av.scope_id=p_occasion AND av.aggregate_id=p_occasion::text),0)
      )
    );
END;
$$;

-- Source: database/functions/events/get_exclusive_group_command_data_v1.sql
CREATE OR REPLACE FUNCTION public.get_exclusive_group_command_data_v1(p_group bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path = public, extensions
AS $function$
  SELECT jsonb_build_object(
    'id',g.id,
    'title',g.title,
    'exclusive_events',COALESCE((SELECT jsonb_agg(
      jsonb_build_object('event',ee.event) ORDER BY ee.event)
      FROM public.exclusive_events ee WHERE ee."group"=g.id),'[]'::jsonb),
    'aggregate_version',COALESCE(v.version,0))
  FROM public.exclusive_groups g
  LEFT JOIN public.client_aggregate_versions v
    ON v.aggregate_type='exclusive_group' AND v.scope_type='occasion'
    AND v.scope_id=g.occasion AND v.aggregate_id=g.id::text
  WHERE g.id=p_group;
$function$
;
REVOKE ALL ON FUNCTION public.get_exclusive_group_command_data_v1(p_group bigint) FROM PUBLIC,anon,authenticated;

-- Source: database/functions/events/get_exclusive_groups_for_edit_v1.sql
CREATE OR REPLACE FUNCTION public.get_exclusive_groups_for_edit_v1(p_occasion bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path = public, extensions
AS $function$
DECLARE v_result jsonb;
BEGIN
  IF NOT public.get_is_editor_view_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor view required';
  END IF;
  SELECT COALESCE(jsonb_agg(public.get_exclusive_group_command_data_v1(g.id)
    ORDER BY g.title,g.id),'[]'::jsonb) INTO v_result
  FROM public.exclusive_groups g WHERE g.occasion=p_occasion;
  RETURN v_result;
END; $function$
;
REVOKE ALL ON FUNCTION public.get_exclusive_groups_for_edit_v1(p_occasion bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_exclusive_groups_for_edit_v1(p_occasion bigint) TO authenticated;

-- Source: database/functions/events/save_exclusive_group_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_exclusive_group_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_group jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_id bigint; v_version bigint; v_begin jsonb;
  v_hash text; v_current jsonb; v_entity jsonb; v_event_ids bigint[];
  v_requested jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  IF p_group IS NULL OR jsonb_typeof(p_group)<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_group) key
      WHERE key NOT IN ('id','title','events'))
    OR nullif(btrim(p_group->>'title'),'') IS NULL
    OR octet_length(p_group->>'title')>2048
    OR jsonb_typeof(p_group->'events')<>'array'
    OR jsonb_array_length(p_group->'events')>500
    OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_group->'events') value
      WHERE jsonb_typeof(value)<>'number') THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid exclusive group'; END IF;
  SELECT COALESCE(array_agg(value::text::bigint ORDER BY value::text::bigint),
    '{}'::bigint[]) INTO v_event_ids FROM jsonb_array_elements(p_group->'events');
  IF cardinality(v_event_ids)<>cardinality(ARRAY(SELECT DISTINCT unnest(v_event_ids))) THEN
    RAISE invalid_parameter_value USING MESSAGE='duplicate exclusive event'; END IF;
  v_id:=(p_group->>'id')::bigint;
  IF v_id IS NULL AND p_expected_version IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new group must not have expected version'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'expectedVersion',p_expected_version,
    'group',p_group)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'schedule.exclusive_group.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF EXISTS (SELECT 1 FROM unnest(v_event_ids) event_id WHERE NOT EXISTS (
    SELECT 1 FROM public.events e WHERE e.id=event_id AND e.occasion=p_occasion)) THEN
    RAISE invalid_parameter_value USING MESSAGE='exclusive event outside occasion'; END IF;
  PERFORM 1 FROM public.events e WHERE e.id=ANY(v_event_ids) ORDER BY e.id FOR UPDATE;
  IF v_id IS NOT NULL THEN
    PERFORM 1 FROM public.exclusive_groups g WHERE g.id=v_id
      AND g.occasion=p_occasion FOR UPDATE;
    IF NOT FOUND THEN RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'rejected',404,jsonb_build_object('version',0,'group',NULL)); END IF;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('exclusive_group','occasion',p_occasion,v_id::text,0)
    ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='exclusive_group' AND scope_type='occasion'
      AND scope_id=p_occasion AND aggregate_id=v_id::text FOR UPDATE;
    v_current:=public.get_exclusive_group_command_data_v1(v_id);
    IF p_expected_version IS DISTINCT FROM v_version THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
        jsonb_build_object('version',v_version,'group',v_current)); END IF;
    v_requested:=jsonb_build_object('id',v_id,'title',p_group->>'title',
      'exclusive_events',COALESCE((SELECT jsonb_agg(jsonb_build_object('event',event_id)
        ORDER BY event_id) FROM unnest(v_event_ids) event_id),'[]'::jsonb),
      'aggregate_version',v_version);
    IF v_current=v_requested THEN RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'unchanged',200,jsonb_build_object(
        'version',v_version,'group',v_current)); END IF;
    UPDATE public.exclusive_groups SET title=p_group->>'title' WHERE id=v_id;
    DELETE FROM public.exclusive_events WHERE "group"=v_id;
    INSERT INTO public.exclusive_events("group",event)
      SELECT v_id,event_id FROM unnest(v_event_ids) event_id;
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='exclusive_group'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text
      RETURNING version INTO v_version;
  ELSE
    INSERT INTO public.exclusive_groups(title,occasion)
      VALUES (p_group->>'title',p_occasion) RETURNING id INTO v_id;
    INSERT INTO public.exclusive_events("group",event)
      SELECT v_id,event_id FROM unnest(v_event_ids) event_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('exclusive_group','occasion',p_occasion,v_id::text,v_version);
  END IF;
  v_entity:=public.get_exclusive_group_command_data_v1(v_id);
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'schedule.exclusive_group.save','schedule_constraints',
    jsonb_build_array(jsonb_build_object('entityType','exclusive_group',
      'entityId',v_id,'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_group->>'title',240),
      'changedFields',jsonb_build_array('title','events'))),
    '{}','[]','[]',jsonb_build_object('version',v_version,'group',v_entity));
END; $function$
;
REVOKE ALL ON FUNCTION public.save_exclusive_group_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_group jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_exclusive_group_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_group jsonb) TO authenticated;

-- Source: database/functions/events/delete_exclusive_group_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.delete_exclusive_group_client_sync_v1(p_occasion bigint, p_group_id bigint, p_command_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_version bigint; v_begin jsonb; v_hash text;
  v_entity jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'groupId',p_group_id,
    'expectedVersion',p_expected_version)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'schedule.exclusive_group.delete',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.exclusive_groups g WHERE g.id=p_group_id
    AND g.occasion=p_occasion FOR UPDATE;
  IF NOT FOUND THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'unchanged',200,jsonb_build_object('version',0,'group',NULL)); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('exclusive_group','occasion',p_occasion,p_group_id::text,0)
  ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='exclusive_group' AND scope_type='occasion'
    AND scope_id=p_occasion AND aggregate_id=p_group_id::text FOR UPDATE;
  v_entity:=public.get_exclusive_group_command_data_v1(p_group_id);
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('version',v_version,'group',v_entity)); END IF;
  DELETE FROM public.exclusive_events WHERE "group"=p_group_id;
  DELETE FROM public.exclusive_groups WHERE id=p_group_id;
  DELETE FROM public.client_aggregate_versions WHERE aggregate_type='exclusive_group'
    AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_group_id::text;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'schedule.exclusive_group.delete','schedule_constraints',
    jsonb_build_array(jsonb_build_object('entityType','exclusive_group',
      'entityId',p_group_id,'operation','delete','safeLabel',left(v_entity->>'title',240),
      'changedFields',jsonb_build_array('aggregate'))),
    '{}','[]','[]',jsonb_build_object('version',v_version,'group',NULL));
END; $function$
;
REVOKE ALL ON FUNCTION public.delete_exclusive_group_client_sync_v1(p_occasion bigint, p_group_id bigint, p_command_id uuid, p_expected_version bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.delete_exclusive_group_client_sync_v1(p_occasion bigint, p_group_id bigint, p_command_id uuid, p_expected_version bigint) TO authenticated;

-- Source: database/functions/news/save_news_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_news_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_news jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_id bigint; v_version bigint; v_begin jsonb;
  v_hash text; v_current jsonb; v_entity jsonb; v_is_publishable boolean;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  SELECT NOT o.is_hidden INTO v_is_publishable FROM public.occasions o
    WHERE o.id=p_occasion;
  IF v_is_publishable IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='occasion not found';
  END IF;
  IF p_news IS NULL OR jsonb_typeof(p_news)<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_news) key
      WHERE key NOT IN ('id','message'))
    OR NOT (p_news ? 'message')
    OR octet_length(COALESCE(p_news->>'message','')) NOT BETWEEN 1 AND 524288 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid news';
  END IF;
  v_id:=(p_news->>'id')::bigint;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'expectedVersion',p_expected_version,
    'news',p_news)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.news.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF v_id IS NOT NULL THEN
    SELECT jsonb_build_object('id',n.id,'message',n.message) INTO v_current
    FROM public.news n WHERE n.id=v_id AND n.occasion=p_occasion FOR UPDATE;
    IF v_current IS NULL THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'rejected',404,jsonb_build_object('version',0,'news',NULL));
    END IF;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('news','occasion',p_occasion,v_id::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='news' AND scope_type='occasion'
      AND scope_id=p_occasion AND aggregate_id=v_id::text FOR UPDATE;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      SELECT to_jsonb(n)||jsonb_build_object('aggregate_version',v_version)
        INTO v_entity FROM public.news n WHERE n.id=v_id;
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'conflict',409,jsonb_build_object('version',v_version,'news',v_entity));
    END IF;
    IF v_current=jsonb_build_object('id',v_id,'message',p_news->>'message') THEN
      SELECT to_jsonb(n)||jsonb_build_object('aggregate_version',v_version)
        INTO v_entity FROM public.news n WHERE n.id=v_id;
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'unchanged',200,jsonb_build_object('version',v_version,'news',v_entity));
    END IF;
    UPDATE public.news SET message=p_news->>'message',updated_at=clock_timestamp()
      WHERE id=v_id;
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='news'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text
      RETURNING version INTO v_version;
  ELSE
    IF p_expected_version IS NOT NULL THEN
      RAISE invalid_parameter_value USING MESSAGE='new news must not have expected version';
    END IF;
    INSERT INTO public.news(message,created_by,occasion)
    VALUES (p_news->>'message',v_actor,p_occasion) RETURNING id INTO v_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('news','occasion',p_occasion,v_id::text,v_version);
  END IF;
  SELECT to_jsonb(n)||jsonb_build_object('aggregate_version',v_version)
    INTO v_entity FROM public.news n WHERE n.id=v_id;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.news.save','content',jsonb_build_array(jsonb_build_object(
      'entityType','news','entityId',v_id,
      'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel','News','changedFields',jsonb_build_array('message'))),
    CASE WHEN v_is_publishable THEN ARRAY['content_catalog'] ELSE '{}'::text[] END,
    '[]','[]',jsonb_build_object('version',v_version,'news',v_entity));
END; $function$
;
REVOKE ALL ON FUNCTION public.save_news_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_news jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_news_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_news jsonb) TO authenticated;

-- Source: database/functions/news/delete_news_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.delete_news_client_sync_v1(p_occasion bigint, p_news_id bigint, p_command_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_version bigint; v_begin jsonb; v_hash text;
  v_entity jsonb; v_previous_id bigint; v_private_impacts jsonb;
  v_is_publishable boolean;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  SELECT NOT o.is_hidden INTO v_is_publishable FROM public.occasions o
    WHERE o.id=p_occasion;
  IF v_is_publishable IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='occasion not found';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'newsId',p_news_id,'expectedVersion',p_expected_version)::text,'UTF8'),
    'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.news.delete',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT to_jsonb(n) INTO v_entity FROM public.news n
    WHERE n.id=p_news_id AND n.occasion=p_occasion FOR UPDATE;
  IF v_entity IS NULL THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'unchanged',200,jsonb_build_object('version',0,'news',NULL));
  END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('news','occasion',p_occasion,p_news_id::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='news' AND scope_type='occasion'
    AND scope_id=p_occasion AND aggregate_id=p_news_id::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'conflict',409,jsonb_build_object('version',v_version,'news',v_entity));
  END IF;
  SELECT n.id INTO v_previous_id FROM public.news n
    WHERE n.occasion=p_occasion AND n.id<p_news_id ORDER BY n.id DESC LIMIT 1;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_news',
    'userId',un."user")),'[]'::jsonb) INTO v_private_impacts
  FROM public.user_news un JOIN public.occasion_users ou
    ON ou.occasion=p_occasion AND ou."user"=un."user"
  WHERE un.occasion=p_occasion AND un.news_id=p_news_id;
  IF v_previous_id IS NULL THEN
    DELETE FROM public.user_news WHERE occasion=p_occasion AND news_id=p_news_id;
  ELSE
    UPDATE public.user_news SET news_id=v_previous_id
      WHERE occasion=p_occasion AND news_id=p_news_id;
  END IF;
  DELETE FROM public.news WHERE id=p_news_id;
  DELETE FROM public.client_aggregate_versions WHERE aggregate_type='news'
    AND scope_type='occasion' AND scope_id=p_occasion
    AND aggregate_id=p_news_id::text;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.news.delete','content',jsonb_build_array(jsonb_build_object(
      'entityType','news','entityId',p_news_id,'operation','delete',
      'safeLabel','News','changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_is_publishable THEN ARRAY['content_catalog'] ELSE '{}'::text[] END,
    v_private_impacts,'[]',jsonb_build_object('version',v_version,'news',NULL));
END; $function$
;
REVOKE ALL ON FUNCTION public.delete_news_client_sync_v1(p_occasion bigint, p_news_id bigint, p_command_id uuid, p_expected_version bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.delete_news_client_sync_v1(p_occasion bigint, p_news_id bigint, p_command_id uuid, p_expected_version bigint) TO authenticated;

-- Source: database/functions/news/publish_news_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.publish_news_client_sync_v1(p_occasion bigint, p_add_to_news boolean, p_news_message text, p_send_notification boolean, p_notification_heading text, p_notification_content text, p_recipients jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_notification uuid; v_actor uuid:=auth.uid(); v_organization bigint; v_begin jsonb; v_hash text;
  v_id bigint; v_version bigint:=0; v_entity jsonb; v_items jsonb:='[]'::jsonb;
  v_is_publishable boolean; v_response jsonb; v_required_revision bigint;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  SELECT o.organization,NOT o.is_hidden INTO v_organization,v_is_publishable
    FROM public.occasions o WHERE o.id=p_occasion;
  IF v_organization IS NULL OR NOT COALESCE(p_add_to_news,false)
      AND NOT COALESCE(p_send_notification,false)
    OR p_add_to_news AND (p_news_message IS NULL
      OR octet_length(p_news_message) NOT BETWEEN 1 AND 524288)
    OR p_send_notification AND (p_notification_content IS NULL
      OR octet_length(p_notification_content)>65536
      OR octet_length(COALESCE(p_notification_heading,''))>2048
      OR p_recipients IS NOT NULL AND (jsonb_typeof(p_recipients)<>'array'
        OR jsonb_array_length(p_recipients)>5000
        OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_recipients) value
          WHERE jsonb_typeof(value)<>'string'
            OR octet_length(value#>>'{}')>512))) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid news publication'; END IF;
  IF COALESCE(p_add_to_news,false) AND COALESCE(p_send_notification,false)
      AND NOT v_is_publishable THEN
    RAISE invalid_parameter_value
      USING MESSAGE='news push requires a publicly publishable occasion';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'addToNews',p_add_to_news,'newsMessage',p_news_message,
    'sendNotification',p_send_notification,'notificationHeading',p_notification_heading,
    'notificationContent',p_notification_content,'recipients',p_recipients)::text,
    'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.news.publish',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF coalesce(p_send_notification,false) THEN PERFORM public.charge_notification_intent_v1(p_occasion,v_actor,p_recipients,p_notification_heading,p_notification_content); END IF;
  IF COALESCE(p_add_to_news,false) THEN
    INSERT INTO public.news(message,created_by,occasion)
      VALUES (p_news_message,v_actor,p_occasion) RETURNING id INTO v_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('news','occasion',p_occasion,v_id::text,v_version);
    SELECT to_jsonb(n)||jsonb_build_object('aggregate_version',v_version)
      INTO v_entity FROM public.news n WHERE n.id=v_id;
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'entityType','news','entityId',v_id,'operation','insert','safeLabel','News',
      'changedFields',jsonb_build_array('message')));
  END IF;
  IF COALESCE(p_send_notification,false) THEN
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'entityType','notification','entityId',NULL,'operation','publish',
      'safeLabel','Notification','changedFields',jsonb_build_array('delivery_request')));
  END IF;

  -- A notification-only test has no news publication to wait for.
  IF COALESCE(p_send_notification,false) AND NOT COALESCE(p_add_to_news,false) THEN
    INSERT INTO public.log_notifications
      (occasion,organization,user_id,"to",heading,content,data,abuse_admitted_at)
    VALUES (p_occasion,v_organization,v_actor,p_recipients,
      p_notification_heading,p_notification_content,jsonb_build_object('path','news'),statement_timestamp()) RETURNING id INTO v_notification;
    PERFORM public.dispatch_log_notification_v1(v_notification);
  END IF;

  v_response:=public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.news.publish','content',v_items,
    CASE WHEN COALESCE(p_add_to_news,false) AND v_is_publishable
      THEN ARRAY['content_catalog'] ELSE '{}'::text[] END,'[]','[]',
    jsonb_build_object('version',v_version,'news',v_entity,
      'notificationQueued',COALESCE(p_send_notification,false)));

  IF COALESCE(p_add_to_news,false) AND COALESCE(p_send_notification,false) THEN
    SELECT c.resulting_revision INTO v_required_revision
    FROM public.client_commit_components c
    WHERE c.commit_id=(v_response#>>'{mutation,commitId}')::uuid
      AND c.component='content_catalog' AND c.scope_type='occasion'
      AND c.scope_id=p_occasion AND c.user_id IS NULL;
    IF v_required_revision IS NULL THEN
      RAISE EXCEPTION 'news publication did not produce a content revision';
    END IF;
    INSERT INTO public.news_notification_outbox
      (command_id,occasion,organization,user_id,required_content_revision,
       "to",heading,content,data,abuse_admitted_at)
    VALUES (p_command_id,p_occasion,v_organization,v_actor,v_required_revision,
      p_recipients,p_notification_heading,p_notification_content,
      jsonb_build_object('path','news'),statement_timestamp());
  END IF;
  RETURN v_response;
END; $function$;
REVOKE ALL ON FUNCTION public.publish_news_client_sync_v1(bigint,boolean,text,boolean,text,text,jsonb,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.publish_news_client_sync_v1(bigint,boolean,text,boolean,text,text,jsonb,uuid) TO authenticated;

-- Source: database/functions/security/news_read_marker.sql
CREATE OR REPLACE FUNCTION public.mark_news_read_client_sync_v1(p_occasion bigint, p_news_id bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_user uuid:=auth.uid();
  v_revision bigint;
  v_begin jsonb;
  v_commit jsonb;
  v_read_at timestamptz;
  v_data jsonb;
  v_response jsonb;
  v_request_sha256 text;
BEGIN
  IF v_user IS NULL
     OR NOT EXISTS (SELECT 1 FROM public.occasion_users ou
       WHERE ou.occasion=p_occasion AND ou."user"=v_user)
     OR NOT EXISTS (SELECT 1 FROM public.news n
       WHERE n.id=p_news_id AND n.occasion=p_occasion)
  THEN RETURN jsonb_build_object('code',403); END IF;

  v_request_sha256:=encode(extensions.digest(convert_to(
    jsonb_build_object('occasion',p_occasion,'newsId',p_news_id)::text,'UTF8'),
    'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'news.mark_read',
    p_occasion,v_user,v_request_sha256);
  IF v_begin->>'disposition'='replay' THEN
    RETURN v_begin->'response';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_user::text||':'||p_occasion::text,0));

  SELECT COALESCE(source_revision,0) INTO v_revision
  FROM (SELECT 1) seed LEFT JOIN public.client_sync_private_scopes s
    ON s.component='private_news' AND s.occasion=p_occasion AND s.user_id=v_user;
  -- A delayed command never moves the high-water mark backwards.
  SELECT greatest(p_news_id,coalesce(max(news_id),0)) INTO p_news_id
    FROM public.user_news WHERE "user"=v_user AND occasion=p_occasion;
  IF (SELECT count(*)=1 AND max(news_id)=p_news_id
      FROM public.user_news
      WHERE "user"=v_user AND occasion=p_occasion) THEN
    v_data:=jsonb_build_object('revision',v_revision,'payload',jsonb_build_array(
      jsonb_build_object('newsId',p_news_id)));
    v_response:=jsonb_build_object('status','unchanged','code',200,'data',v_data,
      'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
        'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
      'sync',jsonb_build_object('replacements','[]'::jsonb));
    RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
  END IF;

  v_read_at:=clock_timestamp();
  v_data:=jsonb_build_object('revision',v_revision+1,'payload',jsonb_build_array(
    jsonb_build_object('newsId',p_news_id,'readAt',v_read_at)));
  DELETE FROM public.user_news WHERE "user"=v_user AND occasion=p_occasion;
  INSERT INTO public.user_news(news_id,"user",occasion) VALUES(p_news_id,v_user,p_occasion);
  v_commit:=public.record_client_sync_commit_v1(p_occasion,'mark_news_read','private',
    jsonb_build_array(jsonb_build_object('entityType','news_marker',
      'entityId',p_news_id,'operation','update','safeLabel','News read marker',
    'changedFields',jsonb_build_array('news_id'))),ARRAY['live_public'],jsonb_build_array(
      jsonb_build_object('component','private_news','userId',v_user)),jsonb_build_array(
      jsonb_build_object('component','live_public','entityId',p_news_id)),
    'user',NULL);
  SELECT source_revision INTO v_revision FROM public.client_sync_private_scopes
    WHERE component='private_news' AND occasion=p_occasion AND user_id=v_user;
  v_data:=v_data||jsonb_build_object('revision',v_revision);
  v_response:=jsonb_build_object('status','applied','code',200,'data',v_data,
    'mutation',jsonb_build_object('commandId',p_command_id,
      'receiptId',p_command_id,'commitId',v_commit->>'commitId','replayed',false,
      'occurredAt',v_commit->>'occurredAt'),
    'sync',jsonb_build_object('replacements',jsonb_build_array(jsonb_build_object(
      'component','private_news','revision',v_revision,'payload',v_data->'payload'))));
  RETURN public.finish_client_mutation_v1(
    p_command_id,v_response,(v_commit->>'commitId')::uuid);
END; $function$;


REVOKE ALL ON FUNCTION public.mark_news_read_client_sync_v1(bigint,bigint,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.mark_news_read_client_sync_v1(bigint,bigint,uuid) TO authenticated,service_role;

-- Source: database/functions/units/update_unit_internal_v1.sql
CREATE OR REPLACE FUNCTION public.update_unit_internal_v1(p_unit_id bigint, p_title text, p_data jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
    IF length(p_title) > 30 THEN
        RAISE EXCEPTION 'Unit title cannot exceed 30 characters';
    END IF;

    -- Check if the current user is a manager for the provided unit
    IF NOT get_is_manager_on_unit(p_unit_id) THEN
        RAISE EXCEPTION 'User is not a manager on this unit';
    END IF;

    -- Update the unit
    UPDATE units
    SET
        title = p_title,
        data = p_data
    WHERE id = p_unit_id;
END;
$function$
;
REVOKE ALL ON FUNCTION public.update_unit_internal_v1(p_unit_id bigint, p_title text, p_data jsonb) FROM PUBLIC,anon,authenticated;

-- Source: database/functions/units/save_unit_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_unit_client_sync_v1(p_unit bigint, p_command_id uuid, p_expected_version bigint, p_unit_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_version bigint;
  v_before jsonb; v_after jsonb; v_commit public.client_commits%ROWTYPE;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_manager_on_unit(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  IF p_unit_data IS NULL OR jsonb_typeof(p_unit_data)<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_unit_data) key
      WHERE key NOT IN ('id','title','data'))
    OR (p_unit_data->>'id')::bigint IS DISTINCT FROM p_unit
    OR nullif(btrim(p_unit_data->>'title'),'') IS NULL
    OR length(p_unit_data->>'title')>30
    OR jsonb_typeof(COALESCE(p_unit_data->'data','{}'::jsonb))<>'object'
    OR octet_length(p_unit_data::text)>262144 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid unit aggregate'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'unit',p_unit,'expectedVersion',p_expected_version,
    'data',p_unit_data)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_unit_client_mutation_v1(p_command_id,'unit.config.save',
    p_unit,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT jsonb_build_object('id',u.id,'title',u.title,'data',u.data)
    INTO v_before FROM public.units u WHERE u.id=p_unit FOR UPDATE;
  IF v_before IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'rejected',404,jsonb_build_object('version',0,'unit',NULL)); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('unit','unit',p_unit,p_unit::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='unit' AND scope_type='unit'
      AND scope_id=p_unit AND aggregate_id=p_unit::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('version',v_version,'unit',v_before||
        jsonb_build_object('aggregate_version',v_version))); END IF;
  v_after:=jsonb_build_object('id',p_unit,'title',p_unit_data->>'title',
    'data',COALESCE(p_unit_data->'data','{}'::jsonb));
  IF v_before=v_after THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'unchanged',200,jsonb_build_object('version',v_version,
      'unit',v_before||jsonb_build_object('aggregate_version',v_version))); END IF;
  PERFORM public.update_unit_internal_v1(
    p_unit,p_unit_data->>'title',COALESCE(p_unit_data->'data','{}'::jsonb));
  UPDATE public.client_aggregate_versions SET version=version+1,
    updated_at=clock_timestamp() WHERE aggregate_type='unit' AND scope_type='unit'
    AND scope_id=p_unit AND aggregate_id=p_unit::text RETURNING version INTO v_version;
  INSERT INTO public.client_commits
    (unit,actor_id,actor_display,actor_kind,source,change_class)
  SELECT p_unit,v_actor,nullif(concat_ws(' ',ui.name,ui.surname),''),'user',
    'unit.config.save','configuration' FROM public.user_info ui WHERE ui.id=v_actor
  RETURNING * INTO v_commit;
  INSERT INTO public.client_commit_items
    (commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
  VALUES (v_commit.commit_id,0,'unit',p_unit::text,'update',
    left(p_unit_data->>'title',240),ARRAY['configuration']);
  PERFORM public.fanout_unit_catalog_v1(v_commit.commit_id,p_unit);
  RETURN public.finish_client_mutation_v1(p_command_id,jsonb_build_object(
    'status','applied','code',200,'data',jsonb_build_object('version',v_version,
      'unit',v_after||jsonb_build_object('aggregate_version',v_version)),
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',v_commit.commit_id,'replayed',false,'occurredAt',v_commit.occurred_at),
    'sync',jsonb_build_object('replacements','[]'::jsonb)),v_commit.commit_id);
END; $function$
;
REVOKE ALL ON FUNCTION public.save_unit_client_sync_v1(p_unit bigint, p_command_id uuid, p_expected_version bigint, p_unit_data jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_unit_client_sync_v1(p_unit bigint, p_command_id uuid, p_expected_version bigint, p_unit_data jsonb) TO authenticated;

-- Source: database/functions/units/get_unit_edit_data_v1.sql
CREATE OR REPLACE FUNCTION public.get_unit_edit_data_v1(p_unit bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path = public, extensions
AS $function$
DECLARE v_result jsonb; v_version bigint;
BEGIN
  IF auth.uid() IS NULL OR NOT public.get_is_manager_on_unit(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  v_result:=public.get_unit_edit_data(p_unit);
  SELECT COALESCE(v.version,0) INTO v_version
    FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
      ON v.aggregate_type='unit' AND v.scope_type='unit'
      AND v.scope_id=p_unit AND v.aggregate_id=p_unit::text;
  RETURN jsonb_set(v_result,'{unit}',(v_result->'unit')||
    jsonb_build_object('aggregate_version',v_version));
END; $function$
;
REVOKE ALL ON FUNCTION public.get_unit_edit_data_v1(p_unit bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_unit_edit_data_v1(p_unit bigint) TO authenticated;

-- Source: database/functions/users/create_companion_in_organization_internal_v1.sql
CREATE OR REPLACE FUNCTION public.create_companion_in_organization_internal_v1(org bigint, oc bigint, usr uuid, c_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE new_companion uuid:=gen_random_uuid(); user_email text;
  companion_email text; v_policy jsonb;
BEGIN
  v_policy:=public.get_companion_feature_policy_v1(oc);
  IF auth.uid() IS NULL OR auth.uid()<>usr
    OR NOT EXISTS (SELECT 1 FROM public.occasion_users ou
      WHERE ou.occasion=oc AND ou."user"=usr)
    OR NOT COALESCE((v_policy->>'is_enabled')::boolean,false)
    OR NOT COALESCE((v_policy->>'allow_user_create')::boolean,true) THEN
    RETURN jsonb_build_object('code',403);
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'companion-member:'||oc::text||':'||usr::text,0));
  IF (SELECT count(*) FROM public.user_companions uc
      WHERE uc.occasion=oc AND uc."user"=usr)
      >= (v_policy->>'max_companions')::integer THEN
    RETURN jsonb_build_object('code',403);
  END IF;
  SELECT ui.email_readonly INTO user_email FROM public.user_info ui WHERE ui.id=usr;
  companion_email:=user_email||'+'||btrim(c_name);
  INSERT INTO auth.users(instance_id,id,aud,role,email,encrypted_password,
    email_confirmed_at,raw_app_meta_data,created_at,updated_at,
    confirmation_token,email_change,email_change_token_new,recovery_token)
  VALUES('00000000-0000-0000-0000-000000000000',new_companion,
    'authenticated','authenticated',format('%s+%s',org,companion_email),'',now(),
    '{"provider":"email","providers":["email"]}',now(),now(),'','','','');
  INSERT INTO auth.identities(id,provider_id,user_id,identity_data,provider,
    created_at,updated_at)
  VALUES(gen_random_uuid(),new_companion,new_companion,
    jsonb_build_object('sub',new_companion,'email',format('%s+%s',org,companion_email)),
    'email',now(),now());
  INSERT INTO public.user_info(id,email_readonly,name,organization)
    VALUES(new_companion,companion_email,btrim(c_name),org);
  PERFORM public.add_user_to_occasion_internal_v1(oc,new_companion);
  -- The target membership now exists; serialize and recheck the complete graph.
  PERFORM public.check_companion_relation_invariants_v1(oc,usr,new_companion);
  INSERT INTO public.user_companions(occasion,"user",companion,origin,created_by)
    VALUES(oc,usr,new_companion,'self_created',usr);
  RETURN jsonb_build_object('code',200);
END $function$
;
REVOKE ALL ON FUNCTION public.create_companion_in_organization_internal_v1(org bigint, oc bigint, usr uuid, c_name text) FROM PUBLIC,anon,authenticated;

-- Source: database/functions/users/create_companion_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.create_companion_client_sync_v1(p_occasion bigint, p_name text, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path = public, extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_organization bigint; v_begin jsonb; v_hash text;
  v_result jsonb; v_before uuid[]; v_companion uuid; v_replacements jsonb;
BEGIN
  IF v_actor IS NULL OR nullif(btrim(p_name),'') IS NULL
    OR octet_length(p_name)>512 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid companion'; END IF;
  SELECT o.organization INTO v_organization FROM public.occasions o
    JOIN public.occasion_users ou ON ou.occasion=o.id AND ou."user"=v_actor
    WHERE o.id=p_occasion;
  IF v_organization IS NULL THEN
    RAISE insufficient_privilege USING MESSAGE='occasion participant required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'name',p_name)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.companion.create',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'companion-owner:'||v_actor::text||':'||p_occasion::text,0));
  SELECT COALESCE(array_agg(uc.companion),'{}'::uuid[]) INTO v_before
    FROM public.user_companions uc WHERE uc.occasion=p_occasion AND uc."user"=v_actor;
  v_result:=public.create_companion_in_organization_internal_v1(
    v_organization,p_occasion,v_actor,p_name);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      CASE WHEN (v_result->>'code')::integer=403 THEN 403 ELSE 400 END,
      jsonb_build_object('companion',NULL,'domainCode',v_result->'code'));
  END IF;
  SELECT uc.companion INTO v_companion FROM public.user_companions uc
    WHERE uc.occasion=p_occasion AND uc."user"=v_actor AND NOT uc.companion=ANY(v_before)
    ORDER BY uc.companion LIMIT 1;
  IF v_companion IS NULL THEN
    RAISE EXCEPTION 'companion handler did not create a companion'; END IF;
  v_replacements:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',v_actor,
    'payload',public.get_private_profile_payload_v1(p_occasion,v_actor)));
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.companion.create','profile',jsonb_build_array(jsonb_build_object(
      'entityType','companion','entityId',v_companion,'operation','insert',
      'safeLabel','Companion','changedFields',jsonb_build_array('name'))),
    '{}',jsonb_build_array(jsonb_build_object('component','private_profile',
      'userId',v_actor)),'[]',jsonb_build_object('companion',jsonb_build_object(
        'id',v_companion,'name',p_name,'event_ids','[]'::jsonb)),
    '{}','[]','user',NULL,v_replacements);
END; $function$
;
REVOKE ALL ON FUNCTION public.create_companion_client_sync_v1(p_occasion bigint, p_name text, p_command_id uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_companion_client_sync_v1(p_occasion bigint, p_name text, p_command_id uuid) TO authenticated;

