-- Source: database/functions/information/get_information_command_data_v1.sql
CREATE OR REPLACE FUNCTION public.get_information_command_data_v1(p_information_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
  SELECT to_jsonb(i)||jsonb_build_object('information_hidden',CASE
    WHEN ih.id IS NULL THEN NULL ELSE jsonb_build_object('id',ih.id,'data',ih.data) END)
  FROM public.information i LEFT JOIN public.information_hidden ih
    ON ih.id=i.information_hidden WHERE i.id=p_information_id;
$function$
;
REVOKE ALL ON FUNCTION public.get_information_command_data_v1(p_information_id bigint) FROM PUBLIC,anon,authenticated;

-- Source: database/functions/information/get_information_editor_bundle_v1.sql
CREATE OR REPLACE FUNCTION public.get_information_editor_bundle_v1(p_occasion bigint, p_type text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_information jsonb;
BEGIN
  IF NOT public.get_is_editor_view_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor view required';
  END IF;
  SELECT COALESCE(jsonb_agg(public.get_information_command_data_v1(i.id)||
    jsonb_build_object('aggregate_version',COALESCE(v.version,0))
    ORDER BY i."order" NULLS LAST,i.id),'[]'::jsonb) INTO v_information
  FROM public.information i LEFT JOIN public.client_aggregate_versions v
    ON v.aggregate_type='information' AND v.scope_type='occasion'
    AND v.scope_id=p_occasion AND v.aggregate_id=i.id::text
  WHERE i.occasion=p_occasion AND (CASE WHEN p_type IS NULL
    THEN NULLIF(i.type,'') IS NULL ELSE i.type=p_type END);
  RETURN jsonb_build_object('code',200,'information',v_information);
END; $function$
;
REVOKE ALL ON FUNCTION public.get_information_editor_bundle_v1(p_occasion bigint, p_type text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_information_editor_bundle_v1(p_occasion bigint, p_type text) TO authenticated;

-- Source: database/functions/information/save_information_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_information_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_information jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_id bigint; v_hidden_id bigint; v_old_hidden_id bigint;
  v_version bigint; v_begin jsonb; v_hash text; v_current jsonb;
  v_requested jsonb; v_entity jsonb; v_commit jsonb; v_public jsonb;
  v_response jsonb; v_is_publishable boolean; v_old_is_hidden boolean;
  v_new_is_hidden boolean; v_affects_public boolean;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  SELECT NOT o.is_hidden INTO v_is_publishable FROM public.occasions o
    WHERE o.id=p_occasion;
  IF v_is_publishable IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='occasion not found';
  END IF;
  PERFORM public.validate_information_content_internal_v1(p_information,false);
  v_id:=(p_information->>'id')::bigint;
  v_new_is_hidden:=(p_information->>'isHidden')::boolean;
  v_requested:=jsonb_build_object('id',v_id,'title',p_information->>'title',
    'description',p_information->>'description','type',p_information->>'type',
    'isHidden',v_new_is_hidden,'order',(p_information->>'order')::bigint,
    'data',p_information->'data','hiddenData',p_information->'hiddenData');
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'expectedVersion',p_expected_version,
    'information',p_information)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.information.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;

  IF v_id IS NOT NULL THEN
    PERFORM 1 FROM public.information i WHERE i.id=v_id AND i.occasion=p_occasion
      FOR UPDATE;
    IF NOT FOUND THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'rejected',404,jsonb_build_object('version',0,'information',NULL));
    END IF;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('information','occasion',p_occasion,v_id::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='information' AND scope_type='occasion'
      AND scope_id=p_occasion AND aggregate_id=v_id::text FOR UPDATE;
    SELECT jsonb_build_object('id',i.id,'title',i.title,'description',i.description,
      'type',i.type,'isHidden',i.is_hidden,'order',i."order",'data',i.data,
      'hiddenData',ih.data),i.is_hidden,i.information_hidden
      INTO v_current,v_old_is_hidden,v_old_hidden_id
    FROM public.information i LEFT JOIN public.information_hidden ih
      ON ih.id=i.information_hidden WHERE i.id=v_id;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'conflict',409,jsonb_build_object('version',v_version,'information',
          public.get_information_command_data_v1(v_id)));
    END IF;
  ELSIF p_expected_version IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new information must not have expected version';
  END IF;

  IF v_current IS NOT DISTINCT FROM v_requested THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'unchanged',200,jsonb_build_object('version',v_version,'information',
        public.get_information_command_data_v1(v_id)));
  END IF;

  IF p_information->>'type'='game' THEN
    IF v_old_hidden_id IS NULL THEN
      INSERT INTO public.information_hidden(data,occasion)
      VALUES (p_information->'hiddenData',p_occasion) RETURNING id INTO v_hidden_id;
    ELSE
      UPDATE public.information_hidden SET data=p_information->'hiddenData'
      WHERE id=v_old_hidden_id AND occasion=p_occasion RETURNING id INTO v_hidden_id;
      IF v_hidden_id IS NULL THEN
        RAISE invalid_parameter_value USING MESSAGE='cross-scope hidden information';
      END IF;
    END IF;
  END IF;
  IF v_id IS NULL THEN
    INSERT INTO public.information(title,description,type,is_hidden,"order",data,
      information_hidden,occasion)
    VALUES (p_information->>'title',p_information->>'description',
      p_information->>'type',v_new_is_hidden,(p_information->>'order')::bigint,
      p_information->'data',v_hidden_id,p_occasion) RETURNING id INTO v_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('information','occasion',p_occasion,v_id::text,v_version);
  ELSE
    UPDATE public.information SET title=p_information->>'title',
      description=p_information->>'description',type=p_information->>'type',
      is_hidden=v_new_is_hidden,"order"=(p_information->>'order')::bigint,
      data=p_information->'data',information_hidden=v_hidden_id,
      updated_at=clock_timestamp() WHERE id=v_id;
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='information'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text
      RETURNING version INTO v_version;
    IF v_old_hidden_id IS NOT NULL AND v_hidden_id IS NULL THEN
      DELETE FROM public.information_hidden WHERE id=v_old_hidden_id
        AND occasion=p_occasion;
    END IF;
  END IF;
  v_entity:=public.get_information_command_data_v1(v_id)||
    jsonb_build_object('aggregate_version',v_version);
  v_affects_public:=NOT COALESCE(v_old_is_hidden,true) OR NOT v_new_is_hidden;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.information.save','content',jsonb_build_array(jsonb_build_object(
      'entityType','information','entityId',v_id,
      'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_information->>'title',240),
      'changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_is_publishable AND v_affects_public THEN ARRAY['content_catalog']
      ELSE '{}'::text[] END,'[]','[]',
    jsonb_build_object('version',v_version,'information',v_entity));
END; $function$
;
REVOKE ALL ON FUNCTION public.save_information_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_information jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.save_information_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_information jsonb) TO authenticated;

-- Source: database/functions/information/delete_information_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.delete_information_client_sync_v1(p_occasion bigint, p_information_id bigint, p_command_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_version bigint; v_hidden_id bigint;
  v_entity jsonb; v_begin jsonb; v_hash text; v_commit jsonb; v_public jsonb;
  v_response jsonb; v_is_publishable boolean; v_is_hidden boolean;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  SELECT NOT o.is_hidden INTO v_is_publishable FROM public.occasions o
    WHERE o.id=p_occasion;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'informationId',p_information_id,'expectedVersion',p_expected_version)::text,
    'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.information.delete',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT public.get_information_command_data_v1(i.id),i.information_hidden,i.is_hidden
    INTO v_entity,v_hidden_id,v_is_hidden FROM public.information i
    WHERE i.id=p_information_id AND i.occasion=p_occasion FOR UPDATE;
  IF v_entity IS NULL THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'unchanged',200,jsonb_build_object('version',0,'information',NULL));
  END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('information','occasion',p_occasion,p_information_id::text,0)
  ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='information' AND scope_type='occasion'
    AND scope_id=p_occasion AND aggregate_id=p_information_id::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'conflict',409,jsonb_build_object('version',v_version,
        'information',v_entity));
  END IF;
  DELETE FROM public.information WHERE id=p_information_id;
  IF v_hidden_id IS NOT NULL THEN
    DELETE FROM public.information_hidden WHERE id=v_hidden_id AND occasion=p_occasion;
  END IF;
  DELETE FROM public.client_aggregate_versions WHERE aggregate_type='information'
    AND scope_type='occasion' AND scope_id=p_occasion
    AND aggregate_id=p_information_id::text;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.information.delete','content',jsonb_build_array(jsonb_build_object(
      'entityType','information','entityId',p_information_id,'operation','delete',
      'safeLabel',left(v_entity->>'title',240),
      'changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_is_publishable AND NOT v_is_hidden THEN ARRAY['content_catalog']
      ELSE '{}'::text[] END,'[]','[]',
    jsonb_build_object('version',v_version,'information',NULL));
END; $function$
;
REVOKE ALL ON FUNCTION public.delete_information_client_sync_v1(p_occasion bigint, p_information_id bigint, p_command_id uuid, p_expected_version bigint) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.delete_information_client_sync_v1(p_occasion bigint, p_information_id bigint, p_command_id uuid, p_expected_version bigint) TO authenticated;

-- Source: database/functions/information/unit_information.sql
CREATE OR REPLACE FUNCTION public.get_unit_information_for_edit_v1(p_unit bigint,p_type text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT public.get_is_editor_view_on_unit(p_unit) THEN
  RAISE insufficient_privilege USING MESSAGE='unit editor view required'; END IF;
 IF p_type='game' THEN RAISE invalid_parameter_value USING MESSAGE='unit games unsupported'; END IF;
 RETURN coalesce((SELECT jsonb_agg(to_jsonb(i)||jsonb_build_object('aggregate_version',coalesce(v.version,0)) ORDER BY i.id)
 FROM public.information i LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='information'
 AND v.scope_type='unit' AND v.scope_id=p_unit AND v.aggregate_id=i.id::text
 WHERE i.unit=p_unit AND i.occasion IS NULL AND i.information_hidden IS NULL
 AND coalesce(i.type,'')=coalesce(p_type,'')),'[]');
END $$;
CREATE OR REPLACE FUNCTION public.save_unit_information_client_sync_v1(p_unit bigint,p_command_id uuid,p_expected_version bigint,p_information jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE actor uuid:=auth.uid(); ident bigint; ver bigint; before_row jsonb; after_row jsonb; begun jsonb; hash text;
BEGIN
 IF actor IS NULL OR NOT public.get_is_editor_on_unit(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='unit editor required'; END IF;
 PERFORM public.validate_information_content_internal_v1(p_information,true);
 ident:=(p_information->>'id')::bigint;
 hash:=encode(extensions.digest(convert_to(jsonb_build_object('unit',p_unit,'expectedVersion',p_expected_version,'information',p_information)::text,'UTF8'),'sha256'),'hex');
 begun:=public.begin_unit_client_mutation_v1(p_command_id,'unit.information.save',p_unit,actor,hash);
 IF begun->>'disposition'='replay' THEN RETURN begun->'response'; END IF;
 IF ident IS NOT NULL THEN
  SELECT to_jsonb(i) INTO before_row FROM public.information i WHERE i.id=ident AND i.unit=p_unit AND i.occasion IS NULL FOR UPDATE;
  IF before_row IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',404,'{}'); END IF;
  IF before_row->>'type'='game' OR before_row->>'information_hidden' IS NOT NULL THEN RAISE invalid_parameter_value USING MESSAGE='unit games unsupported'; END IF;
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES('information','unit',p_unit,ident::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO ver FROM public.client_aggregate_versions WHERE aggregate_type='information' AND scope_type='unit' AND scope_id=p_unit AND aggregate_id=ident::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM ver THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('version',ver,'information',before_row)); END IF;
  IF jsonb_build_object('title',before_row->'title','description',before_row->'description','type',before_row->'type','isHidden',before_row->'is_hidden','order',before_row->'order','data',before_row->'data')
   =p_information-'id'-'hiddenData' THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,jsonb_build_object('version',ver,'information',before_row)); END IF;
  UPDATE public.information SET title=p_information->>'title',description=p_information->>'description',type=p_information->>'type',
   is_hidden=(p_information->>'isHidden')::boolean,"order"=(p_information->>'order')::bigint,data=p_information->'data',updated_at=clock_timestamp() WHERE id=ident;
  UPDATE public.client_aggregate_versions SET version=version+1,updated_at=clock_timestamp() WHERE aggregate_type='information' AND scope_type='unit' AND scope_id=p_unit AND aggregate_id=ident::text RETURNING version INTO ver;
 ELSE
  IF p_expected_version IS NOT NULL THEN RAISE invalid_parameter_value USING MESSAGE='new information cannot have version'; END IF;
  INSERT INTO public.information(unit,title,description,type,is_hidden,"order",data)
  VALUES(p_unit,p_information->>'title',p_information->>'description',p_information->>'type',(p_information->>'isHidden')::boolean,(p_information->>'order')::bigint,p_information->'data') RETURNING id INTO ident;
  ver:=1;INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version) VALUES('information','unit',p_unit,ident::text,ver);
 END IF;
 SELECT to_jsonb(i)||jsonb_build_object('aggregate_version',ver) INTO after_row FROM public.information i WHERE id=ident;
 RETURN public.complete_unit_mutation_internal_v1(p_command_id,p_unit,'unit.information.save','information',ident,CASE WHEN before_row IS NULL THEN 'insert' ELSE 'update' END,jsonb_build_object('version',ver,'information',after_row));
END $$;
CREATE OR REPLACE FUNCTION public.delete_unit_information_client_sync_v1(p_unit bigint,p_information_id bigint,p_command_id uuid,p_expected_version bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE actor uuid:=auth.uid(); ver bigint; old_row jsonb; begun jsonb; hash text;
BEGIN
 IF actor IS NULL OR NOT public.get_is_editor_on_unit(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='unit editor required'; END IF;
 hash:=encode(extensions.digest(convert_to(jsonb_build_object('unit',p_unit,'id',p_information_id,'expectedVersion',p_expected_version)::text,'UTF8'),'sha256'),'hex');
 begun:=public.begin_unit_client_mutation_v1(p_command_id,'unit.information.delete',p_unit,actor,hash);
 IF begun->>'disposition'='replay' THEN RETURN begun->'response'; END IF;
 SELECT to_jsonb(i) INTO old_row FROM public.information i WHERE id=p_information_id AND unit=p_unit AND occasion IS NULL FOR UPDATE;
 IF old_row IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,'{}'); END IF;
 IF old_row->>'type'='game' OR old_row->>'information_hidden' IS NOT NULL THEN RAISE invalid_parameter_value USING MESSAGE='unit games unsupported'; END IF;
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version) VALUES('information','unit',p_unit,p_information_id::text,0) ON CONFLICT DO NOTHING;
 SELECT version INTO ver FROM public.client_aggregate_versions WHERE aggregate_type='information' AND scope_type='unit' AND scope_id=p_unit AND aggregate_id=p_information_id::text FOR UPDATE;
 IF p_expected_version IS DISTINCT FROM ver THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('version',ver,'information',old_row)); END IF;
 DELETE FROM public.information WHERE id=p_information_id;
 DELETE FROM public.client_aggregate_versions WHERE aggregate_type='information' AND scope_type='unit' AND scope_id=p_unit AND aggregate_id=p_information_id::text;
 RETURN public.complete_unit_mutation_internal_v1(p_command_id,p_unit,'unit.information.delete','information',p_information_id,'delete',jsonb_build_object('version',ver,'information',NULL));
END $$;
REVOKE ALL ON FUNCTION public.get_unit_information_for_edit_v1(bigint,text),public.save_unit_information_client_sync_v1(bigint,uuid,bigint,jsonb),public.delete_unit_information_client_sync_v1(bigint,bigint,uuid,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_unit_information_for_edit_v1(bigint,text),public.save_unit_information_client_sync_v1(bigint,uuid,bigint,jsonb),public.delete_unit_information_client_sync_v1(bigint,bigint,uuid,bigint) TO authenticated;
REVOKE INSERT,UPDATE,DELETE ON public.information,public.information_hidden FROM anon,authenticated;

-- Source: database/functions/units/fanout_unit_map_catalog_internal_v1.sql
CREATE OR REPLACE FUNCTION public.fanout_unit_map_catalog_internal_v1(p_commit_id uuid, p_unit bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_occasion bigint; v_revision bigint;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.client_commits c
    WHERE c.commit_id=p_commit_id) THEN
    RAISE foreign_key_violation USING MESSAGE='unit fanout requires an audit commit';
  END IF;
  FOR v_occasion IN SELECT o.id FROM public.occasions o
    WHERE o.unit=p_unit AND NOT o.is_hidden ORDER BY o.id LOOP
    INSERT INTO public.client_sync_scopes
      (component,scope_type,scope_id,source_revision)
    VALUES ('map_catalog','occasion',v_occasion,1)
    ON CONFLICT (component,scope_type,scope_id) DO UPDATE
      SET source_revision=public.client_sync_scopes.source_revision+1,
          updated_at=now()
    RETURNING source_revision INTO v_revision;
    INSERT INTO public.client_commit_components
      (commit_id,component,scope_type,scope_id,user_id,resulting_revision)
    VALUES (p_commit_id,'map_catalog','occasion',v_occasion,NULL,v_revision);
    INSERT INTO public.client_projection_dirty_keys
      (component,scope_type,scope_id,entity_id,source_revision)
    VALUES ('map_catalog','occasion',v_occasion,0,v_revision)
    ON CONFLICT (component,scope_type,scope_id,entity_id) DO UPDATE
      SET source_revision=EXCLUDED.source_revision,dirty_since=now(),
          claimed_at=NULL,claim_token=NULL;
  END LOOP;
END; $function$

;

REVOKE ALL ON FUNCTION public.fanout_unit_map_catalog_internal_v1(uuid,bigint) FROM PUBLIC,anon,authenticated;

-- Source: database/functions/icons/save_unit_icon_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_unit_icon_client_sync_v1(p_unit bigint, p_command_id uuid, p_icon jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE
  v_actor uuid:=auth.uid();  v_organization bigint; v_id bigint;
  v_begin jsonb; v_hash text; v_commit jsonb; v_icon jsonb; v_response jsonb;
BEGIN
  SELECT u.organization INTO v_organization FROM public.units u WHERE u.id=p_unit;
  IF v_actor IS NULL OR p_unit IS NULL OR NOT public.get_is_editor_on_unit(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE='unit editor required';
  END IF;
  IF p_icon IS NULL OR jsonb_typeof(p_icon)<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_icon) key WHERE key NOT IN ('link','svg'))
    OR NOT (p_icon ?& ARRAY['link','svg'])
    OR length(p_icon->>'link') NOT BETWEEN 1 AND 200
    OR octet_length(COALESCE(p_icon->>'svg','')) NOT BETWEEN 1 AND 51200 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid icon';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('unit',p_unit,
    'icon',p_icon)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_unit_client_mutation_v1(p_command_id,'unit.icon.save',p_unit,
    v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  INSERT INTO public.icons(link,data,organization,unit,created_by)
  VALUES (p_icon->>'link',p_icon->>'svg',v_organization,p_unit,v_actor)
  RETURNING id INTO v_id;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('icon','unit',p_unit,v_id::text,1);
  SELECT to_jsonb(i)||jsonb_build_object('aggregate_version',1)
    INTO v_icon FROM public.icons i WHERE i.id=v_id;
  v_response:=public.complete_unit_mutation_internal_v1(p_command_id,p_unit,'unit.icon.save','icon',v_id,'insert',jsonb_build_object('icon',v_icon));
  PERFORM public.fanout_unit_map_catalog_internal_v1((v_response#>>'{mutation,commitId}')::uuid,p_unit);
  RETURN v_response;
END; $function$

;

REVOKE ALL ON FUNCTION public.save_unit_icon_client_sync_v1(bigint,uuid,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_unit_icon_client_sync_v1(bigint,uuid,jsonb) TO authenticated;

-- Source: database/functions/icons/save_icon_client_sync_v1.sql
-- Occasion-shaped released-client adapter; unit ownership is canonical.
CREATE OR REPLACE FUNCTION public.save_icon_client_sync_v1(p_occasion bigint,p_command_id uuid,p_icon jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE u bigint; old_receipt jsonb; old_hash text;
BEGIN
 SELECT unit INTO u FROM public.occasions WHERE id=p_occasion;
 IF u IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='occasion unit required'; END IF;
 -- Preserve receipts produced by the former occasion-scoped command.
 IF EXISTS(SELECT 1 FROM public.client_mutation_receipts WHERE command_id=p_command_id
   AND command_name='map.icon.save') THEN
  IF auth.uid() IS NULL OR NOT public.get_is_editor_on_unit(u) THEN
   RAISE insufficient_privilege USING MESSAGE='unit editor required'; END IF;
  old_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,'icon',p_icon)::text,'UTF8'),'sha256'),'hex');
  old_receipt:=public.begin_client_mutation_v1(p_command_id,'map.icon.save',p_occasion,auth.uid(),old_hash);
  IF old_receipt->>'disposition'='replay' THEN RETURN old_receipt->'response'; END IF;
  RAISE serialization_failure USING MESSAGE='incomplete legacy icon intent';
 END IF;
 RETURN public.save_unit_icon_client_sync_v1(u,p_command_id,p_icon);
END $$;

REVOKE ALL ON FUNCTION public.save_icon_client_sync_v1(bigint,uuid,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_icon_client_sync_v1(bigint,uuid,jsonb) TO authenticated;

-- Source: database/functions/icons/delete_unit_icon_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.delete_unit_icon_client_sync_v1(p_unit bigint, p_icon_id bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE
  v_actor uuid:=auth.uid();  v_icon public.icons%ROWTYPE;
  v_begin jsonb; v_hash text; v_commit jsonb; v_response jsonb;
  v_places bigint; v_paths bigint; v_types bigint; v_refs jsonb;
BEGIN
  PERFORM 1 FROM public.units WHERE id=p_unit;
  IF v_actor IS NULL OR p_unit IS NULL OR NOT public.get_is_editor_on_unit(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE='unit editor required';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('unit',p_unit,
    'iconId',p_icon_id)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_unit_client_mutation_v1(p_command_id,'unit.icon.delete',p_unit,
    v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT i.* INTO v_icon FROM public.icons i WHERE i.id=p_icon_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'unchanged',200,jsonb_build_object('icon',NULL));
  END IF;
  IF v_icon.unit IS NULL OR v_icon.unit IS DISTINCT FROM p_unit THEN
    RAISE insufficient_privilege USING MESSAGE='icon belongs to another unit or is legacy';
  END IF;
  SELECT count(*) INTO v_places FROM public.places p WHERE p.icon=p_icon_id;
  SELECT count(*) INTO v_paths FROM public.path_groups pg WHERE pg.icon=p_icon_id;
  SELECT count(*) INTO v_types FROM public.place_types pt WHERE pt.icon=p_icon_id;
  IF v_places+v_paths+v_types>0 THEN
    v_refs:=jsonb_build_object('places',v_places,'path_groups',v_paths,
      'place_types',v_types);
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'rejected',409,jsonb_build_object('icon',to_jsonb(v_icon),'refs',v_refs));
  END IF;
  DELETE FROM public.icons WHERE id=p_icon_id;
  DELETE FROM public.client_aggregate_versions WHERE aggregate_type='icon'
    AND scope_type='unit' AND scope_id=p_unit AND aggregate_id=p_icon_id::text;
  v_response:=public.complete_unit_mutation_internal_v1(p_command_id,p_unit,'unit.icon.delete','icon',p_icon_id,'delete',jsonb_build_object('icon',NULL));
  PERFORM public.fanout_unit_map_catalog_internal_v1((v_response#>>'{mutation,commitId}')::uuid,p_unit);
  RETURN v_response;
END; $function$

;

REVOKE ALL ON FUNCTION public.delete_unit_icon_client_sync_v1(bigint,bigint,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.delete_unit_icon_client_sync_v1(bigint,bigint,uuid) TO authenticated;

