-- Source: database/functions/users/create_occasion_user_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.create_occasion_user_client_sync_v1(p_occasion bigint, p_command_id uuid, p_profile jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_user uuid; v_begin jsonb; v_hash text;
  v_version bigint;
  v_result jsonb; v_profile jsonb; v_entity jsonb;
BEGIN
  IF v_actor IS NULL OR NOT (public.get_is_manager_on_occasion(p_occasion)
    OR public.get_is_admin_on_occasion(p_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion manager required'; END IF;
  IF p_profile IS NULL OR jsonb_typeof(p_profile)<>'object'
    OR octet_length(p_profile::text)>262144
    OR (p_profile->>'occasion')::bigint IS DISTINCT FROM p_occasion
    OR p_profile->>'user' IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid new occasion user profile'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'profile',p_profile)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.user.create',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  BEGIN
  v_result:=public.update_user_internal_v1(jsonb_build_object(
    'occasion',p_occasion,'user',NULL,'data',p_profile->'data'));
  IF COALESCE((v_result->>'code')::integer,500) NOT IN (200,201) THEN
    RAISE SQLSTATE 'P0P01' USING MESSAGE='profile creation rejected'; END IF;
  v_user:=(v_result->>'user')::uuid;
  v_result:=public.add_user_to_occasion_internal_v1(p_occasion,v_user);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RAISE SQLSTATE 'P0P01' USING MESSAGE='profile creation rejected'; END IF;
  v_profile:=p_profile||jsonb_build_object('user',v_user);
  v_result:=public.save_occasion_user_for_edit_internal_v1(v_profile);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RAISE SQLSTATE 'P0P01' USING MESSAGE='profile creation rejected'; END IF;
  EXCEPTION WHEN SQLSTATE 'P0P01' THEN
    -- All domain writes, including an account/membership created earlier, rolled back.
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      coalesce((v_result->>'code')::integer,400),jsonb_build_object('version',0,'profile',NULL,'message',v_result->>'message'));
  END;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('occasion_user','occasion',p_occasion,v_user::text,1)
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp() RETURNING version INTO v_version;
  SELECT public.get_occasion_user_command_data_v1(p_occasion,v_user) INTO v_entity;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.user.create','profile',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_user','entityId',v_user,'operation','insert',
      'safeLabel','Occasion user','changedFields',jsonb_build_array('profile','rights','services'))),
    '{}',jsonb_build_array(jsonb_build_object('component','private_profile',
    'userId',v_user)),'[]',jsonb_build_object('version',v_version,'userId',v_user,
      'profile',v_entity));
END; $function$
;
REVOKE ALL ON FUNCTION public.create_occasion_user_client_sync_v1(p_occasion bigint, p_command_id uuid, p_profile jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_occasion_user_client_sync_v1(p_occasion bigint, p_command_id uuid, p_profile jsonb) TO authenticated;

-- Source: database/functions/users/get_occasion_user_command_data_v1.sql
CREATE OR REPLACE FUNCTION public.get_occasion_user_command_data_v1(p_occasion bigint, p_user uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
  SELECT to_jsonb(ou)||jsonb_build_object('profile',jsonb_build_object(
    'id',ui.id,'email',ui.email_readonly,'name',ui.name,'surname',ui.surname,
    'sex',ui.sex,'phone',ui.phone,'birthDate',ui.birth_date,'data',ui.data))
  FROM public.occasion_users ou JOIN public.user_info ui ON ui.id=ou."user"
  WHERE ou.occasion=p_occasion AND ou."user"=p_user;
$function$
;
REVOKE ALL ON FUNCTION public.get_occasion_user_command_data_v1(p_occasion bigint, p_user uuid) FROM PUBLIC,anon,authenticated;

-- Source: database/functions/users/get_occasion_users_editor_bundle_v1.sql
CREATE OR REPLACE FUNCTION public.get_occasion_users_editor_bundle_v1(p_occasion bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_result jsonb; v_users jsonb;
BEGIN
  v_result:=public.get_occasion_users_for_edit(p_occasion)::jsonb;
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN RETURN v_result; END IF;
  WITH companion_owners AS (
    SELECT uc.companion,uc."user" owner_id,uc.origin,
      concat_ws(' ',owner_info.name,owner_info.surname) owner_name
    FROM public.user_companions uc
    JOIN public.user_info owner_info ON owner_info.id=uc."user"
    WHERE uc.occasion=p_occasion
  )
  SELECT COALESCE(jsonb_agg(row.value||jsonb_strip_nulls(jsonb_build_object(
      'aggregate_version',COALESCE(v.version,0),
      'companion_owner_id',owners.owner_id,
      'companion_owner_name',owners.owner_name,
      'companion_origin',owners.origin))),'[]'::jsonb)
  INTO v_users
  FROM jsonb_array_elements(v_result#>'{data,occasion_users}') row
  LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='occasion_user'
    AND v.scope_type='occasion' AND v.scope_id=p_occasion
    AND v.aggregate_id=row.value->>'user'
  LEFT JOIN companion_owners owners ON owners.companion=(row.value->>'user')::uuid;
  RETURN jsonb_set(v_result,'{data,occasion_users}',v_users);
END $function$
;
REVOKE ALL ON FUNCTION public.get_occasion_users_editor_bundle_v1(p_occasion bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_occasion_users_editor_bundle_v1(p_occasion bigint) TO authenticated;

-- Source: database/functions/users/add_user_to_occasion_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.add_user_to_occasion_client_sync_v1(p_occasion bigint, p_user uuid, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_before jsonb;
  v_after jsonb; v_result jsonb; v_version bigint; v_replacements jsonb:='[]';
BEGIN
  IF v_actor IS NULL OR p_user IS NULL OR NOT (
    v_actor=p_user OR public.get_is_manager_on_occasion(p_occasion)
    OR public.get_is_admin_on_occasion(p_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion membership permission required';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'userId',p_user)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'profile.membership.ensure',p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT to_jsonb(ou) INTO v_before FROM public.occasion_users ou
    WHERE ou.occasion=p_occasion AND ou."user"=p_user FOR UPDATE;
  v_result:=public.add_user_to_occasion_internal_v1(p_occasion,p_user);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),v_result); END IF;
  SELECT to_jsonb(ou) INTO v_after FROM public.occasion_users ou
    WHERE ou.occasion=p_occasion AND ou."user"=p_user;
  SELECT COALESCE(v.version,0) INTO v_version FROM (SELECT 1) seed
    LEFT JOIN public.client_aggregate_versions v
      ON v.aggregate_type='occasion_user' AND v.scope_type='occasion'
      AND v.scope_id=p_occasion AND v.aggregate_id=p_user::text;
  IF v_before IS NOT DISTINCT FROM v_after THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('version',v_version,'userId',p_user)); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('occasion_user','occasion',p_occasion,p_user::text,1)
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp() RETURNING version INTO v_version;
  IF v_actor=p_user THEN v_replacements:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',p_user,
    'payload',public.get_private_profile_payload_v1(p_occasion,p_user))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.membership.ensure','profile',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_user','entityId',p_user,'operation',
      CASE WHEN v_before IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel','Occasion membership','changedFields',jsonb_build_array(
        'membership','rights'))),'{}',jsonb_build_array(jsonb_build_object(
          'component','private_profile','userId',p_user)),'[]',
    jsonb_build_object('version',v_version,'userId',p_user),
    '{}','[]','user',NULL,v_replacements);
END; $function$
;
REVOKE ALL ON FUNCTION public.add_user_to_occasion_client_sync_v1(p_occasion bigint, p_user uuid, p_command_id uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.add_user_to_occasion_client_sync_v1(p_occasion bigint, p_user uuid, p_command_id uuid) TO authenticated;

-- Source: database/functions/users/save_occasion_user_for_edit.sql
CREATE OR REPLACE FUNCTION public.save_occasion_user_for_edit_internal_v1(input_data jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_occasion bigint := (input_data->>'occasion')::bigint;
    v_user uuid := (input_data->>'user')::uuid;
    v_unit bigint;
    v_data jsonb := CASE WHEN jsonb_typeof(input_data->'data') = 'object'
                         THEN input_data->'data' ELSE '{}'::jsonb END;
    v_services jsonb := CASE WHEN jsonb_typeof(input_data->'services') = 'object'
                             THEN input_data->'services' ELSE '{}'::jsonb END;
    v_catalog jsonb;
    v_existing_services jsonb;
    v_code text;
    v_global_before jsonb;
BEGIN
    SELECT o.unit,
           CASE WHEN jsonb_typeof(o.services) = 'object'
                THEN o.services ELSE '{}'::jsonb END
      INTO v_unit, v_catalog
      FROM public.occasions o
     WHERE o.id = v_occasion;

    IF v_unit IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Occasion not found');
    END IF;

    -- Keep the write boundary at occasion management level. In particular,
    -- a unit editor must not gain the ability to assign manager/editor flags
    -- through this SECURITY DEFINER function.
    IF NOT public.get_is_manager_on_occasion(v_occasion)
       AND NOT public.get_is_admin_on_occasion(v_occasion) THEN
        RETURN jsonb_build_object('code', 403, 'message', 'Not authorized to update occasion users');
    END IF;

    SELECT CASE WHEN jsonb_typeof(ou.services) = 'object'
                THEN ou.services ELSE '{}'::jsonb END
      INTO v_existing_services
      FROM public.occasion_users ou
     WHERE ou.occasion = v_occasion AND ou."user" = v_user;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Occasion user not found');
    END IF;

    -- Every assigned accommodation code must still exist in this occasion's
    -- catalog. This keeps the grid select and persisted service data aligned.
    FOR v_code IN
        SELECT key FROM jsonb_each(
            CASE WHEN jsonb_typeof(v_services->'accommodation') = 'object'
                 THEN v_services->'accommodation' ELSE '{}'::jsonb END
        )
    LOOP
        IF NOT EXISTS (
            SELECT 1
              FROM jsonb_array_elements(
                  CASE WHEN jsonb_typeof(v_catalog->'accommodation') = 'array'
                       THEN v_catalog->'accommodation' ELSE '[]'::jsonb END
              ) item
             WHERE item->>'code' = v_code
        ) AND NOT COALESCE((
            -- Historical assignments can outlive a removed catalog item.
            -- Preserve such a code on unrelated edits, but never allow a new
            -- unknown code to be introduced.
            jsonb_typeof(v_existing_services->'accommodation') = 'object'
            AND (v_existing_services->'accommodation') ? v_code
        ), false) THEN
            RETURN jsonb_build_object('code', 400, 'message', 'Unknown accommodation code: ' || v_code);
        END IF;
    END LOOP;

    SELECT to_jsonb(ui) INTO v_global_before FROM public.user_info ui WHERE id=v_user FOR UPDATE;
    UPDATE public.user_info
       SET data = COALESCE(user_info.data, '{}'::jsonb)
                  || public.get_user_profile_data_patch(v_data),
           name = COALESCE(v_data->>'name', user_info.name),
           surname = COALESCE(v_data->>'surname', user_info.surname),
           sex = COALESCE(v_data->>'sex', user_info.sex),
           phone = CASE
               WHEN v_data ? 'phone' THEN v_data->>'phone'
               ELSE user_info.phone
           END,
           birth_date = CASE
               WHEN v_data ? 'birthDate'
                   THEN NULLIF(v_data->>'birthDate', '')::date
               ELSE user_info.birth_date
           END
     WHERE id = v_user;

    PERFORM public.publish_user_profile_change_internal_v1(v_user,v_occasion,v_global_before);

    UPDATE public.occasion_users
       SET data = v_data,
           -- A grid may edit only one service family. Merge top-level service
           -- keys so changing accommodation never erases food (and vice versa).
           -- An explicitly supplied empty object still clears that family.
           services = COALESCE(occasion_users.services, '{}'::jsonb) || v_services,
           role = CASE WHEN input_data ? 'role' THEN (input_data->>'role')::int ELSE role END,
           is_editor = COALESCE((input_data->>'is_editor')::boolean, is_editor),
           is_editor_view = COALESCE((input_data->>'is_editor_view')::boolean, is_editor_view),
           is_editor_order = COALESCE((input_data->>'is_editor_order')::boolean, is_editor_order),
           is_editor_order_view = COALESCE((input_data->>'is_editor_order_view')::boolean, is_editor_order_view),
           is_cleaning_crew = COALESCE((input_data->>'is_cleaning_crew')::boolean, is_cleaning_crew),
           is_cleaning_blocked = COALESCE((input_data->>'is_cleaning_blocked')::boolean, is_cleaning_blocked),
           is_receptionist = COALESCE((input_data->>'is_receptionist')::boolean, is_receptionist),
           is_approver = COALESCE((input_data->>'is_approver')::boolean, is_approver),
           is_approved = COALESCE((input_data->>'is_approved')::boolean, is_approved),
           is_manager = COALESCE((input_data->>'is_manager')::boolean, is_manager)
     WHERE occasion = v_occasion AND "user" = v_user;

    RETURN jsonb_build_object('code', 200, 'message', 'Occasion user updated');
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$;

-- Released grid facade. Baseline is read under the membership lock.
CREATE OR REPLACE FUNCTION public.save_occasion_user_for_edit(input_data jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE oc bigint:=(input_data->>'occasion')::bigint; usr uuid:=(input_data->>'user')::uuid; ver bigint; r jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT(public.get_is_manager_on_occasion(oc) OR public.get_is_admin_on_occasion(oc)) THEN RETURN jsonb_build_object('code',403); END IF;
 PERFORM 1 FROM public.user_info WHERE id=usr FOR UPDATE;
 PERFORM 1 FROM public.occasion_users WHERE occasion=oc AND "user"=usr FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('code',404); END IF;
 SELECT coalesce(v.version,0) INTO ver FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='occasion_user' AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=usr::text;
 input_data:=jsonb_set(input_data,'{data}',CASE WHEN jsonb_typeof(input_data->'data')='object' THEN (input_data->'data')-'is_invited' ELSE '{}' END);
 r:=public.save_profile_client_sync_v1(oc,usr,extensions.gen_random_uuid(),ver,input_data);
 RETURN jsonb_build_object('code',r->'code','message',r#>'{data,message}');
END $$;
REVOKE ALL ON FUNCTION public.save_occasion_user_for_edit_internal_v1(jsonb) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.save_occasion_user_for_edit(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_occasion_user_for_edit(jsonb) TO authenticated;

-- Source: database/functions/users/update_user.sql
CREATE OR REPLACE FUNCTION public.update_user_internal_v1(
  input_data jsonb
) RETURNS jsonb
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_user uuid;
  v_occasion bigint;
  v_unit_input bigint;
  v_is_manager boolean;
  v_is_editor boolean;
  v_data jsonb;
  v_email text;
  v_password text;
  v_org bigint;
  v_unit bigint;
  new_user uuid;
  existing_user_id uuid;
  v_global_before jsonb;
  v_create_response jsonb;
BEGIN
  -- Extract main fields from the input_data jsonb object
  v_user := (input_data->>'user')::uuid;
  v_occasion := (input_data->>'occasion')::bigint;
  v_unit_input := (input_data->>'unit')::bigint;
  v_is_manager := COALESCE((input_data->>'is_manager')::boolean, false);
  v_is_editor := COALESCE((input_data->>'is_editor')::boolean, false);

  -- Ensure 'data' field is a valid jsonb
  v_data := CASE
        WHEN input_data->>'data' IS NULL OR input_data->>'data' = ''
        THEN '{}'::jsonb
        ELSE input_data->'data'
       END;

  -- Determine the unit
  IF v_occasion IS NOT NULL THEN
    SELECT unit INTO v_unit FROM public.occasions WHERE id = v_occasion;
    IF v_unit IS NULL THEN
     RETURN jsonb_build_object('code', 404, 'message', 'Occasion not found');
    END IF;
  ELSIF v_unit_input IS NOT NULL THEN
    v_unit := v_unit_input;
    IF NOT EXISTS (SELECT 1 FROM public.units WHERE id = v_unit) THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Unit not found');
    END IF;
  ELSE
    RETURN jsonb_build_object('code', 400, 'message', 'Either an occasion or a unit must be provided');
  END IF;

  -- Get the organization
  SELECT organization INTO v_org FROM public.units WHERE id = v_unit;
  IF v_org IS NULL THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Organization not found for the specified unit');
  END IF;

  -- Authorization check
  IF v_occasion IS NOT NULL THEN
    IF NOT EXISTS (
     SELECT 1 FROM public.occasion_users
     WHERE "user" = auth.uid()
      AND occasion = v_occasion
      AND is_manager = true
    ) THEN
     RETURN jsonb_build_object('code', 403, 'message', 'Unauthorized: Caller is not a manager for this occasion');
    END IF;
  ELSE
    IF NOT EXISTS (
        SELECT 1 FROM public.unit_users
        WHERE "user" = auth.uid()
        AND unit = v_unit
        AND is_manager = true
    ) THEN
        RETURN jsonb_build_object('code', 403, 'message', 'Unauthorized: Caller is not a manager for this unit');
    END IF;
  END IF;

  -- Logic for finding or creating user
  IF v_user IS NULL THEN
    v_email := input_data->'data'->>'email';

    IF v_email IS NULL OR v_email = '' THEN
      RETURN jsonb_build_object('code', 400, 'message', 'Email is required to find or create a user.');
    END IF;

    -- Check if user exists
    SELECT id INTO existing_user_id
    FROM auth.users
    WHERE email = v_org::text || '+' || v_email;

    IF existing_user_id IS NOT NULL THEN
      IF EXISTS(SELECT 1 FROM public.user_info WHERE id=existing_user_id AND organization IS DISTINCT FROM v_org) THEN
        RETURN jsonb_build_object('code',403,'message','User is outside the unit organization'); END IF;
      -- Create profile if missing
      IF NOT EXISTS (SELECT 1 FROM public.user_info WHERE id = existing_user_id) THEN
        INSERT INTO public.user_info (
          id, organization, email_readonly, data, name, surname, sex, phone,
          birth_date
        )
        VALUES (
            existing_user_id,
            v_org,
            v_email,
            v_data,
            v_data->>'name',
            v_data->>'surname',
            v_data->>'sex',
            v_data->>'phone',
            NULLIF(v_data->>'birthDate', '')::date
        );
      END IF;

      RETURN jsonb_build_object('code', 200, 'message', 'User found', 'user', existing_user_id::text);

    ELSE
      -- User does not exist, create new one
      v_password := encode(gen_random_bytes(16), 'hex');

      -- 1. Capture the JSONB response
      v_create_response := create_user_in_organization_with_data_ws(v_org, v_email, v_password, v_data);

      -- 2. Check if creation was successful (code 200)
      IF (v_create_response->>'code')::int != 200 THEN
          RETURN v_create_response; -- Return the error from the creation function
      END IF;

      -- 3. Extract the UUID string and cast it to UUID type
      new_user := (v_create_response->>'id')::uuid;

      RETURN jsonb_build_object(
       'code', 201,
       'message', 'User created successfully',
       'user', new_user::text
      );
    END IF;
  END IF;

  -- Global profile is the parent of its occasion projections.
  SELECT to_jsonb(ui) INTO v_global_before FROM public.user_info ui WHERE id=v_user AND organization=v_org FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('code',403,'message','User is outside the unit organization'); END IF;
  -- Update existing user logic
  UPDATE public.user_info
  SET
    data = COALESCE(user_info.data, '{}'::jsonb)
           || public.get_user_profile_data_patch(v_data),
    name = COALESCE(v_data->>'name', user_info.name),
    surname = COALESCE(v_data->>'surname', user_info.surname),
    sex = COALESCE(v_data->>'sex', user_info.sex),
    phone = CASE
      WHEN v_data ? 'phone' THEN v_data->>'phone'
      ELSE user_info.phone
    END,
    birth_date = CASE
      WHEN v_data ? 'birthDate'
        THEN NULLIF(v_data->>'birthDate', '')::date
      ELSE user_info.birth_date
    END
  WHERE id = v_user;

  PERFORM public.publish_user_profile_change_internal_v1(v_user,v_occasion,v_global_before);
  RETURN jsonb_build_object(
   'code', 200,
   'message', 'User details updated successfully',
   'user', v_user
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$ LANGUAGE plpgsql;

-- Unit account management remains a distinct legacy scope; occasion creation uses its command.
CREATE OR REPLACE FUNCTION public.update_user(input_data jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF input_data->>'occasion' IS NOT NULL THEN RETURN jsonb_build_object('code',426,'message','Upgrade required: create_occasion_user_client_sync_v1'); END IF;
 RETURN public.update_user_internal_v1(input_data);
END $$;
REVOKE ALL ON FUNCTION public.update_user_internal_v1(jsonb) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.update_user(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_user(jsonb) TO authenticated;
-- No current caller of this obsolete occasion-profile overload remains.
REVOKE ALL ON FUNCTION public.update_user(uuid,bigint,jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/users/get_occasion_membership_for_edit_v1.sql
CREATE OR REPLACE FUNCTION public.get_occasion_membership_for_edit_v1(p_occasion bigint,p_user uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT(auth.uid()=p_user OR public.get_is_manager_on_occasion(p_occasion) OR public.get_is_admin_on_occasion(p_occasion)) THEN RAISE insufficient_privilege USING MESSAGE='profile owner or manager required'; END IF;
 RETURN (SELECT to_jsonb(ou)||jsonb_build_object('aggregate_version',coalesce(v.version,0)) FROM public.occasion_users ou LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='occasion_user' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=p_user::text WHERE ou.occasion=p_occasion AND ou."user"=p_user);
END $$;
REVOKE ALL ON FUNCTION public.get_occasion_membership_for_edit_v1(bigint,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_occasion_membership_for_edit_v1(bigint,uuid) TO authenticated;

