 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
BEGIN RETURN public.create_service_item_client_sync_v1(
  oc,type,code,title,reference,extensions.gen_random_uuid())->'data'; END; $function$
