-- Source: database/functions/user_services/create_service_item_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.create_service_item_client_sync_v1(p_occasion bigint, p_type text, p_code text, p_title text, p_reference bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_result jsonb;
  v_before jsonb; v_after jsonb;
BEGIN
  IF v_actor IS NULL OR p_type NOT IN ('food','accommodation')
    OR nullif(btrim(p_code),'') IS NULL OR length(p_code)>100
    OR length(COALESCE(p_title,''))>500
    OR NOT public.get_is_manager_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion manager required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'type',p_type,'code',p_code,'title',p_title,
    'reference',p_reference)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'occasion.service.create',p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT o.services INTO v_before FROM public.occasions o
    WHERE o.id=p_occasion FOR UPDATE;
  v_result:=public.create_service_item_internal_v1(
    p_occasion,p_type,p_code,p_title,p_reference);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      400,v_result); END IF;
  SELECT o.services INTO v_after FROM public.occasions o WHERE o.id=p_occasion;
  IF v_before IS NOT DISTINCT FROM v_after THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'unchanged',200,v_result); END IF;
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES('occasion','occasion',p_occasion,p_occasion::text,1)
  ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
  SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'occasion.service.create','configuration',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_service','entityId',p_code,'operation','insert',
      'safeLabel',left(p_title,240),'changedFields',jsonb_build_array('services'))),
    ARRAY['occasion_config'],'[]','[]',v_result);
END; $function$
;
REVOKE ALL ON FUNCTION public.create_service_item_client_sync_v1(bigint,text,text,text,bigint,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_service_item_client_sync_v1(bigint,text,text,text,bigint,uuid) TO authenticated;

-- Source: database/functions/user_services/update_service_item.sql
CREATE OR REPLACE FUNCTION public.update_service_item_internal_v1(oc bigint, type text, code text, new_title text, new_reference bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  updated_services JSONB;
BEGIN

  IF (SELECT get_is_manager_on_occasion(oc)) <> TRUE THEN
    RETURN jsonb_build_object('code', 403);
  END IF;

  -- Check if the code exists within the specified type
  IF NOT EXISTS (
    SELECT 1
    FROM public.occasions,
         jsonb_array_elements(occasions.services->type) AS item
    WHERE occasions.id = oc
      AND (item->>'code') = code
  ) THEN
    -- If code does not exist, return an error response
    RETURN jsonb_build_object(
      'code', 404,
      'message', 'Service item not found'
    );
  END IF;

  -- Update the specified service item
  updated_services := (
    SELECT jsonb_agg(
      CASE
        WHEN (item->>'code') = code THEN
          item || jsonb_build_object('title', new_title, 'reference', new_reference)
        ELSE
          item
      END
    )
    FROM public.occasions,
         jsonb_array_elements(occasions.services->type) AS item
    WHERE occasions.id = oc
  );

  -- Apply the updated services JSON to the specified type
  UPDATE public.occasions
  SET services = jsonb_set(
    services,
    ARRAY[type],
    updated_services,
    true
  )
  WHERE id = oc;

  -- Return success response
  RETURN jsonb_build_object(
    'code', 200,
    'message', 'Service item updated successfully'
  );
END;
$function$
;
REVOKE ALL ON FUNCTION public.update_service_item_internal_v1(bigint,text,text,text,bigint) FROM PUBLIC,anon,authenticated,service_role;
