CREATE OR REPLACE FUNCTION public.get_event_command_data_v1(p_event_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
  SELECT jsonb_build_object(
    'id',e.id,'title',e.title,'startTime',e.start_time,'endTime',e.end_time,
    'maxParticipants',e.max_participants,'description',e.description,
    'placeId',e.place,'splitForMenWomen',e.split_for_men_women,
    'isGroupEvent',e.is_group_event,'isHidden',e.is_hidden,'type',e.type,
    'data',e.data,'order',e."order",
    'parentEventIds',COALESCE((SELECT jsonb_agg(g.event_parent ORDER BY g.event_parent)
      FROM public.event_groups g WHERE g.event_child=e.id),'[]'::jsonb),
    'eventRoleIds',COALESCE((SELECT jsonb_agg(r.role ORDER BY r.role)
      FROM public.event_roles r WHERE r.event=e.id),'[]'::jsonb))
  FROM public.events e WHERE e.id=p_event_id;
$function$
;
REVOKE ALL ON FUNCTION public.get_event_command_data_v1(bigint) FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/events/save_event_domain_command_internal_v1.sql
CREATE OR REPLACE FUNCTION public.save_event_domain_command_internal_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_event_id bigint := (p_event->>'id')::bigint;
  v_version bigint;
  v_begin jsonb;
  v_commit jsonb;
  v_data jsonb;
  v_current jsonb;
  v_requested jsonb;
  v_response jsonb;
  v_program jsonb;
  v_hash text;
  v_changed boolean := true;
  v_is_publishable boolean;
  v_parent_ids bigint[];
  v_role_ids bigint[];
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  SELECT NOT o.is_hidden INTO v_is_publishable
  FROM public.occasions o WHERE o.id=p_occasion;
  IF v_is_publishable IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='occasion not found';
  END IF;
  IF p_event IS NULL OR jsonb_typeof(p_event)<>'object'
     OR octet_length(p_event::text)>131072
     OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_event) key WHERE key NOT IN
       ('id','title','startTime','endTime','maxParticipants','description',
        'placeId','splitForMenWomen','isGroupEvent','isHidden','type','data',
        'order','parentEventIds','eventRoleIds'))
     OR NOT (p_event ?& ARRAY['title','startTime','endTime','splitForMenWomen',
       'isGroupEvent','isHidden','order','parentEventIds','eventRoleIds'])
     OR jsonb_typeof(p_event->'parentEventIds')<>'array'
     OR jsonb_typeof(p_event->'eventRoleIds')<>'array'
     OR jsonb_array_length(p_event->'parentEventIds')>1000
     OR jsonb_array_length(p_event->'eventRoleIds')>1000
     OR length(p_event->>'title') NOT BETWEEN 1 AND 500
     OR (p_event->>'startTime')::timestamptz >= (p_event->>'endTime')::timestamptz
     OR COALESCE((p_event->>'maxParticipants')::bigint,0)<0 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid event aggregate';
  END IF;

  SELECT COALESCE(array_agg(value::bigint ORDER BY value::bigint),'{}')
    INTO v_parent_ids FROM jsonb_array_elements_text(p_event->'parentEventIds');
  SELECT COALESCE(array_agg(value::bigint ORDER BY value::bigint),'{}')
    INTO v_role_ids FROM jsonb_array_elements_text(p_event->'eventRoleIds');
  v_requested:=jsonb_build_object(
    'id',v_event_id,'title',p_event->>'title',
    'startTime',(p_event->>'startTime')::timestamptz,
    'endTime',(p_event->>'endTime')::timestamptz,
    'maxParticipants',(p_event->>'maxParticipants')::bigint,
    'description',p_event->>'description',
    'placeId',(p_event->>'placeId')::bigint,
    'splitForMenWomen',(p_event->>'splitForMenWomen')::boolean,
    'isGroupEvent',(p_event->>'isGroupEvent')::boolean,
    'isHidden',(p_event->>'isHidden')::boolean,'type',p_event->>'type',
    'data',p_event->'data','order',(p_event->>'order')::bigint,
    'parentEventIds',to_jsonb(v_parent_ids),'eventRoleIds',to_jsonb(v_role_ids));

  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'expectedVersion',p_expected_version,'event',p_event)::text,
    'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'event.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.places WHERE id=(p_event->>'placeId')::bigint AND occasion=p_occasion FOR KEY SHARE;
  PERFORM 1 FROM public.role_info WHERE id=ANY(v_role_ids) AND occasion=p_occasion ORDER BY id FOR KEY SHARE;
  PERFORM 1 FROM public.events WHERE id=ANY(v_parent_ids||ARRAY[v_event_id]) AND occasion=p_occasion ORDER BY id FOR UPDATE;

  IF v_event_id IS NOT NULL THEN
    PERFORM 1 FROM public.events e WHERE e.id=v_event_id AND e.occasion=p_occasion
      FOR UPDATE;
    IF NOT FOUND THEN
      v_response:=jsonb_build_object('status','rejected','code',404,
        'data',jsonb_build_object('eventId',v_event_id),
        'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
          'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
        'sync',jsonb_build_object('replacements','[]'::jsonb));
      RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
    END IF;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('event','occasion',p_occasion,v_event_id::text,0)
    ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='event' AND scope_type='occasion'
        AND scope_id=p_occasion AND aggregate_id=v_event_id::text FOR UPDATE;
    v_current:=public.get_event_command_data_v1(v_event_id);
    IF p_expected_version IS DISTINCT FROM v_version THEN
      v_response:=jsonb_build_object('status','conflict','code',409,
        'data',jsonb_build_object('version',v_version,'event',v_current),
        'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
          'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
        'sync',jsonb_build_object('replacements','[]'::jsonb));
      RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
    END IF;
    v_changed:=v_current IS DISTINCT FROM v_requested;
  ELSIF p_expected_version IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new event must not have an expected version';
  END IF;

  IF cardinality(v_parent_ids)<>cardinality(ARRAY(SELECT DISTINCT unnest(v_parent_ids)))
     OR cardinality(v_role_ids)<>cardinality(ARRAY(SELECT DISTINCT unnest(v_role_ids)))
     OR (v_event_id IS NOT NULL AND v_event_id=ANY(v_parent_ids))
     OR EXISTS (
       SELECT 1
       FROM unnest(v_parent_ids) AS parent(parent_id)
       LEFT JOIN public.events e
         ON e.id=parent.parent_id AND e.occasion=p_occasion
       WHERE e.id IS NULL
     )
     OR EXISTS (
       SELECT 1
       FROM unnest(v_role_ids) AS requested_role(role_id)
       LEFT JOIN public.role_info r
         ON r.id=requested_role.role_id AND r.occasion=p_occasion
       WHERE r.id IS NULL
     )
     OR ((p_event->>'placeId') IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM public.places p WHERE p.id=(p_event->>'placeId')::bigint
         AND p.occasion=p_occasion)) THEN
    RAISE invalid_parameter_value USING MESSAGE='event aggregate contains cross-scope references';
  END IF;


  IF NOT v_changed THEN
    v_response:=jsonb_build_object('status','unchanged','code',200,
      'data',jsonb_build_object('version',v_version,'event',v_current),
      'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
        'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
      'sync',jsonb_build_object('replacements','[]'::jsonb));
    RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
  END IF;

  IF v_event_id IS NULL THEN
    INSERT INTO public.events(title,start_time,end_time,max_participants,description,
      place,split_for_men_women,is_group_event,is_hidden,occasion,type,data,"order")
    VALUES (p_event->>'title',(p_event->>'startTime')::timestamptz,
      (p_event->>'endTime')::timestamptz,(p_event->>'maxParticipants')::bigint,
      p_event->>'description',(p_event->>'placeId')::bigint,
      (p_event->>'splitForMenWomen')::boolean,(p_event->>'isGroupEvent')::boolean,
      (p_event->>'isHidden')::boolean,p_occasion,p_event->>'type',p_event->'data',
      (p_event->>'order')::bigint) RETURNING id INTO v_event_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('event','occasion',p_occasion,v_event_id::text,v_version);
  ELSE
    UPDATE public.events SET title=p_event->>'title',
      start_time=(p_event->>'startTime')::timestamptz,
      end_time=(p_event->>'endTime')::timestamptz,
      max_participants=(p_event->>'maxParticipants')::bigint,
      description=p_event->>'description',place=(p_event->>'placeId')::bigint,
      split_for_men_women=(p_event->>'splitForMenWomen')::boolean,
      is_group_event=(p_event->>'isGroupEvent')::boolean,
      is_hidden=(p_event->>'isHidden')::boolean,type=p_event->>'type',
      data=p_event->'data',"order"=(p_event->>'order')::bigint,updated_at=now()
    WHERE id=v_event_id;
    UPDATE public.client_aggregate_versions SET version=version+1,updated_at=clock_timestamp()
      WHERE aggregate_type='event' AND scope_type='occasion'
        AND scope_id=p_occasion AND aggregate_id=v_event_id::text
      RETURNING version INTO v_version;
  END IF;
  DELETE FROM public.event_groups WHERE event_child=v_event_id;
  INSERT INTO public.event_groups(event_parent,event_child)
    SELECT parent.parent_id,v_event_id
    FROM unnest(v_parent_ids) AS parent(parent_id);
  DELETE FROM public.event_roles WHERE event=v_event_id;
  INSERT INTO public.event_roles(event,role)
    SELECT v_event_id,requested_role.role_id
    FROM unnest(v_role_ids) AS requested_role(role_id);

  v_data:=jsonb_build_object('version',v_version,
    'event',public.get_event_command_data_v1(v_event_id));
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'event.save','program',jsonb_build_array(jsonb_build_object(
      'entityType','event','entityId',v_event_id,
      'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_event->>'title',240),
      'changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_is_publishable THEN ARRAY['program_catalog'] ELSE '{}'::text[] END,
    '[]','[]',v_data);
END;
$function$
;
REVOKE ALL ON FUNCTION public.save_event_domain_command_internal_v1(bigint,uuid,bigint,jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- Source: database/functions/events/save_event_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_event_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_response jsonb; v_commit uuid; v_event bigint;
BEGIN
  v_response:=public.save_event_domain_command_internal_v1(
    p_occasion,p_command_id,p_expected_version,p_event);
  IF v_response->>'status'='applied' THEN
    v_commit:=NULLIF(v_response#>>'{mutation,commitId}','')::uuid;
    v_event:=NULLIF(v_response#>>'{data,event,id}','')::bigint;
    IF v_event IS NULL THEN v_event:=NULLIF(v_response#>>'{data,eventId}','')::bigint; END IF;
    IF v_commit IS NOT NULL AND v_event IS NOT NULL
       AND EXISTS (SELECT 1 FROM public.occasions o WHERE o.id=p_occasion AND NOT o.is_hidden) THEN
      PERFORM public.attach_event_live_projection_v1(v_commit,p_occasion,ARRAY[v_event]);
    END IF;
  END IF;
  RETURN v_response;
END; $function$
;
REVOKE ALL ON FUNCTION public.save_event_client_sync_v1(bigint,uuid,bigint,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.save_event_client_sync_v1(bigint,uuid,bigint,jsonb) TO authenticated;

-- Source: database/functions/events/save_event_speakers_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_event_speakers_client_sync_v1(p_occasion bigint, p_event bigint, p_command_id uuid, p_expected_version bigint, p_speaker_ids bigint[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_version bigint; v_begin jsonb; v_hash text;
  v_current bigint[]; v_requested bigint[];
  v_publishable boolean; v_event_hidden boolean;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  SELECT COALESCE(array_agg(requested_speaker.speaker_id
      ORDER BY requested_speaker.speaker_id),'{}'::bigint[])
    INTO v_requested
    FROM unnest(COALESCE(p_speaker_ids,'{}'::bigint[]))
      AS requested_speaker(speaker_id);
  IF cardinality(v_requested)<>cardinality(ARRAY(SELECT DISTINCT unnest(v_requested)))
    OR cardinality(v_requested)>1000 OR EXISTS (
      SELECT 1
      FROM unnest(v_requested) AS requested_speaker(speaker_id)
      LEFT JOIN public.speakers s
        ON s.id=requested_speaker.speaker_id AND s.occasion=p_occasion
      WHERE s.id IS NULL) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid event speakers'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'eventId',p_event,'expectedVersion',p_expected_version,
    'speakerIds',to_jsonb(v_requested))::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'program.event_speakers.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT e.is_hidden,NOT o.is_hidden INTO v_event_hidden,v_publishable
    FROM public.events e JOIN public.occasions o ON o.id=e.occasion
    WHERE e.id=p_event AND e.occasion=p_occasion FOR UPDATE OF e;
  IF v_event_hidden IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'rejected',404,jsonb_build_object('version',0,'eventId',p_event,
      'speakerIds','[]'::jsonb)); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('event','occasion',p_occasion,p_event::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='event' AND scope_type='occasion'
    AND scope_id=p_occasion AND aggregate_id=p_event::text FOR UPDATE;
  SELECT COALESCE(array_agg(es.speaker ORDER BY es.speaker),'{}') INTO v_current
    FROM public.event_speakers es WHERE es.event=p_event;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('version',v_version,'eventId',p_event,
        'speakerIds',to_jsonb(v_current))); END IF;
  IF v_current=v_requested THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'unchanged',200,jsonb_build_object('version',v_version,
      'eventId',p_event,'speakerIds',to_jsonb(v_current))); END IF;
  DELETE FROM public.event_speakers WHERE event=p_event;
  INSERT INTO public.event_speakers(event,speaker)
    SELECT p_event,requested_speaker.speaker_id
    FROM unnest(v_requested) AS requested_speaker(speaker_id);
  UPDATE public.client_aggregate_versions SET version=version+1,
    updated_at=clock_timestamp() WHERE aggregate_type='event'
    AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_event::text
    RETURNING version INTO v_version;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'program.event_speakers.save','program',jsonb_build_array(jsonb_build_object(
      'entityType','event_speakers','entityId',p_event,'operation','update',
      'safeLabel','Event speakers','changedFields',jsonb_build_array('speakerIds'))),
    CASE WHEN v_publishable AND NOT v_event_hidden THEN ARRAY['program_catalog']
      ELSE '{}'::text[] END,'[]','[]',jsonb_build_object('version',v_version,
      'eventId',p_event,'speakerIds',to_jsonb(v_requested)));
END; $function$
;
REVOKE ALL ON FUNCTION public.save_event_speakers_client_sync_v1(bigint,bigint,uuid,bigint,bigint[]) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.save_event_speakers_client_sync_v1(bigint,bigint,uuid,bigint,bigint[]) TO authenticated;

-- Source: database/functions/speakers/set_event_speakers.sql
CREATE OR REPLACE FUNCTION public.set_event_speakers(p_event bigint,p_speakers bigint[])
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE oc bigint; ver bigint; result jsonb;
BEGIN
 SELECT occasion INTO oc FROM public.events WHERE id=p_event;
 IF oc IS NULL THEN RETURN jsonb_build_object('code',404); END IF;
 IF public.get_is_editor_on_occasion(oc) IS NOT TRUE THEN RETURN jsonb_build_object('code',403); END IF;
 PERFORM 1 FROM public.events WHERE id=p_event FOR UPDATE;
 SELECT coalesce(v.version,0) INTO ver FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='event' AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=p_event::text;
 result:=public.save_event_speakers_client_sync_v1(oc,p_event,extensions.gen_random_uuid(),ver,p_speakers);
 RETURN jsonb_build_object('code',result->'code');
EXCEPTION WHEN invalid_parameter_value THEN RETURN jsonb_build_object('code',400);
END $$;
REVOKE ALL ON FUNCTION public.set_event_speakers(bigint,bigint[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_event_speakers(bigint,bigint[]) TO authenticated;

-- Source: database/functions/groups/group_editor_read.sql
CREATE OR REPLACE FUNCTION public.get_user_group_command_data_v1(p_group bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO public, extensions
AS $function$
  SELECT jsonb_build_object('id',g.id,'title',g.title,
    'description',g.description,'type',g.type,'data',g.data,'place',g.place,
    'is_admin',COALESCE((SELECT is_admin FROM public.user_groups WHERE "group"=g.id AND "user"=auth.uid()),false),
    'aggregate_version',COALESCE((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='user_group' AND scope_type='occasion' AND scope_id=g.occasion AND aggregate_id=g.id::text),0),
    'placeData',(SELECT to_jsonb(p)||jsonb_build_object('aggregate_version',COALESCE((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='place' AND scope_type='occasion' AND scope_id=g.occasion AND aggregate_id=p.id::text),0)) FROM public.places p WHERE p.id=g.place),
    'participants',COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'userId',ug."user",'isAdmin',ug.is_admin,'is_admin',ug.is_admin,
      'user_info',jsonb_build_object('id',ui.id,'name',ui.name,'surname',ui.surname))
      ORDER BY ug."user") FROM public.user_groups ug JOIN public.user_info ui
      ON ui.id=ug."user" WHERE ug."group"=g.id),'[]'::jsonb))
  FROM public.user_group_info g WHERE g.id=p_group;
$function$
;
REVOKE ALL ON FUNCTION public.get_user_group_command_data_v1(bigint) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.get_user_group_editor_bundle_v1(p_occasion bigint,p_group_id bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT (public.get_is_editor_view_on_occasion(p_occasion) OR public.get_is_editor_on_occasion(p_occasion) OR EXISTS(SELECT 1 FROM public.user_groups ug JOIN public.user_group_info g ON g.id=ug."group" WHERE g.id=p_group_id AND g.occasion=p_occasion AND ug."user"=auth.uid() AND ug.is_admin)) THEN
 RAISE insufficient_privilege USING MESSAGE='group editor required'; END IF;
 RETURN (SELECT public.get_user_group_command_data_v1(id) FROM public.user_group_info WHERE id=p_group_id AND occasion=p_occasion);
END $$;
REVOKE ALL ON FUNCTION public.get_user_group_editor_bundle_v1(bigint,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_user_group_editor_bundle_v1(bigint,bigint) TO authenticated;

-- Source: database/functions/groups/get_group_places_for_map_v1.sql
-- The map's authenticated occasion members retain their existing group-place
-- projection, scoped to one occasion and carrying the original place revision.
CREATE OR REPLACE FUNCTION public.get_group_places_for_map_v1(p_occasion bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT(EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=p_occasion AND "user"=auth.uid())
   OR public.get_is_editor_on_occasion(p_occasion) OR public.get_is_editor_view_on_occasion(p_occasion))
   OR (public.is_demo_occasion(p_occasion) AND NOT public.get_is_editor_order_view_on_occasion(p_occasion)) THEN
  RAISE insufficient_privilege USING MESSAGE='occasion member required'; END IF;
 RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',g.id,'title',g.title,'place',g.place,'places',
  jsonb_build_object('id',p.id,'occasion',p.occasion,'unit',p.unit,'title',p.title,'description',p.description,
    'coordinates',p.coordinates,'type',p.type,'is_hidden',p.is_hidden,'order',p."order",'icon',p.icon,'aggregate_version',coalesce(v.version,0))) ORDER BY g.id)
  FROM public.user_group_info g JOIN public.places p ON p.id=g.place AND p.occasion=g.occasion
  LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='place' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=p.id::text
  WHERE g.occasion=p_occasion AND (NOT public.is_demo_unit(p.unit) OR public.demo_unit_can_read(p.unit))),'[]'::jsonb);
END $$;
REVOKE ALL ON FUNCTION public.get_group_places_for_map_v1(bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_group_places_for_map_v1(bigint) TO authenticated;

-- Source: database/functions/eshop/delete_product.sql
CREATE OR REPLACE FUNCTION public.delete_product_internal_v1(p_product_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_occasion_id BIGINT;
  v_order_count INT;
BEGIN
  -- Determine the occasion of the product to check permissions.
  SELECT pt.occasion
    INTO v_occasion_id
  FROM eshop.products p
  JOIN eshop.product_types pt ON p.product_type = pt.id
  WHERE p.id = p_product_id FOR UPDATE OF p;

  -- If the product does not exist, raise a structured error.
  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object(
        'code', 'PRD404',
        'message', 'Product with ID ' || p_product_id || ' not found.'
    )::text;
  END IF;

  -- Authorization check. This function is expected to throw on failure.
  PERFORM public.check_is_editor_order_on_occasion(v_occasion_id);

  -- Safety Check: Ensure the product is not part of any existing orders.
  SELECT COUNT(*) INTO v_order_count
    FROM eshop.order_product_ticket
   WHERE product = p_product_id;
  IF v_order_count > 0 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
        'code', 'PRD409',
        'message', 'Cannot delete product because it is included in ' || v_order_count || ' order(s).',
        'hint', 'Remove this product from all orders before deleting it.'
    )::text;
  END IF;

  -- **INTEGRATION:** Before deleting the product, clear all its inventory context associations.
  -- This call will also trigger the necessary de-allocation of spots.
  PERFORM public.update_product_inventory_contexts_internal_v1(p_product_id, '[]'::jsonb);

  DELETE FROM eshop.planned_changes WHERE subject_id=p_product_id AND change_type IN('products.price','products.is_hidden') AND NOT applied;

  -- Finally, delete the product itself.
  DELETE FROM eshop.products
   WHERE id = p_product_id;

END;
$function$
;
REVOKE ALL ON FUNCTION public.delete_product_internal_v1(bigint) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.delete_product(p_product_id bigint)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN PERFORM public.delete_product_client_sync_v1(p_product_id,extensions.gen_random_uuid()); END $$;
REVOKE ALL ON FUNCTION public.delete_product(bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.delete_product(bigint) TO authenticated;

-- Source: database/functions/eshop/delete_product_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.delete_product_domain_command_internal_v1(p_product_id bigint,p_command_id uuid,p_expected_version bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE actor uuid:=auth.uid(); oc bigint; title text; begin_result jsonb; hash text; version bigint; used bigint; original_key uuid;
BEGIN
 SELECT occasion INTO oc FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=actor AND command_name='inventory.product.delete';
 IF NOT FOUND THEN SELECT t.occasion INTO oc FROM eshop.products t WHERE id=p_product_id; END IF;
 IF actor IS NULL OR oc IS NULL OR public.get_is_editor_order_on_occasion(oc) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='product editor required'; END IF;
 hash:=encode(extensions.digest(convert_to((jsonb_build_object('productId',p_product_id)||CASE WHEN p_expected_version IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('expectedVersion',p_expected_version) END)::text,'UTF8'),'sha256'),'hex');
 begin_result:=public.begin_client_mutation_v1(p_command_id,'inventory.product.delete',oc,actor,hash);
 IF begin_result->>'disposition'='replay' THEN RETURN begin_result->'response'; END IF;
 PERFORM public.lock_product_order_dependencies_internal_v1(p_product_id);
 SELECT t.title INTO title FROM eshop.products t WHERE id=p_product_id AND occasion=oc FOR UPDATE;
 IF NOT FOUND THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',404,jsonb_build_object('productId',p_product_id)); END IF;
 SELECT coalesce(v.version,0) INTO version FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='product' AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=p_product_id::text;
 IF p_expected_version IS NOT NULL AND p_expected_version IS DISTINCT FROM version THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('aggregate_version',version)); END IF;
 SELECT count(*) INTO used FROM eshop.order_product_ticket WHERE product=p_product_id;
 IF used>0 THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('message','product is in use')); END IF;
 PERFORM public.delete_product_internal_v1(p_product_id);
 DELETE FROM public.client_aggregate_versions WHERE aggregate_type='product' AND scope_type='occasion' AND scope_id=oc AND aggregate_id=p_product_id::text;
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,oc,'inventory.product.delete',jsonb_build_array(jsonb_build_object('entityType','product','entityId',p_product_id,'operation','delete','safeLabel',left(title,240),'changedFields',jsonb_build_array('aggregate'))),'{}'::uuid[],jsonb_build_object('productId',p_product_id));
END $$;
REVOKE ALL ON FUNCTION public.delete_product_domain_command_internal_v1(bigint,uuid,bigint) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.delete_product_client_sync_v1(p_product_id bigint,p_command_id uuid,p_expected_version bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF p_expected_version IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='original product version required'; END IF;
 RETURN public.delete_product_domain_command_internal_v1(p_product_id,p_command_id,p_expected_version);
END $$;
REVOKE ALL ON FUNCTION public.delete_product_client_sync_v1(bigint,uuid,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.delete_product_client_sync_v1(bigint,uuid,bigint) TO authenticated;
