-- Source: database/functions/eshop_forms/create_form_ws.sql
CREATE OR REPLACE FUNCTION public.create_form_ws(input_data jsonb)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE v_response jsonb;
BEGIN
  IF input_data IS NULL OR jsonb_typeof(input_data)<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(input_data) k
      WHERE k NOT IN ('occasion_link','link','title')) THEN
    RETURN jsonb_build_object('code',4000,'message','Invalid form input'); END IF;
  v_response:=public.create_form_client_sync_v1(input_data->>'occasion_link',
    input_data->>'link',input_data->>'title',extensions.gen_random_uuid());
  RETURN jsonb_build_object('code',CASE WHEN v_response->>'status'='applied'
      THEN 201 ELSE (v_response->>'code')::integer END,
    'message',CASE WHEN v_response->>'status'='applied'
      THEN 'Form created successfully' ELSE v_response#>>'{data,message}' END,
    'data',v_response#>'{data,form}');
END; $$;
REVOKE ALL ON FUNCTION public.create_form_ws(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_form_ws(jsonb) TO authenticated;

-- Source: database/functions/users/delete_owned_companion_guard_v1.sql
CREATE OR REPLACE FUNCTION public.delete_owned_companion_guard_v1(p_occasion bigint, p_companion uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_policy jsonb;
BEGIN
  v_policy:=public.get_companion_feature_policy_v1(p_occasion);
  IF NOT COALESCE((v_policy->>'is_enabled')::boolean,false)
      OR NOT COALESCE((v_policy->>'allow_user_create')::boolean,true) THEN
    RAISE insufficient_privilege USING MESSAGE='self-created companion lifecycle disabled';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.user_companions uc
    WHERE uc.occasion=p_occasion AND uc."user"=auth.uid()
      AND uc.companion=p_companion AND uc.origin='self_created') THEN
    RAISE insufficient_privilege USING MESSAGE='self-created companion ownership required';
  END IF;
END $function$
;
REVOKE ALL ON FUNCTION public.delete_owned_companion_guard_v1(bigint,uuid) FROM PUBLIC,anon,authenticated,service_role;

