-- Source: database/functions/eshop_forms/duplicate_form_to_occasion_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.duplicate_form_to_occasion_client_sync_v1(
  p_source_form_id bigint,p_target_occasion_link text,p_command_id uuid
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE v_actor uuid:=auth.uid(); v_source_occasion bigint; v_source_unit bigint;
  v_target bigint; v_begin jsonb; v_hash text; v_form bigint;
BEGIN
  SELECT f.occasion,o.unit INTO v_source_occasion,v_source_unit
    FROM public.forms f JOIN public.occasions o ON o.id=f.occasion
    WHERE f.id=p_source_form_id;
  SELECT o.id INTO v_target FROM public.occasions o
    WHERE o.id=public.resolve_occasion_link_internal(p_target_occasion_link);
  IF v_actor IS NULL OR v_target IS NULL
    OR NOT public.get_is_editor_on_occasion(v_target) THEN
    RAISE insufficient_privilege USING MESSAGE='form copy permission required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'sourceFormId',p_source_form_id,'targetOccasion',v_target)::text,'UTF8'),
    'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.form.duplicate',v_target,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF v_source_occasion IS NULL OR NOT(public.get_is_editor_view_on_occasion(v_source_occasion) OR public.get_is_editor_view_on_unit(v_source_unit)) THEN RAISE insufficient_privilege USING MESSAGE='form copy permission required'; END IF;
  v_form:=public.duplicate_form_to_occasion_internal_v1(
    p_source_form_id,p_target_occasion_link);
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_target,
    'inventory.form.duplicate',jsonb_build_array(jsonb_build_object(
      'entityType','form','entityId',v_form,'operation','insert',
      'safeLabel','Duplicated form','changedFields',jsonb_build_array(
        'configuration','fields','products'))),'{}'::uuid[],
    jsonb_build_object('formId',v_form));
END; $$;
REVOKE ALL ON FUNCTION public.duplicate_form_to_occasion_client_sync_v1(bigint,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.duplicate_form_to_occasion_client_sync_v1(bigint,text,uuid) TO authenticated;

-- Source: database/functions/events/get_all_events_for_datagrid.sql
-- Creates the updated function that correctly handles null places
CREATE OR REPLACE FUNCTION public.get_all_events_for_datagrid(p_occasion_id bigint)
RETURNS jsonb
LANGUAGE "plpgsql"
STABLE
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    result_jsonb jsonb;
BEGIN
    -- 1. Security Check: Ensures the calling user has editor permissions.
    IF NOT get_is_editor_view_on_occasion(p_occasion_id) THEN
        RAISE EXCEPTION 'Insufficient permissions. User requires editor view rights for this occasion.'
            USING ERRCODE = '42501'; -- insufficient_privilege
    END IF;

    -- 2. Data Retrieval and JSON Aggregation
    SELECT
        COALESCE(jsonb_agg(event_row.data), '[]'::jsonb)
    INTO
        result_jsonb
    FROM (
        SELECT
            jsonb_build_object(
                'id', e.id,
                'aggregate_version', COALESCE(av.version, 0),
                'is_hidden', e.is_hidden,
                'title', e.title,
                'start_time', e.start_time,
                'end_time', e.end_time,
                'max_participants', e.max_participants,
                'split_for_men_women', e.split_for_men_women,
                'is_group_event', e.is_group_event,
                'type', e.type,
                'data', e.data,
                'places', CASE
                    WHEN p.id IS NULL THEN NULL::jsonb
                    ELSE jsonb_build_object('id', p.id, 'title', p.title)
                END,
                'event_groups', (
                    SELECT COALESCE(jsonb_agg(jsonb_build_object('event_parent', eg.event_parent)), '[]'::jsonb)
                    FROM public.event_groups eg
                    WHERE eg.event_child = e.id
                ),
                'event_roles', (
                    SELECT COALESCE(jsonb_agg(jsonb_build_object('role', er.role)), '[]'::jsonb)
                    FROM public.event_roles er
                    WHERE er.event = e.id
                ),
                'event_users_saved', (
                    SELECT jsonb_agg(jsonb_build_object('count', T.c))
                    FROM (SELECT count(*) AS c FROM public.event_users_saved eus WHERE eus.event = e.id) AS T
                ),
                'event_users', (
                    SELECT jsonb_agg(jsonb_build_object('count', T.c))
                    FROM (SELECT count(*) AS c FROM public.event_users eu WHERE eu.event = e.id) AS T
                )
            ) AS data
        FROM
            public.events AS e
        LEFT JOIN
            public.places AS p ON e.place = p.id
        LEFT JOIN public.client_aggregate_versions av
            ON av.aggregate_type = 'event'
           AND av.scope_type = 'occasion'
           AND av.scope_id = p_occasion_id
           AND av.aggregate_id = e.id::text
        WHERE
            e.occasion = p_occasion_id
        ORDER BY
            e.start_time ASC
    ) AS event_row;

    -- 3. Return the final JSONB array
    RETURN result_jsonb;
END;
$$;

-- Source: database/functions/activities/legacy_activity_facades.sql
-- Released legacy shapes remain adapters; the canonical lifecycle owns every write.
-- Two-step live publication cannot preserve atomicity and requires an upgrade.
CREATE OR REPLACE FUNCTION public.update_activities(p_occasion_id bigint,p_activities_data jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT coalesce(public.get_is_editor_on_occasion(p_occasion_id),false) THEN
  RETURN jsonb_build_object('code',403); END IF;
 RETURN jsonb_build_object('code',426,'message','Upgrade required for atomic activity publication');
END $$;
CREATE OR REPLACE FUNCTION public.save_activity_history(
 p_occasion_id bigint,p_activities_data jsonb,p_history_type text,p_parent_history_id bigint,p_note text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE version bigint; result jsonb; canonical_history jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT coalesce(public.get_is_editor_on_occasion(p_occasion_id),false) THEN
  RETURN jsonb_build_object('code',403); END IF;
 IF p_history_type IS DISTINCT FROM 'AUTOSAVE' THEN
  RETURN jsonb_build_object('code',426,'message','Upgrade required for atomic activity publication'); END IF;
 version:=public.lock_activity_editor_internal_v1(p_occasion_id);
 canonical_history:=public.activity_graph_history_internal_v1(
  public.activity_history_graph_internal_v1(p_occasion_id,p_activities_data));
 result:=public.save_activity_draft_client_sync_v1(p_occasion_id,extensions.gen_random_uuid(),version,canonical_history,p_parent_history_id);
 RETURN jsonb_build_object('code',result->'code','message',result->>'status','data',
  jsonb_build_object('historyId',result#>'{data,draftId}',
   'created_at',(SELECT created_at FROM public.activity_history WHERE id=(result#>>'{data,draftId}')::bigint),
   'latest_publish_id',result#>'{data,latestPublishId}'));
END $$;
CREATE OR REPLACE FUNCTION public.delete_autosave_history(p_occasion_id bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE draft bigint; result jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT coalesce(public.get_is_editor_on_occasion(p_occasion_id),false) THEN
  RETURN jsonb_build_object('code',403); END IF;
 PERFORM public.lock_activity_editor_internal_v1(p_occasion_id);
 SELECT id INTO draft FROM public.activity_history WHERE occasion_id=p_occasion_id
  AND user_id=auth.uid() AND history_type='AUTOSAVE' ORDER BY id DESC LIMIT 1;
 result:=public.discard_activity_draft_client_sync_v1(p_occasion_id,extensions.gen_random_uuid(),draft);
 RETURN jsonb_build_object('code',result->'code','message',result->>'status');
END $$;
REVOKE ALL ON FUNCTION public.update_activities(bigint,jsonb),public.save_activity_history(bigint,jsonb,text,bigint,text),public.delete_autosave_history(bigint)
 FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.update_activities(bigint,jsonb),public.save_activity_history(bigint,jsonb,text,bigint,text),public.delete_autosave_history(bigint)
 TO authenticated;

